Object.assign(window.MLSysGuidedLessons, {"vol2:fig-3d-parallelism-cube":{"key":"vol2:fig-3d-parallelism-cube","figure_id":"fig-3d-parallelism-cube","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"The 3D parallelism cube","status":"ready","treatment":"annotated","question":"Which training relationship does each axis of the device cube represent?","scope":"The cube is a configuration schematic. Memory fit, divisibility, and network placement must still be checked.","regions":{"tensor":{"x":0.26,"y":0.72,"w":0.51,"h":0.22,"label":"Tensor axis and front-row group"},"pipeline":{"x":0.27,"y":0.19,"w":0.33,"h":0.57,"label":"Pipeline axis and vertical group"},"data":{"x":0.53,"y":0.48,"w":0.3,"h":0.35,"label":"Data axis and depth group"},"product":{"x":0.39,"y":0.01,"w":0.57,"h":0.12,"label":"Product of parallel degrees"}},"steps":[{"title":"Split a layer","description":"The horizontal tensor axis groups devices that shard work within a layer. Its communication is frequent enough that placement within a fast domain matters.","focus":["tensor"]},{"title":"Place sequential stages","description":"The vertical pipeline axis separates layers into stages that exchange activations and gradients. It changes where a batch executes through depth.","focus":["pipeline"]},{"title":"Replicate for batches","description":"The diagonal data axis groups replicas processing different batch shards. These ranks exchange model-update information.","focus":["data"]},{"title":"Count the combined configuration","description":"The printed product multiplies all three degrees to give device count. Increasing an axis changes its own traffic and per-device state, not just the total number of GPUs.","focus":["product"]}],"artwork_reviewed":true,"art_sha1":"7ec4ec5c6af1f8e53c673c2bdb86049a76051b84","art_kind":"svg","art_width":1200,"art_height":669,"art_structural_sha1":"c8e2808539d84478fc50ef2fac85d7dedf5b0cae"},"vol2:fig-accelerator-memory-tier-map":{"key":"vol2:fig-accelerator-memory-tier-map","figure_id":"fig-accelerator-memory-tier-map","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Accelerator memory tiers","status":"ready","treatment":"annotated","question":"Why must memory capacity and bandwidth be compared together?","scope":"Peak memory specifications describe different organizations and dataflows; regions are not workload-performance rankings.","regions":{"sram":{"x":0.11,"y":0.16,"w":0.58,"h":0.53,"label":"Local SRAM devices"},"hbm":{"x":0.6,"y":0.49,"w":0.36,"h":0.26,"label":"HBM device group"},"edge":{"x":0.36,"y":0.6,"w":0.44,"h":0.24,"label":"Edge and shared LPDDR group including Jetson"},"wafer":{"x":0.69,"y":0.02,"w":0.19,"h":0.15,"label":"WSE-3 SRAM point"}},"steps":[{"title":"Inspect nearby small memories","description":"Solid stars represent local SRAM designs. They expose high aggregate bandwidth with less capacity than many HBM devices.","focus":["sram"]},{"title":"Inspect high-capacity devices","description":"The filled-circle HBM group lies farther right, trading a larger memory capacity for a different bandwidth scale and physical organization.","focus":["hbm"]},{"title":"Keep edge memory distinct","description":"Hollow-square edge and shared-LPDDR devices occupy another part of the capacity-bandwidth space. Marker shape distinguishes organization without implying a new resource category.","focus":["edge"]},{"title":"Read exceptional integration carefully","description":"WSE-3 aggregates SRAM across a wafer. Its distant point does not make its bandwidth directly comparable to one GPU’s HBM interface for arbitrary workloads.","focus":["wafer"]}],"artwork_reviewed":true,"art_sha1":"dec9e9a7a725c31ce29aef5e40e0f55e29591b82","art_kind":"png","art_width":3826,"art_height":2626},"vol2:fig-accelerator-spectrum":{"key":"vol2:fig-accelerator-spectrum","figure_id":"fig-accelerator-spectrum","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"The accelerator spectrum","status":"ready","treatment":"annotated","question":"What does specialization buy, and what does it give up?","scope":"Die shares are approximate illustrative allocations, not measured product floorplans or a ranking of overall usefulness.","regions":{"cpu":{"x":0.01,"y":0.03,"w":0.23,"h":0.75,"label":"CPU die"},"gpu":{"x":0.26,"y":0.03,"w":0.23,"h":0.75,"label":"GPU die"},"tpu":{"x":0.51,"y":0.03,"w":0.23,"h":0.75,"label":"TPU die"},"asic":{"x":0.76,"y":0.03,"w":0.23,"h":0.75,"label":"Custom ASIC die"}},"steps":[{"title":"Retain general control","description":"The CPU reserves most cells for control, caches, and other functions. These support diverse and irregular workloads.","focus":["cpu"]},{"title":"Expand parallel arithmetic","description":"The GPU allocates a larger share to arithmetic while retaining programmable execution. Its benefit depends on the workload using that parallelism.","focus":["gpu"]},{"title":"Match a regular dataflow","description":"The TPU panel increases arithmetic share with systolic execution. Nonmatrix work still needs other execution and control resources.","focus":["tpu"]},{"title":"Commit to the workload","description":"The custom ASIC hardwires more dataflow. Its large arithmetic share trades away flexibility when model operations change.","focus":["asic"]}],"artwork_reviewed":true,"art_sha1":"3716bca0a4dff2c6f415c624c9f68e671237aa33","art_kind":"svg","art_width":1200,"art_height":557,"art_structural_sha1":"f276eb79da5c18a2d4d6487f7bbb285617912ad8"},"vol2:fig-acme-job-size":{"key":"vol2:fig-acme-job-size","figure_id":"fig-acme-job-size","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Jobs versus GPU Time by Job Size","status":"ready","treatment":"annotated","question":"Why can a small number of large jobs dominate fleet scheduling?","scope":"These are empirical cumulative distributions for one cluster and observation period, not a universal workload mix.","regions":{"small":{"x":0.11,"y":0.04,"w":0.44,"h":0.8,"label":"Small-job cumulative region"},"large":{"x":0.77,"y":0.03,"w":0.21,"h":0.83,"label":"Jobs requesting at least 256 GPUs"},"annotation":{"x":0.77,"y":0.34,"w":0.2,"h":0.23,"label":"Large-job GPU-time annotation"}},"steps":[{"title":"Count jobs first","description":"The gray cumulative curve rises early: most jobs request few GPUs. Optimizing only job count emphasizes these small submissions.","focus":["small"]},{"title":"Count occupied GPU time","description":"The red curve rises mainly among large requests. Jobs requesting at least 256 GPUs are few but consume almost all GPU time in this trace.","focus":["large"]},{"title":"Separate scheduling objectives","description":"The annotation reports 4 percent of jobs and 96 percent of GPU time. A policy should distinguish request frequency, resource consumption, and fairness rather than treating these shares as interchangeable.","focus":["annotation"]}],"artwork_reviewed":true,"art_sha1":"b045579dbc61b8ee039aae1853b6be08b848a4cd","art_kind":"png","art_width":3789,"art_height":2050},"vol2:fig-adapter-lora-arch":{"key":"vol2:fig-adapter-lora-arch","figure_id":"fig-adapter-lora-arch","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"LoRA architecture","status":"ready","treatment":"annotated","question":"Which LoRA parameters train, and what can be merged for serving?","scope":"The diagram uses one square base matrix. Merging requires a supported numerical representation, and trainable-parameter savings are not total-model memory savings.","regions":{"input":{"x":0.01,"y":0.36,"w":0.08,"h":0.39,"label":"Input vector x"},"base":{"x":0.13,"y":0.05,"w":0.29,"h":0.36,"label":"Frozen W0 path"},"down":{"x":0.13,"y":0.65,"w":0.26,"h":0.14,"label":"Trainable down-projection A"},"up":{"x":0.39,"y":0.48,"w":0.14,"h":0.38,"label":"Trainable up-projection B"},"sum":{"x":0.62,"y":0.34,"w":0.14,"h":0.32,"label":"Sum into h"},"merged":{"x":0.8,"y":0.3,"w":0.19,"h":0.38,"label":"Merged W0 + BA for serving"}},"steps":[{"title":"Retain the base computation","description":"The input x follows the frozen W0 path. Frozen means no base parameter gradients or optimizer state, not that the base weights disappear.","focus":["input","base"]},{"title":"Learn a low-rank correction","description":"A maps the input down to rank r, then B projects back to dimension d. Only these two matrices are trainable in the drawn update.","focus":["down","up"]},{"title":"Add the two outputs","description":"The summation forms h = W0 x + BA x. The adapter changes the layer output while retaining the frozen base contribution.","focus":["sum"]},{"title":"Consider a merged representation","description":"For supported serving formats, BA can be folded into W0 to form one matrix. Compatibility, requantization, and any retained copies still affect deployment cost.","focus":["merged"]}],"artwork_reviewed":true,"art_sha1":"710bc445c9472ada1cfaf3d1433bb8ae0fbd52b2","art_kind":"svg","art_width":1200,"art_height":774,"art_structural_sha1":"8a66f6cab93081da5cb3ab41127e233ddb50b36d"},"vol2:fig-adversarial-arms-race":{"key":"vol2:fig-adversarial-arms-race","figure_id":"fig-adversarial-arms-race","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Adversarial arms race","status":"ready","treatment":"annotated","question":"Why must robustness evaluation be repeated after defenses change?","scope":"This is an evaluation workflow, not a claim that a particular defense defeats the illustrated adversary.","regions":{"threat":{"x":0.01,"y":0.02,"w":0.34,"h":0.24,"label":"Specify adversary"},"attacks":{"x":0.67,"y":0.02,"w":0.33,"h":0.24,"label":"Adaptive tests"},"harden":{"x":0.67,"y":0.7,"w":0.33,"h":0.24,"label":"System hardening"},"retest":{"x":0.01,"y":0.7,"w":0.34,"h":0.24,"label":"Retest changed system"},"model":{"x":0.39,"y":0.32,"w":0.24,"h":0.33,"label":"Defended model"}},"steps":[{"title":"Declare the threat model","description":"White-, gray-, and black-box access, the perturbation budget, and the attacker’s goal define what an evaluation actually tests.","focus":["threat"]},{"title":"Test the deployed defense","description":"Adaptive attacks target the current defense, including relevant physical and digital variants. Nonadaptive tests can overstate protection.","focus":["attacks","model"]},{"title":"Change the system","description":"Robust training, input filters, rate limits, or isolation alter the defended system and its attack surface.","focus":["harden"]},{"title":"Invalidate stale evidence","description":"New weights, data, or deployment require retesting. Earlier results do not automatically transfer to the changed system.","focus":["retest"]}],"artwork_reviewed":true,"art_sha1":"792562bb5925da4c37e870d0963514d67fb1cc3e","art_kind":"svg","art_width":1200,"art_height":583,"art_structural_sha1":"0b13282204bba6f950462bbbab560baddb769c3e"},"vol2:fig-adversarial-attack-injection":{"key":"vol2:fig-adversarial-attack-injection","figure_id":"fig-adversarial-attack-injection","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Data Poisoning and Interception Workflow","status":"ready","treatment":"annotated","question":"Where can an ingestion defense intercept poisoned ratings?","scope":"The filter flags suspected records and reduces risk; neither anomaly scores nor the retained rows prove an uncorrupted model.","regions":{"rows":{"x":0.01,"y":0.12,"w":0.35,"h":0.65,"label":"Contributed ratings and sybil rows"},"unfiltered":{"x":0.4,"y":0.01,"w":0.59,"h":0.26,"label":"Unfiltered compromised path"},"filter":{"x":0.41,"y":0.29,"w":0.28,"h":0.62,"label":"Interception and quarantine"},"candidate":{"x":0.75,"y":0.47,"w":0.24,"h":0.2,"label":"Candidate model validation"}},"steps":[{"title":"Identify the injected records","description":"The red sybil rows assign item 3 a low rating and item 4 a high rating. Their contribution attempts to change recommendation behavior.","focus":["rows"]},{"title":"Trace the unchecked path","description":"The upper dashed branch sends contributed records to training without filtering. Its model box illustrates the attacker’s desired suppression and promotion.","focus":["unfiltered"]},{"title":"Separate retained from suspect records","description":"The interception stage scores rows and diverts suspected records to quarantine. Legitimate rare data and stealthy poisons can still complicate that decision.","focus":["filter"]},{"title":"Validate before release","description":"The filtered path ends at a candidate model, explicitly awaiting validation. A successful ingestion step does not remove the need to evaluate downstream behavior.","focus":["candidate"]}],"artwork_reviewed":true,"art_sha1":"bef092a1c3049eafb91fdacb3f8279cf1f44b06c","art_kind":"svg","art_width":1200,"art_height":558,"art_structural_sha1":"f68d788e2ccfd2b05f62d738348f96ab7b0aacc1"},"vol2:fig-adversarial-boundary":{"key":"vol2:fig-adversarial-boundary","figure_id":"fig-adversarial-boundary","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Adversarial decision boundary","status":"ready","treatment":"annotated","question":"How can a small input change cross a classifier’s decision boundary?","scope":"The drawing is a two-dimensional conceptual projection; distance and displayed geometry are not physical image similarity or a measured robustness bound.","regions":{"clean":{"x":0.24,"y":0.51,"w":0.26,"h":0.34,"label":"Clean input and perturbation budget"},"boundary":{"x":0.01,"y":0.24,"w":0.98,"h":0.53,"label":"Decision boundary"},"changed":{"x":0.2,"y":0.2,"w":0.33,"h":0.32,"label":"Adversarial input across boundary"}},"steps":[{"title":"Locate the clean classification","description":"The clean point lies in Class A, labeled stop sign, and its dashed neighborhood marks the allowed perturbation radius.","focus":["clean"]},{"title":"Inspect the nearby boundary","description":"The blue curve separates the model’s class regions. A nearby boundary can permit prediction changes within the allowed neighborhood.","focus":["boundary"]},{"title":"Follow the changed input","description":"The red perturbation reaches the Class B side while the ground-truth interpretation remains the clean input’s stop sign. Crossing the classifier boundary does not itself justify a changed real-world label.","focus":["changed"]}],"artwork_reviewed":true,"art_sha1":"3e89bfbb991e6d0548dd47ee738e4a757296f3d0","art_kind":"svg","art_width":1200,"art_height":671,"art_structural_sha1":"7ba8a265c41ab97da25a260f2d84d6f0142c584b"},"vol2:fig-adversarial-googlenet":{"key":"vol2:fig-adversarial-googlenet","figure_id":"fig-adversarial-googlenet","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Imperceptible Misclassification in GoogLeNet","status":"ready","treatment":"annotated","question":"How can nearly identical-looking inputs yield different predictions?","scope":"The center perturbation is displayed for visibility; the figure is a cited attack example, not evidence that all small perturbations fool every model.","regions":{"clean":{"x":0.0,"y":0.0,"w":0.21,"h":1.0,"label":"Original panda"},"noise":{"x":0.43,"y":0.0,"w":0.21,"h":1.0,"label":"Displayed perturbation"},"attack":{"x":0.79,"y":0.0,"w":0.21,"h":1.0,"label":"Perturbed panda"}},"steps":[{"title":"Establish the original image","description":"The left panel supplies the clean panda input in the reported example. Visual recognizability and the model’s decision are different properties.","focus":["clean"]},{"title":"Inspect the added signal","description":"The center panel makes the perturbation visible. Its displayed appearance is not the scale at which a viewer sees it in the final image.","focus":["noise"]},{"title":"Compare the attacked input","description":"The right panel remains visually similar to the panda while the cited model’s prediction changes. Interpret the result under the study’s model and perturbation budget.","focus":["attack"]}],"artwork_reviewed":true,"art_sha1":"0dae38a1097a637ca305e577e228fe0c56316b4a","art_kind":"png","art_width":1631,"art_height":458},"vol2:fig-adversarial-stickers":{"key":"vol2:fig-adversarial-stickers","figure_id":"fig-adversarial-stickers","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Adversarial stickers","status":"ready","treatment":"annotated","question":"Why must a physical attack be evaluated through the sensing path?","scope":"The photographs show tested conditions, not a continuous simulated camera trajectory; the reported laboratory and field rates are study-specific.","regions":{"lab":{"x":0.0,"y":0.0,"w":0.79,"h":0.49,"label":"Near and angled sign views"},"distance":{"x":0.8,"y":0.0,"w":0.2,"h":0.49,"label":"Distant indoor view"},"field":{"x":0.0,"y":0.51,"w":1,"h":0.49,"label":"Outdoor and field views"}},"steps":[{"title":"Inspect the modified sign","description":"The close views show sticker placement on a sign still recognizable to a person. The classifier sees camera measurements rather than the physical object directly.","focus":["lab"]},{"title":"Change the acquisition condition","description":"The smaller distant view changes the sign’s apparent scale and surrounding scene. A digital or close laboratory test does not cover all such conditions.","focus":["distance"]},{"title":"Use field evidence for field claims","description":"The outdoor views expose additional sensing variation. The cited study’s lower moving-vehicle success rate illustrates why physical robustness needs actual sensing-path evaluation.","focus":["field"]}],"artwork_reviewed":true,"art_sha1":"4e29c24ec6895c32c072d2811abd2b6aee644acf","art_kind":"png","art_width":620,"art_height":320},"vol2:fig-ai-compute-growth":{"key":"vol2:fig-ai-compute-growth","figure_id":"fig-ai-compute-growth","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Training Compute of Notable Models","status":"ready","treatment":"annotated","question":"What does rising training compute imply—and not imply—about energy?","scope":"Points are estimated training operations for notable models; the fitted trend describes this series. Energy conversion requires realized efficiency at a declared boundary.","regions":{"early":{"x":0.07,"y":0.52,"w":0.4,"h":0.41,"label":"Earlier model operation estimates"},"recent":{"x":0.58,"y":0.02,"w":0.36,"h":0.4,"label":"Recent frontier estimates"},"fit":{"x":0.45,"y":0.33,"w":0.49,"h":0.32,"label":"Fitted five-month doubling line"},"cadence":{"x":0.5,"y":0.7,"w":0.44,"h":0.15,"label":"Two-year comparison cadence"}},"steps":[{"title":"Read the logarithmic quantity","description":"The vertical axis counts FLOPs of training work rather than joules. Early examples already span multiple orders of magnitude.","focus":["early"]},{"title":"Inspect estimated frontier growth","description":"Recent model points extend the series toward much larger operation counts. They remain estimates of selected notable runs, not every fleet workload.","focus":["recent"]},{"title":"Distinguish a fit from a mechanism","description":"The red least-squares fit corresponds to roughly five-month doubling for this data. It does not require future demand to continue at that rate.","focus":["fit"]},{"title":"Retain the energy conversion","description":"The dashed two-year line provides a transistor-cadence comparison. The widening work gap becomes an energy question only after accounting for achieved operations per joule.","focus":["cadence"]}],"artwork_reviewed":true,"art_sha1":"cb93d6a22289dae8948c057a19f77eadcb4b1a12","art_kind":"png","art_width":3832,"art_height":2280},"vol2:fig-ai-lca":{"key":"vol2:fig-ai-lca","figure_id":"fig-ai-lca","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"AI System Lifecycle","status":"ready","treatment":"annotated","question":"Which lifecycle decisions create burdens after hardware leaves the factory?","scope":"The diagram provides accounting categories and a recovery route, not numerical lifecycle shares.","regions":{"design":{"x":0.01,"y":0.26,"w":0.23,"h":0.7,"label":"Design and locked-in load"},"manufacture":{"x":0.28,"y":0.26,"w":0.22,"h":0.67,"label":"Manufacturing burdens"},"use":{"x":0.53,"y":0.26,"w":0.23,"h":0.67,"label":"Use-phase energy"},"retire":{"x":0.78,"y":0.26,"w":0.21,"h":0.67,"label":"Decommission and e-waste"},"recover":{"x":0.3,"y":0.02,"w":0.61,"h":0.23,"label":"Refurbish or recover loop"}},"steps":[{"title":"Set later demand at design time","description":"Architecture and hardware choices determine much of the load later stages must carry. The dashed baseline connects design to those downstream burdens.","focus":["design"]},{"title":"Count production and operation separately","description":"Manufacture adds embodied carbon, water, and chemicals. Use adds training and inference energy multiplied by the grid intensity.","focus":["manufacture","use"]},{"title":"Account for retirement","description":"Decommissioning creates e-waste unless hardware is refurbished or components are recovered. Disposal is part of the system boundary.","focus":["retire"]},{"title":"Inspect the recovery path","description":"The green loop returns useful hardware or material to manufacture. Recovery can change later resource demand but is not assumed to erase prior burdens.","focus":["recover"]}],"artwork_reviewed":true,"art_sha1":"b4bfc7ed428a42db1ac538c7a1ff7d52b9d08f72","art_kind":"svg","art_width":1200,"art_height":437,"art_structural_sha1":"447f3b81c4df156ece3d0e07511fe07c26462f36"},"vol2:fig-allreduce-crossover":{"key":"vol2:fig-allreduce-crossover","figure_id":"fig-allreduce-crossover","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Algorithm crossover in collective communication","status":"ready","treatment":"annotated","question":"Why does the preferred AllReduce algorithm change with message size?","scope":"These are alpha-beta cost-model curves for the caption’s fixed cluster and link assumptions; Tree means the simple full-message model. The shaded comparison covers Ring versus Tree only.","regions":{"small":{"x":0.11,"y":0.55,"w":0.3,"h":0.3,"label":"Small-message startup regime"},"cross":{"x":0.4,"y":0.64,"w":0.12,"h":0.19,"label":"Ring–Tree crossover"},"large":{"x":0.66,"y":0.06,"w":0.31,"h":0.58,"label":"Large-message byte regime"},"double":{"x":0.44,"y":0.77,"w":0.33,"h":0.12,"label":"Double binary tree curve"}},"steps":[{"title":"Count startup rounds for small messages","description":"The Ring curve has a higher small-message floor because its startup count grows with rank count. The simple Tree needs fewer rounds in this regime.","focus":["small"]},{"title":"Read the pairwise crossover","description":"The open marker identifies where Ring and Tree cost the same in this model. The green and violet backgrounds compare those two curves, not every algorithm.","focus":["cross"]},{"title":"Track the byte term as messages grow","description":"The simple Tree’s repeated full-message transfers raise its large-message cost. Ring becomes better than that Tree while retaining its bandwidth-efficient byte term.","focus":["large"]},{"title":"Inspect a different trade-off","description":"Double binary tree combines logarithmic depth with a near-optimal byte term, with the caption’s explicit overhead factors. Its curve is a separate comparison rather than the background region label.","focus":["double"]}],"artwork_reviewed":true,"art_sha1":"6a52e95586fb94ac4d39e1f13a2a85c25c921fb4","art_kind":"png","art_width":4018,"art_height":2518},"vol2:fig-alpha-beta-crossover":{"key":"vol2:fig-alpha-beta-crossover","figure_id":"fig-alpha-beta-crossover","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"The $\\MessageStartupLatency$-$\\LinkBandwidth$ crossover","status":"ready","treatment":"annotated","question":"Where does transfer startup stop dominating payload transmission?","scope":"Both curves are alpha + n/beta scenarios. Their parameter values describe the declared paths and do not establish universal protocol latency or bandwidth.","regions":{"plateaus":{"x":0.14,"y":0.48,"w":0.33,"h":0.36,"label":"Small-message startup plateaus"},"ibknee":{"x":0.47,"y":0.62,"w":0.22,"h":0.17,"label":"InfiniBand crossover near 75 KB"},"roceknee":{"x":0.36,"y":0.45,"w":0.22,"h":0.17,"label":"RoCE crossover near 62.5 KB"},"asymptotes":{"x":0.34,"y":0.72,"w":0.46,"h":0.2,"label":"InfiniBand startup and transmission asymptotes"},"large":{"x":0.66,"y":0.02,"w":0.33,"h":0.5,"label":"Large-message transmission-dominated slopes"}},"steps":[{"title":"Pay startup for a small message","description":"At the left, reducing payload size barely changes total time. Startup alpha dominates both nearly flat curves.","focus":["plateaus"]},{"title":"Balance the two terms","description":"A crossover occurs where alpha equals n/beta. The marked knees differ because each path has a different startup and bandwidth pair.","focus":["ibknee","roceknee"]},{"title":"Read the asymptotes","description":"The dotted InfiniBand startup floor and transmission line meet below its actual curve. At equality, total time includes both terms rather than equaling either alone.","focus":["asymptotes","ibknee"]},{"title":"Grow the payload","description":"Far to the right, n/beta dominates and total time rises nearly proportionally with message size. End-to-end measurements are still needed to locate a real path’s crossover.","focus":["large"]}],"artwork_reviewed":true,"art_sha1":"bb20e83ba3fad1830f26a6cf9d86c4299cf000da","art_kind":"png","art_width":3538,"art_height":2459},"vol2:fig-attack-surface":{"key":"vol2:fig-attack-surface","figure_id":"fig-attack-surface","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"ML system attack surface","status":"ready","treatment":"annotated","question":"Where can an attacker enter an ML system?","scope":"This taxonomy identifies entry points, not probabilities or proof that every entry compromises every layer.","regions":{"data":{"x":0.01,"y":0.17,"w":0.21,"h":0.6,"label":"Training data boundary"},"model":{"x":0.23,"y":0.17,"w":0.4,"h":0.6,"label":"Training and stored weights"},"api":{"x":0.65,"y":0.17,"w":0.19,"h":0.6,"label":"Serving interface"},"infra":{"x":0.02,"y":0.63,"w":0.83,"h":0.34,"label":"Infrastructure container and incoming threat paths"}},"steps":[{"title":"Inspect incoming records","description":"Poisoned records and backdoor triggers enter through training data. Data provenance and validation address this boundary.","focus":["data"]},{"title":"Inspect code and artifacts","description":"Imported packages affect training execution, while weight theft and unsafe loading affect model artifacts. These are different trust decisions.","focus":["model"]},{"title":"Inspect exposed queries","description":"The serving API permits extraction, adversarial inputs, and membership-inference attempts through interactions with the deployed system.","focus":["api"]},{"title":"Inspect the supporting platform","description":"Hosts, network, firmware, drivers, schedulers, and keys underpin the upper layers. A model-only defense leaves these dependencies outside its scope.","focus":["infra"]}],"artwork_reviewed":true,"art_sha1":"ea5320722ab152868efec53b3f1d4b875d7eea07","art_kind":"svg","art_width":1200,"art_height":777,"art_structural_sha1":"e2c5247392baddda8ac6a903250ab48a3567af0f"},"vol2:fig-autoencoder":{"key":"vol2:fig-autoencoder","figure_id":"fig-autoencoder","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Autoencoder Ingestion Gate","status":"ready","treatment":"annotated","question":"What does reconstruction error establish at an ingestion gate?","scope":"The gate is calibrated using held-out clean data; high error is an anomaly signal, not proof of poisoning.","regions":{"encode":{"x":0.01,"y":0.03,"w":0.31,"h":0.92,"label":"Encoder and input"},"latent":{"x":0.3,"y":0.35,"w":0.07,"h":0.6,"label":"Latent representation"},"decode":{"x":0.37,"y":0.03,"w":0.27,"h":0.92,"label":"Decoder and reconstruction"},"score":{"x":0.69,"y":0.19,"w":0.3,"h":0.75,"label":"Reconstruction error and calibrated threshold"}},"steps":[{"title":"Compress the candidate input","description":"The encoder maps the input x through progressively narrower layers into latent z. Training on trusted data defines which structures the model learns to reconstruct.","focus":["encode","latent"]},{"title":"Reconstruct the input","description":"The decoder expands z into reconstructed x. A well-formed output is not by itself evidence that the record is trusted.","focus":["decode"]},{"title":"Apply the calibrated error threshold","description":"The score compares x with its reconstruction. Values at or below tau are accepted; higher values are quarantined. Legitimate unfamiliar inputs can also have high error, so evaluate false rejections and missed poisons.","focus":["score"]}],"artwork_reviewed":true,"art_sha1":"3bd570cd2b57d9576ca10aec2e93ead0f021dcb9","art_kind":"svg","art_width":1200,"art_height":510,"art_structural_sha1":"038948ba81496ef171c0538a13e4398dacfe8550"},"vol2:fig-autonomous-miles-scaling":{"key":"vol2:fig-autonomous-miles-scaling","figure_id":"fig-autonomous-miles-scaling","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Measured Driverless Exposure and Crash Rates","status":"ready","treatment":"annotated","question":"Why must autonomous-driving exposure and crash rate be read separately?","scope":"These are published Waymo releases and the stated matched-road human benchmark, with uncertainty. They do not establish universal autonomous-driving safety.","regions":{"region-1":{"x":0.16,"y":0.03,"w":0.83,"h":0.47,"label":"Cumulative exposure panel"},"region-2":{"x":0.01,"y":0.56,"w":0.98,"h":0.22,"label":"Common crash outcomes"},"region-3":{"x":0.01,"y":0.79,"w":0.98,"h":0.2,"label":"Rare severe outcomes"}},"steps":[{"title":"Read the growing denominator","description":"Panel (a) shows cumulative rider-only miles increasing across releases. More exposure can produce more incidents even when a per-mile rate is low.","focus":["region-1"]},{"title":"Compare rates under the benchmark definition","description":"The police-reported, injury, and airbag rows compare red Waymo points with gray human-benchmark points. The horizontal axis is logarithmic, so spacing represents ratios rather than equal rate differences.","focus":["region-2"]},{"title":"Keep rare-event uncertainty visible","description":"Serious-injury and fatal rows have wide red intervals relative to their point estimates. These intervals and benchmark definitions constrain interpretation, especially for rare outcomes.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"70d7edcac51952361f7687b346cc1bd3e1d7f5be","art_kind":"png","art_width":3957,"art_height":3545},"vol2:fig-bandwidth-cliff-gantt":{"key":"vol2:fig-bandwidth-cliff-gantt","figure_id":"fig-bandwidth-cliff-gantt","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"The bandwidth cliff in a training step","status":"ready","treatment":"annotated","question":"Where does exposed communication lengthen a training step?","scope":"The 1 ms and 30 ms AllReduce durations are illustrative assumptions; the percentages are compute shares of these schedules, not measured GPU utilization.","regions":{"intra":{"x":0.18,"y":0.04,"w":0.56,"h":0.23,"label":"Intra-node compute phases"},"short":{"x":0.69,"y":0.04,"w":0.27,"h":0.23,"label":"Assumed 1 ms AllReduce"},"inter":{"x":0.18,"y":0.35,"w":0.65,"h":0.24,"label":"Inter-node schedule"},"idle":{"x":0.69,"y":0.35,"w":0.27,"h":0.37,"label":"Assumed 30 ms exposed AllReduce"},"axis":{"x":0.17,"y":0.78,"w":0.79,"h":0.16,"label":"Common millisecond axis"}},"steps":[{"title":"Hold computation fixed","description":"Both rows contain 100 ms forward and 100 ms backward phases. The shared axis makes their equal compute budgets visible.","focus":["intra","inter","axis"]},{"title":"Add a short synchronization","description":"The intra-node row adds the assumed 1 ms AllReduce after backward computation. Compute occupies 99.5 percent of this illustrative step.","focus":["short"]},{"title":"Expose the longer transfer","description":"The inter-node row waits another 30 ms before the next dependent work can begin. With no overlap in the drawing, compute occupies 87 percent of the step.","focus":["idle"]},{"title":"Interpret the gap","description":"The wider red interval explains the lower compute share. It is a schedule comparison, not a transfer-time prediction from the network bandwidth ratio.","focus":["short","idle"]}],"artwork_reviewed":true,"art_sha1":"379349c90dd8e79eae757e09ff700684aebd3df7","art_kind":"svg","art_width":1200,"art_height":407,"art_structural_sha1":"9bd10ffb82395644bb2752069338fc44c8d68d0f"},"vol2:fig-bandwidth-divergence":{"key":"vol2:fig-bandwidth-divergence","figure_id":"fig-bandwidth-divergence","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Interconnect bandwidth conventions","status":"ready","treatment":"annotated","question":"What comparison does the advertised intra-node/inter-node capacity gap support?","scope":"Rates are advertised one-way capacities at unequal endpoint boundaries, not achieved collective bandwidth; points use first commercial product years.","regions":{"intra":{"x":0.25,"y":0.1,"w":0.66,"h":0.48,"label":"GPU aggregate intra-node capacity"},"inter":{"x":0.16,"y":0.56,"w":0.74,"h":0.28,"label":"One-port InfiniBand capacity"},"gap":{"x":0.83,"y":0.14,"w":0.15,"h":0.39,"label":"Ninefold latest-generation capacity gap"}},"steps":[{"title":"Fix the capacity convention","description":"The orange series counts a PCIe x16 interface initially and then the sum of a GPU’s NVLink links, per direction. Bidirectional datasheet totals cannot be inserted unchanged.","focus":["intra"]},{"title":"Read the narrower endpoint budget","description":"The violet series counts one InfiniBand port per direction. It is a different endpoint boundary from all of a GPU’s local links.","focus":["inter"]},{"title":"Use the gap to motivate hierarchy","description":"The marked ninefold capacity difference supports separating fast local communication from external traffic. It does not predict achieved AllReduce rate without startup, port, routing, and contention costs.","focus":["gap"]}],"artwork_reviewed":true,"art_sha1":"a76064a78bc641c8d275b59b0d5b04356414cf54","art_kind":"png","art_width":3646,"art_height":2460},"vol2:fig-bandwidth-hierarchy":{"key":"vol2:fig-bandwidth-hierarchy","figure_id":"fig-bandwidth-hierarchy","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"The bandwidth hierarchy","status":"ready","treatment":"annotated","question":"Which hierarchy boundary creates the bandwidth cliff?","scope":"These are per-direction budgets across four specified generations. Comparing one external port with aggregate GPU NVLink bandwidth does not predict achieved collective bandwidth.","regions":{"legend":{"x":0.12,"y":0.02,"w":0.69,"h":0.17,"label":"Four hierarchy levels"},"v100":{"x":0.13,"y":0.35,"w":0.18,"h":0.6,"label":"V100 bandwidth group"},"a100":{"x":0.35,"y":0.25,"w":0.18,"h":0.7,"label":"A100 bandwidth group"},"h100":{"x":0.56,"y":0.2,"w":0.18,"h":0.75,"label":"H100 bandwidth group"},"b200":{"x":0.77,"y":0.11,"w":0.18,"h":0.84,"label":"B200 bandwidth group"}},"steps":[{"title":"Separate the storage and links","description":"The legend distinguishes on-package HBM, intra-node NVLink, one InfiniBand port, and the PCIe host bus. These resources serve different parts of a data path.","focus":["legend"]},{"title":"Read the H100 cliff","description":"The H100 annotation compares NVLink with one NDR InfiniBand port, showing about a ninefold per-direction budget gap. It is not a ratio of measured training times.","focus":["h100"]},{"title":"Compare generations consistently","description":"V100 and A100 show roughly twelvefold gaps in the same comparison, while B200 shows eighteenfold. Improvements within the node do not automatically remove its external-port bottleneck.","focus":["v100","a100","b200"]},{"title":"Place frequent exchanges carefully","description":"A partition with frequent per-layer exchanges benefits from remaining inside the higher-bandwidth domain when feasible. Workload dependencies and provisioning still decide the actual cost.","focus":["h100"]}],"artwork_reviewed":true,"art_sha1":"a21099b9fdba0e8ddb5f78ffc8cb1e06d1d31f5e","art_kind":"png","art_width":3540,"art_height":2279},"vol2:fig-batch-tradeoff-curves":{"key":"vol2:fig-batch-tradeoff-curves","figure_id":"fig-batch-tradeoff-curves","source":"books/vol2/backmatter/appendix_inference.qmd","title":"Batch Size Trade-Off Curves","status":"ready","treatment":"annotated","question":"Why can larger batches improve throughput while taking longer to finish?","scope":"The dimensionless toy model is t(B) = 1 + 0.15(B − 1), with throughput B/t(B). It excludes queuing and batch formation, and asserts no optimal batch or memory limit.","regions":{"baseline":{"x":0.14,"y":0.78,"w":0.08,"h":0.14,"label":"Batch-one normalized reference"},"throughput":{"x":0.23,"y":0.63,"w":0.73,"h":0.24,"label":"Normalized throughput curve"},"service":{"x":0.59,"y":0.06,"w":0.37,"h":0.61,"label":"Growing batch-service-time curve"},"legend":{"x":0.11,"y":0.02,"w":0.49,"h":0.15,"label":"Two separately normalized quantities"},"axis":{"x":0.13,"y":0.9,"w":0.84,"h":0.1,"label":"Log-spaced batch sizes"}},"steps":[{"title":"Establish the reference","description":"At batch one, both normalized quantities equal one. The curves compare relative throughput and relative batch completion time rather than raw units.","focus":["baseline","legend"]},{"title":"Amortize fixed work","description":"As batch size grows, B/t(B) rises with diminishing returns. Multiple examples share the fixed component of the assumed service cost.","focus":["throughput"]},{"title":"Pay longer service time","description":"The red t(B) curve continues increasing while throughput begins to level. Higher throughput can therefore coexist with a longer wait for a complete batch execution.","focus":["service"]},{"title":"Do not select an optimum from the crossing","description":"The two normalized curves use different quantities. Their crossing is not an optimal batch size, a latency SLO, or a memory-capacity boundary.","focus":["throughput","service","axis"]}],"artwork_reviewed":true,"art_sha1":"3d0c5f2d50b630f821c6787cb28a7d84695b8861","art_kind":"png","art_width":3659,"art_height":2100},"vol2:fig-batching-strategies":{"key":"vol2:fig-batching-strategies","figure_id":"fig-batching-strategies","source":"books/vol2/10_inference/10_inference.qmd","title":"Batching strategies compared","status":"ready","treatment":"annotated","question":"How does batch formation trade waiting against shared GPU passes?","scope":"This is an illustrative arrival timeline. Formation delay is separate from waiting for an occupied worker.","regions":{"region-1":{"x":0.02,"y":0.03,"w":0.93,"h":0.27,"label":"No batching timeline"},"region-2":{"x":0.02,"y":0.32,"w":0.93,"h":0.28,"label":"Static batching timeline"},"region-3":{"x":0.02,"y":0.63,"w":0.93,"h":0.28,"label":"Dynamic batching timeline"}},"steps":[{"title":"Run four individual passes","description":"Each request gets a separate GPU forward pass. Later requests wait while earlier passes occupy the worker.","focus":["region-1"]},{"title":"Wait for the full batch","description":"The batch-full line dispatches all four requests together. Early arrivals wait longest, and shorter requests incur hatched padding to match the longest request.","focus":["region-2"]},{"title":"Close a short formation window","description":"The two window-closing lines dispatch two requests at a time. In this example, intentional formation delay is bounded while each pass serves more than one request.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"5ad2d0afd3703bc96ec2aaa035d02bc0912be687","art_kind":"svg","art_width":1200,"art_height":1070,"art_structural_sha1":"b9ac197f7a63e60678f56882ae6d63507b0e5b6e"},"vol2:fig-bathtub-curve":{"key":"vol2:fig-bathtub-curve","figure_id":"fig-bathtub-curve","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"The bathtub curve","status":"ready","treatment":"annotated","question":"When is a constant hardware hazard rate a reasonable approximation?","scope":"This is an illustrative component-age hazard curve, not a measured cohort or a universal fleet trajectory; mixed-age fleets need not follow the same shape.","regions":{"early":{"x":0.05,"y":0.02,"w":0.28,"h":0.86,"label":"Infant mortality"},"useful":{"x":0.33,"y":0.02,"w":0.38,"h":0.86,"label":"Useful-life region"},"wear":{"x":0.71,"y":0.02,"w":0.28,"h":0.86,"label":"Wear-out region"}},"steps":[{"title":"Screen early defects","description":"The early hazard declines as manufacturing-related failures are screened. Burn-in aims to remove these components before production.","focus":["early"]},{"title":"Declare the constant-rate window","description":"The central useful-life region is approximately flat. That window motivates a constant-rate planning model; it does not describe every age.","focus":["useful"]},{"title":"Revisit aging assumptions","description":"The wear-out region rises as age-related mechanisms matter. Replacement and cohort age distributions determine how much of this pattern appears in a fleet.","focus":["wear"]}],"artwork_reviewed":true,"art_sha1":"c0f07767103d5eba819e627fa332ed07fc3630bb","art_kind":"png","art_width":3660,"art_height":2159},"vol2:fig-bias-amplification":{"key":"vol2:fig-bias-amplification","figure_id":"fig-bias-amplification","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Bias Amplification Feedback Loop","status":"ready","treatment":"annotated","question":"Where can interventions interrupt a possible bias-reinforcement loop?","scope":"The edges describe a possible reinforcing mechanism; they do not guarantee that each retraining round increases disparity.","regions":{"region-1":{"x":0.38,"y":0.04,"w":0.46,"h":0.52,"label":"Data-to-model edge"},"region-2":{"x":0.38,"y":0.45,"w":0.6,"h":0.51,"label":"Model-to-outcome edge"},"region-3":{"x":0.03,"y":0.12,"w":0.44,"h":0.76,"label":"New-data feedback and preprocessing"}},"steps":[{"title":"Inspect training and in-processing","description":"Biased training data trains the model. The in-processing box points to the training arc, locating fairness constraints during model fitting.","focus":["region-1"]},{"title":"Inspect decisions and post-processing","description":"Biased model predictions can produce disparate outcomes. Post-processing threshold calibration intervenes on this decision-to-outcome arc rather than rewriting past training data.","focus":["region-2"]},{"title":"Audit what returns as training data","description":"Outcomes create new data that can reinforce the original bias. Pre-processing audit and reweighting cut the feeds-into arc before the next training dataset is formed.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"137c9a33f4d50b7d11aab8d9d810c3c03a4e4315","art_kind":"svg","art_width":1200,"art_height":700,"art_structural_sha1":"f5200a4c94bc3dcfe442f1e63d9818f8003d1ad2"},"vol2:fig-bulkhead-patterns":{"key":"vol2:fig-bulkhead-patterns","figure_id":"fig-bulkhead-patterns","source":"books/vol2/10_inference/10_inference.qmd","title":"Bulkhead isolation patterns","status":"ready","treatment":"annotated","question":"What does a bulkhead isolate, and which shared resources can still carry interference?","scope":"The engine crash is illustrative. Isolation depends on actual resource boundaries, not service-tier labels alone.","regions":{"region-1":{"x":0.03,"y":0.07,"w":0.56,"h":0.62,"label":"Standard tier and failed engine"},"region-2":{"x":0.6,"y":0.07,"w":0.37,"h":0.62,"label":"Gold tier protected workers"},"region-3":{"x":0.03,"y":0.69,"w":0.94,"h":0.24,"label":"Shared substrate and interference path"}},"steps":[{"title":"Contain an engine failure","description":"The Standard tier contains multiple engines, with one marked crashed. Separate engine resources can keep the failure from directly taking down every worker.","focus":["region-1"]},{"title":"Preserve another tier’s service","description":"A bulkhead separates Gold-tier load balancing and engines from the failed Standard-tier engine. The Gold tier is labeled keeps serving.","focus":["region-2"]},{"title":"Inspect what remains shared","description":"Network, storage, and control plane remain below both tiers. The dashed interference path warns that a logical bulkhead is incomplete if shared infrastructure remains a failure path.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"48535326443d9711fe2319859b256abbc98c3aa0","art_kind":"svg","art_width":1200,"art_height":643,"art_structural_sha1":"f931cdf6968194b8b0207193005723397c646161"},"vol2:fig-c3-taxonomy":{"key":"vol2:fig-c3-taxonomy","figure_id":"fig-c3-taxonomy","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The C$^3$ Intersection Landscape","status":"ready","treatment":"annotated","question":"How do the three C³ dimensions interact in fleet engineering?","scope":"The circles organize engineering responsibilities; their area is not a measured fraction of time or cost.","regions":{"region-1":{"x":0.25,"y":0.045,"w":0.61,"h":0.36,"label":"Compute substrate"},"region-2":{"x":0.29,"y":0.35,"w":0.23,"h":0.21,"label":"Communication and compute overlap"},"region-3":{"x":0.51,"y":0.35,"w":0.29,"h":0.46,"label":"Coordination interactions"},"region-4":{"x":0.44,"y":0.52,"w":0.25,"h":0.16,"label":"Central engineering intersection"}},"steps":[{"title":"Locate local computation","description":"Compute C1 names the node substrate and the Tcompute/N term. Dividing work across nodes addresses this term but does not account for network or coordination time.","focus":["region-1"]},{"title":"Hide network work where possible","description":"The Compute–Communication overlap names hiding network latency. Only communication that can actually overlap useful computation can be hidden.","focus":["region-2"]},{"title":"Coordinate useful progress","description":"Compute–Coordination concerns fleet goodput, while Communication–Coordination concerns collective synchronization. Failures and synchronization can reduce useful work even when nodes and links are fast.","focus":["region-3"]},{"title":"Combine all three dimensions","description":"Fleet ML systems engineering sits in the shared center. A change to one substrate must be evaluated against its effects on the other two.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"85a1010ab37978faddc22a72bdbe84c8e00d222e","art_kind":"svg","art_width":1200,"art_height":1172,"art_structural_sha1":"85a1010ab37978faddc22a72bdbe84c8e00d222e"},"vol2:fig-carbon-aware-scheduling":{"key":"vol2:fig-carbon-aware-scheduling","figure_id":"fig-carbon-aware-scheduling","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"A Feasible Carbon-Aware Schedule","status":"ready","treatment":"annotated","question":"When does delaying a job make a carbon-aware schedule feasible?","scope":"The grid trace is schematic. Net avoided emissions must exceed checkpoint, waiting, and migration costs; this is not automatically an energy reduction.","regions":{"peak":{"x":0.17,"y":0.06,"w":0.23,"h":0.43,"label":"High-carbon interval"},"run":{"x":0.45,"y":0.51,"w":0.28,"h":0.12,"label":"Run in low-carbon window"},"headroom":{"x":0.37,"y":0.64,"w":0.57,"h":0.1,"label":"Available capacity"},"deadline":{"x":0.73,"y":0.03,"w":0.12,"h":0.74,"label":"Slack before deadline"},"equation":{"x":0.2,"y":0.86,"w":0.75,"h":0.11,"label":"Net carbon with shift costs"}},"steps":[{"title":"Wait through the unfavorable window","description":"The dashed job arrow waits in checkpointed state during the high-carbon peak. Waiting itself may retain standby and checkpoint costs.","focus":["peak"]},{"title":"Require a usable window","description":"The green run block lies under a lower-carbon signal only after the hatched busy interval ends. A cleaner grid interval without cluster headroom is not executable.","focus":["run","headroom"]},{"title":"Finish before the contract expires","description":"The slack block precedes the red deadline. A lower-carbon plan that misses the deadline is outside the feasible schedule shown.","focus":["deadline"]},{"title":"Charge the shift for its overhead","description":"The equation adds checkpoint, idle-wait, and migration carbon to the integrated execution term. Delaying pays only if the avoided emissions exceed those additions.","focus":["equation"]}],"artwork_reviewed":true,"art_sha1":"64bae2750ccc84ee9ec88b0940b0c5586a7f2702","art_kind":"svg","art_width":1200,"art_height":609,"art_structural_sha1":"7b5346595af30aa93e65154a019a64a0e1f2ead4"},"vol2:fig-carbon-intensity":{"key":"vol2:fig-carbon-intensity","figure_id":"fig-carbon-intensity","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Comparing Regional Electricity Emissions","status":"ready","treatment":"annotated","question":"How much can the grid factor change carbon at fixed facility energy?","scope":"The plot applies rounded annual-average regional factors to one 10,000 MWh account. It is not the same job measured at each site and gives neither hourly nor marginal emissions.","regions":{"high":{"x":0.1,"y":0.12,"w":0.88,"h":0.24,"label":"Higher regional factors"},"average":{"x":0.02,"y":0.39,"w":0.96,"h":0.22,"label":"Regional averages and intermediate factors"},"low":{"x":0.1,"y":0.64,"w":0.69,"h":0.24,"label":"Lower regional factors"},"range":{"x":0.21,"y":0.01,"w":0.66,"h":0.12,"label":"Nearly two orders of magnitude"}},"steps":[{"title":"Hold electricity constant","description":"Every marker converts the same 10,000 MWh facility-energy workload. Carbon differences therefore come from the assumed regional factor in this comparison.","focus":["high"]},{"title":"Distinguish aggregate regions","description":"Open markers denote US and EU regional averages. Their accounting scope differs from individual-country and utility factors.","focus":["average"]},{"title":"Inspect the low-factor cases","description":"France, Quebec, and Norway lie well to the left on the logarithmic carbon axis. The Norway label gives 100 t versus Poland’s 8,200 t for this fixed account.","focus":["low","high"]},{"title":"Avoid a scheduling inference","description":"The range is an annual-average comparison, not an hourly clean-window forecast. Placement must also count migration energy and any facility-overhead change.","focus":["range"]}],"artwork_reviewed":true,"art_sha1":"6ab3ad44ee9ef6abf728c813dcddc6b615bd9fb3","art_kind":"png","art_width":3636,"art_height":2334},"vol2:fig-carbon-lifecycle":{"key":"vol2:fig-carbon-lifecycle","figure_id":"fig-carbon-lifecycle","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"The Carbon Lifecycle of an ML System","status":"ready","treatment":"annotated","question":"How do manufacturing and repeated inference enter one lifecycle carbon account?","scope":"Block widths encode timing, not emission magnitude. Workload volume, hardware life, PUE, and grid intensity determine the terms.","regions":{"manufacture":{"x":0.02,"y":0.09,"w":0.43,"h":0.22,"label":"Manufacturing before service"},"training":{"x":0.02,"y":0.33,"w":0.61,"h":0.24,"label":"One training interval"},"inference":{"x":0.02,"y":0.59,"w":0.91,"h":0.24,"label":"Repeated inference during service"},"sum":{"x":0.19,"y":0.9,"w":0.74,"h":0.08,"label":"Lifecycle carbon sum"}},"steps":[{"title":"Start with embodied carbon","description":"Manufacturing adds carbon before the hardware enters service. This contribution exists even before the first training or inference job.","focus":["manufacture"]},{"title":"Add the training account","description":"Training contributes an operational term through its electricity, facility overhead, and grid intensity. The displayed interval occurs once in this schematic.","focus":["training"]},{"title":"Accumulate serving work","description":"Inference recurs per request over service life. A short training interval does not establish which term will dominate the lifetime total.","focus":["inference"]},{"title":"Sum compatible accounts","description":"The equation combines embodied, training, and inference carbon. Timing widths cannot be read as those terms’ relative sizes.","focus":["sum"]}],"artwork_reviewed":true,"art_sha1":"2d834702d95e1528145db9870102745f47d32aae","art_kind":"svg","art_width":1200,"art_height":695,"art_structural_sha1":"2cde6f1779992fbb585c8b8cd82b2918f58f3735"},"vol2:fig-centralized-vs-decentralized":{"key":"vol2:fig-centralized-vs-decentralized","figure_id":"fig-centralized-vs-decentralized","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Local-only, centralized-cloud, and federated learning","status":"ready","treatment":"annotated","question":"What crosses the device boundary in each learning architecture?","scope":"The three panels are alternatives, not stages in a required evolution. Keeping raw data local does not by itself protect model updates or metadata.","regions":{"local":{"x":0.03,"y":0.03,"w":0.27,"h":0.9,"label":"A: local-only learning"},"central":{"x":0.35,"y":0.03,"w":0.31,"h":0.9,"label":"B: centralized-cloud learning"},"federated":{"x":0.69,"y":0.03,"w":0.3,"h":0.9,"label":"C: federated learning"},"boundary":{"x":0.02,"y":0.5,"w":0.97,"h":0.06,"label":"Dashed device boundary"}},"steps":[{"title":"Train without exchange","description":"Panel A keeps training on the device and sends nothing across the dashed boundary. There is no server contribution in this local-only architecture.","focus":["local","boundary"]},{"title":"Upload raw examples","description":"Panel B moves device data to the cloud trainer. The server sees the raw examples that drive centralized training.","focus":["central"]},{"title":"Exchange model state","description":"Panel C downloads the global model theta and uploads changes delta theta. Raw data stays on the device while model state crosses the boundary.","focus":["federated"]},{"title":"Separate locality from privacy","description":"The federated path changes what leaves the device; it does not establish that the update reveals nothing about local data. Updates and metadata still require explicit privacy controls.","focus":["federated","boundary"]}],"artwork_reviewed":true,"art_sha1":"03296ea76f665fd1424be9fb1bc06db12e74a7fd","art_kind":"svg","art_width":1200,"art_height":538,"art_structural_sha1":"c815e0a5ed11ad1af9bf0a435037c4395449f9b5"},"vol2:fig-checkpoint-recovery-timeline":{"key":"vol2:fig-checkpoint-recovery-timeline","figure_id":"fig-checkpoint-recovery-timeline","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Checkpoint-recovery timeline","status":"ready","treatment":"annotated","question":"Which parts of a failed run must be paid for again?","scope":"The progress trace is schematic; save, rework, and recovery are distinct costs, not measured durations here.","regions":{"save":{"x":0.19,"y":0.01,"w":0.36,"h":0.25,"label":"Save intervals"},"lost":{"x":0.53,"y":0.01,"w":0.27,"h":0.28,"label":"Lost work and recovery"},"durable":{"x":0.2,"y":0.55,"w":0.35,"h":0.28,"label":"Durable checkpoint progress"},"rollback":{"x":0.51,"y":0.49,"w":0.29,"h":0.31,"label":"Rollback to durable progress"}},"steps":[{"title":"Make progress durable","description":"Green save segments persist a checkpoint. Work completed after that checkpoint is not yet protected by the next durable state.","focus":["save","durable"]},{"title":"Lose unsaved work at failure","description":"The red extension in the progress trace rises past the last checkpoint, then drops back at failure. That interval is rework, not checkpoint-write overhead.","focus":["rollback"]},{"title":"Budget restart separately","description":"The recovery segment restores execution before useful computation resumes. A checkpoint policy must account for writes, lost work, and recovery time.","focus":["lost"]}],"artwork_reviewed":true,"art_sha1":"b3d9a2abaa199f391ed0a5cdd349684c70dbda39","art_kind":"svg","art_width":1200,"art_height":459,"art_structural_sha1":"390379c26168caaeebbf01d437b146440322036d"},"vol2:fig-checkpoint-tradeoff":{"key":"vol2:fig-checkpoint-tradeoff","figure_id":"fig-checkpoint-tradeoff","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"The checkpoint trade-off","status":"ready","treatment":"annotated","question":"Why is neither constant saving nor very infrequent saving optimal?","scope":"The curves use the chapter’s fixed first-order checkpoint model; they separate write overhead from expected rework and do not include every operational recovery cost.","regions":{"writes":{"x":0.1,"y":0.06,"w":0.18,"h":0.77,"label":"Short intervals and write overhead"},"minimum":{"x":0.22,"y":0.39,"w":0.19,"h":0.44,"label":"Young–Daly minimum and equal terms"},"rework":{"x":0.54,"y":0.22,"w":0.44,"h":0.61,"label":"Long intervals and expected rework"}},"steps":[{"title":"Avoid spending the run on writes","description":"The dashed blue save term rises sharply at short intervals because each write is repeated more often. Frequent checkpoints protect progress but consume productive time.","focus":["writes"]},{"title":"Balance the two modeled costs","description":"At the marked optimum near fourteen minutes, the blue and red terms are equal and their black sum is minimized. The shallow floor means small interval errors have a modest cost.","focus":["minimum"]},{"title":"Account for work lost after a failure","description":"The dashed red expected-rework term grows as checkpoints spread apart. A long interval saves write overhead while exposing more unsaved computation.","focus":["rework"]}],"artwork_reviewed":true,"art_sha1":"7a4a56b637b023787406c4079f5090c0f4d61cd6","art_kind":"png","art_width":3659,"art_height":2040},"vol2:fig-chip-vs-cluster-power":{"key":"vol2:fig-chip-vs-cluster-power","figure_id":"fig-chip-vs-cluster-power","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Package Power versus System Power","status":"ready","treatment":"annotated","question":"Why must facility power be distinguished from accelerator package power?","scope":"Published device ratings use vendor-specific conventions; facility observations describe whole systems, and neither panel measures a common workload.","regions":{"package":{"x":0.09,"y":0.06,"w":0.84,"h":0.45,"label":"One-accelerator package ratings"},"facility":{"x":0.09,"y":0.58,"w":0.84,"h":0.38,"label":"Whole-system facility power"},"record":{"x":0.57,"y":0.59,"w":0.36,"h":0.19,"label":"Recent system-power records"}},"steps":[{"title":"Read device design envelopes","description":"The upper panel plots published ratings for individual accelerator packages. Different rating conventions constrain direct product comparisons.","focus":["package"]},{"title":"Change the physical scale","description":"The lower panel measures facility power in megawatts on a log axis. Networking, device count, and supporting infrastructure distinguish a system from one package.","focus":["facility"]},{"title":"Interpret the record line","description":"The red line tracks the largest operating system at each date. Its recent rise reflects system scale, not simply an identical multiplier in individual device power.","focus":["record"]}],"artwork_reviewed":true,"art_sha1":"2efd46de976bf1a037910e637fa06dd05714a1c0","art_kind":"png","art_width":3462,"art_height":3544},"vol2:fig-circuit-breaker":{"key":"vol2:fig-circuit-breaker","figure_id":"fig-circuit-breaker","source":"books/vol2/10_inference/10_inference.qmd","title":"Circuit breaker states","status":"ready","treatment":"annotated","question":"How does a circuit breaker protect a failing dependency and decide when to retry?","scope":"Transitions describe policy states, not fixed timing or a universal error threshold.","regions":{"region-1":{"x":0.04,"y":0.04,"w":0.29,"h":0.32,"label":"Closed state"},"region-2":{"x":0.66,"y":0.04,"w":0.29,"h":0.32,"label":"Open state"},"region-3":{"x":0.31,"y":0.59,"w":0.37,"h":0.34,"label":"Half-open state and return paths"}},"steps":[{"title":"Allow normal traffic","description":"Closed forwards ordinary requests to the dependency. Errors, timeouts, or latency that exceed the configured threshold move the breaker to Open.","focus":["region-1"]},{"title":"Fail fast while the dependency recovers","description":"Open rejects requests rather than continuing to load the dependency. A timeout must elapse before the breaker permits limited probes.","focus":["region-2"]},{"title":"Probe with bounded traffic","description":"Half-open limits probes. A successful probe returns to Closed; a failed probe sends the breaker back to Open instead of immediately restoring full traffic.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"c615102971dff07bd5e40a1b35effb94ecd35686","art_kind":"svg","art_width":1200,"art_height":777,"art_structural_sha1":"ceaeb8206ae21a792113c6166eb54af5773e9869"},"vol2:fig-clean-vs-robust-classification":{"key":"vol2:fig-clean-vs-robust-classification","figure_id":"fig-clean-vs-robust-classification","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Clean Predictions and Perturbation Robustness","status":"ready","treatment":"annotated","question":"Why does correct clean classification fail to establish robustness?","scope":"The circles are the declared perturbation sets in an illustrative two-dimensional input space; the statement applies to those sets, not all possible deployment shifts.","regions":{"a":{"x":0.01,"y":0.01,"w":0.48,"h":0.8,"label":"Boundary A and allowed sets"},"b":{"x":0.51,"y":0.01,"w":0.48,"h":0.8,"label":"Boundary B and class flip"},"key":{"x":0.01,"y":0.84,"w":0.98,"h":0.13,"label":"Perturbation and boundary legend"}},"steps":[{"title":"Fix the evaluation neighborhood","description":"Both panels use the same clean inputs and perturbation radius. The dashed circles define which changes the robustness claim covers.","focus":["key"]},{"title":"Keep all allowed changes on one side","description":"Boundary A separates both complete neighborhoods. A displacement inside these sets cannot change the illustrated prediction.","focus":["a"]},{"title":"Expose a fragile margin","description":"Boundary B still classifies the clean points correctly but cuts the positive input’s allowed set. The depicted displacement crosses it, so clean accuracy alone misses the failure.","focus":["b"]}],"artwork_reviewed":true,"art_sha1":"0a19129c56b20b3e9a7977b3a7e8c876efefa0d6","art_kind":"svg","art_width":1200,"art_height":611,"art_structural_sha1":"218aae1040a3acd7976351b0cd1e10e3c4b53fec"},"vol2:fig-cluster-scaling-trend":{"key":"vol2:fig-cluster-scaling-trend","figure_id":"fig-cluster-scaling-trend","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"The rise of fleet-scale training","status":"ready","treatment":"annotated","question":"How does growing job size turn reliability into an execution budget?","scope":"Accelerator counts are published landmarks except the hollow estimate; the opposite MTBF axis applies one constant per-device planning rate, not measured incident histories.","regions":{"early":{"x":0.13,"y":0.67,"w":0.2,"h":0.23,"label":"AlexNet training size"},"estimate":{"x":0.35,"y":0.11,"w":0.29,"h":0.18,"label":"Estimated GPT-3-era machine"},"fleet":{"x":0.66,"y":0.06,"w":0.23,"h":0.29,"label":"Later large training fleets"},"mtbf":{"x":0.87,"y":0.01,"w":0.13,"h":0.9,"label":"Opposing system-MTBF axis"}},"steps":[{"title":"Establish the small-job scale","description":"The early AlexNet point uses only two accelerators. Under the planning model, a job requiring fewer independent components has a longer system failure interval.","focus":["early"]},{"title":"Distinguish an estimate from a measurement","description":"The hollow GPT-3-era marker is explicitly an estimated machine size. Its symbol preserves that evidence distinction.","focus":["estimate"]},{"title":"Read the opposing reliability axis","description":"Later fleets reach thousands to over sixteen thousand accelerators. With the fixed device rate, system MTBF falls as required device count rises, making recovery part of the schedule.","focus":["fleet","mtbf"]}],"artwork_reviewed":true,"art_sha1":"e28e76902fe0468744c531faa18f3c8356417758","art_kind":"png","art_width":3599,"art_height":2398},"vol2:fig-cluster-size-explosion":{"key":"vol2:fig-cluster-size-explosion","figure_id":"fig-cluster-size-explosion","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The cluster size explosion","status":"ready","treatment":"annotated","question":"What evidence distinguishes a documented cluster count from an infrastructure estimate?","scope":"Landmark counts are historical evidence, and the dashed annual-growth line summarizes rather than predicts future deployments.","regions":{"region-1":{"x":0.13,"y":0.82,"w":0.2,"h":0.09,"label":"AlexNet baseline"},"region-2":{"x":0.44,"y":0.16,"w":0.22,"h":0.09,"label":"GPT-3 hollow estimate"},"region-3":{"x":0.71,"y":0.12,"w":0.27,"h":0.74,"label":"Recent clusters and magnitude bracket"}},"steps":[{"title":"Establish the small-cluster baseline","description":"AlexNet sits near two accelerators in 2012. The vertical logarithmic scale makes orders of magnitude visible rather than treating equal pixel gaps as equal device additions.","focus":["region-1"]},{"title":"Keep estimates distinguishable","description":"GPT-3 uses the hollow marker labeled estimate. It is approximate infrastructure evidence rather than a precise accelerator count from the training paper.","focus":["region-2"]},{"title":"Read the scale of the infrastructure change","description":"Recent landmarks occupy the thousands to tens-of-thousands range. The right bracket marks roughly four orders of magnitude from the early baseline, motivating fleet infrastructure without asserting a fixed future growth rate.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"564f702fbffc3216211d904bab330ddc2e4d1dab","art_kind":"png","art_width":3733,"art_height":2734},"vol2:fig-coll-comm":{"key":"vol2:fig-coll-comm","figure_id":"fig-coll-comm","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Communication patterns and their costs","status":"ready","treatment":"annotated","question":"How do aggregation and peer routing stress the network differently?","scope":"Volumes shown use the diagram’s simplified communication model; the All-to-All graph gives logical destinations rather than physical cables.","regions":{"ring":{"x":0.01,"y":0.04,"w":0.31,"h":0.92,"label":"Ring AllReduce"},"server":{"x":0.35,"y":0.04,"w":0.31,"h":0.92,"label":"Parameter server and central NIC"},"all":{"x":0.68,"y":0.04,"w":0.31,"h":0.92,"label":"Logical All-to-All"}},"steps":[{"title":"Spread aggregation traffic","description":"Ring AllReduce exchanges with neighbors and spreads traffic over ring links. The footer gives per-GPU volume under the displayed model.","focus":["ring"]},{"title":"Inspect the shared ingress","description":"Workers send and receive through the parameter server NIC. The red central segment identifies a shared aggregation bottleneck.","focus":["server"]},{"title":"Route distinct payloads","description":"Logical All-to-All sends different data to each peer. A switched fabric can realize these destinations; routes, message sizes, and contention determine the cost.","focus":["all"]}],"artwork_reviewed":true,"art_sha1":"804f43ef1aa9aca6b55202b96cea40932a66dcb3","art_kind":"svg","art_width":1200,"art_height":484,"art_structural_sha1":"9763db7354322aee0d2c428282f6932f01d9db06"},"vol2:fig-collective-primitives-overview":{"key":"vol2:fig-collective-primitives-overview","figure_id":"fig-collective-primitives-overview","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Four central collective primitives","status":"ready","treatment":"annotated","question":"Which collective changes values, and which changes who holds them?","scope":"Ranks are the four rows in each panel; tiles show logical ownership, not measured packet schedules.","regions":{"allreduce":{"x":0.01,"y":0.01,"w":0.48,"h":0.43,"label":"AllReduce"},"allgather":{"x":0.51,"y":0.01,"w":0.48,"h":0.43,"label":"AllGather"},"reducescatter":{"x":0.01,"y":0.47,"w":0.48,"h":0.43,"label":"ReduceScatter"},"alltoall":{"x":0.51,"y":0.47,"w":0.48,"h":0.43,"label":"AllToAll"}},"steps":[{"title":"Aggregate and replicate","description":"AllReduce sums matching chunks over ranks and places every reduced chunk on every rank. Green tiles distinguish sums from original inputs.","focus":["allreduce"]},{"title":"Concatenate without summing","description":"AllGather distributes each rank’s own chunk so every rank holds the concatenation. The bold outline traces chunk a through that ownership change.","focus":["allgather"]},{"title":"Aggregate into separate shards","description":"ReduceScatter computes the same per-chunk sums but leaves a different reduced shard on each rank. It does not replicate the complete result.","focus":["reducescatter"]},{"title":"Transpose destinations","description":"AllToAll routes each input chunk to its designated rank. Rank 0 receives the a chunks from every source; the values are rearranged rather than reduced.","focus":["alltoall"]}],"artwork_reviewed":true,"art_sha1":"80c879e68b55c1540c83c311809aca93c347efe9","art_kind":"svg","art_width":1200,"art_height":629,"art_structural_sha1":"786a02c681c1cb3b9663fbe017be98bff715df84"},"vol2:fig-comm-compute-tradeoff":{"key":"vol2:fig-comm-compute-tradeoff","figure_id":"fig-comm-compute-tradeoff","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Measuring the local-work trade-off","status":"ready","treatment":"annotated","question":"Why do fewer federated rounds not always mean less wall-clock time?","scope":"These timelines illustrate opposing effects of local work, not measured convergence curves or a universally best epoch count.","regions":{"small":{"x":0.01,"y":0.09,"w":0.98,"h":0.22,"label":"Small local-work setting"},"moderate":{"x":0.01,"y":0.35,"w":0.8,"h":0.2,"label":"Moderate local-work setting"},"large":{"x":0.01,"y":0.59,"w":0.98,"h":0.22,"label":"Large local-work setting with drift"},"legend":{"x":0.17,"y":0.86,"w":0.78,"h":0.13,"label":"Epoch, synchronization, and drift legend"}},"steps":[{"title":"Count both kinds of time","description":"Blue intervals are local epochs and orange intervals are upload and synchronization. A round includes both, so communication frequency alone does not determine completion time.","focus":["small","legend"]},{"title":"Amortize synchronization","description":"The moderate setting does more local work per round and reaches its target with fewer rounds in this schematic example. Its endpoint lies earlier on the shared wall-clock axis.","focus":["moderate"]},{"title":"Account for client drift","description":"The large setting lengthens rounds and includes the hatched round added by drift. Fewer synchronizations can still produce a later target endpoint.","focus":["large"]},{"title":"Measure time to target","description":"Compare the row endpoints only after checking quality, total client energy, and population coverage. The diagram supplies a comparison method, not an admissible policy by itself.","focus":["small","moderate","large"]}],"artwork_reviewed":true,"art_sha1":"853dd5f4ee6797ee006ef838829bafeb98947674","art_kind":"svg","art_width":1200,"art_height":494,"art_structural_sha1":"1331f1b18abe169298939e3581992d30fdf8362b"},"vol2:fig-comm-convergence-tradeoff":{"key":"vol2:fig-comm-convergence-tradeoff","figure_id":"fig-comm-convergence-tradeoff","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Cost and time in the illustrative scaling scenario","status":"ready","treatment":"annotated","question":"Which configuration is dominated in this cost–time scenario?","scope":"The points reuse assumed step times, convergence counts, and GPU-hour rates from the worked example; they do not rank BSP and SSP universally.","regions":{"eight":{"x":0.68,"y":0.71,"w":0.28,"h":0.18,"label":"Eight-worker BSP"},"bsp":{"x":0.15,"y":0.24,"w":0.29,"h":0.14,"label":"64-worker BSP"},"ssp":{"x":0.17,"y":0.11,"w":0.28,"h":0.14,"label":"64-worker SSP"},"dominated":{"x":0.21,"y":0.01,"w":0.75,"h":0.28,"label":"Dominated cost–time region"}},"steps":[{"title":"Choose the lower bill","description":"Eight-worker BSP is the lower-cost point, but it sits much farther right on the logarithmic time axis. Lower cost comes with a later result.","focus":["eight"]},{"title":"Buy a faster result","description":"64-worker BSP reaches target quality earlier at higher cost. Neither BSP point dominates the other because they trade one objective for another.","focus":["bsp","eight"]},{"title":"Account for convergence","description":"The assumed SSP run is both slower and more expensive than 64-worker BSP. Its per-step savings are outweighed by additional iterations in this scenario.","focus":["ssp","bsp"]},{"title":"Use the domination test narrowly","description":"The shaded region is worse in both axes than an available BSP run. This is a scenario-specific frontier, not a general rejection of asynchronous designs.","focus":["dominated"]}],"artwork_reviewed":true,"art_sha1":"bbb363877cf6e7e686ee6ea4fea903b5a66c194f","art_kind":"png","art_width":3659,"art_height":2159},"vol2:fig-compute-comm-timeline":{"key":"vol2:fig-compute-comm-timeline","figure_id":"fig-compute-comm-timeline","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"The compute-communication timeline","status":"ready","treatment":"annotated","question":"Why does faster distributed computation leave communication exposed?","scope":"The four percentage bars are assumed teaching scenarios that each sum to 100%; they are not timing measurements or predictions for a specific fleet.","regions":{"eight":{"x":0.01,"y":0.08,"w":0.96,"h":0.13,"label":"Eight-GPU step share"},"sixtyfour":{"x":0.01,"y":0.28,"w":0.96,"h":0.13,"label":"64-GPU step share"},"large":{"x":0.01,"y":0.68,"w":0.96,"h":0.13,"label":"4,096-GPU step share"},"idle":{"x":0.84,"y":0.68,"w":0.13,"h":0.13,"label":"Synchronization and idle share"}},"steps":[{"title":"Read one complete step","description":"At eight GPUs the illustration assigns 75% to compute and 25% to communication. These fractions divide one training step rather than describing absolute elapsed time.","focus":["eight"]},{"title":"Spread the same workload further","description":"The 64-GPU scenario gives a larger share to communication and adds a synchronization or idle segment. Less local work can leave fewer independent operations to cover communication.","focus":["sixtyfour"]},{"title":"Inspect the critical-path consequence","description":"At 4,096 GPUs the assumed compute share is 20%, with 65% communication and 15% synchronization or idle. A real scaling decision requires measuring these exposed components for the actual partition and workload.","focus":["large","idle"]}],"artwork_reviewed":true,"art_sha1":"37c05b4f8f18a8ad6f82d714a9c9b295949d5073","art_kind":"png","art_width":4019,"art_height":2160},"vol2:fig-compute-optimal":{"key":"vol2:fig-compute-optimal","figure_id":"fig-compute-optimal","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Optimal compute allocation","status":"ready","treatment":"annotated","question":"Why must parameter count and token count be chosen together under a compute budget?","scope":"The panels reproduce a specific language-model scaling study, not universal optimal allocations for every architecture or dataset.","regions":{"region-1":{"x":0.01,"y":0.02,"w":0.32,"h":0.94,"label":"IsoFLOP loss curves"},"region-2":{"x":0.34,"y":0.02,"w":0.32,"h":0.94,"label":"Optimal parameter scaling"},"region-3":{"x":0.67,"y":0.02,"w":0.32,"h":0.94,"label":"Optimal token scaling"}},"steps":[{"title":"Find each budget’s loss valley","description":"The left panel holds FLOPs fixed along each curve while varying parameters. A valley identifies a better allocation than simply selecting the largest model at that budget.","focus":["region-1"]},{"title":"Read the parameter requirement","description":"The middle panel plots optimal parameter count against FLOPs. Its fitted power-law trend describes how the model side of the allocation grows.","focus":["region-2"]},{"title":"Scale training data with the model","description":"The right panel plots optimal tokens against FLOPs. Together the middle and right panels show why additional compute requires a balanced increase in model size and training tokens.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"7362d8457ea2bf436fcb4efc0f219d6288755f5d","art_kind":"png","art_width":1674,"art_height":483},"vol2:fig-compute-trends":{"key":"vol2:fig-compute-trends","figure_id":"fig-compute-trends","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Model training compute trends","status":"ready","treatment":"annotated","question":"How does the historical compute trend change in the deep learning era?","scope":"The image is historical evidence. Model domains, publication coverage, and estimation precision vary; its trend lines are not controlled causal experiments.","regions":{"region-1":{"x":0.03,"y":0.63,"w":0.5,"h":0.31,"label":"Early-model region"},"region-2":{"x":0.72,"y":0.08,"w":0.18,"h":0.83,"label":"Deep-learning-era region"},"region-3":{"x":0.9,"y":0.1,"w":0.1,"h":0.36,"label":"Domain legend"}},"steps":[{"title":"Read the earlier trend","description":"Early notable models lie around the shallower dashed trend, described by the caption as approximately 1.4× per year. The log FLOP axis compresses a very large span of training effort.","focus":["region-1"]},{"title":"Compare the later acceleration","description":"The shaded Deep Learning Era contains a much steeper rise and dense modern model points. This change motivates efficiency and fleet-scale resource management.","focus":["region-2"]},{"title":"Retain the evidence categories","description":"The legend separates language, vision, biology, games, speech, image generation, multimodal, robotics, and other models. Their plotted history is a mixture of workloads rather than one repeated benchmark.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"e69bcad5c7ff710a285787d95797c7ad3131fcf2","art_kind":"png","art_width":3744,"art_height":2088},"vol2:fig-conclusion-traditional-vs-agentic":{"key":"vol2:fig-conclusion-traditional-vs-agentic","figure_id":"fig-conclusion-traditional-vs-agentic","source":"books/vol2/17_conclusion/17_conclusion.qmd","title":"From Model Serving to Closed-Loop Agentic Fleets","status":"ready","treatment":"annotated","question":"Why must an agentic workflow be measured per verified result?","scope":"The panels illustrate accounting boundaries, not measured energy or a guarantee that additional verification improves quality at acceptable cost.","regions":{"forward":{"x":0.29,"y":0.11,"w":0.33,"h":0.18,"label":"Model forward-pass boundary"},"tokens":{"x":0.69,"y":0.12,"w":0.25,"h":0.14,"label":"Per-token output unit"},"workflow":{"x":0.14,"y":0.46,"w":0.69,"h":0.42,"label":"Complete workflow boundary"},"calls":{"x":0.17,"y":0.48,"w":0.43,"h":0.19,"label":"Model calls inside the workflow"},"retry":{"x":0.23,"y":0.78,"w":0.46,"h":0.09,"label":"Failed-check retry path"},"result":{"x":0.85,"y":0.65,"w":0.14,"h":0.17,"label":"Verified-result output unit"}},"steps":[{"title":"Count a model token","description":"Panel a encloses one model forward pass. FLOPs per token and joules per token describe cost within that narrow execution boundary.","focus":["forward","tokens"]},{"title":"Expand to the complete task","description":"Panel b includes planning, retrieval, tool execution, and verification. Model calls are components inside this workflow rather than the whole unit of work.","focus":["workflow","calls"]},{"title":"Charge retries to the task","description":"A failed verification returns the workflow to planning. Work spent on failed attempts remains part of the cost of the eventual useful result.","focus":["retry"]},{"title":"Use a verified output unit","description":"The final accounting unit is the useful task completed at the required quality and safety. A cheaper token does not by itself establish a cheaper successful workflow.","focus":["result"]}],"artwork_reviewed":true,"art_sha1":"1d259c41cb23b45500a9f0cc9fb2546e2a25cb7f","art_kind":"svg","art_width":1200,"art_height":681,"art_structural_sha1":"fdb2d4275df22045b27d0c13ad785e203dc2db8e"},"vol2:fig-congestion-cascade":{"key":"vol2:fig-congestion-cascade","figure_id":"fig-congestion-cascade","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"A true incast burst","status":"ready","treatment":"annotated","question":"Why does this incast overflow one egress despite fast sender links?","scope":"This is the chapter’s deliberately worst-case fan-in, not a bandwidth-optimal ring AllReduce or a measured arrival trace.","regions":{"senders":{"x":0.02,"y":0.12,"w":0.28,"h":0.63,"label":"Sender fan-in"},"buffer":{"x":0.35,"y":0.22,"w":0.31,"h":0.38,"label":"Full 32 MB egress buffer"},"receiver":{"x":0.68,"y":0.3,"w":0.29,"h":0.15,"label":"400 Gb/s egress and receiver"},"pause":{"x":0.07,"y":0.01,"w":0.39,"h":0.15,"label":"Upstream PAUSE path"},"rates":{"x":0.02,"y":0.73,"w":0.96,"h":0.22,"label":"Offered and egress rate bars"}},"steps":[{"title":"Aggregate arrivals","description":"The senders each offer 50 GB/s toward the same destination. The placeholder stands for 252 additional senders, so this is a many-to-one burst.","focus":["senders"]},{"title":"Identify the narrow exit","description":"The single 400 Gb/s egress serves 50 GB/s. It cannot drain bytes as fast as this assumed fan-in supplies them.","focus":["receiver","rates"]},{"title":"Fill a finite queue","description":"The switch buffer absorbs the difference only temporarily. Once its 32 MB capacity is exhausted, the system must drop packets or reduce arrivals.","focus":["buffer"]},{"title":"Move pressure upstream","description":"The red PAUSE path shows backpressure returning toward senders. It can prevent a local drop while spreading blocked traffic through shared upstream resources.","focus":["pause","senders"]}],"artwork_reviewed":true,"art_sha1":"b4bf77154e628151096382bf9c632a88b434da53","art_kind":"svg","art_width":1200,"art_height":632,"art_structural_sha1":"c2089147c2b114270e379a53510d3da5356307ac"},"vol2:fig-continuous-batching-comparison":{"key":"vol2:fig-continuous-batching-comparison","figure_id":"fig-continuous-batching-comparison","source":"books/vol2/10_inference/10_inference.qmd","title":"Static vs. continuous batching","status":"ready","treatment":"annotated","question":"What happens to a decode slot when its request finishes?","scope":"The illustrated iterations show slot utilization, not measured throughput or a guarantee that prefill has zero cost.","regions":{"region-1":{"x":0.13,"y":0.12,"w":0.72,"h":0.32,"label":"Static batching early completions"},"region-2":{"x":0.39,"y":0.57,"w":0.46,"h":0.3,"label":"Continuous batching replacement slots"},"region-3":{"x":0.85,"y":0.18,"w":0.13,"h":0.61,"label":"Busy-slot totals"}},"steps":[{"title":"Leave completed slots idle","description":"In static batching, R1, R3, and R4 finish before R2. Their subsequent hatched cells stay idle until the batch ends.","focus":["region-1"]},{"title":"Admit waiting requests into freed slots","description":"Continuous batching places R5, R6, and R7 into freed slots. Dark cells identify their prefill steps before later decode cells.","focus":["region-2"]},{"title":"Compare the same iteration window","description":"The panels report 20 of 32 busy slots for static batching and 32 of 32 for continuous batching. These totals describe the drawn schedule, not every workload.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"3a18bd36025c9ae359efb52ce88224983be59a29","art_kind":"svg","art_width":1200,"art_height":731,"art_structural_sha1":"ecd82cb4be9173f89bcb45ee65e7dbbc3c1ef6e5"},"vol2:fig-cooling-comparison":{"key":"vol2:fig-cooling-comparison","figure_id":"fig-cooling-comparison","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Air and Liquid Heat Paths","status":"ready","treatment":"annotated","question":"Where does chip heat go in air and direct-to-chip liquid cooling?","scope":"The pathways identify mechanisms, not universal PUE, water-use, or capacity rankings.","regions":{"air":{"x":0.02,"y":0.04,"w":0.42,"h":0.7,"label":"Air through heat sink"},"liquid":{"x":0.51,"y":0.04,"w":0.47,"h":0.7,"label":"Coolant through cold plate"},"boundary":{"x":0.02,"y":0.7,"w":0.96,"h":0.13,"label":"Server/rack and facility boundary"},"reject":{"x":0.26,"y":0.81,"w":0.72,"h":0.14,"label":"Shared heat rejection"}},"steps":[{"title":"Transfer heat to air","description":"On the left, chip heat passes through the heat sink into moving air. The warm-air path carries that heat away from the chip.","focus":["air"]},{"title":"Transfer heat to coolant","description":"On the right, cool supply enters a cold plate and leaves as warm return. Liquid transports the chip’s heat rather than making it disappear.","focus":["liquid"]},{"title":"Cross the facility boundary","description":"Both routes cross from server and rack into facility infrastructure. Capacity and auxiliary loads must be assessed over that complete path.","focus":["boundary"]},{"title":"Reject the heat","description":"Both paths end at heat rejection. The cooling medium alone does not determine water use or parasitic energy.","focus":["reject"]}],"artwork_reviewed":true,"art_sha1":"1ef17d760ecb59d277a6e7aefb16a769e725c29d","art_kind":"svg","art_width":1200,"art_height":584,"art_structural_sha1":"7c580d548d081e015ab548c251fa3605cca6f95f"},"vol2:fig-cost-idle-gpus":{"key":"vol2:fig-cost-idle-gpus","figure_id":"fig-cost-idle-gpus","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"The cost of idle GPUs","status":"ready","treatment":"annotated","question":"How do cluster size and unused capacity combine into a cost estimate?","scope":"This scenario applies a fixed cloud-equivalent hourly price; the Philly utilization reference is not a measured cost curve or observed cluster size.","regions":{"anchor":{"x":0.45,"y":0.55,"w":0.07,"h":0.09,"label":"10K-GPU illustrative anchor"},"range":{"x":0.57,"y":0.15,"w":0.31,"h":0.63,"label":"30 to 70 percent utilization scenario band"},"reference":{"x":0.59,"y":0.4,"w":0.39,"h":0.22,"label":"Published utilization reference line"},"axis":{"x":0.01,"y":0.01,"w":0.13,"h":0.89,"label":"Annual wasted cost axis"}},"steps":[{"title":"Define what the cost counts","description":"The vertical axis estimates annual cost of unused capacity under the declared hourly price. It is not a complete ownership or application-cost model.","focus":["axis"]},{"title":"Inspect the worked anchor","description":"The blue point marks 10,000 GPUs at 50 percent utilization and the corresponding annual wasted-capacity estimate.","focus":["anchor"]},{"title":"Compare utilization assumptions","description":"The shaded band spans the 30-to-70-percent scenarios. For a fixed cluster size, a lower assumed utilization produces more idle-capacity cost.","focus":["range"]},{"title":"Keep the empirical reference in scope","description":"The violet line applies the published Philly mean utilization across hypothetical cluster sizes. Its slope is a scenario calculation, not observed Philly spending.","focus":["reference"]}],"artwork_reviewed":true,"art_sha1":"1520cfc166b901c38f3046bf8224d6024efd2071","art_kind":"png","art_width":3705,"art_height":2280},"vol2:fig-critical-batch-size":{"key":"vol2:fig-critical-batch-size","figure_id":"fig-critical-batch-size","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Statistical cost of larger batches","status":"ready","treatment":"annotated","question":"Why can fewer optimizer steps still require more total examples?","scope":"This normalized gradient-noise illustration uses a fitted critical batch B*. It is not a hardware-throughput optimum or a measured threshold for a specific model.","regions":{"below":{"x":0.1,"y":0.08,"w":0.42,"h":0.82,"label":"Below the critical batch"},"cross":{"x":0.46,"y":0.66,"w":0.13,"h":0.22,"label":"Crossover at B/B* = 1"},"steps":{"x":0.56,"y":0.73,"w":0.42,"h":0.18,"label":"Step count approaching its minimum"},"examples":{"x":0.61,"y":0.07,"w":0.37,"h":0.65,"label":"Increasing example consumption"}},"steps":[{"title":"Increase a small batch","description":"Below B*, the blue optimization-step curve falls almost inversely with batch size while the orange example count stays near its minimum.","focus":["below"]},{"title":"Reach the statistical crossover","description":"At B/B* = 1 both normalized costs equal 2. The intersection describes a trade-off in this model, not the fastest hardware operating point.","focus":["cross"]},{"title":"Observe diminishing step savings","description":"Above the crossover, blue steps flatten toward their lower limit. Further batch growth buys progressively less reduction in optimizer updates.","focus":["steps"]},{"title":"Pay for extra samples","description":"The orange examples curve continues upward even as steps flatten. Device throughput and convergence must both enter the time-to-quality decision.","focus":["examples"]}],"artwork_reviewed":true,"art_sha1":"356854766fd8fa73ec15c7d3fa1c86ce22789257","art_kind":"png","art_width":3656,"art_height":2160},"vol2:fig-data-augmentation":{"key":"vol2:fig-data-augmentation","figure_id":"fig-data-augmentation","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Data Augmentation Techniques","status":"ready","treatment":"annotated","question":"When is an image transformation a valid training example?","scope":"The visible digit examples illustrate transformations; their label validity and robustness benefit depend on the task and must be evaluated.","regions":{"original":{"x":0.0,"y":0.0,"w":0.21,"h":0.99,"label":"Original digit"},"flip":{"x":0.26,"y":0.0,"w":0.22,"h":0.99,"label":"Horizontal flip"},"crop":{"x":0.52,"y":0.0,"w":0.19,"h":0.99,"label":"Crop"},"rotate":{"x":0.77,"y":0.0,"w":0.23,"h":0.99,"label":"Rotation"}},"steps":[{"title":"Fix the intended label","description":"The original image depicts a digit 3. An augmented example must preserve the task’s intended answer to remain a valid labeled record.","focus":["original"]},{"title":"Inspect a potentially invalid flip","description":"The mirrored digit changes its orientation. A transformation useful for natural images can violate a digit-recognition label contract.","focus":["flip"]},{"title":"Check retained information after cropping","description":"The crop removes part of the source. Whether enough evidence remains for the original class depends on the task.","focus":["crop"]},{"title":"Evaluate rotation rather than assuming benefit","description":"Rotation produces another variant, but its label and usefulness require validation. Augmentation is not a general guarantee of poisoning resistance.","focus":["rotate"]}],"artwork_reviewed":true,"art_sha1":"f16bf095fc2a3d6c458c8ecab843e5a27c230f0f","art_kind":"png","art_width":2399,"art_height":583},"vol2:fig-data-movement-hierarchy":{"key":"vol2:fig-data-movement-hierarchy","figure_id":"fig-data-movement-hierarchy","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Data-movement accounting boundaries","status":"ready","treatment":"annotated","question":"What must an energy estimate include as a transfer crosses larger boundaries?","scope":"This is an accounting schematic, not a universal energy-versus-distance law.","regions":{"package":{"x":0.01,"y":0.3,"w":0.28,"h":0.66,"label":"SRAM, HBM, and package boundary"},"node":{"x":0.3,"y":0.02,"w":0.18,"h":0.88,"label":"Crossbar and peer GPU"},"fabric":{"x":0.48,"y":0.29,"w":0.51,"h":0.71,"label":"SerDes through remote node"}},"steps":[{"title":"Start with package-local state","description":"The SRAM and HBM endpoints occupy the package boundary. Estimate their arrays and interfaces before comparing their energy with a wider path.","focus":["package"]},{"title":"Include the node path","description":"The crossbar and its peer-GPU branch expand the boundary to the node. This path activates components absent from the package-only comparison.","focus":["node"]},{"title":"Account for the complete fabric","description":"SerDes, optical transceivers, switches, and the remote endpoint belong in the fabric-path estimate. Compare energy per byte only under matching boundaries and utilization.","focus":["fabric"]}],"artwork_reviewed":true,"art_sha1":"76060ad086b378d0b16d483bb0068577017620f2","art_kind":"svg","art_width":1200,"art_height":569,"art_structural_sha1":"76060ad086b378d0b16d483bb0068577017620f2"},"vol2:fig-data-pipeline-vol2":{"key":"vol2:fig-data-pipeline-vol2","figure_id":"fig-data-pipeline-vol2","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"Pipelined data loading","status":"ready","treatment":"annotated","question":"What work must overlap to keep a GPU supplied with batches?","scope":"Equal timeline scales and durations are illustrative. Successful overlap requires sufficient delivery rate and prefetch depth.","regions":{"sequential":{"x":0.02,"y":0.02,"w":0.95,"h":0.42,"label":"Sequential read, prepare, train"},"overlap":{"x":0.02,"y":0.49,"w":0.95,"h":0.44,"label":"Overlapped pipeline"},"inflight":{"x":0.56,"y":0.53,"w":0.19,"h":0.34,"label":"Three batches in flight"},"gpu":{"x":0.15,"y":0.81,"w":0.76,"h":0.1,"label":"Pipelined GPU training lane"}},"steps":[{"title":"Find avoidable idle time","description":"In panel a, GPU idle intervals cover storage reads and CPU preparation. One batch finishes before the next begins its input work.","focus":["sequential"]},{"title":"Overlap different batches","description":"Panel b prepares future batches while the GPU trains on an earlier batch. Read, preparation, and training are concurrent work on different resources.","focus":["overlap"]},{"title":"Inspect one instant","description":"The shaded column crosses read 4, prep 3, and train 2. Three batches need distinct in-flight state; this overlap is not three operations on one batch.","focus":["inflight"]},{"title":"Check sustained delivery","description":"Back-to-back training blocks follow the initial fill. They remain possible only while input stages keep up and buffering absorbs variability.","focus":["gpu"]}],"artwork_reviewed":true,"art_sha1":"847680b04cc8b08fd55953a76ee8192bf621af38","art_kind":"svg","art_width":1200,"art_height":833,"art_structural_sha1":"3aa9ec6f684a69b04832d05fc973a967bd831a4c"},"vol2:fig-data-poisoning-loop":{"key":"vol2:fig-data-poisoning-loop","figure_id":"fig-data-poisoning-loop","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Data poisoning as bilevel optimization","status":"ready","treatment":"annotated","question":"Why is data poisoning described as a nested optimization problem?","scope":"This is an abstract attacker-defender objective, not a runnable attack or a guarantee that optimization succeeds.","regions":{"outer":{"x":0.12,"y":0.01,"w":0.72,"h":0.25,"label":"Attacker outer objective"},"data":{"x":0.17,"y":0.34,"w":0.42,"h":0.18,"label":"Mixed clean and poisoned data"},"inner":{"x":0.01,"y":0.6,"w":0.66,"h":0.38,"label":"Defender training objective"},"eval":{"x":0.71,"y":0.6,"w":0.28,"h":0.38,"label":"Target evaluation and feedback"}},"steps":[{"title":"Choose the adversarial data","description":"The outer objective selects a bounded poisoned subset to increase target test loss after training. The poison budget constrains this choice.","focus":["outer"]},{"title":"Mix into the training set","description":"The red records enter alongside clean data. The defender optimizes on the combined set rather than knowing which samples are malicious.","focus":["data"]},{"title":"Train the defender","description":"The inner minimization produces parameters through training steps. The attacker’s objective depends on these resulting parameters.","focus":["inner"]},{"title":"Evaluate and refine","description":"The evaluation box measures target loss and feeds it back to the outer loop. This dependency makes the problem nested rather than a single training objective.","focus":["eval"]}],"artwork_reviewed":true,"art_sha1":"927373f44d98b542b1cb608d947a25beef058bab","art_kind":"svg","art_width":1200,"art_height":600,"art_structural_sha1":"07017bf5c27dd1cc00c47a07334ee159f78ba423"},"vol2:fig-data-scaling-regimes":{"key":"vol2:fig-data-scaling-regimes","figure_id":"fig-data-scaling-regimes","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Data scaling regimes","status":"ready","treatment":"annotated","question":"When does collecting more data produce predictable returns and when does it produce little gain?","scope":"The three regimes are schematic, without measured boundaries. An observed plateau can also reflect limited coverage, insufficient model capacity, or incomplete optimization; it does not prove an irreducible floor.","regions":{"region-1":{"x":0.05,"y":0.04,"w":0.27,"h":0.53,"label":"Small-data ceiling"},"region-2":{"x":0.32,"y":0.04,"w":0.41,"h":0.71,"label":"Power-law descent"},"region-3":{"x":0.73,"y":0.04,"w":0.26,"h":0.89,"label":"Irreducible floor"}},"steps":[{"title":"Recognize the best-guess regime","description":"The curve begins near Best Guess Error and is labeled little gain. The figure does not assume every new data point yields the same improvement.","focus":["region-1"]},{"title":"Read the predictable-return regime","description":"In the power-law region, the line descends at approximately constant slope on log axes. Equal proportional increases in data follow a regular reduction pattern within this regime.","focus":["region-2"]},{"title":"Identify a limit data alone cannot remove","description":"The curve flattens at Irreducible Error. The hatched region below the floor is excluded by this schematic assumption, so extrapolating the middle slope indefinitely would be misleading.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"dbb9c83f6ec6280486075caf7c50fbf5f5af566d","art_kind":"png","art_width":3659,"art_height":2279},"vol2:fig-data-stall-frontier":{"key":"vol2:fig-data-stall-frontier","figure_id":"fig-data-stall-frontier","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"The data-stall frontier","status":"ready","treatment":"annotated","question":"When does more input bandwidth stop increasing ideal compute active time?","scope":"The curve min(1, bandwidth/demand) is an ideal overlapped service-rate bound. Real utilization can lie below it because of latency, preparation, and coordination.","regions":{"starved":{"x":0.1,"y":0.07,"w":0.18,"h":0.81,"label":"Starved service-rate region"},"knee":{"x":0.26,"y":0.06,"w":0.06,"h":0.84,"label":"Supply equals demand"},"image":{"x":0.29,"y":0.08,"w":0.29,"h":0.28,"label":"Image job bandwidth headroom"},"text":{"x":0.29,"y":0.33,"w":0.68,"h":0.23,"label":"Text job bandwidth headroom"}},"steps":[{"title":"Identify the service deficit","description":"Left of matching supply, the input stage cannot deliver batches as fast as compute consumes them. The stalled-notebook point sits at 0.8 ideal active fraction.","focus":["starved"]},{"title":"Reach the knee","description":"At bandwidth/demand = 1, input supply matches consumption. The bound reaches active fraction 1 at this service-rate boundary.","focus":["knee"]},{"title":"Interpret moderate headroom","description":"The image-job arrow spans 3.3 times matching bandwidth. It is supply margin, not a 3.3-times speedup above full compute activity.","focus":["image"]},{"title":"Interpret large headroom","description":"The text-job arrow spans 6,000 times demand while the bound remains flat. Additional input supply does not accelerate an already fed compute stage in this ideal model.","focus":["text"]}],"artwork_reviewed":true,"art_sha1":"49ac19378ec59ca26cfabafe9ab871486042cdd6","art_kind":"png","art_width":3421,"art_height":1980},"vol2:fig-defense-stack":{"key":"vol2:fig-defense-stack","figure_id":"fig-defense-stack","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Layered defense stack","status":"ready","treatment":"annotated","question":"Why do security layers remain interdependent?","scope":"Each control has its own threat model. A correctly released DP artifact retains its release-level guarantee even if a host is later compromised.","regions":{"data":{"x":0.01,"y":0.01,"w":0.98,"h":0.22,"label":"Data protections and released artifact"},"model":{"x":0.01,"y":0.26,"w":0.84,"h":0.22,"label":"Model behavior controls"},"platform":{"x":0.01,"y":0.51,"w":0.84,"h":0.22,"label":"Runtime platform protections"},"hardware":{"x":0.01,"y":0.76,"w":0.84,"h":0.22,"label":"Hardware trust anchors"},"breach":{"x":0.83,"y":0.19,"w":0.17,"h":0.59,"label":"Compromised-host path before release"}},"steps":[{"title":"Protect records and releases","description":"Encryption, provenance, secure aggregation, and differential privacy address distinct data risks. The released artifact is a boundary, not merely another runtime state.","focus":["data"]},{"title":"Protect learned behavior","description":"Adversarial training, input validation, output monitoring, and rate limits govern model interactions. They are not substitutes for platform isolation.","focus":["model"]},{"title":"Protect the execution substrate","description":"Containers, network segmentation, access control, and telemetry depend on correctly enforced runtime boundaries. Hardware trust anchors support, but do not replace, those checks.","focus":["platform","hardware"]},{"title":"Locate the compromise in time","description":"The red path shows a compromised host altering a mechanism before release. That differs from compromising a host after a correctly constructed DP artifact has already been released.","focus":["breach"]}],"artwork_reviewed":true,"art_sha1":"ecff69370fd35ff2a19fedcefa57acb56212ef8c","art_kind":"svg","art_width":1200,"art_height":583,"art_structural_sha1":"94b37f170b92931c4fa6d8aa1fadad969d25c565"},"vol2:fig-differential-privacy":{"key":"vol2:fig-differential-privacy","figure_id":"fig-differential-privacy","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Differential privacy and output distributions","status":"ready","treatment":"annotated","question":"Why does overlapping output density not by itself establish differential privacy?","scope":"The curves are illustrative. DP constrains probabilities of measurable output sets under a declared adjacency relation; density difference at one outcome is not the guarantee.","regions":{"left":{"x":0.23,"y":0.18,"w":0.31,"h":0.69,"label":"Mechanism on dataset X"},"right":{"x":0.55,"y":0.17,"w":0.31,"h":0.7,"label":"Mechanism on adjacent X prime"},"difference":{"x":0.49,"y":0.1,"w":0.05,"h":0.22,"label":"Density difference at outcome o"},"overlap":{"x":0.35,"y":0.4,"w":0.36,"h":0.46,"label":"Shared output support and overlap"}},"steps":[{"title":"Compare adjacent inputs","description":"The blue and orange curves depict one randomized mechanism on adjacent datasets. The adjacency relation must be fixed before interpreting privacy.","focus":["left","right"]},{"title":"Read overlap correctly","description":"The gray overlap means either dataset can produce outcomes in the same region. It does not mean both distributions assign identical probabilities.","focus":["overlap"]},{"title":"Distinguish difference from ratio","description":"The double arrow at outcome o marks a density difference. It is neither a likelihood ratio nor an epsilon guarantee.","focus":["difference"]},{"title":"Apply the event-level contract","description":"Differential privacy bounds probabilities over measurable output sets across adjacent datasets, with the declared epsilon and optional delta. The displayed overlap alone cannot establish that contract.","focus":["left","right"]}],"artwork_reviewed":true,"art_sha1":"2da379173740e47aaa55bc48e90b9c318d1d6706","art_kind":"png","art_width":3539,"art_height":1680},"vol2:fig-diffusion-model-example":{"key":"vol2:fig-diffusion-model-example","figure_id":"fig-diffusion-model-example","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Diffusion Model Memorization","status":"ready","treatment":"annotated","question":"What evidence of training-sample reproduction does the displayed diffusion example provide?","scope":"This is one published example of memorization risk; it does not establish that every output is copied or measure the frequency of extraction.","regions":{"region-1":{"x":0.0,"y":0.01,"w":0.44,"h":0.87,"label":"Training-set image"},"region-2":{"x":0.57,"y":0.01,"w":0.43,"h":0.87,"label":"Generated image"},"region-3":{"x":0.1,"y":0.54,"w":0.82,"h":0.3,"label":"Collar and necklace comparison"}},"steps":[{"title":"Inspect the training reference","description":"The chapter identifies the left portrait as the training-set reference. Its pose, clothing, and composition provide the reference against which the generated example can be compared.","focus":["region-1"]},{"title":"Compare the generated sample","description":"The chapter identifies the right portrait as the generated sample. Its close match to the reference’s visible composition illustrates the cited study’s concern about reproduction rather than ordinary semantic similarity alone.","focus":["region-2"]},{"title":"Inspect reproduced visual details","description":"Compare the pale collar, necklace, dark jacket, and their placement in both portraits. The cited extraction protocol supplies the evidence of training-sample reproduction; a similar-looking subject alone would not establish memorization.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"cd7b44b4667ec6f75910fb4e972b28c0168cd1da","art_kind":"png","art_width":2679,"art_height":1557},"vol2:fig-dirty-label-example":{"key":"vol2:fig-dirty-label-example","figure_id":"fig-dirty-label-example","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Dirty-Label Data Poisoning","status":"ready","treatment":"annotated","question":"Where does a dirty-label poison violate the training-data contract?","scope":"These are mismatched image-text pairs; the figure does not measure poisoning success or identify internal model representations.","regions":{"first":{"x":0.01,"y":0.12,"w":0.29,"h":0.8,"label":"Cat paired with dog caption"},"second":{"x":0.34,"y":0.12,"w":0.28,"h":0.8,"label":"Cat artwork paired with dog description"},"third":{"x":0.7,"y":0.12,"w":0.29,"h":0.8,"label":"Another mismatched pair"}},"steps":[{"title":"Compare the two modalities","description":"The first image depicts a cat while its paired text says “dog.” The training unit is the pair, so plausible image content alone does not validate the record.","focus":["first"]},{"title":"Trace the repeated mismatch","description":"The central cat artwork is also described as a dog. Repeated corrupted pairings attempt to teach an incorrect cross-modal association.","focus":["second"]},{"title":"Validate the ingestion boundary","description":"The right pair repeats the false label in another style. Provenance and image-text consistency checks target this data-contract violation, but their effectiveness still requires evaluation.","focus":["third"]}],"artwork_reviewed":true,"art_sha1":"3ab267767bba1257629b2ac674982a46300b79ee","art_kind":"png","art_width":3001,"art_height":698},"vol2:fig-disaggregated-serving":{"key":"vol2:fig-disaggregated-serving","figure_id":"fig-disaggregated-serving","source":"books/vol2/10_inference/10_inference.qmd","title":"Disaggregated Serving Architecture","status":"ready","treatment":"annotated","question":"Why separate prefill and decode pools, and what state crosses between them?","scope":"The source’s long-prompt, small-decode-batch regime labels prefill compute-bound and decode bandwidth-bound. Other batch or context sizes can change the bottleneck; transfers and pool queueing still add latency.","regions":{"region-1":{"x":0.13,"y":0.06,"w":0.29,"h":0.82,"label":"Prefill pool"},"region-2":{"x":0.42,"y":0.36,"w":0.17,"h":0.27,"label":"KV transfer boundary"},"region-3":{"x":0.58,"y":0.06,"w":0.29,"h":0.82,"label":"Decode pool"}},"steps":[{"title":"Complete the prompt pass","description":"The prefill pool runs whole-prompt passes and sets time to first token. Its capacity is sized for prompt tokens per second.","focus":["region-1"]},{"title":"Transfer the request state","description":"The amber KV cache path moves prompt-derived state by RDMA to the decode pool. Disaggregation adds this transfer rather than eliminating the cache.","focus":["region-2"]},{"title":"Sustain token-by-token output","description":"The decode pool performs repeated one-token steps and sets time per output token. Its capacity is sized for output tokens per second.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"8d1fddf2317bcffe9b92dbb0b38d97ed5dee44e9","art_kind":"svg","art_width":1200,"art_height":496,"art_structural_sha1":"716502b8e3dfe8cd37d8cebc05cce4a1a0ae428a"},"vol2:fig-dist-layers-blocks":{"key":"vol2:fig-dist-layers-blocks","figure_id":"fig-dist-layers-blocks","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Layer-wise model parallelism","status":"ready","treatment":"annotated","question":"Why is splitting layers alone insufficient to keep all GPUs busy?","scope":"Sixteen layers, four GPUs, and equal schematic slots form the worked case; the schedule contains one batch without microbatching.","regions":{"placement":{"x":0.01,"y":0.02,"w":0.98,"h":0.38,"label":"Consecutive layer placement"},"forward":{"x":0.1,"y":0.48,"w":0.4,"h":0.4,"label":"Forward stage traversal"},"backward":{"x":0.5,"y":0.48,"w":0.39,"h":0.4,"label":"Backward stage traversal"},"idle":{"x":0.9,"y":0.44,"w":0.09,"h":0.49,"label":"Busy and idle summary"}},"steps":[{"title":"Reduce each weight footprint","description":"Four consecutive layers occupy each GPU. Forward activations move right and backward gradients move left across stage boundaries.","focus":["placement"]},{"title":"Follow one batch forward","description":"Only one stage handles this batch’s forward work in a slot. The other GPUs cannot invent later-stage input before its dependency arrives.","focus":["forward"]},{"title":"Return gradients in reverse","description":"Backward work starts at the final stage and returns toward GPU 0. The reverse dependency leaves most stages idle again.","focus":["backward"]},{"title":"Count utilization in this schedule","description":"Each GPU is busy for two of eight slots in this simplified schedule. Microbatching can fill some of the remaining slots with other batches’ work.","focus":["idle"]}],"artwork_reviewed":true,"art_sha1":"552a9f8d77ecf9c93b3d13a7f2f4128dbc695315","art_kind":"svg","art_width":1200,"art_height":699,"art_structural_sha1":"ee68e9f798b7a5d8c181b8b9da612e48dea37f6c"},"vol2:fig-dist-train-data-parallelism":{"key":"vol2:fig-dist-train-data-parallelism","figure_id":"fig-dist-train-data-parallelism","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Data parallelism implementation pipeline","status":"ready","treatment":"annotated","question":"Why do independent replicas finish with identical parameter updates?","scope":"The diagram describes the shown averaged-gradient SGD workflow; preserving global-batch semantics depends on matching batch and averaging conventions.","regions":{"batch":{"x":0.01,"y":0.04,"w":0.2,"h":0.94,"label":"Partition and assign batch"},"replicas":{"x":0.22,"y":0.1,"w":0.22,"h":0.81,"label":"Independent forward and backward passes"},"reduce":{"x":0.59,"y":0.1,"w":0.15,"h":0.81,"label":"AllReduce average"},"update":{"x":0.66,"y":0.1,"w":0.31,"h":0.81,"label":"Identical updates"}},"steps":[{"title":"Partition the global batch","description":"The batch of 128 examples becomes four shards of 32 in this illustrated case. Each GPU receives different examples while starting from the same model state.","focus":["batch"]},{"title":"Compute local gradients","description":"Each replica performs forward and backward work independently and produces its own gradient gᵢ. Local data differences make those gradients different.","focus":["replicas"]},{"title":"Average across replicas","description":"AllReduce combines all local gradients into one global average. This collective synchronizes the update information, rather than sending examples through the GPUs in sequence.","focus":["reduce"]},{"title":"Apply the same update","description":"Every GPU applies the common averaged gradient and reaches the same updated parameters. Replica agreement is what permits the next global-batch step.","focus":["update"]}],"artwork_reviewed":true,"art_sha1":"cb74007759610eb6b867276b219a082d07920b36","art_kind":"svg","art_width":1200,"art_height":693,"art_structural_sha1":"511e43f81b1a9ecd0296bc3922b174dd7ebc925a"},"vol2:fig-distributed-checkpoint-architecture":{"key":"vol2:fig-distributed-checkpoint-architecture","figure_id":"fig-distributed-checkpoint-architecture","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Distributed checkpoint architecture","status":"ready","treatment":"annotated","question":"Why can distributed checkpointing shorten the blocking write path?","scope":"Background draining still consumes storage and network resources; local staging alone does not establish durable remote recovery.","regions":{"central":{"x":0.01,"y":0.01,"w":0.47,"h":0.59,"label":"Coordinator ingress path"},"serial":{"x":0.01,"y":0.65,"w":0.47,"h":0.33,"label":"Serialized blocking writes"},"distributed":{"x":0.51,"y":0.01,"w":0.48,"h":0.59,"label":"Worker-local NVMe staging"},"drain":{"x":0.51,"y":0.65,"w":0.48,"h":0.33,"label":"Concurrent blocking stage and background drain"}},"steps":[{"title":"Locate centralized contention","description":"All workers send state through the coordinator before shared storage. The single ingress path can serialize checkpoint traffic.","focus":["central","serial"]},{"title":"Stage each worker’s own shard","description":"The distributed design writes worker state directly to its local NVMe. Parallel writes reduce the blocking phase when the storage paths can sustain them.","focus":["distributed"]},{"title":"Track the remaining persistence work","description":"Dashed tails drain state to object storage after blocking staging. The recovery guarantee depends on where the needed checkpoint shards are durable when a failure occurs.","focus":["drain"]}],"artwork_reviewed":true,"art_sha1":"2f6400733ab639fe627af31dcec46f026a8caa36","art_kind":"svg","art_width":1200,"art_height":614,"art_structural_sha1":"cb41938937c5d2f3c7a29d0e24cec03222055c25"},"vol2:fig-distribution-shift-detector":{"key":"vol2:fig-distribution-shift-detector","figure_id":"fig-distribution-shift-detector","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"A Calibrated Distribution-Shift Workflow","status":"ready","treatment":"annotated","question":"Why does a lower PSI after a reference change not establish model recovery?","scope":"The service trace is synthetic and its bands require service-specific calibration. Values before and after week 41 compare against different versioned references.","regions":{"stable":{"x":0.1,"y":0.65,"w":0.32,"h":0.21,"label":"Initial stable population"},"warning":{"x":0.41,"y":0.29,"w":0.27,"h":0.45,"label":"Growth through warning band"},"escalate":{"x":0.63,"y":0.13,"w":0.17,"h":0.29,"label":"Escalation and investigation"},"reference":{"x":0.79,"y":0.39,"w":0.2,"h":0.47,"label":"Week-41 reference change"}},"steps":[{"title":"Fix the initial comparison population","description":"The early observations compare traffic with one input reference and stay in the stable band. PSI monitors input-distribution difference, not prediction accuracy directly.","focus":["stable"]},{"title":"Investigate a growing difference","description":"The trace enters the warning band as user behavior shifts. Binning, baseline, sample size, and response cost affect what a threshold means.","focus":["warning"]},{"title":"Escalate using the declared contract","description":"At week 32 the trace crosses the service’s escalation threshold. Investigation and validation follow rather than automatically declaring a failed model.","focus":["escalate"]},{"title":"Version the reference explicitly","description":"At week 41 the approved new reference changes the comparison population. The low values afterward do not prove better predictions or recovery against the old reference.","focus":["reference"]}],"artwork_reviewed":true,"art_sha1":"676c56c1f2f5e88001d19eb63ea08f62bf999231","art_kind":"png","art_width":3659,"art_height":1980},"vol2:fig-ecommerce-graph":{"key":"vol2:fig-ecommerce-graph","figure_id":"fig-ecommerce-graph","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"E-commerce model ecosystem","status":"ready","treatment":"annotated","question":"Why does an embedding change require coordinated evaluation?","scope":"The graph gives declared data dependencies, not measured effect sizes; a dependency identifies evaluation scope rather than proving a regression.","regions":{"sources":{"x":0.2,"y":0.01,"w":0.77,"h":0.13,"label":"Behavior logs and product catalog"},"embeddings":{"x":0.2,"y":0.18,"w":0.77,"h":0.14,"label":"User and product embeddings"},"consumers":{"x":0.2,"y":0.4,"w":0.77,"h":0.16,"label":"Retrieval and price sensitivity"},"ranking":{"x":0.38,"y":0.59,"w":0.41,"h":0.14,"label":"Ranking model"},"rules":{"x":0.38,"y":0.78,"w":0.41,"h":0.15,"label":"Business rules"}},"steps":[{"title":"Build two representations","description":"Behavior logs produce the user embedding; catalog data produces the product embedding. Their sources and meanings differ.","focus":["sources","embeddings"]},{"title":"Trace the shared bus","description":"Both embeddings reach both mid-tier models. Changing one embedding can affect retrieval and price sensitivity, rather than only the visually nearest box.","focus":["embeddings","consumers"]},{"title":"Follow the merged decision","description":"Outputs merge in the ranking model, then business rules apply inventory and promotion constraints. Downstream consumers remain within the evaluation scope.","focus":["ranking","rules"]},{"title":"Evaluate the connected subsystem","description":"The dashed coordinated-evaluation boundary encloses all four downstream consumers. A local embedding improvement alone cannot establish an end-to-end product gain.","focus":["consumers","ranking","rules"]}],"artwork_reviewed":true,"art_sha1":"d5706447aa072bd2a457dc4490f5ed4a55e9596d","art_kind":"svg","art_width":1200,"art_height":808,"art_structural_sha1":"ff7b43564cbba4c2a0d8b4c295badc7dc70fd263"},"vol2:fig-edge-cache-routing":{"key":"vol2:fig-edge-cache-routing","figure_id":"fig-edge-cache-routing","source":"books/vol2/10_inference/10_inference.qmd","title":"Cache hit and cache miss paths at the edge","status":"ready","treatment":"annotated","question":"When does an edge cache save GPU work, and what happens on a miss?","scope":"The under-10-ms label is a stated target. Reuse requires authorization and eligibility; open-ended generation may offer few cacheable requests.","regions":{"region-1":{"x":0.03,"y":0.34,"w":0.44,"h":0.28,"label":"Authorized edge lookup"},"region-2":{"x":0.08,"y":0.07,"w":0.34,"h":0.29,"label":"Cache-hit return path"},"region-3":{"x":0.1,"y":0.36,"w":0.88,"h":0.58,"label":"Cache-miss generation and storage"}},"steps":[{"title":"Check reuse at the edge","description":"The query first reaches the Edge PoP, which authorizes before checking the cache. A nearby stored response alone is not sufficient permission to return it.","focus":["region-1"]},{"title":"Return an eligible hit","description":"The upper green path returns from the Edge PoP directly to the user. This path avoids GPU generation for a request eligible for reuse.","focus":["region-2"]},{"title":"Generate and optionally retain a response","description":"A miss passes the regional gateway to GPU prefill and decode. Tokens stream back along the lower path; only an eligible response follows the dashed store-response branch into the cache.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"8d015ee105d6a333cc2c21c064dd9cfafd75a2db","art_kind":"svg","art_width":1200,"art_height":413,"art_structural_sha1":"844a319ce49b0d57258128db02ba3f4857c57ac3"},"vol2:fig-edge-inference-landscape":{"key":"vol2:fig-edge-inference-landscape","figure_id":"fig-edge-inference-landscape","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"The edge inference landscape","status":"ready","treatment":"annotated","question":"Why are edge latency-energy points not a matched-workload efficiency ranking?","scope":"Published points use different inference tasks and acceleration paths. Tier shading is descriptive; the chart does not compare training performance or directly determine battery life.","regions":{"mcu":{"x":0.19,"y":0.49,"w":0.7,"h":0.39,"label":"MCU and ASIC inference points"},"coral":{"x":0.36,"y":0.18,"w":0.42,"h":0.16,"label":"Coral Edge TPU point"},"gpu":{"x":0.26,"y":0.04,"w":0.55,"h":0.14,"label":"Jetson Orin ResNet-50 point"},"gap":{"x":0.19,"y":0.08,"w":0.16,"h":0.62,"label":"Approximate cross-tier energy gap"},"axes":{"x":0.02,"y":0.04,"w":0.18,"h":0.88,"label":"Energy axis and units"}},"steps":[{"title":"Locate small-task devices","description":"The MCU/ASIC region includes keyword spotting, visual wake words, and small-image tasks. Their energy and latency points describe the specific published workloads.","focus":["mcu"]},{"title":"Compare the higher tiers carefully","description":"Coral and Jetson points operate at larger energy scales; the Jetson label explicitly names ResNet-50. Moving between tiers also changes the workload.","focus":["coral","gpu"]},{"title":"Qualify the apparent gap","description":"The roughly hundredfold energy separation mixes hardware efficiency with task size. It cannot establish that one platform is that much more efficient on the same task.","focus":["gap"]},{"title":"Budget repeated operation","description":"Energy per inference is one input to a device budget. Training frequency, inference frequency, sensing, radio use, and idle power are additional costs outside this plot.","focus":["axes","mcu"]}],"artwork_reviewed":true,"art_sha1":"13566c7bb9760b460de07545d35ea4fcdd16f6c6","art_kind":"png","art_width":3178,"art_height":2700},"vol2:fig-edge-mlops-pipeline":{"key":"vol2:fig-edge-mlops-pipeline","figure_id":"fig-edge-mlops-pipeline","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Edge MLOps lifecycle pipeline","status":"ready","treatment":"annotated","question":"How does an adapted device model remain part of a managed release lifecycle?","scope":"The pipeline distinguishes raw-data locality from privacy of returned telemetry. A retraining trigger is a decision requiring validated evidence, not proof of regression.","regions":{"prepare":{"x":0.01,"y":0.07,"w":0.46,"h":0.19,"label":"Cloud pretraining and per-tier compression"},"rollout":{"x":0.51,"y":0.07,"w":0.23,"h":0.19,"label":"Staged over-the-air rollout"},"adapt":{"x":0.02,"y":0.53,"w":0.37,"h":0.38,"label":"Local adaptation policy"},"fleet":{"x":0.44,"y":0.52,"w":0.54,"h":0.39,"label":"First, wider, and pending rollout waves"},"telemetry":{"x":0.74,"y":0.07,"w":0.25,"h":0.4,"label":"Telemetry and privacy controls"},"trigger":{"x":0.1,"y":0.0,"w":0.79,"h":0.09,"label":"Retraining feedback"}},"steps":[{"title":"Prepare tier-compatible releases","description":"Cloud pretraining produces the base model, and compression creates forms suited to different device tiers. Compatibility includes the permitted local update policy.","focus":["prepare"]},{"title":"Roll out in stages","description":"The over-the-air stage releases to a first wave before a wider wave. Not-yet-updated devices coexist with newer versions.","focus":["rollout","fleet"]},{"title":"Adapt under the policy","description":"The device keeps local data and adapts the permitted model components. Versioned weights alone no longer describe every behavior that can emerge.","focus":["adapt"]},{"title":"Return governed evidence","description":"Telemetry supplies aggregate metrics through privacy controls. Keeping raw data local does not make those returned metrics inherently private.","focus":["telemetry"]},{"title":"Validate before retraining","description":"The dashed feedback path can trigger cloud retraining when the evidence warrants it. A detected change must first be distinguished from an actual quality regression.","focus":["trigger"]}],"artwork_reviewed":true,"art_sha1":"5d8f00134a746c08cd592eb0ae7c66ff163feda8","art_kind":"svg","art_width":1200,"art_height":588,"art_structural_sha1":"0db77f9955e2cc88dc8e54c36772dc21445e3740"},"vol2:fig-edge-npu-tops":{"key":"vol2:fig-edge-npu-tops","figure_id":"fig-edge-npu-tops","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Mobile NPU performance scaling","status":"ready","treatment":"annotated","question":"What can a mobile accelerator’s TOPS history tell us about local learning?","scope":"These are inference-oriented peak ratings with unspecified number formats. The hollow A13 point is derived; none of the points establishes backward-operator support or achieved training throughput.","regions":{"early":{"x":0.1,"y":0.72,"w":0.3,"h":0.2,"label":"A11 to A13 ratings"},"a13":{"x":0.32,"y":0.68,"w":0.12,"h":0.16,"label":"Hollow derived A13 point"},"middle":{"x":0.45,"y":0.42,"w":0.34,"h":0.23,"label":"A14 through A16 ratings"},"a17":{"x":0.75,"y":0.08,"w":0.18,"h":0.5,"label":"A17 Pro step"},"precision":{"x":0.8,"y":0.62,"w":0.18,"h":0.16,"label":"Possible rating-precision change"}},"steps":[{"title":"Read a peak inference budget","description":"The early points rise from the A11’s 0.6 TOPS rating. These are stated peak capability indicators rather than measured application throughput.","focus":["early"]},{"title":"Separate derived evidence","description":"A13 uses a hollow marker because its value is derived from stated speedups. Its evidence differs from a directly stated rating.","focus":["a13"]},{"title":"Qualify the large step","description":"A17 Pro rises to nearly 35 TOPS after A16. The dotted divider flags that unspecified precision may partly account for the apparent jump.","focus":["middle","a17","precision"]},{"title":"Do not infer training feasibility","description":"A larger inference rating does not establish support or speed for backward operations. Local training still needs runtime, working-memory, energy, and sustained-execution measurements.","focus":["a17"]}],"artwork_reviewed":true,"art_sha1":"9cf358fdec84abb332cc08622134394445ffb3c9","art_kind":"png","art_width":3635,"art_height":2340},"vol2:fig-elastic-flow":{"key":"vol2:fig-elastic-flow","figure_id":"fig-elastic-flow","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Elastic training recovery","status":"ready","treatment":"annotated","question":"What must change when a four-node training job resumes on three nodes?","scope":"The displayed 75% throughput assumes unchanged per-worker rate and feasible state placement; it is not a general elasticity guarantee.","regions":{"four":{"x":0.01,"y":0.01,"w":0.98,"h":0.3,"label":"Four-node initial ring"},"pause":{"x":0.01,"y":0.34,"w":0.98,"h":0.3,"label":"Failure and rendezvous"},"three":{"x":0.01,"y":0.67,"w":0.98,"h":0.31,"label":"Three-node resharded ring"}},"steps":[{"title":"Begin with balanced ownership","description":"The four-node ring distributes the data shards evenly and supplies the full illustrative throughput.","focus":["four"]},{"title":"Pause to re-establish consistent state","description":"When N3 fails, the remaining nodes rendezvous and reload. Removing a node without coordinating membership, ranks, and data state is not sufficient.","focus":["pause"]},{"title":"Resume with a new partition","description":"Three workers each take a one-third larger shard. The shown throughput falls to 75% only under the stated constant-rate assumption; model-state feasibility and batch semantics must also hold.","focus":["three"]}],"artwork_reviewed":true,"art_sha1":"6ee4798aa65a6b4fc1163b4e6cb9d2eec7886892","art_kind":"svg","art_width":1200,"art_height":985,"art_structural_sha1":"0f7bc40db95590014bfe545760422f696b45edff"},"vol2:fig-embedding-sharding":{"key":"vol2:fig-embedding-sharding","figure_id":"fig-embedding-sharding","source":"books/vol2/10_inference/10_inference.qmd","title":"Embedding sharding strategies","status":"ready","treatment":"annotated","question":"What does an embedding lookup transfer under each sharding layout?","scope":"The printed AllToAll and AllGather are realizations of these layouts, not collectives mandated by placement alone. A runtime can instead use shard RPCs; hot-row replication consumes extra capacity.","regions":{"region-1":{"x":0.03,"y":0.04,"w":0.29,"h":0.87,"label":"Row-wise sharding"},"region-2":{"x":0.36,"y":0.04,"w":0.27,"h":0.87,"label":"Column-wise sharding"},"region-3":{"x":0.68,"y":0.04,"w":0.29,"h":0.87,"label":"Hybrid hot-row layout"}},"steps":[{"title":"Split IDs across servers","description":"Row-wise sharding gives each server whole vectors for some IDs. AllToAll routes lookups and whole vectors to the servers that own them.","focus":["region-1"]},{"title":"Split each vector’s dimensions","description":"Column-wise sharding places a slice of every vector on each server. AllGather assembles the slices needed to recover a complete embedding.","focus":["region-2"]},{"title":"Replicate hot rows and shard the tail","description":"The hybrid panel duplicates hot rows while distributing cold rows. The printed AllToAll applies to the cold tail; the replicated hot portion consumes extra storage.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"632b5e518e06fdc78efc01c1a8c3e353f76ab1cc","art_kind":"svg","art_width":1200,"art_height":518,"art_structural_sha1":"632b5e518e06fdc78efc01c1a8c3e353f76ab1cc"},"vol2:fig-enclave":{"key":"vol2:fig-enclave","figure_id":"fig-enclave","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Secure enclave architecture","status":"ready","treatment":"annotated","question":"Which paths keep enclave keys and memory separate from the application processor?","scope":"This is the depicted Secure Enclave architecture, not a claim that every trusted execution environment uses these components.","regions":{"app":{"x":0.03,"y":0.09,"w":0.32,"h":0.23,"label":"Application processor and mailbox"},"enclave":{"x":0.03,"y":0.33,"w":0.68,"h":0.43,"label":"Secure Enclave boundary"},"dram":{"x":0.73,"y":0.09,"w":0.26,"h":0.43,"label":"Separate DRAM regions"},"keys":{"x":0.34,"y":0.52,"w":0.19,"h":0.23,"label":"Root keys and storage-key path"},"storage":{"x":0.3,"y":0.8,"w":0.69,"h":0.17,"label":"Storage AES and NAND"}},"steps":[{"title":"Enter through a mailbox","description":"The application processor communicates with the enclave through the mailbox rather than directly controlling its internal execution.","focus":["app","enclave"]},{"title":"Protect enclave memory","description":"Enclave DRAM passes through the memory protection engine. The diagram separates encrypted enclave memory from OS and application memory.","focus":["enclave","dram"]},{"title":"Keep keys on the protected path","description":"Root keys connect to the storage AES engine without passing through the application processor. The application processor therefore need not hold those storage keys.","focus":["keys"]},{"title":"Encrypt the storage transfer","description":"The storage AES engine writes encrypted data to NAND. This key-custody path is distinct from the enclave’s protected DRAM path.","focus":["storage"]}],"artwork_reviewed":true,"art_sha1":"0a7e54dfa96ce4498e3b1557dfe47d88f4d1c363","art_kind":"svg","art_width":1200,"art_height":706,"art_structural_sha1":"d9cd671ddf54462c0f7f8f27c191475d43d99008"},"vol2:fig-encryption2":{"key":"vol2:fig-encryption2","figure_id":"fig-encryption2","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Side-channel attack vulnerability","status":"ready","treatment":"annotated","question":"What can the captured traces reveal about a password comparison?","scope":"This is a recorded example; highlighted differences are observations, not a general password-recovery guarantee.","regions":{"prefix":{"x":0.02,"y":0.01,"w":0.57,"h":0.35,"label":"Accepted-prefix trace windows"},"mismatch":{"x":0.59,"y":0.01,"w":0.19,"h":0.35,"label":"First incorrect byte window"},"power":{"x":0.01,"y":0.36,"w":0.98,"h":0.49,"label":"Measured power trace"},"input":{"x":0.09,"y":0.88,"w":0.83,"h":0.11,"label":"Annotated input bytes"}},"steps":[{"title":"Locate the compared bytes","description":"The bottom annotation lists the supplied password bytes. Green and red annotations distinguish the prefix from the incorrect byte in this recording.","focus":["input"]},{"title":"Compare the marked windows","description":"The green windows cover earlier comparisons and the red window marks the first mismatch. They identify where the observed execution changes.","focus":["prefix","mismatch"]},{"title":"Read the physical signal cautiously","description":"The lower signal changes near the marked mismatch. The trace motivates constant-time comparison and physical leakage evaluation; one capture alone does not quantify recoverable information.","focus":["power"]}],"artwork_reviewed":true,"art_sha1":"2f9d6a3dfb958f2e106e9431996058166252a658","art_kind":"png","art_width":1654,"art_height":924},"vol2:fig-energy-gap":{"key":"vol2:fig-energy-gap","figure_id":"fig-energy-gap","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"The Energy Gap","status":"ready","treatment":"annotated","question":"Which parts of the data-center electricity trajectory are observations and scenarios?","scope":"LBNL history and 2030 scenarios describe national demand, not a measured generation-capacity ceiling or AI-only electricity consumption.","regions":{"history":{"x":0.13,"y":0.67,"w":0.44,"h":0.29,"label":"2014 and 2024 consumption"},"low":{"x":0.66,"y":0.49,"w":0.17,"h":0.43,"label":"2030 low projection"},"range":{"x":0.65,"y":0.13,"w":0.2,"h":0.38,"label":"2030 scenario range"},"reference":{"x":0.44,"y":0.06,"w":0.54,"h":0.38,"label":"Reference and high-case labels"}},"steps":[{"title":"Establish historical growth","description":"The solid bars rise from 58 TWh in 2014 to 192 TWh in 2024, about 3.3 times over ten years. These are US data-center totals.","focus":["history"]},{"title":"Mark projected demand","description":"The hatched 2030 column begins with the 521 TWh low bound. Its different fill separates projection from history.","focus":["low"]},{"title":"Keep the range visible","description":"The gray scenario range extends to 843 TWh, with the reference case at 649 TWh. The uncertainty is part of the planning evidence.","focus":["range","reference"]},{"title":"Plan infrastructure against the scenario","description":"The high-case annotation gives 15.3 percent of US electricity. It motivates checking generation, transmission, and connection capacity rather than treating the projection as an existing supply limit.","focus":["reference"]}],"artwork_reviewed":true,"art_sha1":"6ab1d0601f7a5efcda14ad5850e63e64a73b366f","art_kind":"png","art_width":3540,"art_height":2219},"vol2:fig-energy-intervention":{"key":"vol2:fig-energy-intervention","figure_id":"fig-energy-intervention","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Interventions and Their Accounting Boundaries","status":"ready","treatment":"annotated","question":"At which boundary does each sustainability intervention change the account?","scope":"The cascade is evaluated at fixed useful work. Independent improvement factors cannot simply be multiplied across mismatched boundaries.","regions":{"it":{"x":0.02,"y":0.01,"w":0.96,"h":0.31,"label":"Useful work, reduction, and IT execution"},"facility":{"x":0.53,"y":0.31,"w":0.45,"h":0.22,"label":"PUE and facility electricity"},"grid":{"x":0.02,"y":0.52,"w":0.96,"h":0.19,"label":"Grid factor and electricity carbon"},"life":{"x":0.02,"y":0.73,"w":0.96,"h":0.25,"label":"Embodied lifecycle addition"}},"steps":[{"title":"Reduce IT energy at fixed work","description":"Work reduction and execution efficiency feed the IT-energy box. Assess them while preserving the useful-work requirement.","focus":["it"]},{"title":"Account for facility overhead","description":"PUE transforms IT energy into facility energy. A chip-level improvement alone does not specify the facility total.","focus":["facility"]},{"title":"Apply the chosen electricity factor","description":"The grid factor converts facility electricity into operational emissions. It changes the carbon account without necessarily reducing electricity consumption.","focus":["grid"]},{"title":"Add hardware lifecycle emissions","description":"Embodied hardware carbon enters separately at the plus sign. The final lifecycle account combines terms with compatible boundaries.","focus":["life"]}],"artwork_reviewed":true,"art_sha1":"8d9e1d571f19eb211a8f5e29ef50a0e3c4aa5aef","art_kind":"svg","art_width":1200,"art_height":943,"art_structural_sha1":"f3fe954959fa33fa001a5d4c3ed683bd54c59530"},"vol2:fig-energy-roofline":{"key":"vol2:fig-energy-roofline","figure_id":"fig-energy-roofline","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Energy Roofline Model","status":"ready","treatment":"annotated","question":"Why is total-energy efficiency below the dominant-term roofline?","scope":"The stated 160 pJ/byte movement and 10 pJ/FLOP arithmetic coefficients define the example. Static and other system energy are omitted.","regions":{"movement":{"x":0.1,"y":0.11,"w":0.46,"h":0.72,"label":"Movement-dominated regime"},"cross":{"x":0.53,"y":0.08,"w":0.12,"h":0.82,"label":"16 FLOP/byte crossover"},"compute":{"x":0.64,"y":0.02,"w":0.34,"h":0.17,"label":"Arithmetic dominant-term bound"},"total":{"x":0.6,"y":0.16,"w":0.38,"h":0.2,"label":"Compute-plus-memory efficiency"}},"steps":[{"title":"Amortize movement over arithmetic","description":"At low arithmetic intensity, movement energy is the larger contribution. Reusing each moved byte across more FLOPs raises modeled FLOPs per joule.","focus":["movement"]},{"title":"Reach equal contributions","description":"At 16 FLOP/byte, compute and movement contribute equally. Keeping only the dominant term drops one of two equal costs.","focus":["cross"]},{"title":"Compare bound and complete dynamic sum","description":"The solid curve includes both terms and is half the dashed dominant-term bound at the crossover. Calling the dashed corner actual efficiency would overstate it.","focus":["total","cross"]},{"title":"Retain the arithmetic cost","description":"At high intensity the arithmetic term limits the dominant-term bound near 100 GFLOP/J. Additional static or system energy can lower efficiency further.","focus":["compute"]}],"artwork_reviewed":true,"art_sha1":"ded0e62230d91db798f1e35d10b48cf3a7eb826d","art_kind":"png","art_width":3838,"art_height":2280},"vol2:fig-energy-wall":{"key":"vol2:fig-energy-wall","figure_id":"fig-energy-wall","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Power and Energy Boundaries","status":"ready","treatment":"annotated","question":"Why does a feasible power draw not settle a run’s energy budget?","scope":"Both panels are schematic. Facility power caps and cumulative energy are different quantities and use different time boundaries.","regions":{"cap":{"x":0.03,"y":0.12,"w":0.4,"h":0.18,"label":"Grid cap and extra server"},"stack":{"x":0.03,"y":0.3,"w":0.4,"h":0.63,"label":"Server, IT, and facility power"},"integral":{"x":0.54,"y":0.26,"w":0.43,"h":0.65,"label":"Area under run power"},"time":{"x":0.57,"y":0.9,"w":0.39,"h":0.08,"label":"Job duration"}},"steps":[{"title":"Check the instantaneous ceiling","description":"The left red line limits power at one instant. Adding server N+1 can exceed the grid cap even if a longer-term energy budget remains.","focus":["cap"]},{"title":"Include facility overhead","description":"The brackets distinguish server power, IT power, and facility power. The grid feed supports the complete facility load, not only accelerator chips.","focus":["stack"]},{"title":"Integrate over the job","description":"The shaded right-hand area is total energy under P(t). Average power multiplied by job duration gives the same integral.","focus":["integral","time"]},{"title":"Keep the limits separate","description":"A job can stay under the instantaneous cap yet use substantial energy by running longer. Neither the cap nor duration alone determines the total.","focus":["cap","integral"]}],"artwork_reviewed":true,"art_sha1":"2e957f91cdf559fdc05d4555d406e5b3f2064650","art_kind":"svg","art_width":1200,"art_height":547,"art_structural_sha1":"82c7f5502a2fd4930d90595266cce9e7e8070999"},"vol2:fig-error-masking-ft":{"key":"vol2:fig-error-masking-ft","figure_id":"fig-error-masking-ft","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Error masking","status":"ready","treatment":"annotated","question":"Which fault effects does software-level injection omit?","scope":"This is an abstraction boundary for experiments, not a probability tree; no branch frequencies are shown.","regions":{"micro":{"x":0.03,"y":0.01,"w":0.94,"h":0.36,"label":"Hardware masking decision"},"software":{"x":0.03,"y":0.43,"w":0.94,"h":0.4,"label":"Software-visible masking decision"},"failure":{"x":0.05,"y":0.82,"w":0.3,"h":0.12,"label":"Unmasked failure"}},"steps":[{"title":"Ask whether corrupted state is read","description":"A soft error can be masked before software sees it: an unused component, overwritten value, or squashed speculation may prevent propagation.","focus":["micro"]},{"title":"Test the software-visible consequence","description":"If corrupted data is read, the effect can still be masked by a dead instruction, comparison, or uninfluential branch. Software fault injection starts below the first masking stage.","focus":["software"]},{"title":"Define the experiment’s coverage","description":"Only an unmasked effect reaches incorrect output or a crash in this diagram. Software-level injection cannot establish the hardware masking probability it bypasses.","focus":["failure"]}],"artwork_reviewed":true,"art_sha1":"386b858fffb2217ccf887832ac7b9bce21eb518c","art_kind":"svg","art_width":1200,"art_height":822,"art_structural_sha1":"62b08867f4708bc83d12d35d0066f5c630413d4b"},"vol2:fig-ethical-ai":{"key":"vol2:fig-ethical-ai","figure_id":"fig-ethical-ai","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Ethical AI Concerns","status":"ready","treatment":"annotated","question":"What evidence lets engineers assess infrastructure’s distributional burdens?","scope":"Telemetry supports assessment; it does not by itself resolve justice, equity, or resource-allocation decisions.","regions":{"justice":{"x":0.02,"y":0.02,"w":0.3,"h":0.32,"label":"Environmental justice"},"equity":{"x":0.34,"y":0.02,"w":0.3,"h":0.32,"label":"Intergenerational equity"},"resource":{"x":0.66,"y":0.02,"w":0.3,"h":0.32,"label":"Resource competition"},"records":{"x":0.02,"y":0.55,"w":0.94,"h":0.4,"label":"Missing per-model energy, carbon, water records"},"links":{"x":0.16,"y":0.34,"w":0.66,"h":0.22,"label":"Assessment depends on telemetry"}},"steps":[{"title":"Locate present local burdens","description":"Environmental justice names water withdrawal and grid strain. The question concerns who experiences the infrastructure’s resource demand.","focus":["justice"]},{"title":"Extend the boundary in time and use","description":"Intergenerational equity concerns persistent CO₂ and long-lived infrastructure; resource competition concerns agricultural and municipal claims on land, water, and minerals.","focus":["equity","resource"]},{"title":"Inspect the missing evidence","description":"Dashed undisclosed cells show absent per-model energy, carbon, and water records. Engineering acts directly by making these measurements auditable.","focus":["records"]},{"title":"Connect evidence to assessment","description":"The shared trunk feeds all three concerns. Telemetry is a prerequisite for assessing these burdens, while decisions still require participation and judgment.","focus":["links"]}],"artwork_reviewed":true,"art_sha1":"e308c1c182ebf4892d28aab98e3739a50e925d58","art_kind":"svg","art_width":1200,"art_height":519,"art_structural_sha1":"7f2949174fd7bb141a0a05a42de06cba3f5e8d19"},"vol2:fig-europe-energy-grid":{"key":"vol2:fig-europe-energy-grid","figure_id":"fig-europe-energy-grid","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"European Electricity Generation over One Week","status":"ready","treatment":"annotated","question":"Why must a deferrable job use a regional forecast rather than a fixed daily rule?","scope":"The figure is hourly EU generation for 20–26 November 2023. Generation mix is evidence about this week, not a marginal-emissions trace or a direct job-carbon calculation.","regions":{"base":{"x":0.1,"y":0.7,"w":0.73,"h":0.19,"label":"Near-flat nuclear base"},"windmax":{"x":0.46,"y":0.1,"w":0.13,"h":0.45,"label":"Thursday wind near 111 GW"},"windmin":{"x":0.72,"y":0.49,"w":0.11,"h":0.21,"label":"Sunday wind near 27 GW"},"fossil":{"x":0.1,"y":0.05,"w":0.72,"h":0.35,"label":"Load and residual fossil bands"},"solar":{"x":0.2,"y":0.29,"w":0.1,"h":0.28,"label":"Small midday solar bulge"}},"steps":[{"title":"Read the stable base","description":"The nuclear band stays near 70 GW across the week. Other resources and demand vary above that base.","focus":["base"]},{"title":"Inspect changes across days","description":"The navy wind band is widest around Thursday and much thinner on Sunday. The labeled 111 and 27 GW points show why one repeated daily pattern is inadequate.","focus":["windmax","windmin"]},{"title":"Keep demand and other supply in view","description":"The black load curve and upper fossil bands vary too. Wind alone does not determine fossil dispatch; other supply and exchanges also matter.","focus":["fossil","solar"]},{"title":"Use the evidence for scheduling carefully","description":"A flexible job needs a forecast for its actual region and week plus a suitable emissions signal. This historical generation plot cannot itself select a future lowest-carbon hour.","focus":["windmax","windmin"]}],"artwork_reviewed":true,"art_sha1":"f51fa129d120273f06353d1a8f9749daef64cbf6","art_kind":"png","art_width":3610,"art_height":2039},"vol2:fig-failure-domains":{"key":"vol2:fig-failure-domains","figure_id":"fig-failure-domains","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Hierarchy of failure domains","status":"ready","treatment":"annotated","question":"Why does replica placement need failure-domain boundaries?","scope":"The colored rack is one illustrative top-of-rack failure; domain sizes printed in the art are not a universal deployment topology.","regions":{"node":{"x":0.07,"y":0.34,"w":0.19,"h":0.51,"label":"Eight-GPU node"},"rack":{"x":0.04,"y":0.21,"w":0.44,"h":0.7,"label":"Failed rack"},"healthy":{"x":0.5,"y":0.21,"w":0.44,"h":0.7,"label":"Unaffected rack"},"domain":{"x":0.02,"y":0.1,"w":0.94,"h":0.85,"label":"Shared power and network domain"}},"steps":[{"title":"Locate the smallest shared enclosure","description":"The GPU cells share a node, so placing redundant state on two cells in that node does not isolate node-wide faults.","focus":["node"]},{"title":"Expand the blast radius to a rack","description":"The failed top-of-rack switch affects both depicted nodes in the red rack. The neighboring rack is outside that specific failure domain.","focus":["rack","healthy"]},{"title":"Check higher shared dependencies","description":"Both racks still lie inside a common power and network domain. Separating racks does not establish independence from every datacenter failure.","focus":["domain"]}],"artwork_reviewed":true,"art_sha1":"317b4fe51e19031948814003a7e00d0d7a7115fc","art_kind":"svg","art_width":1200,"art_height":536,"art_structural_sha1":"317b4fe51e19031948814003a7e00d0d7a7115fc"},"vol2:fig-failure-types":{"key":"vol2:fig-failure-types","figure_id":"fig-failure-types","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Fail-stop vs. Byzantine failures","status":"ready","treatment":"annotated","question":"Why can a live worker still corrupt a distributed computation?","scope":"The panels illustrate failure models; heartbeats establish liveness rather than numerical correctness.","regions":{"silence":{"x":0.01,"y":0.25,"w":0.46,"h":0.19,"label":"W2 silence and timeout"},"live":{"x":0.39,"y":0.12,"w":0.1,"h":0.66,"label":"Fail-stop liveness results"},"wrong":{"x":0.52,"y":0.25,"w":0.47,"h":0.19,"label":"W6 wrong gradients, live worker"}},"steps":[{"title":"Detect an absent participant","description":"W2 stops sending heartbeats. The timeout converts missing progress into a suspicion of failure, with a delay chosen by the detector.","focus":["silence"]},{"title":"Read the liveness result","description":"The fail-stop panel marks W2 unavailable while the other workers remain live. A timeout alone must still distinguish failure from slowness.","focus":["live"]},{"title":"Test values as well as presence","description":"W6 continues transmitting on schedule, so its liveness check stays green even after its gradients turn red. Correctness checks must cover the values used by the computation.","focus":["wrong"]}],"artwork_reviewed":true,"art_sha1":"d4dc7bd70b14f809aa5d0a282e41f1bd75061b70","art_kind":"svg","art_width":1200,"art_height":482,"art_structural_sha1":"05e0222343070928fe22e9b59270a54ae5aefd72"},"vol2:fig-fairness-example":{"key":"vol2:fig-fairness-example","figure_id":"fig-fairness-example","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Threshold-Dependent Fairness","status":"ready","treatment":"annotated","question":"What does a group-adapted decision threshold change in the printed approval example?","scope":"This constructed score example matches TPR only. Equal TPR does not establish every fairness criterion or a universally appropriate policy.","regions":{"region-1":{"x":0.01,"y":0.09,"w":0.98,"h":0.37,"label":"Uniform threshold panel"},"region-2":{"x":0.01,"y":0.5,"w":0.98,"h":0.18,"label":"Adapted A threshold"},"region-3":{"x":0.01,"y":0.68,"w":0.98,"h":0.18,"label":"Adapted B threshold"}},"steps":[{"title":"Compare the same cutoff across groups","description":"At the common 0.75 threshold, the shaded approval regions include three of four qualified A applicants but only one of four qualified B applicants. The printed TPRs are 75% and 25%.","focus":["region-1"]},{"title":"Keep subgroup A’s decision rule","description":"Panel (b) leaves A’s threshold at 0.75 and its TPR at 75%. The change is not a global lowering of every applicant’s cutoff.","focus":["region-2"]},{"title":"Change B’s approval boundary","description":"B’s threshold moves to 0.45, admitting three of four qualified B applicants and matching the illustrated TPR. Implementing such a rule requires subgroup information and evaluation of other outcomes and constraints.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"054672135ac3d8fe7b3fa358b62a622873ca243e","art_kind":"png","art_width":3950,"art_height":2439},"vol2:fig-fairness-impossibility":{"key":"vol2:fig-fairness-impossibility","figure_id":"fig-fairness-impossibility","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Conditional Fairness Trade-Offs","status":"ready","treatment":"annotated","question":"Under what conditions do the three score-based fairness criteria conflict?","scope":"This score-balance result is distinct from checking equalized odds at one binary decision threshold.","regions":{"region-1":{"x":0.11,"y":0.04,"w":0.31,"h":0.14,"label":"Unequal-base-rate assumptions"},"region-2":{"x":0.21,"y":0.42,"w":0.09,"h":0.22,"label":"Incompatible three-way intersection"},"region-3":{"x":0.71,"y":0.42,"w":0.09,"h":0.22,"label":"Exceptional-case intersection"}},"steps":[{"title":"Read the theorem’s conditions","description":"Panel (a) assumes unequal base rates and imperfect prediction. Both conditions matter before interpreting its empty central intersection.","focus":["region-1"]},{"title":"Identify the joint requirement","description":"The red hatched center marks simultaneous calibration within groups and balance within both outcome classes. Under panel (a)’s conditions, all three cannot hold together.","focus":["region-2"]},{"title":"Keep the exceptions explicit","description":"Panel (b) permits equal base rates or perfect prediction. Its green center indicates all three can hold in these exceptional cases, not that every trained model will satisfy them.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"6ba4d1a8e13298d66f98f2179bba8787830308dd","art_kind":"svg","art_width":1200,"art_height":495,"art_structural_sha1":"4894d1ff6a0404d15adf53ad9911032544e63be8"},"vol2:fig-fairness-metric-disagreement":{"key":"vol2:fig-fairness-metric-disagreement","figure_id":"fig-fairness-metric-disagreement","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Fairness Metric Disagreement Across Thresholds","status":"ready","treatment":"annotated","question":"Can one threshold make all three illustrated fairness violations small?","scope":"Metrics use synthetic scores and the evaluated nontrivial threshold range. This example is not the score-calibration impossibility theorem.","regions":{"region-1":{"x":0.29,"y":0.04,"w":0.49,"h":0.61,"label":"Metric curves and central thresholds"},"region-2":{"x":0.12,"y":0.18,"w":0.85,"h":0.68,"label":"Worst-case envelope"},"region-3":{"x":0.13,"y":0.65,"w":0.86,"h":0.25,"label":"Smallest worst-case gap"}},"steps":[{"title":"Compare definitions at the same threshold","description":"Equalized odds, demographic parity, and equal opportunity trace different violation curves. A threshold that improves one metric can leave another farther from zero.","focus":["region-1"]},{"title":"Track the largest violation","description":"The gray envelope follows the largest of the three violations at each threshold. It records the criterion that remains most violated for that operating point.","focus":["region-2"]},{"title":"Read the limit of this evaluated range","description":"The dotted line and open circle mark the smallest worst-case gap observed. The hatched band remains below every evaluated envelope value; always-positive and always-negative classifiers are outside the shown range.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"ff7414005507282f491f02773eed91cc132ce049","art_kind":"png","art_width":3671,"art_height":2125},"vol2:fig-fat-tree-detail":{"key":"vol2:fig-fat-tree-detail","figure_id":"fig-fat-tree-detail","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"Non-blocking fat-tree topology","status":"ready","treatment":"annotated","question":"How do leaf, spine, and core paths connect GPUs across pods?","scope":"This is the printed small topology with four core, eight spine, eight leaf switches and sixteen endpoints; its connectivity alone is not a universal bandwidth guarantee.","regions":{"leaf":{"x":0.03,"y":0.53,"w":0.78,"h":0.32,"label":"Leaf switches and GPU endpoints"},"spine":{"x":0.03,"y":0.3,"w":0.78,"h":0.14,"label":"Spine switches"},"core":{"x":0.08,"y":0.03,"w":0.68,"h":0.14,"label":"Core switches"},"path":{"x":0.02,"y":0.08,"w":0.8,"h":0.75,"label":"Highlighted cross-pod route"},"counts":{"x":0.86,"y":0.03,"w":0.13,"h":0.82,"label":"Tier and link counts"}},"steps":[{"title":"Enter at the leaf","description":"Each GPU endpoint enters the fabric through its leaf switch. Dashed pod boundaries group the leaf and spine resources.","focus":["leaf"]},{"title":"Use multiple upward paths","description":"Leaves connect to the spine tier rather than relying on a single uplink. These alternate paths distribute cross-pod traffic when routing and provisioning permit.","focus":["spine"]},{"title":"Cross the core","description":"The highlighted route climbs through a core switch and descends into a different pod. A cross-pod transfer consumes resources at multiple tiers.","focus":["core","path"]},{"title":"Check provisioning","description":"The right margin lists switches, endpoints, and links by tier. Nonblocking behavior requires suitable link capacities and routing, not merely a tree-shaped drawing.","focus":["counts"]}],"artwork_reviewed":true,"art_sha1":"69439c4d5be13633a445c14cd5fe505aebf907ec","art_kind":"svg","art_width":1200,"art_height":538,"art_structural_sha1":"69439c4d5be13633a445c14cd5fe505aebf907ec"},"vol2:fig-fault-tolerance-failure-spectrum":{"key":"vol2:fig-fault-tolerance-failure-spectrum","figure_id":"fig-fault-tolerance-failure-spectrum","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"The ML failure spectrum","status":"ready","treatment":"annotated","question":"How should the fleet response change with fault persistence?","scope":"Examples classify persistence, not a diagnosis from one failed attempt.","regions":{"transient":{"x":0.01,"y":0.17,"w":0.31,"h":0.8,"label":"Transient attempts and response"},"intermittent":{"x":0.34,"y":0.17,"w":0.31,"h":0.8,"label":"Intermittent attempts and response"},"permanent":{"x":0.67,"y":0.17,"w":0.31,"h":0.8,"label":"Permanent attempts and response"}},"steps":[{"title":"Recover after a one-time event","description":"A transient fault appears once, then later attempts succeed. Retry or rollback repairs affected execution state when the fault leaves no lasting defect.","focus":["transient"]},{"title":"Investigate faults that return under load","description":"The intermittent sequence fails again under load. Draining and stress-testing a suspect device addresses the recurring cause rather than repeatedly retrying production work.","focus":["intermittent"]},{"title":"Replace a persistently faulty component","description":"The permanent sequence keeps failing on retries. Replacement and restoration are appropriate when the physical defect remains.","focus":["permanent"]}],"artwork_reviewed":true,"art_sha1":"8662b7fd954429f0f6a471913557dcb0b54fea65","art_kind":"svg","art_width":1200,"art_height":521,"art_structural_sha1":"fa5d77b3fab59faefae2267a50a6cadab57511d6"},"vol2:fig-feature-parallel-pipeline":{"key":"vol2:fig-feature-parallel-pipeline","figure_id":"fig-feature-parallel-pipeline","source":"books/vol2/10_inference/10_inference.qmd","title":"Feature-parallel batching pipeline","status":"ready","treatment":"annotated","question":"How does one recommendation request combine sharded feature lookups?","scope":"Highlighted embedding rows are schematic lookups; this diagram does not specify measured communication or ranking latency.","regions":{"region-1":{"x":0.02,"y":0.34,"w":0.28,"h":0.3,"label":"Request feature split"},"region-2":{"x":0.34,"y":0.03,"w":0.26,"h":0.91,"label":"Sharded embedding tables"},"region-3":{"x":0.61,"y":0.17,"w":0.24,"h":0.61,"label":"Gather and ranking head"}},"steps":[{"title":"Route features by type","description":"The request reaches Feature split, which separates user, item, and context features. Each feature type can then address its embedding shards.","focus":["region-1"]},{"title":"Fetch the needed rows","description":"User, item, and context tables are distributed across shard 0 and shard 1. Dark rows identify the entries needed by this request, rather than scanning every row.","focus":["region-2"]},{"title":"Reassemble inputs for dense scoring","description":"Orange gather paths concatenate the retrieved embeddings into U, I, and C. The dense MLP ranking head consumes that assembled representation to produce ranked output.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"19d3739f9dae11f2e6ae65eb71cc8af4a49a2bc1","art_kind":"svg","art_width":1200,"art_height":501,"art_structural_sha1":"d75c56dc916a0d3625f85a469ec5f4c8df254613"},"vol2:fig-feature-store-architecture":{"key":"vol2:fig-feature-store-architecture","figure_id":"fig-feature-store-architecture","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Feature store architecture","status":"ready","treatment":"annotated","question":"Why does one feature definition feed two different stores?","scope":"Shared definitions support consistent semantics but do not guarantee historical availability or correct materialization by themselves.","regions":{"definition":{"x":0.22,"y":0.01,"w":0.23,"h":0.2,"label":"Shared feature definitions"},"material":{"x":0.22,"y":0.23,"w":0.21,"h":0.71,"label":"Materialization"},"offline":{"x":0.48,"y":0.2,"w":0.26,"h":0.36,"label":"Offline history and training scan"},"online":{"x":0.48,"y":0.62,"w":0.26,"h":0.32,"label":"Online latest values"},"consumers":{"x":0.81,"y":0.25,"w":0.18,"h":0.66,"label":"Training and serving consumers"}},"steps":[{"title":"Define meaning once","description":"Schema and transforms enter one materialization system. Batch and event-stream inputs can both supply features under that shared definition.","focus":["definition","material"]},{"title":"Keep training history","description":"The offline store retains history so a training scan can join features at the correct past timestamp. Throughput and historical availability govern this path.","focus":["offline"]},{"title":"Serve current entities","description":"The online store retains the latest value per key for point lookups. This path is organized around serving latency rather than full-history scans.","focus":["online"]},{"title":"Verify the contract","description":"Training and serving use different retrieval paths. Tests must check materialized values and point-in-time availability, not only matching definition names.","focus":["consumers"]}],"artwork_reviewed":true,"art_sha1":"55f9f97d8b1e441a1565afb1cdf135b08f3d69d9","art_kind":"svg","art_width":1200,"art_height":558,"art_structural_sha1":"9ce4b8cd6cf54d73a0ac3b8a74be022cfe62ea88"},"vol2:fig-federated-averaging-cycle":{"key":"vol2:fig-federated-averaging-cycle","figure_id":"fig-federated-averaging-cycle","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Federated averaging protocol","status":"ready","treatment":"annotated","question":"Which client updates actually enter one FedAvg round?","scope":"The diagram uses example-weighted aggregation of completed clients. It does not claim this objective is universally fair or that all invited clients finish.","regions":{"cohort":{"x":0.25,"y":0.08,"w":0.25,"h":0.15,"label":"Select cohort and broadcast"},"data":{"x":0.02,"y":0.26,"w":0.2,"h":0.62,"label":"Private client datasets"},"local":{"x":0.27,"y":0.23,"w":0.44,"h":0.58,"label":"Local epoch timelines"},"uploads":{"x":0.52,"y":0.24,"w":0.2,"h":0.56,"label":"Completed uploads"},"deadline":{"x":0.67,"y":0.24,"w":0.25,"h":0.64,"label":"Deadline and dropped straggler"},"aggregate":{"x":0.71,"y":0.08,"w":0.27,"h":0.15,"label":"Example-weighted aggregation"}},"steps":[{"title":"Invite and initialize","description":"The coordinator selects a cohort and broadcasts the round’s global model. Selection policy determines which population gets a chance to contribute.","focus":["cohort","data"]},{"title":"Compute on private data","description":"Each client runs local epochs on its own dataset. The unequal timeline lengths show that completion times need not match.","focus":["local"]},{"title":"Enforce the deadline","description":"Only completed uploads enter this round. Client 5 crosses the red deadline and is dropped, so its examples are absent from the round denominator.","focus":["uploads","deadline"]},{"title":"Weight the completed models","description":"The coordinator averages completed client models with weights based on their local example counts. A user-weighted objective would require a different declared aggregation rule.","focus":["aggregate"]}],"artwork_reviewed":true,"art_sha1":"3b890b2ee9c3711e4396099e621c35f080adb11d","art_kind":"svg","art_width":1200,"art_height":587,"art_structural_sha1":"b7a35b08fb8a94781744b402c648fc6354e5f239"},"vol2:fig-fl-communication-computation":{"key":"vol2:fig-fl-communication-computation","figure_id":"fig-fl-communication-computation","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Communication-computation trade-off in federated learning","status":"ready","treatment":"annotated","question":"Why does a slower network move the toy model’s preferred local-work setting?","scope":"The curves are an illustrative relative-cost model rather than measured convergence results. Their minima require later validation of drift, energy, and client coverage.","regions":{"fast":{"x":0.18,"y":0.58,"w":0.26,"h":0.17,"label":"Fast-network minimum at E = 10"},"medium":{"x":0.3,"y":0.46,"w":0.27,"h":0.17,"label":"Medium-network minimum at E = 20"},"slow":{"x":0.55,"y":0.33,"w":0.32,"h":0.18,"label":"Slow-network minimum at E = 40"},"left":{"x":0.12,"y":0.06,"w":0.2,"h":0.54,"label":"Communication-dominated low-work side"},"right":{"x":0.67,"y":0.35,"w":0.31,"h":0.24,"label":"Increasing excessive-local-work cost"},"shift":{"x":0.25,"y":0.77,"w":0.4,"h":0.1,"label":"Rightward minimum shift"}},"steps":[{"title":"Amortize expensive exchange","description":"At very little local work, repeated synchronization dominates the model, especially for the slow network. Increasing local epochs initially reduces that cost.","focus":["left"]},{"title":"Locate the fast-network minimum","description":"The dotted fast-network curve reaches its minimum at ten epochs. With cheap exchange, less local work is needed to amortize communication.","focus":["fast"]},{"title":"Move under slower communication","description":"The medium and slow curves place minima at twenty and forty epochs. The arrow summarizes this shift under the declared cost model.","focus":["medium","slow","shift"]},{"title":"Stop before local work dominates","description":"The curves eventually rise because additional local work carries cost and stands in for growing drift penalties. These toy minima do not replace deployment measurements.","focus":["right"]}],"artwork_reviewed":true,"art_sha1":"b8135f65bcc7309f71f33dabd6fb7f5c87af26a4","art_kind":"png","art_width":3116,"art_height":2131},"vol2:fig-flashattention-memory-savings":{"key":"vol2:fig-flashattention-memory-savings","figure_id":"fig-flashattention-memory-savings","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"FlashAttention memory savings","status":"ready","treatment":"annotated","question":"Why does eliminating the quadratic attention workspace matter more at long context?","scope":"The chart counts resident attention workspace for 32 FP16 heads. Its ratios are capacity comparisons, not HBM traffic ratios, total-model memory, or speedup.","regions":{"standard":{"x":0.2,"y":0.06,"w":0.75,"h":0.45,"label":"Quadratic standard-attention workspace"},"flash":{"x":0.19,"y":0.57,"w":0.76,"h":0.29,"label":"Linear FlashAttention workspace"},"at8k":{"x":0.42,"y":0.04,"w":0.18,"h":0.8,"label":"8K context capacity comparison"},"at64k":{"x":0.7,"y":0.04,"w":0.18,"h":0.75,"label":"64K context capacity comparison"},"freed":{"x":0.22,"y":0.46,"w":0.39,"h":0.19,"label":"Freed capacity between curves"}},"steps":[{"title":"Store the full scores","description":"The red standard-attention curve grows quadratically with sequence length because the full score matrix is resident in HBM.","focus":["standard"]},{"title":"Keep running statistics","description":"The blue FlashAttention curve grows linearly in this workspace accounting. Online softmax avoids materializing the full quadratic score matrix.","focus":["flash"]},{"title":"Compare at a fixed context","description":"At 8K tokens, the vertical comparison spans the two workspace requirements and is labeled 4,096 times smaller. This is a capacity ratio at one sequence length.","focus":["at8k"]},{"title":"Extend context without changing the metric","description":"At 64K the plotted ratio grows to 32,768. The freed capacity can support KV cache, activations, or batches, but the ratio is not a runtime prediction.","focus":["at64k","freed"]}],"artwork_reviewed":true,"art_sha1":"e3d17c93f87612aae2d622becb416b7bdb1b17c6","art_kind":"png","art_width":3537,"art_height":2099},"vol2:fig-fleet-law-step":{"key":"vol2:fig-fleet-law-step","figure_id":"fig-fleet-law-step","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Anatomy of a Fleet Law step","status":"ready","treatment":"annotated","question":"Why does doubling devices fail to halve the illustrated step time?","scope":"Bar lengths are illustrative, not measurements. Overlap removes only time concurrent with useful computation.","regions":{"region-1":{"x":0.21,"y":0.12,"w":0.76,"h":0.38,"label":"N-device step and overlap"},"region-2":{"x":0.21,"y":0.56,"w":0.26,"h":0.16,"label":"2N-device local compute"},"region-3":{"x":0.58,"y":0.51,"w":0.26,"h":0.35,"label":"Ideal boundary and residual overhead"}},"steps":[{"title":"Read the whole step","description":"For N devices, compute overlaps part of communication. The lower bracket spans the actual step through the end of synchronization; it is longer than the compute bar alone.","focus":["region-1"]},{"title":"Halve only local computation","description":"At 2N devices, the blue compute bar is half as long. The communication and synchronization terms have not halved with it.","focus":["region-2"]},{"title":"Locate the remaining gap","description":"The dashed line marks half the original step. The hatched part of the new step lies beyond that ideal, showing the residual cost after overlap.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"02076dea097ab4252fbeabbc70d6e317f5b7b0ea","art_kind":"svg","art_width":1200,"art_height":611,"art_structural_sha1":"a8807a2b4217d4834816eb5814737835cc82bbf9"},"vol2:fig-fleet-orchestration-capacity-reservation":{"key":"vol2:fig-fleet-orchestration-capacity-reservation","figure_id":"fig-fleet-orchestration-capacity-reservation","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Capacity reservation tiers and portfolio optimization","status":"ready","treatment":"annotated","question":"Why combine reserved, on-demand, and spot capacity?","scope":"The one-day demand curve is constructed, not a measured demand trace or an optimal purchasing prescription.","regions":{"base":{"x":0.09,"y":0.48,"w":0.66,"h":0.45,"label":"Reserved base load"},"burst":{"x":0.22,"y":0.2,"w":0.35,"h":0.32,"label":"On-demand demand band"},"spot":{"x":0.25,"y":0.09,"w":0.26,"h":0.2,"label":"Spot demand peak"},"idle":{"x":0.49,"y":0.37,"w":0.26,"h":0.22,"label":"Reserved but idle capacity"}},"steps":[{"title":"Cover predictable load","description":"The blue reserved region covers steady demand up to the reserved level. Reservation commits capacity even when instantaneous demand falls.","focus":["base"]},{"title":"Handle waiting-tolerant bursts","description":"The yellow band serves demand above the base with on-demand capacity. The workload must tolerate the relevant acquisition and queueing behavior.","focus":["burst"]},{"title":"Use interruptible capacity selectively","description":"The green peak is assigned to restart-tolerant work on spot resources. Its lower price comes with interruption risk.","focus":["spot"]},{"title":"Expose idle commitments","description":"The hatched region lies below the reservation line but above demand. Purchased capacity is not necessarily useful work.","focus":["idle"]}],"artwork_reviewed":true,"art_sha1":"f4a56991c1b786e4443ec41e5c1b90eb35c18e55","art_kind":"svg","art_width":1200,"art_height":488,"art_structural_sha1":"b380a60702a9ace06a1cf83d137ddab412bbaf96"},"vol2:fig-fleet-orchestration-elastic-state-machine":{"key":"vol2:fig-fleet-orchestration-elastic-state-machine","figure_id":"fig-fleet-orchestration-elastic-state-machine","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Elastic training worker lifecycle and state machine","status":"ready","treatment":"annotated","question":"Why does elastic training require coordinated state transitions?","scope":"Transitions show lifecycle dependencies, not measured transition durations or a promise of interruption-free resizing.","regions":{"active":{"x":0.34,"y":0.36,"w":0.33,"h":0.23,"label":"Active training group"},"up":{"x":0.01,"y":0.03,"w":0.29,"h":0.19,"label":"Scale up"},"down":{"x":0.72,"y":0.03,"w":0.28,"h":0.19,"label":"Scale down"},"replace":{"x":0.34,"y":0.79,"w":0.33,"h":0.2,"label":"Replace failed worker"}},"steps":[{"title":"Maintain one active group","description":"Active training uses N ranks and an AllReduce every step. Membership changes must preserve a coherent collective group.","focus":["active"]},{"title":"Admit new capacity","description":"The scale-up path starts with idle GPUs and returns only after rebuilding the group. Capacity availability alone does not make new ranks ready.","focus":["up"]},{"title":"Release capacity safely","description":"Scale-down releases workers under preemption. The return path requires rank release to finish.","focus":["down"]},{"title":"Replace an unhealthy participant","description":"A host timeout or ECC event triggers replacement. After any required process restart, the application must restore valid training state and coordinate the healthy spare’s membership before resuming; a reclaim deadline can force this path too.","focus":["replace"]}],"artwork_reviewed":true,"art_sha1":"cfd8468b61d03a5ab2afa9053c2cf5a7237b39a4","art_kind":"svg","art_width":1200,"art_height":537,"art_structural_sha1":"1307cd8952e411c8b40d9ddf8c8658923bb870c1"},"vol2:fig-fleet-orchestration-hierarchical-placement":{"key":"vol2:fig-fleet-orchestration-hierarchical-placement","figure_id":"fig-fleet-orchestration-hierarchical-placement","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Hierarchical placement for 3D parallelism","status":"ready","treatment":"annotated","question":"Which parallelism should cross each level of the fleet network?","scope":"The illustrated hierarchy is a workload-specific placement strategy, not a guarantee for every model or fabric.","regions":{"tp":{"x":0.01,"y":0.43,"w":0.15,"h":0.44,"label":"Tensor parallelism inside a node"},"pp":{"x":0.04,"y":0.42,"w":0.43,"h":0.45,"label":"Pipeline stages within a rack"},"dp":{"x":0.23,"y":0.01,"w":0.57,"h":0.28,"label":"Data-parallel gradient exchange across racks"}},"steps":[{"title":"Keep frequent exchanges closest","description":"Tensor-parallel groups occupy the node’s NVLink domain. Frequent layer-level exchanges use the fastest drawn interconnect.","focus":["tp"]},{"title":"Join pipeline stages locally","description":"Pipeline stages span nodes under the same leaf switch. Stage-boundary traffic uses rack-level links.","focus":["pp"]},{"title":"Use the outer tier deliberately","description":"Data-parallel replicas exchange gradients across the spine once per step in this example. Less frequent synchronization is assigned to the oversubscribed tier.","focus":["dp"]}],"artwork_reviewed":true,"art_sha1":"21509c3fcbb7beb63f38b5cdcb4204e952858aeb","art_kind":"svg","art_width":1200,"art_height":533,"art_structural_sha1":"b1cc07c95133e585ee5afd149ca3854b716e3889"},"vol2:fig-fleet-orchestration-scaling-efficiency-curve":{"key":"vol2:fig-fleet-orchestration-scaling-efficiency-curve","figure_id":"fig-fleet-orchestration-scaling-efficiency-curve","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Modeled scaling efficiency and elastic operating range","status":"ready","treatment":"annotated","question":"Why can scaling throughput improve while scaling efficiency falls?","scope":"The plotted job model fixes workload and parallelism assumptions. The shaded admission interval is an assumed policy, not an efficiency-derived feasibility bound.","regions":{"small":{"x":0.12,"y":0.08,"w":0.3,"h":0.35,"label":"Smaller modeled GPU counts"},"window":{"x":0.4,"y":0.03,"w":0.22,"h":0.42,"label":"Assumed policy window"},"large":{"x":0.62,"y":0.09,"w":0.24,"h":0.35,"label":"Lower efficiency at large scale"},"costs":{"x":0.12,"y":0.59,"w":0.74,"h":0.35,"label":"Modeled step-time losses"}},"steps":[{"title":"Read the efficiency measure","description":"Efficiency is below ideal linear scaling even at smaller GPU counts. It describes throughput per allocated GPU relative to the scaling reference.","focus":["small"]},{"title":"Separate admission from efficiency","description":"The shaded 256-to-1,024-GPU interval is an assumed policy window. The efficiency curve alone does not determine its endpoints.","focus":["window"]},{"title":"Inspect growing coordination costs","description":"The lower panel separates tensor-parallel communication, pipeline bubbles, and exposed gradient synchronization. Their relative shares explain the modeled efficiency decline.","focus":["costs"]},{"title":"Do not confuse efficiency with total throughput","description":"At larger scale each GPU can contribute less efficiently while the fleet still completes more work per unit time. A falling efficiency curve alone does not establish negative scaling.","focus":["large"]}],"artwork_reviewed":true,"art_sha1":"aaebb5330ec03bc2e31b3fa8252e06367866548f","art_kind":"png","art_width":3643,"art_height":3300},"vol2:fig-fleet-orchestration-scheduling-tradeoffs":{"key":"vol2:fig-fleet-orchestration-scheduling-tradeoffs","figure_id":"fig-fleet-orchestration-scheduling-tradeoffs","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Scheduling trade-offs across competing fleet objectives","status":"ready","treatment":"annotated","question":"Why can a scheduler not optimize every objective independently?","scope":"The sketches illustrate policy tensions; they are not measured scheduler comparisons.","regions":{"throughput":{"x":0.34,"y":0.01,"w":0.33,"h":0.31,"label":"Throughput objective"},"cost":{"x":0.01,"y":0.33,"w":0.32,"h":0.31,"label":"Cost objective"},"fair":{"x":0.68,"y":0.33,"w":0.32,"h":0.31,"label":"Fairness objective"},"latency":{"x":0.34,"y":0.68,"w":0.33,"h":0.31,"label":"Latency objective"}},"steps":[{"title":"Keep a gang running","description":"The throughput sketch leaves the large gang unbroken. That choice can delay smaller jobs.","focus":["throughput"]},{"title":"Accept interruptions for cost","description":"Spot capacity reduces purchase cost but introduces preemption and recovery overhead.","focus":["cost"]},{"title":"Honor resource shares","description":"The fairness sketch preserves a team’s share even when it is idle. Entitlement and peak utilization need not coincide.","focus":["fair"]},{"title":"Serve short jobs quickly","description":"The latency sketch inserts small jobs early. The resulting gaps can make it harder to place a later large gang.","focus":["latency"]}],"artwork_reviewed":true,"art_sha1":"756375a9f351535cfa374563698bccc187e1dd05","art_kind":"svg","art_width":1200,"art_height":668,"art_structural_sha1":"bc17987eef9241ebb8963ce2cd30382cbedee8b3"},"vol2:fig-fleet-orchestration-slurm-vs-k8s":{"key":"vol2:fig-fleet-orchestration-slurm-vs-k8s","figure_id":"fig-fleet-orchestration-slurm-vs-k8s","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Architectural paradigms: Slurm vs. Kubernetes","status":"ready","treatment":"annotated","question":"How do imperative job allocation and declarative reconciliation differ?","scope":"These are schematic control paths, not complete descriptions of all Slurm or Kubernetes features.","regions":{"slurm":{"x":0.01,"y":0.01,"w":0.45,"h":0.96,"label":"Slurm job allocation"},"desired":{"x":0.58,"y":0.01,"w":0.4,"h":0.4,"label":"Kubernetes desired state"},"reconcile":{"x":0.53,"y":0.43,"w":0.46,"h":0.54,"label":"Observed state and controllers"}},"steps":[{"title":"Allocate an explicit job","description":"The Slurm path takes a job script through the global scheduler to node daemons. The illustrated job receives all nodes together or waits.","focus":["slurm"]},{"title":"Declare a target state","description":"The Kubernetes API stores desired state alongside observed state. The example target has four pods while only three are observed.","focus":["desired"]},{"title":"Act on the difference","description":"Controllers watch the state gap and recreate the failed pod. Reconciliation is an ongoing loop rather than a single allocation instruction.","focus":["reconcile"]}],"artwork_reviewed":true,"art_sha1":"54b54ebebace30de70398606c18b9c4852e31f3b","art_kind":"svg","art_width":1200,"art_height":629,"art_structural_sha1":"c24b191fa0970b0fdbf8aaeed8b75771ee9ba07c"},"vol2:fig-fleet-orchestration-topology-hierarchy":{"key":"vol2:fig-fleet-orchestration-topology-hierarchy","figure_id":"fig-fleet-orchestration-topology-hierarchy","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Physical topology hierarchy and bandwidth cliffs","status":"ready","treatment":"annotated","question":"Why does the scheduler need the hierarchy of links above each GPU?","scope":"Bandwidth labels are the figure’s directional budgets; pod oversubscription depends on the illustrated provisioning.","regions":{"node":{"x":0.05,"y":0.27,"w":0.49,"h":0.63,"label":"Node NVSwitch domain"},"rack":{"x":0.03,"y":0.15,"w":0.71,"h":0.79,"label":"Rack leaf-switch domain"},"pod":{"x":0.01,"y":0.01,"w":0.97,"h":0.13,"label":"Pod spine-switch bandwidth budget"}},"steps":[{"title":"Prefer the closest domain","description":"The eight GPUs share an NVSwitch domain. Their local communication budget is larger than the enclosing network tiers.","focus":["node"]},{"title":"Cross a leaf-switch boundary","description":"Other nodes share a rack-level leaf path. Placement that spills beyond the node changes the communication resource used.","focus":["rack"]},{"title":"Account for shared uplinks","description":"The outer pod crosses spine switches with oversubscribed endpoint budgets. A feasible GPU count can still produce an unfavorable communication placement.","focus":["pod"]}],"artwork_reviewed":true,"art_sha1":"f0ea0e96c84ac2bd7dd5f2a8ce2e9025233b777f","art_kind":"svg","art_width":1200,"art_height":498,"art_structural_sha1":"f0ea0e96c84ac2bd7dd5f2a8ce2e9025233b777f"},"vol2:fig-fleet-orchestration-training-serving-diurnal":{"key":"vol2:fig-fleet-orchestration-training-serving-diurnal","figure_id":"fig-fleet-orchestration-training-serving-diurnal","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Training vs. serving diurnal GPU capacity shift","status":"ready","treatment":"annotated","question":"How can a serving reservation release capacity for training without consuming its surge buffer?","scope":"The daily shape is illustrative and anchored to the chapter notebook; transfer and restart costs are not simulated.","regions":{"demand":{"x":0.48,"y":0.7,"w":0.27,"h":0.12,"label":"Serving demand label and green region"},"buffer":{"x":0.15,"y":0.63,"w":0.18,"h":0.12,"label":"Surge buffer near the demand trough"},"reclaim":{"x":0.15,"y":0.35,"w":0.25,"h":0.24,"label":"Reclaimed capacity near the demand trough"},"base":{"x":0.12,"y":0.01,"w":0.86,"h":0.2,"label":"Fixed training base and maintenance headroom"},"buffer_noon":{"x":0.54,"y":0.35,"w":0.14,"h":0.13,"label":"Surge buffer near peak demand"}},"steps":[{"title":"Reserve for live demand","description":"The green area is serving demand. It changes over the illustrative day while remaining below the static serving reservation.","focus":["demand"]},{"title":"Retain the safety margin","description":"The hatched band adds the same declared surge buffer above demand at the trough and near the peak. Reclaiming this band would change the serving-availability assumption.","focus":["buffer","buffer_noon"]},{"title":"Return only the remaining capacity","description":"Near the demand trough, the blue gap between buffered serving demand and the dashed reservation is large. This reclaimable capacity shrinks toward the peak; it excludes the hatched surge buffer.","focus":["reclaim"]},{"title":"Account for the whole fleet","description":"The upper panel retains the fixed training base and explicitly names maintenance headroom. The broken axis compresses the view without creating extra GPUs.","focus":["base"]}],"artwork_reviewed":true,"art_sha1":"8d9494902cd0480a45024e768c48987f05b92206","art_kind":"png","art_width":3708,"art_height":2318},"vol2:fig-fleet-stack":{"key":"vol2:fig-fleet-stack","figure_id":"fig-fleet-stack","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The Fleet Stack","status":"ready","treatment":"annotated","question":"How do lower fleet-stack decisions constrain deployment and governance?","scope":"This stack is an organizing map, not an execution timeline or a claim that lower layers determine every policy.","regions":{"region-1":{"x":0.1,"y":0.76,"w":0.86,"h":0.2,"label":"Infrastructure band"},"region-2":{"x":0.13,"y":0.52,"w":0.8,"h":0.2,"label":"Distribution band"},"region-3":{"x":0.16,"y":0.28,"w":0.74,"h":0.2,"label":"Serving band"},"region-4":{"x":0.19,"y":0.05,"w":0.68,"h":0.19,"label":"Governance band"}},"steps":[{"title":"Establish the physical substrate","description":"Facility & Accelerators and Fabric & Storage provide power, cooling, HBM, topology, bandwidth, and storage tiers. Upper layers must operate within these capabilities.","focus":["region-1"]},{"title":"Distribute and recover execution","description":"Distributed Execution supplies parallelism and collectives. Reliability & Control supplies checkpointing, recovery, and scheduling so distributed work can continue usefully.","focus":["region-2"]},{"title":"Operate requests and releases","description":"Runtime & Serving contains kernels, batching, routing, and edge operation. Operations adds SLOs, monitoring, drift detection, and release processes.","focus":["region-3"]},{"title":"Set assurance and operating obligations","description":"Assurance and Governance & Sustainability connect security, privacy, robustness, policy, audit, and carbon budgets. Their requirements must be implemented through the lower bands.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"d634053bf7f91245e8bd01055f09da9a39768b4a","art_kind":"svg","art_width":1200,"art_height":761,"art_structural_sha1":"ee3b7d23339ebf00d64d4975f65ff4c8ae75b189"},"vol2:fig-fleet-stack-conclusion":{"key":"vol2:fig-fleet-stack-conclusion","figure_id":"fig-fleet-stack-conclusion","source":"books/vol2/17_conclusion/17_conclusion.qmd","title":"The Fleet Stack Revisited","status":"ready","treatment":"annotated","question":"Where do the six fleet principles apply in the stack?","scope":"The arrow indicates scale-induced change across all bands and is not a seventh principle. Responsibility and sustainability divide governance by obligation.","regions":{"infrastructure":{"x":0.24,"y":0.75,"w":0.34,"h":0.19,"label":"Infrastructure territory"},"execution":{"x":0.24,"y":0.62,"w":0.34,"h":0.1,"label":"Distributed execution territory"},"reliability":{"x":0.24,"y":0.51,"w":0.34,"h":0.1,"label":"Reliability and control territory"},"serving":{"x":0.24,"y":0.29,"w":0.34,"h":0.19,"label":"Serving territory"},"responsibility":{"x":0.24,"y":0.06,"w":0.16,"h":0.19,"label":"Governance and assurance responsibility"},"sustainability":{"x":0.4,"y":0.06,"w":0.18,"h":0.1,"label":"Sustainability resource obligation"},"scale":{"x":0.04,"y":0.06,"w":0.04,"h":0.88,"label":"Scale creates qualitative change"},"assurance":{"x":0.24,"y":0.15,"w":0.34,"h":0.1,"label":"Assurance row within responsibility"}},"steps":[{"title":"Start with capability","description":"Infrastructure owns Facility and Accelerators together with Fabric and Storage. FLOP/s, bandwidth, and rack power constrain what the fleet can execute.","focus":["infrastructure"]},{"title":"Separate execution from recovery","description":"Distribution contains communication can dominate and failure is routine as distinct row-level principles. Exposed communication time and recovery overhead answer different questions.","focus":["execution","reliability"]},{"title":"Keep the serving contract","description":"The Serving territory covers runtime, serving, and operations. Its p99-within-SLO metric evaluates delivered service rather than raw token rate alone.","focus":["serving"]},{"title":"Distinguish governance obligations","description":"Responsibility covers Assurance and the governance half of the top row. Sustainability occupies the resource half with energy-per-query and carbon metrics.","focus":["responsibility","assurance","sustainability"]},{"title":"Read the scale premise","description":"The vertical arrow spans every band because scale changes the behavior of the whole stack. It connects the six territories without adding another principle.","focus":["scale"]}],"artwork_reviewed":true,"art_sha1":"5673e8d88a4a1d9360322b9a5137f5989117471c","art_kind":"svg","art_width":1200,"art_height":692,"art_structural_sha1":"38b65f27e34f5b8d49fe04740372bfd6ca9a7f01"},"vol2:fig-flops-per-watt-trend":{"key":"vol2:fig-flops-per-watt-trend","figure_id":"fig-flops-per-watt-trend","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Peak Arithmetic per Watt over Time","status":"ready","treatment":"annotated","question":"What does a peak-throughput-per-watt trend establish about accelerator efficiency?","scope":"The observations are dense FP16 peak throughput divided by published TDP, not measured energy for a shared application; the fitted trend is descriptive.","regions":{"early":{"x":0.11,"y":0.39,"w":0.15,"h":0.3,"label":"V100 and early observations"},"later":{"x":0.47,"y":0.12,"w":0.4,"h":0.39,"label":"Later vendor observations and labeled GPUs"},"fit":{"x":0.12,"y":0.18,"w":0.83,"h":0.5,"label":"Dashed fitted trend"},"legend":{"x":0.11,"y":0.02,"w":0.29,"h":0.31,"label":"Vendor legend"}},"steps":[{"title":"Read the comparison contract","description":"Marker colors identify vendors, while the logarithmic vertical axis reports dense FP16 TFLOP/s per watt. Product ratios need consistent precision and power conventions.","focus":["legend"]},{"title":"Inspect the labeled GPU sequence","description":"V100, A100, H100, and B200 are circled references within a larger device sample. They do not constitute a controlled workload-energy experiment.","focus":["early","later"]},{"title":"Distinguish trend from outcome","description":"The dashed line summarizes the sample with a least-squares fit. It describes peak arithmetic efficiency over release dates, not a guarantee that every workload or future device follows it.","focus":["fit"]}],"artwork_reviewed":true,"art_sha1":"6f536aa7defaa57ad897f0d9935dba7c7a1f1ea9","art_kind":"png","art_width":3766,"art_height":2142},"vol2:fig-fragmentation-problem":{"key":"vol2:fig-fragmentation-problem","figure_id":"fig-fragmentation-problem","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"The fragmentation problem","status":"ready","treatment":"annotated","question":"Why can a cluster have enough free GPUs and still reject a job?","scope":"This is an unchanged allocation snapshot. No defragmentation or migration is simulated, and the pending job requires one whole node.","regions":{"request":{"x":0.1,"y":0.01,"w":0.72,"h":0.1,"label":"Pending full-node request"},"top":{"x":0.1,"y":0.18,"w":0.72,"h":0.25,"label":"Free slots in nodes 0 through 2"},"bottom":{"x":0.1,"y":0.47,"w":0.72,"h":0.41,"label":"Free slots in nodes 3 through 7"},"total":{"x":0.85,"y":0.87,"w":0.15,"h":0.09,"label":"Aggregate free count"}},"steps":[{"title":"Read the placement requirement","description":"The queued job needs eight GPUs on one node. Eight arbitrary free slots across the cluster would not satisfy its constraint.","focus":["request"]},{"title":"Inspect the scattered gaps","description":"Dashed cells mark free GPUs, but active blue jobs occupy part of every node. None of the rows can host the requested gang.","focus":["top","bottom"]},{"title":"Contrast quantity with feasibility","description":"The total reports 19 free GPUs, roughly 30 percent of capacity. That aggregate exceeds eight but does not establish a feasible placement.","focus":["total"]}],"artwork_reviewed":true,"art_sha1":"7a9b09e141258488ef0f54627252ff71d8b9e13c","art_kind":"png","art_width":3676,"art_height":2164},"vol2:fig-fusion-before-after":{"key":"vol2:fig-fusion-before-after","figure_id":"fig-fusion-before-after","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Operator fusion before and after","status":"ready","treatment":"annotated","question":"Which activation transfers disappear when these operators fuse?","scope":"The figure counts activation transfers only; weights and small vectors are omitted, and equal transfer counts need not mean equal byte counts.","regions":{"unfused":{"x":0.01,"y":0.01,"w":0.98,"h":0.1,"label":"Unfused six-transfer count"},"intermediates":{"x":0.29,"y":0.13,"w":0.52,"h":0.17,"label":"HBM intermediates Z1 and Z2"},"separate":{"x":0.07,"y":0.36,"w":0.89,"h":0.17,"label":"Three separate kernels"},"fusedhbm":{"x":0.06,"y":0.64,"w":0.9,"h":0.16,"label":"Fused HBM endpoints"},"onchip":{"x":0.06,"y":0.82,"w":0.89,"h":0.17,"label":"Fused on-chip pipeline"}},"steps":[{"title":"Read the unfused path","description":"Linear, GELU, and LayerNorm execute as separate kernels. The path reads X and writes Y, and also writes and rereads both intermediates.","focus":["unfused","separate"]},{"title":"Materialize the middle values","description":"Z1 and Z2 cross the HBM boundary between their producers and consumers. These four intermediate transfers are the red paths.","focus":["intermediates"]},{"title":"Keep intermediates on chip","description":"In the fused kernel, the same operator sequence passes Z1 and Z2 on chip. The dashed HBM boxes explicitly show that those intermediates are not materialized there.","focus":["onchip","fusedhbm"]},{"title":"Interpret the saving","description":"Only the activation read of X and write of Y remain at the drawn HBM boundary. This is a traffic mechanism, not a proportional speedup guarantee.","focus":["fusedhbm"]}],"artwork_reviewed":true,"art_sha1":"9f961ac1326d829ef36b138b9c7342378524420b","art_kind":"svg","art_width":1200,"art_height":837,"art_structural_sha1":"fec97905da149e68dac28ead0e61cf1e909bfb68"},"vol2:fig-gang-scheduling-deadlock":{"key":"vol2:fig-gang-scheduling-deadlock","figure_id":"fig-gang-scheduling-deadlock","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"The distributed deadlock (hold and wait)","status":"ready","treatment":"annotated","question":"Why must a distributed job acquire its workers together?","scope":"The two eight-GPU jobs illustrate allocation deadlock; the guide does not claim gang scheduling solves every scheduling failure.","regions":{"holds":{"x":0.01,"y":0.12,"w":0.45,"h":0.72,"label":"Partial holds and circular wait"},"gang":{"x":0.54,"y":0.12,"w":0.45,"h":0.72,"label":"Atomic gang allocations"},"wait":{"x":0.57,"y":0.1,"w":0.34,"h":0.13,"label":"J2 waits without holding GPUs"}},"steps":[{"title":"Hold unusable partial allocations","description":"On the left, J1 and J2 each hold four of the eight required GPUs. Neither can start, yet neither releases its partial allocation.","focus":["holds"]},{"title":"Wait without reserving fragments","description":"On the right, J2 waits while holding zero GPUs. Free resources remain available to complete a runnable gang.","focus":["wait"]},{"title":"Run complete allocations","description":"J1 receives all eight GPUs, then J2 receives all eight after J1 finishes. Atomic placement prevents the illustrated circular hold-and-wait.","focus":["gang"]}],"artwork_reviewed":true,"art_sha1":"e3e24754da3a9c0a68d922ea1a1f2dbba7dcf260","art_kind":"svg","art_width":1200,"art_height":512,"art_structural_sha1":"51441d77913c7062f92aef073237d0697d1fd3d7"},"vol2:fig-gds-path":{"key":"vol2:fig-gds-path","figure_id":"fig-gds-path","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"Traditional vs. GPUDirect Storage path","status":"ready","treatment":"annotated","question":"Which bytes and control operations does GPUDirect Storage change?","scope":"Panel a is the particular buffered baseline drawn, not every conventional I/O configuration. Routes encode payload paths, not transfer timing.","regions":{"buffer":{"x":0.22,"y":0.1,"w":0.24,"h":0.28,"label":"Host bounce buffers and CPU copy"},"hops":{"x":0.01,"y":0.37,"w":0.45,"h":0.57,"label":"Two buffered DMA hops"},"direct":{"x":0.53,"y":0.42,"w":0.44,"h":0.52,"label":"Direct NVMe-to-HBM DMA"},"control":{"x":0.52,"y":0.12,"w":0.14,"h":0.66,"label":"CPU control remains"}},"steps":[{"title":"Stage the buffered payload","description":"DMA 1 brings NVMe payload into the kernel buffer in host DRAM. The CPU copies it to a pinned buffer before the next DMA.","focus":["buffer","hops"]},{"title":"Reach the GPU","description":"DMA 2 transfers the pinned payload into GPU HBM. Both green hops carry payload through the same PCIe switching fabric.","focus":["hops"]},{"title":"Bypass host payload storage","description":"The GDS panel routes NVMe payload directly to GPU HBM. Removing the host bounce stage changes byte movement.","focus":["direct"]},{"title":"Retain orchestration","description":"The dashed CPU control link still submits and completes I/O. A direct payload path does not mean the host and software control path disappear.","focus":["control"]}],"artwork_reviewed":true,"art_sha1":"eebf08c9a0a242652d5c3ab5eabed84924bc4b2d","art_kind":"svg","art_width":1200,"art_height":503,"art_structural_sha1":"63c5f2a97100565f7fc427c5433c0ec90eee5c6b"},"vol2:fig-gender-shades-audit":{"key":"vol2:fig-gender-shades-audit","figure_id":"fig-gender-shades-audit","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Audit and Re-Audit","status":"ready","treatment":"annotated","question":"What can an audit and re-audit reveal that an aggregate accuracy number hides?","scope":"These are reported subgroup measurements on the Pilot Parliaments Benchmark. Before/after observations do not isolate why a system changed.","regions":{"region-1":{"x":0.01,"y":0.03,"w":0.97,"h":0.32,"label":"IBM and Face++ paired rows"},"region-2":{"x":0.01,"y":0.37,"w":0.97,"h":0.16,"label":"Microsoft paired rows"},"region-3":{"x":0.01,"y":0.57,"w":0.97,"h":0.3,"label":"Amazon and Kairos rows"}},"steps":[{"title":"Compare matched subgroup measurements","description":"Red 2017 and blue 2018 points are joined for IBM and Face++. Large darker-female error gaps are visible, while individual subgroup changes are not uniformly downward.","focus":["region-1"]},{"title":"Inspect another re-audited system","description":"Microsoft’s darker-female row also shows a substantial reduction. Comparing the subgroup rows reveals variation hidden by one overall system number.","focus":["region-2"]},{"title":"Distinguish a new measurement from improvement","description":"Amazon and Kairos have blue re-audit values only. Without a corresponding red baseline here, these rows describe 2018 error levels rather than a measured reduction.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"2c715eca896ec6a3a87777a0e74844525d208ef1","art_kind":"png","art_width":3962,"art_height":2789},"vol2:fig-ghg-protocol":{"key":"vol2:fig-ghg-protocol","figure_id":"fig-ghg-protocol","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"GHG Emission Scopes","status":"ready","treatment":"annotated","question":"Whose accounting boundary determines an emission’s scope?","scope":"The concentric rings encode reporting distance from the data-center operator, not relative emission quantities.","regions":{"one":{"x":0.32,"y":0.34,"w":0.32,"h":0.32,"label":"Scope 1 direct emissions"},"two":{"x":0.2,"y":0.22,"w":0.56,"h":0.55,"label":"Scope 2 purchased energy"},"three":{"x":0.02,"y":0.02,"w":0.92,"h":0.93,"label":"Scope 3 value chain"},"control":{"x":0.58,"y":0.61,"w":0.41,"h":0.37,"label":"Direction away from direct control"}},"steps":[{"title":"Count direct operation","description":"Diesel generators and fleet vehicles sit inside Scope 1 because their emissions arise from sources controlled by the reporting organization.","focus":["one"]},{"title":"Account for purchased energy","description":"Scope 2 covers purchased grid electricity for IT and cooling. Generation occurs outside the data-center site but supplies its energy use.","focus":["two"]},{"title":"Include the value chain","description":"Fabrication, travel, and end-of-life recycling appear in Scope 3. Their outer position indicates value-chain accounting, not a larger measured footprint.","focus":["three"]},{"title":"Preserve the reporting perspective","description":"The outward arrow marks distance from direct control. The same activity can appear in different organizations’ scope accounts.","focus":["control"]}],"artwork_reviewed":true,"art_sha1":"d0e0d7eb699c8fa4fa5c6df033df2c7a2522649d","art_kind":"svg","art_width":1200,"art_height":1067,"art_structural_sha1":"d0e0d7eb699c8fa4fa5c6df033df2c7a2522649d"},"vol2:fig-global-inference-multiregion":{"key":"vol2:fig-global-inference-multiregion","figure_id":"fig-global-inference-multiregion","source":"books/vol2/10_inference/10_inference.qmd","title":"Global load balancing across inference regions","status":"ready","treatment":"annotated","question":"What makes a region eligible for a globally routed inference request?","scope":"The diagram describes placement, readiness, and capacity constraints; geographic proximity alone is insufficient.","regions":{"region-1":{"x":0.03,"y":0.12,"w":0.93,"h":0.25,"label":"Users and global load balancer"},"region-2":{"x":0.33,"y":0.04,"w":0.32,"h":0.75,"label":"EU residency path"},"region-3":{"x":0.04,"y":0.4,"w":0.91,"h":0.56,"label":"Registry and regional replicas"}},"steps":[{"title":"Route under eligibility constraints","description":"The global load balancer routes users toward a ready region with suitable capacity and latency. It must preserve placement constraints during ordinary routing and failover.","focus":["region-1"]},{"title":"Keep constrained requests in their zone","description":"The highlighted EU data-residency zone links EU users to EU-West. A region failure does not automatically authorize routing those requests outside the permitted zone.","focus":["region-2"]},{"title":"Distinguish model distribution from requests","description":"Independent regional replicas serve requests. The model registry’s dashed sync paths distribute versioned weights to each region; these paths are not the user request flow.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"5ed508b46bf763860fd513a4a01a236a8ce4d1e5","art_kind":"svg","art_width":1200,"art_height":727,"art_structural_sha1":"089ebf3e0389de71d5ef63a45afc209b3e68813f"},"vol2:fig-gpu-memory-wall":{"key":"vol2:fig-gpu-memory-wall","figure_id":"fig-gpu-memory-wall","source":"books/vol2/10_inference/10_inference.qmd","title":"Decode inherits the bandwidth deficit","status":"ready","treatment":"annotated","question":"Why does rising peak compute not eliminate the decode bandwidth constraint?","scope":"The hardware ratios are relative to V100 and use the chapter’s selected specifications. Peak ratios are not achieved application speedups.","regions":{"region-1":{"x":0.12,"y":0.61,"w":0.39,"h":0.3,"label":"V100 reference and A100 point"},"region-2":{"x":0.52,"y":0.06,"w":0.45,"h":0.61,"label":"Diverging H100-to-B200 series"},"region-3":{"x":0.53,"y":0.13,"w":0.22,"h":0.41,"label":"Shaded bandwidth deficit"}},"steps":[{"title":"Normalize both resources","description":"Both series begin at the V100 reference and grow toward newer devices. The y-axis measures relative growth, not absolute FLOPs or bytes per second.","focus":["region-1"]},{"title":"Compare compute with bandwidth growth","description":"The black peak-compute series rises faster than the purple memory-bandwidth series. The B200 endpoint labels show a larger compute multiplier than bandwidth multiplier.","focus":["region-2"]},{"title":"Relate the gap to decode","description":"The shaded gap is the bandwidth deficit. Decode that repeatedly reads model state can remain constrained by data delivery even as arithmetic capacity grows; the plot alone does not quantify its runtime.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"d7d7c9c01360022a60af00eb8259a2f3615db243","art_kind":"png","art_width":3302,"art_height":2160},"vol2:fig-gpu-scaling-trends":{"key":"vol2:fig-gpu-scaling-trends","figure_id":"fig-gpu-scaling-trends","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Compute, bandwidth, and power scale at three different rates","status":"ready","treatment":"annotated","question":"Why can faster arithmetic increase the reuse required from a kernel?","scope":"The series show normalized peak specifications, not measured workload throughput; the log axis and release-year spacing remain unchanged.","regions":{"baseline":{"x":0.1,"y":0.72,"w":0.1,"h":0.2,"label":"V100 normalization baseline"},"compute":{"x":0.46,"y":0.04,"w":0.5,"h":0.4,"label":"Compute growth and widened gap"},"memory":{"x":0.47,"y":0.25,"w":0.49,"h":0.29,"label":"Memory-bandwidth growth"},"power":{"x":0.47,"y":0.48,"w":0.49,"h":0.26,"label":"Power-envelope growth"}},"steps":[{"title":"Start from a common baseline","description":"All three series equal one at the V100. Normalization permits growth comparison without treating FLOP/s, bytes/s, and watts as the same quantity.","focus":["baseline"]},{"title":"Compare arithmetic with bytes","description":"The compute line reaches 18 times while bandwidth reaches 8.9 times. Their widening separation means a kernel needs more operations per delivered byte to stay compute-bound.","focus":["compute","memory"]},{"title":"Keep power separate","description":"The dashed TDP line reaches 3.3 times. A peak-throughput-to-TDP ratio is an architectural ceiling comparison, not measured workload energy efficiency.","focus":["power"]}],"artwork_reviewed":true,"art_sha1":"031b70109ee81db7ef4b23b7c9eb140c9dc7e9d0","art_kind":"png","art_width":3477,"art_height":2278},"vol2:fig-gpudirect-data-path":{"key":"vol2:fig-gpudirect-data-path","figure_id":"fig-gpudirect-data-path","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"GPUDirect RDMA data path","status":"ready","treatment":"annotated","question":"Which host-memory staging traffic does GPUDirect RDMA avoid?","scope":"The diagram isolates the sending-node path. Direct GPU-memory access still uses the platform interconnect and does not eliminate all CPU setup or network costs.","regions":{"gpu":{"x":0.27,"y":0.65,"w":0.27,"h":0.23,"label":"GPU memory payload"},"host":{"x":0.04,"y":0.12,"w":0.61,"h":0.25,"label":"Host staging and CPU"},"pcie":{"x":0.15,"y":0.41,"w":0.7,"h":0.16,"label":"PCIe switch"},"nic":{"x":0.58,"y":0.64,"w":0.22,"h":0.2,"label":"RDMA NIC"},"paths":{"x":0.34,"y":0.18,"w":0.48,"h":0.48,"label":"Staged and direct data paths"}},"steps":[{"title":"Locate the payload","description":"The payload n starts in GPU memory. The RDMA NIC must obtain those same bytes before sending them to the fabric.","focus":["gpu","nic"]},{"title":"Trace host staging","description":"The dashed route stages the payload through registered host memory. Its write and reread account for approximately 2n bytes of staging-bus traffic.","focus":["host","paths"]},{"title":"Follow direct DMA","description":"The green GPUDirect route connects GPU memory to the RDMA NIC through the PCIe fabric. It avoids the illustrated host-memory staging round trip.","focus":["pcie","paths","nic"]},{"title":"Keep the boundary explicit","description":"Avoiding host staging does not remove the NIC, PCIe path, or external fabric. Their bandwidth and topology still constrain the transfer.","focus":["gpu","pcie","nic"]}],"artwork_reviewed":true,"art_sha1":"c330332683bcc792821da2e54a7bb0a048881e7b","art_kind":"svg","art_width":1200,"art_height":648,"art_structural_sha1":"d55901cba0d12af1d4b08bab10221a0c448ec3b5"},"vol2:fig-gradient-attack":{"key":"vol2:fig-gradient-attack","figure_id":"fig-gradient-attack","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Gradient-Based Attack Geometry","status":"ready","treatment":"annotated","question":"Why does the FGSM update land on a corner of the allowed set?","scope":"The class boundary and two-dimensional inputs are illustrative; a different gradient or boundary need not yield a successful attack at the same budget.","regions":{"set":{"x":0.43,"y":0.36,"w":0.39,"h":0.52,"label":"Clean input and allowed square"},"gradient":{"x":0.45,"y":0.52,"w":0.16,"h":0.15,"label":"Loss gradient direction"},"corner":{"x":0.14,"y":0.3,"w":0.38,"h":0.14,"label":"Adversarial corner"},"boundary":{"x":0.2,"y":0.03,"w":0.68,"h":0.83,"label":"Decision boundary"}},"steps":[{"title":"Bound every coordinate change","description":"The dashed square contains perturbations whose absolute change in each coordinate is at most epsilon. The budget is coordinate-wise, not the arrow’s Euclidean length.","focus":["set"]},{"title":"Take the sign of the gradient","description":"The short blue arrow gives the local loss gradient. FGSM uses its coordinate signs and applies the full budget to each coordinate.","focus":["gradient"]},{"title":"Test the resulting class","description":"The red update reaches the upper-left allowed corner. In this particular drawing that corner crosses the decision boundary; the geometry does not guarantee success for every input.","focus":["corner","boundary"]}],"artwork_reviewed":true,"art_sha1":"4135745bb67982f7eae4143851ddcb29d91414a9","art_kind":"svg","art_width":1200,"art_height":660,"art_structural_sha1":"2ff8fce9ba35f4ce0fb174e6cdc4797a1738747e"},"vol2:fig-gradient-compression":{"key":"vol2:fig-gradient-compression","figure_id":"fig-gradient-compression","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Gradient compression techniques","status":"ready","treatment":"annotated","question":"What changes besides payload size when an update is compressed?","scope":"The four-coordinate illustration excludes full protocol overhead. Quantization needs scale metadata, and sparsification needs indices and persistent residual storage.","regions":{"fp32":{"x":0.01,"y":0.06,"w":0.97,"h":0.23,"label":"FP32 values and full payload"},"int8":{"x":0.01,"y":0.36,"w":0.97,"h":0.23,"label":"INT8 quantization and scale"},"topk":{"x":0.01,"y":0.63,"w":0.97,"h":0.25,"label":"Top-k values and indices"},"residual":{"x":0.3,"y":0.82,"w":0.2,"h":0.12,"label":"Local error-feedback residual"}},"steps":[{"title":"Transmit full precision","description":"Panel A sends all four 32-bit values. The payload bar shows 128 value bits before protocol metadata.","focus":["fp32"]},{"title":"Quantize every coordinate","description":"Panel B represents all coordinates with INT8 values. Its 32 value bits require a scale, and the reconstructed values generally have quantization error.","focus":["int8"]},{"title":"Send selected coordinates","description":"Panel C transmits the two selected values along with their coordinate identities. Values alone would not tell the receiver where to apply them.","focus":["topk"]},{"title":"Retain omitted information","description":"The residual stays on the client for error feedback into later updates. Compression saves transmitted bytes while creating local state that must fit the device budget.","focus":["residual"]}],"artwork_reviewed":true,"art_sha1":"3a93fe7664e79b281d834210e44fa644c20f03ea","art_kind":"svg","art_width":1200,"art_height":555,"art_structural_sha1":"db5774ade740b24943db2651fa2062df69cb89da"},"vol2:fig-graffiti":{"key":"vol2:fig-graffiti","figure_id":"fig-graffiti","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Physically Realizable Road-Sign Perturbations","status":"ready","treatment":"annotated","question":"Must a physically effective perturbation be visually subtle?","scope":"These are original study examples; inspecting their appearance does not establish a new attack success rate.","regions":{"poster":{"x":0.0,"y":0.0,"w":0.3,"h":1,"label":"Full-sign poster"},"graffiti":{"x":0.3,"y":0.0,"w":0.43,"h":1,"label":"Graffiti-style modification"},"patches":{"x":0.73,"y":0.0,"w":0.27,"h":1,"label":"Black-and-white patches"}},"steps":[{"title":"Inspect a full-sign modification","description":"The first panel applies a poster across the sign surface. Physical realizability is a constraint on the object and capture pipeline, not just digital pixels.","focus":["poster"]},{"title":"Separate conspicuousness from model effect","description":"The central graffiti-style markings are visibly conspicuous. An attack need not be imperceptible to a human to produce a harmful model prediction.","focus":["graffiti"]},{"title":"Evaluate the patch arrangement","description":"The final sign carries localized black-and-white patches. Their measured effect belongs to the cited study and its capture conditions.","focus":["patches"]}],"artwork_reviewed":true,"art_sha1":"7c2fad7f09f2d63c8c963165ba2c88af3d472320","art_kind":"png","art_width":1116,"art_height":500},"vol2:fig-hbm-architecture":{"key":"vol2:fig-hbm-architecture","figure_id":"fig-hbm-architecture","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"HBM 3D-stacked architecture","status":"ready","treatment":"annotated","question":"Why does HBM use a wide nearby connection rather than a distant memory module?","scope":"The diagram contrasts physical organizations, not equal-capacity or equal-cost benchmark systems.","regions":{"stack":{"x":0.23,"y":0.2,"w":0.22,"h":0.49,"label":"Stacked DRAM and TSVs"},"interposer":{"x":0.02,"y":0.64,"w":0.45,"h":0.2,"label":"GPU die and silicon interposer"},"dimm":{"x":0.58,"y":0.15,"w":0.37,"h":0.68,"label":"DDR5 controller and DIMM"}},"steps":[{"title":"Stack memory vertically","description":"The HBM stack joins DRAM dies with through-silicon vias. The wide interface is physically close to the processor.","focus":["stack"]},{"title":"Connect beside the die","description":"The silicon interposer joins the GPU and HBM on the package. Short routing supports many parallel wires.","focus":["interposer"]},{"title":"Cross the board","description":"The DDR5 panel routes a narrower connection over the motherboard to a DIMM. Connection width and distance explain the architectural contrast without alone determining application throughput.","focus":["dimm"]}],"artwork_reviewed":true,"art_sha1":"306091894a0ffc6e1be22739a33bb9cd57fd627e","art_kind":"svg","art_width":1200,"art_height":504,"art_structural_sha1":"0d8874eca5fb94da4a0a60e5afd5d187b73f4b79"},"vol2:fig-human-centered-ai":{"key":"vol2:fig-human-centered-ai","figure_id":"fig-human-centered-ai","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Layers of Responsibility","status":"ready","treatment":"annotated","question":"Which responsibilities cannot be carried by the development team alone?","scope":"Nested rectangles show accountability boundaries, not an execution sequence or assurance that compliance eliminates harm.","regions":{"region-1":{"x":0.19,"y":0.48,"w":0.61,"h":0.32,"label":"Development-team boundary"},"region-2":{"x":0.14,"y":0.34,"w":0.73,"h":0.51,"label":"Organization boundary"},"region-3":{"x":0.08,"y":0.2,"w":0.84,"h":0.7,"label":"Industry boundary"},"region-4":{"x":0.02,"y":0.05,"w":0.96,"h":0.89,"label":"Government and society boundary"}},"steps":[{"title":"Implement technical controls","description":"The development-team boundary names fairness testing, model cards, and red-teaming around the AI system. These controls require resources and authority supplied beyond the team.","focus":["region-1"]},{"title":"Govern operational decisions","description":"The organization adds impact assessments and ethical review boards. These processes connect technical findings to accountable decisions about deployment and remediation.","focus":["region-2"]},{"title":"Set shared external baselines","description":"Industry supplies ISO standards and external audits. These anchors make the surrounding layer a source of requirements the inner team cannot self-impose.","focus":["region-3"]},{"title":"Respect enforceable public obligations","description":"The outer boundary names GDPR, the EU AI Act, and sector-specific law. Legal and societal responsibilities remain part of the operating contract alongside technical evaluation.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"f45606b96e66716710286636a928c2471d780c22","art_kind":"svg","art_width":1200,"art_height":635,"art_structural_sha1":"f45606b96e66716710286636a928c2471d780c22"},"vol2:fig-hw-supply-chain":{"key":"vol2:fig-hw-supply-chain","figure_id":"fig-hw-supply-chain","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Hardware supply chain attack surface","status":"ready","treatment":"annotated","question":"Why must hardware integrity be checked across the supply chain?","scope":"The controls are examples with limited coverage; no single check proves the absence of all hardware compromise.","regions":{"design":{"x":0.01,"y":0.04,"w":0.19,"h":0.57,"label":"Design risks and review"},"fab":{"x":0.21,"y":0.04,"w":0.19,"h":0.57,"label":"Fabrication and inspection"},"assembly":{"x":0.41,"y":0.04,"w":0.19,"h":0.57,"label":"Assembly and screening"},"distribution":{"x":0.61,"y":0.04,"w":0.19,"h":0.57,"label":"Distribution and provenance"},"deployment":{"x":0.81,"y":0.04,"w":0.18,"h":0.57,"label":"Deployment and attestation"},"miss":{"x":0.06,"y":0.63,"w":0.91,"h":0.35,"label":"Missed threats reaching physical replacement"}},"steps":[{"title":"Review the design and fabrication","description":"Malicious IP and hardware Trojans arise at different stages. Design verification and die inspection provide different kinds of evidence.","focus":["design","fab"]},{"title":"Inspect assembled components","description":"Substituted components and relabeled parts motivate X-ray screening, provenance checks, and functional tests.","focus":["assembly","distribution"]},{"title":"Recheck deployed hardware","description":"Secure boot and attestation check specified properties at deployment, while probing and fault injection remain distinct physical threats.","focus":["deployment"]},{"title":"Track residual paths","description":"The dashed arrows show earlier missed threats continuing downstream. Passing a later check does not imply that every upstream component is authentic.","focus":["miss"]}],"artwork_reviewed":true,"art_sha1":"7c434a84fdbcaa9cf7e83f0c4b32b0cc658c2304","art_kind":"svg","art_width":1200,"art_height":455,"art_structural_sha1":"41d0c46159abdb77446eecf0c50aa77b12778ccf"},"vol2:fig-ib-roce-stack":{"key":"vol2:fig-ib-roce-stack","figure_id":"fig-ib-roce-stack","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"Traditional TCP/IP vs. RDMA verbs stacks","status":"ready","treatment":"annotated","question":"What changes when transport moves from sockets to RDMA verbs?","scope":"The two panels contrast representative data paths. RDMA bypasses the kernel in the steady-state data path, not in every setup and control operation.","regions":{"user":{"x":0.02,"y":0.06,"w":0.46,"h":0.23,"label":"Socket user-space framework"},"kernel":{"x":0.02,"y":0.32,"w":0.46,"h":0.45,"label":"Socket kernel stack and copies"},"ethernet":{"x":0.04,"y":0.77,"w":0.43,"h":0.18,"label":"Ethernet NIC"},"verbs":{"x":0.52,"y":0.06,"w":0.46,"h":0.22,"label":"NCCL and verbs API"},"bypass":{"x":0.58,"y":0.29,"w":0.22,"h":0.54,"label":"RDMA data-path bypass"},"rdma":{"x":0.54,"y":0.76,"w":0.44,"h":0.2,"label":"RDMA NIC and GPU memory"}},"steps":[{"title":"Start with sockets","description":"The left framework sends from a host-memory buffer through the Socket API. The drawn buffer chain includes two CPU-mediated copies.","focus":["user","kernel"]},{"title":"Execute transport in software","description":"The kernel TCP/IP stack performs reliability and the NIC driver fills its transmit ring before DMA. These operations occupy the left data path.","focus":["kernel","ethernet"]},{"title":"Post work with verbs","description":"On the right, NCCL posts work through the verbs API. The data path then proceeds to the RDMA NIC without traversing the kernel transport stack.","focus":["verbs","bypass"]},{"title":"Read accelerator memory","description":"The green connection marks the NIC reading GPU memory directly through GPUDirect. RDMA transport offload and direct accelerator access are distinct parts of this path.","focus":["rdma"]}],"artwork_reviewed":true,"art_sha1":"789d1e087e472b5e1ec71f4f9f46ec4b958801dc","art_kind":"svg","art_width":1200,"art_height":843,"art_structural_sha1":"0ad7f0abe3c35df30b613c891e5bf2ed24ba817a"},"vol2:fig-imagenet-v2-shift":{"key":"vol2:fig-imagenet-v2-shift","figure_id":"fig-imagenet-v2-shift","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Accuracy on a Fresh Test Set from the Same Recipe","status":"ready","treatment":"annotated","question":"What does a fresh test set reveal that original validation accuracy misses?","scope":"Points are reported model evaluations under the testbed’s selection rule; the fitted line describes association, not the causal effect of architecture or training changes.","regions":{"reference":{"x":0.1,"y":0.02,"w":0.87,"h":0.66,"label":"Equal-accuracy reference"},"lower":{"x":0.12,"y":0.62,"w":0.36,"h":0.29,"label":"Lower-accuracy model observations"},"upper":{"x":0.58,"y":0.23,"w":0.4,"h":0.41,"label":"Higher-accuracy model observations"},"fit":{"x":0.39,"y":0.44,"w":0.33,"h":0.27,"label":"Observed trend and fit"}},"steps":[{"title":"Read both evaluation axes","description":"The horizontal axis measures original ImageNet top-1 accuracy and the vertical axis measures ImageNet-V2 accuracy. A point on the dashed diagonal would score equally on both.","focus":["reference"]},{"title":"Compare one model across populations","description":"The labeled AlexNet point lies below the equality reference. Following the original collection recipe did not preserve this model’s original validation score.","focus":["lower"]},{"title":"Check whether stronger original scores close the gap","description":"Higher-scoring labeled models also lie below equality. Their better scores do not eliminate the observed population gap.","focus":["upper"]},{"title":"Keep the fitted trend descriptive","description":"The red least-squares line summarizes how scores co-vary in this testbed. It does not identify which hidden population difference caused the reduction.","focus":["fit"]}],"artwork_reviewed":true,"art_sha1":"ed49f40672011ee2e33b4c526fda300903328455","art_kind":"png","art_width":3773,"art_height":2327},"vol2:fig-inference-lifecycle":{"key":"vol2:fig-inference-lifecycle","figure_id":"fig-inference-lifecycle","source":"books/vol2/10_inference/10_inference.qmd","title":"End-to-end inference pipeline","status":"ready","treatment":"annotated","question":"Which parts of a language-model request spend the first-token and per-token latency budgets?","scope":"One request is traced. Segment widths are illustrative, and the CPU/GPU split does not quantify achieved latency.","regions":{"region-1":{"x":0.03,"y":0.05,"w":0.3,"h":0.45,"label":"CPU admission and tokenization"},"region-2":{"x":0.38,"y":0.34,"w":0.56,"h":0.18,"label":"Prefill and KV creation"},"region-3":{"x":0.04,"y":0.5,"w":0.9,"h":0.27,"label":"Decode and streaming"},"region-4":{"x":0.03,"y":0.82,"w":0.91,"h":0.16,"label":"Latency strip and brackets"}},"steps":[{"title":"Prepare the request","description":"The load balancer routes and admits the request, then the CPU tokenizer creates token IDs. These steps spend latency before GPU prefill starts.","focus":["region-1"]},{"title":"Process the whole prompt","description":"Prefill processes the prompt in one pass and writes keys and values to the KV cache in HBM. This stored state is reused during generation.","focus":["region-2"]},{"title":"Generate one token at a time","description":"Decode reads and appends the KV cache on successive steps. Generated token IDs return to CPU detokenization and the response stream.","focus":["region-3"]},{"title":"Separate TTFT from token pacing","description":"Time to first token includes routing, preprocessing, and prefill. The decode segment contains per-token steps; CPU work and routing are serving-tax costs outside GPU compute.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"284797cc835f27bc052b158e1ae196c33c53ec93","art_kind":"svg","art_width":1200,"art_height":779,"art_structural_sha1":"64af1606ce8c4f80fde97399d0bf3a80e9aabaf6"},"vol2:fig-infra-bandwidth-hierarchy":{"key":"vol2:fig-infra-bandwidth-hierarchy","figure_id":"fig-infra-bandwidth-hierarchy","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"The infrastructure bandwidth hierarchy","status":"ready","treatment":"annotated","question":"Where does a data transfer encounter the largest bandwidth cliffs?","scope":"Rates use the figure’s per-port and per-GPU direction conventions; the storage path is illustrative, and band widths are logarithmic.","regions":{"hbm":{"x":0.36,"y":0.37,"w":0.2,"h":0.26,"label":"HBM3 bandwidth"},"local":{"x":0.25,"y":0.23,"w":0.44,"h":0.52,"label":"NVLink and NVSwitch tier"},"network":{"x":0.12,"y":0.12,"w":0.73,"h":0.74,"label":"InfiniBand tier"},"storage":{"x":0.01,"y":0.36,"w":0.12,"h":0.22,"label":"Example storage bandwidth label"}},"steps":[{"title":"Start at HBM","description":"HBM3 sits at the center with 3.35 TB/s. Operations that reuse data here avoid slower outer paths.","focus":["hbm"]},{"title":"Cross between GPUs","description":"The NVLink/NVSwitch tier has a lower per-GPU budget. The printed divisor compares this tier with HBM under the stated conventions.","focus":["local"]},{"title":"Leave the node","description":"One InfiniBand NDR port supplies 50 GB/s per direction in this example. Crossing the node boundary exposes another bandwidth cliff.","focus":["network"]},{"title":"Fetch from storage","description":"The outer example storage path provides 7 GB/s. A pipeline must manage these successive boundaries rather than assume the innermost bandwidth applies end to end.","focus":["storage"]}],"artwork_reviewed":true,"art_sha1":"09c8034f63beece9720fd3b96ae94bf3b16da9de","art_kind":"svg","art_width":1200,"art_height":643,"art_structural_sha1":"93e57b66c77bb01ba6433709f22f388e90489e72"},"vol2:fig-injection":{"key":"vol2:fig-injection","figure_id":"fig-injection","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Fault injection attack","status":"ready","treatment":"annotated","question":"How can a skipped instruction change a neural computation?","scope":"The assembly sketch illustrates a fault mechanism; it does not give device settings or establish reliability of an attack.","regions":{"copy":{"x":0.02,"y":0.01,"w":0.47,"h":0.45,"label":"Positive-input copy path"},"jump":{"x":0.02,"y":0.46,"w":0.47,"h":0.1,"label":"Skipped jump instruction"},"zero":{"x":0.02,"y":0.57,"w":0.47,"h":0.3,"label":"Fall-through zeroing block"},"target":{"x":0.02,"y":0.88,"w":0.47,"h":0.1,"label":"Intended jump target"}},"steps":[{"title":"Follow the normal positive path","description":"The positive input takes the copy-activation path. The intended jump should then bypass the zeroing instructions.","focus":["copy"]},{"title":"Identify the faulted control transfer","description":"The highlighted jump is the instruction skipped in the illustration. The fault changes control flow rather than the input value.","focus":["jump"]},{"title":"Fall through to zeroing","description":"Execution continues into the else block and clears the output, making the neuron inactive despite a positive input.","focus":["zero"]},{"title":"Contrast with intended execution","description":"The dashed intended path would reach the end label directly. Correct arithmetic instructions do not protect a computation whose control flow is faulted.","focus":["target"]}],"artwork_reviewed":true,"art_sha1":"b85b45e94007eb6f9ca98165a84ec45c71ada04c","art_kind":"svg","art_width":1200,"art_height":619,"art_structural_sha1":"cd52a881fe5b2cccd258b00009fd719f380e9d07"},"vol2:fig-interleaving-vs-ab":{"key":"vol2:fig-interleaving-vs-ab","figure_id":"fig-interleaving-vs-ab","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Interleaving vs. A/B testing","status":"ready","treatment":"annotated","question":"What makes an interleaved ranker comparison paired?","scope":"Interleaving screens relative ranker preference for shared queries; it does not measure every deployment outcome captured by a full A/B test.","regions":{"abusers":{"x":0.02,"y":0.04,"w":0.45,"h":0.28,"label":"Separate A/B cohorts"},"ablists":{"x":0.1,"y":0.32,"w":0.31,"h":0.62,"label":"Single-ranker lists and cohort means"},"merge":{"x":0.57,"y":0.17,"w":0.41,"h":0.56,"label":"Same query and merged list"},"credit":{"x":0.56,"y":0.66,"w":0.42,"h":0.3,"label":"Credit clicks to source ranker"}},"steps":[{"title":"Assign separate cohorts","description":"A/B testing sends different users to ranker A or ranker B. Their cohort means therefore include variation between users.","focus":["abusers","ablists"]},{"title":"Hold the user query shared","description":"Interleaving asks both rankers to rank the same query. Team draft merges contributions into one displayed list.","focus":["merge"]},{"title":"Attribute the clicked item","description":"Each click is credited to the ranker that contributed its item. That shared-query comparison pairs the evidence within the user.","focus":["credit"]},{"title":"Keep the evaluation question narrow","description":"Preference screening can become more sample-efficient through pairing. It does not replace measuring the full effect of independently deployed systems.","focus":["ablists","credit"]}],"artwork_reviewed":true,"art_sha1":"7a1cb9776a139a2ed734ad4a3661c1496b21e18d","art_kind":"svg","art_width":1200,"art_height":542,"art_structural_sha1":"223a9f5406f6a0997baaa721126ded6e138dd704"},"vol2:fig-iot-number":{"key":"vol2:fig-iot-number","figure_id":"fig-iot-number","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"IoT Device Growth","status":"ready","treatment":"annotated","question":"What does a connected-device projection tell us about e-waste?","scope":"The series counts connected devices, not AI systems or discarded equipment. Service life, repair, reuse, and disposal determine waste generation.","regions":{"history":{"x":0.07,"y":0.51,"w":0.37,"h":0.42,"label":"Historical 2019–2023 counts"},"boundary":{"x":0.43,"y":0.07,"w":0.03,"h":0.87,"label":"Historical/projection boundary"},"projection":{"x":0.46,"y":0.2,"w":0.5,"h":0.73,"label":"Hatched 2024–2030 projections"},"last":{"x":0.89,"y":0.14,"w":0.07,"h":0.8,"label":"2030 projected count"}},"steps":[{"title":"Read the historical base","description":"Unhatched bars rise from 8.6 billion in 2019 to 15.1 billion in 2023. These counts describe the connected-device ecosystem.","focus":["history"]},{"title":"Cross into a projection","description":"The dashed divider and hatching mark 2024 onward as projected values. They do not carry the same evidentiary status as historical counts.","focus":["boundary","projection"]},{"title":"Interpret the endpoint narrowly","description":"The final bar projects about 29.4 billion connected devices by 2030. It is neither an AI-device census nor an e-waste mass estimate.","focus":["last"]},{"title":"Add the missing lifetime model","description":"Converting device counts to waste requires replacement schedules, repairability, reuse paths, and disposal rates. Growth alone does not specify how much hardware is discarded.","focus":["history","projection"]}],"artwork_reviewed":true,"art_sha1":"6b6641cce03df14af6c79ac14ca173e7a82b8962","art_kind":"png","art_width":3840,"art_height":2100},"vol2:fig-iron-law-flowchart":{"key":"vol2:fig-iron-law-flowchart","figure_id":"fig-iron-law-flowchart","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Iron law diagnostic flowchart","status":"ready","treatment":"annotated","question":"Which bottleneck should be diagnosed before choosing a kernel optimization?","scope":"The flow is a troubleshooting guide, not a proof that a utilization threshold uniquely identifies the limiting resource.","regions":{"symptom":{"x":0.19,"y":0.01,"w":0.35,"h":0.22,"label":"Missed target and utilization check"},"overhead":{"x":0.43,"y":0.13,"w":0.47,"h":0.39,"label":"I/O, CPU, and communication branches"},"roof":{"x":0.02,"y":0.25,"w":0.54,"h":0.37,"label":"Arithmetic intensity versus ridge"},"memory":{"x":0.03,"y":0.63,"w":0.25,"h":0.19,"label":"Memory-bound remedies"},"compute":{"x":0.29,"y":0.63,"w":0.27,"h":0.19,"label":"Compute-bound remedies"},"repeat":{"x":0.34,"y":0.91,"w":0.19,"h":0.07,"label":"Re-profile after intervention"}},"steps":[{"title":"Start outside the kernel","description":"A missed target with low accelerator utilization first calls for stall diagnosis. An accelerator waiting for input cannot benefit from faster arithmetic alone.","focus":["symptom"]},{"title":"Eliminate feeding overhead","description":"The right branch checks I/O, CPU preprocessing, and exposed communication. Each branch names a different intervention because each delays useful device work differently.","focus":["overhead"]},{"title":"Classify busy execution","description":"Once the device is usefully occupied, compare arithmetic intensity with the ridge point. Below the ridge the bandwidth bound is tighter; above it the compute bound is tighter.","focus":["roof"]},{"title":"Choose and verify a remedy","description":"Memory-bound remedies reduce traffic or improve reuse; compute-bound remedies reduce arithmetic cost or active work. Re-profile because removing one bottleneck can expose another.","focus":["memory","compute","repeat"]}],"artwork_reviewed":true,"art_sha1":"40c3cbd5c65e5635622b0c16723ff29cf9b8ed00","art_kind":"svg","art_width":1200,"art_height":936,"art_structural_sha1":"26b0d5d2b416faeb02225a642f026f2598dbeaa6"},"vol2:fig-jevons-ai":{"key":"vol2:fig-jevons-ai","figure_id":"fig-jevons-ai","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Jevons Paradox in AI Workloads","status":"ready","treatment":"annotated","question":"How can lower unit cost increase total expenditure?","scope":"The curve is a schematic elastic-demand case. Areas measure monetary expenditure; interpreting them as energy requires proportional unit-energy changes and carbon needs a grid factor.","regions":{"saving":{"x":0.24,"y":0.25,"w":0.18,"h":0.3,"label":"Savings on original volume"},"retained":{"x":0.24,"y":0.57,"w":0.18,"h":0.3,"label":"Retained base-volume expenditure"},"added":{"x":0.42,"y":0.57,"w":0.39,"h":0.3,"label":"Added-volume expenditure"},"demand":{"x":0.41,"y":0.23,"w":0.55,"h":0.38,"label":"Lower price and expanded demand"}},"steps":[{"title":"Lower the cost of existing work","description":"The green area saves (P₀−P₁)Q₀ on the original compute volume. At fixed volume this would reduce total expenditure.","focus":["saving"]},{"title":"Retain the base volume","description":"The gray rectangle is the cost still paid for the original Q₀ at the reduced price P₁. Efficiency does not eliminate this baseline work.","focus":["retained"]},{"title":"Expand demand","description":"The elastic curve moves from Q₀ to Q₁ as price falls. The red rectangle charges P₁ for the additional volume.","focus":["demand","added"]},{"title":"Compare the areas with their units","description":"Here red exceeds green, so total expenditure rises. A claim about energy or emissions needs the additional conversion assumptions rather than relabeling the price axis.","focus":["added","saving"]}],"artwork_reviewed":true,"art_sha1":"ca50924874ab01720c9acd43a2f5d7c517b14539","art_kind":"png","art_width":3840,"art_height":2280},"vol2:fig-kaplan-scaling":{"key":"vol2:fig-kaplan-scaling","figure_id":"fig-kaplan-scaling","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Scaling laws and compute optimality","status":"ready","treatment":"annotated","question":"Why can compute-efficient training stop before a model’s own loss curve converges?","scope":"These published scaling curves concern their study setup. Curve interpolation is evidence from the source, not an interactive prediction for a new model.","regions":{"region-1":{"x":0.01,"y":0.03,"w":0.43,"h":0.91,"label":"Tokens-processed curves"},"region-2":{"x":0.84,"y":0.04,"w":0.15,"h":0.21,"label":"Parameter-color legend"},"region-3":{"x":0.48,"y":0.36,"w":0.51,"h":0.58,"label":"Compute-efficient stopping bracket"}},"steps":[{"title":"Distinguish model capacity from training duration","description":"The left panel compares test loss as tokens are processed. Different parameter counts follow different curves and settle at different loss floors.","focus":["region-1"]},{"title":"Keep model identity consistent","description":"The color scale identifies parameter count across both panels. A change of horizontal axis does not change which model a curve represents.","focus":["region-2"]},{"title":"Compare cost before full convergence","description":"The right panel uses compute rather than tokens. The annotated compute-efficient region lies short of full convergence: spending more compute on the same model can be less effective than reallocating it across model size and training duration.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"9887a76edfd08b24772ee45a44a4e0d4c23cd98c","art_kind":"png","art_width":1821,"art_height":636},"vol2:fig-kv-cache-wall":{"key":"vol2:fig-kv-cache-wall","figure_id":"fig-kv-cache-wall","source":"books/vol2/10_inference/10_inference.qmd","title":"The KV cache wall","status":"ready","treatment":"annotated","question":"How do sequence length and concurrency compete for a fixed HBM budget?","scope":"This is the chapter’s idealized 35-GB weight-plus-KV capacity model under a decimal 80-GB budget. Quantization metadata, runtime buffers, and other allocations make its capacity boundary optimistic; it does not predict achieved bandwidth.","regions":{"region-1":{"x":0.12,"y":0.56,"w":0.86,"h":0.3,"label":"Persistent model weights"},"region-2":{"x":0.12,"y":0.19,"w":0.85,"h":0.5,"label":"Concurrency-dependent KV slopes"},"region-3":{"x":0.12,"y":0.09,"w":0.85,"h":0.16,"label":"80-GB boundary crossings"}},"steps":[{"title":"Reserve memory before caching tokens","description":"The blue base is Model weights (35 GB), independent of sequence length in this scenario. It consumes capacity before any request’s growing KV state.","focus":["region-1"]},{"title":"Add cache growth for active sequences","description":"The batch-1, batch-2, batch-4, and batch-8 lines rise as sequence length grows. More concurrent sequences increase KV growth and use the remaining HBM sooner.","focus":["region-2"]},{"title":"Locate capacity-limited sequence lengths","description":"The red dashed HBM capacity line meets larger batches at shorter lengths. The region above it is infeasible under the stated capacity assumptions, regardless of spare arithmetic throughput.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"c052ce3da781cdf4d6407e7b0162d82033bfac68","art_kind":"png","art_width":3303,"art_height":2159},"vol2:fig-llama3-interruptions":{"key":"vol2:fig-llama3-interruptions","figure_id":"fig-llama3-interruptions","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Root Causes of Training Interruptions","status":"ready","treatment":"annotated","question":"Which interruptions dominate the reported training run, and what is unobserved?","scope":"The bars count 419 recorded interruptions in one 54-day run, not universal fleet failure probabilities; silent corruption appears only when detected.","regions":{"gpu":{"x":0.1,"y":0.04,"w":0.85,"h":0.11,"label":"Faulty GPU and HBM interruptions"},"other":{"x":0.1,"y":0.15,"w":0.47,"h":0.12,"label":"Software and network interruptions"},"sdc":{"x":0.05,"y":0.49,"w":0.3,"h":0.05,"label":"Detected silent data corruption"},"legend":{"x":0.7,"y":0.49,"w":0.28,"h":0.37,"label":"Root-cause categories"}},"steps":[{"title":"Prioritize the frequent recorded causes","description":"The longest bars are faulty GPUs and GPU HBM3 memory. Their counts motivate recovery paths for frequent detectable accelerator failures.","focus":["gpu"]},{"title":"Include the rest of the system","description":"Software bugs and network switches or cables also interrupt the job. A GPU-only reliability model omits these operational paths.","focus":["other","legend"]},{"title":"Do not read absence of detection as absence of corruption","description":"The silent-data-corruption bar includes six attributed interruptions. Uncaught corruption cannot appear in a root-cause count, so that small bar does not establish low total exposure.","focus":["sdc"]}],"artwork_reviewed":true,"art_sha1":"2f885c2866074b21e416c00b462340530e143923","art_kind":"png","art_width":4020,"art_height":2373},"vol2:fig-loss-vs-n-d":{"key":"vol2:fig-loss-vs-n-d","figure_id":"fig-loss-vs-n-d","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Loss vs. dataset size across model scales","status":"ready","treatment":"annotated","question":"Why does more data stop helping a small model before it stops helping a larger one?","scope":"Points and curves are digitized from the cited published plot; their precision is limited by that reading.","regions":{"region-1":{"x":0.29,"y":0.13,"w":0.7,"h":0.29,"label":"Small-model plateaus"},"region-2":{"x":0.15,"y":0.23,"w":0.44,"h":0.52,"label":"Shared descent region"},"region-3":{"x":0.49,"y":0.68,"w":0.5,"h":0.22,"label":"Large-model lower floor"}},"steps":[{"title":"Locate capacity-limited curves","description":"The 393.2K and 3M curves flatten at relatively high test loss. Adding dataset tokens along these plateaus offers little improvement for these model capacities.","focus":["region-1"]},{"title":"Find the common data-limited trend","description":"Several larger-model curves descend together in the region labeled shared power-law descent. Here, more data still reduces loss before those models reach their own floors.","focus":["region-2"]},{"title":"Compare where larger models level off","description":"The 302M and 708M curves continue toward lower floors. The result supports joint model-and-data planning rather than a claim that dataset size alone determines loss.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"a516e868027aa999a73f4a89267f99badaf183d6","art_kind":"png","art_width":3661,"art_height":2400},"vol2:fig-machine-unlearning":{"key":"vol2:fig-machine-unlearning","figure_id":"fig-machine-unlearning","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Model Update Strategies","status":"ready","treatment":"annotated","question":"How do unlearning approaches differ in recomputation and removal guarantees?","scope":"The exact labels refer to the stated retraining constructions and retained-data reference, not a guarantee for every approximate deletion algorithm.","regions":{"region-1":{"x":0.02,"y":0.03,"w":0.31,"h":0.88,"label":"Full retraining panel"},"region-2":{"x":0.34,"y":0.03,"w":0.31,"h":0.88,"label":"Gradient-ascent panel"},"region-3":{"x":0.67,"y":0.03,"w":0.31,"h":0.88,"label":"SISA panel"}},"steps":[{"title":"Rebuild from retained data","description":"Full retraining removes the forget-set tiles and recomputes the whole model from retained data. Its exact guarantee comes with the widest recomputation scope.","focus":["region-1"]},{"title":"Update against the forget set","description":"Gradient ascent applies forget-set passes to increase its loss. The panel labels the guarantee approximate; changing loss is not proof of equivalence to retraining.","focus":["region-2"]},{"title":"Retrain the affected shard","description":"SISA keeps S1 and S2 while retraining affected shard S3 without its removed tiles. Serving combines shard votes, so the partitioned training and serving construction is part of the guarantee.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"02050fe91f9cf838dfd7fa4a7995e030b9c9e9ab","art_kind":"svg","art_width":1200,"art_height":557,"art_structural_sha1":"cfae1f9ce8bf4f14f420b656d4d2df74be8189f1"},"vol2:fig-memory-wall-trend":{"key":"vol2:fig-memory-wall-trend","figure_id":"fig-memory-wall-trend","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"The memory wall","status":"ready","treatment":"annotated","question":"Why must frontier training state extend beyond one accelerator?","scope":"The model-demand series uses 16 bytes per parameter for mixed-precision Adam. Plotted frontier models are selected examples; GPT-3 is the first crossing among those points, not the first partitioned model in history.","regions":{"capacity":{"x":0.18,"y":0.4,"w":0.62,"h":0.3,"label":"Accelerator memory capacity"},"early":{"x":0.13,"y":0.7,"w":0.39,"h":0.22,"label":"Earlier model training-state points"},"gpt3":{"x":0.43,"y":0.13,"w":0.26,"h":0.39,"label":"GPT-3 gap and crossing annotation"},"later":{"x":0.63,"y":0.1,"w":0.35,"h":0.47,"label":"Later training-state gap"}},"steps":[{"title":"Read capacity as one device","description":"The blue capacity series describes individual accelerators, not total fleet memory. Its growth is substantial but remains far below later training-state demand.","focus":["capacity"]},{"title":"Include complete training state","description":"The red series includes weights, gradients, and optimizer state under the stated 16-byte convention. A parameter-only estimate would be a different quantity.","focus":["early"]},{"title":"Inspect the plotted crossing","description":"GPT-3 is the first shown model beyond one accelerator, by roughly 35 times the largest device of its year. Models between the plotted points can already have required partitioning.","focus":["gpt3"]},{"title":"Treat sharding as feasibility","description":"PaLM and Llama 3 remain far above the capacity curve. For these examples, spreading training state across devices is needed to fit before it can improve speed.","focus":["later"]}],"artwork_reviewed":true,"art_sha1":"50c3b8f012d9171a0534dc44b050b0cbc2fb7bb7","art_kind":"png","art_width":3641,"art_height":2515},"vol2:fig-meta-analysis":{"key":"vol2:fig-meta-analysis","figure_id":"fig-meta-analysis","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Operational Carbon Footprint of Large-Scale ML Tasks","status":"ready","treatment":"annotated","question":"Why can training-only bars misrepresent a deployed service’s carbon footprint?","scope":"Bars cover reported operational accounting periods. Public training-only baselines do not establish lifetime training-to-inference ratios or controlled model comparisons.","regions":{"lm":{"x":0.04,"y":0.05,"w":0.41,"h":0.14,"label":"Production language model"},"recommend":{"x":0.04,"y":0.17,"w":0.92,"h":0.36,"label":"Recommendation training and inference"},"public":{"x":0.01,"y":0.49,"w":0.91,"h":0.48,"label":"Public training-only benchmarks"},"rm1":{"x":0.28,"y":0.18,"w":0.66,"h":0.09,"label":"RM-1 training and inference components"}},"steps":[{"title":"Inspect a deployed workload","description":"The production language-model row includes recurring inference. Its narrow scale in this figure does not mean training-only accounting is a complete service account.","focus":["lm"]},{"title":"Separate update and serving work","description":"RM-1’s light and mid-orange training components sit beside solid inference. Across the shown recommendation workloads, recurring serving can rival training.","focus":["rm1","recommend"]},{"title":"Identify the missing phase","description":"Hatched public-benchmark bars report training only. Their absent inference segments are unreported workload scope, not evidence of zero serving emissions.","focus":["public"]},{"title":"Compare only compatible boundaries","description":"A footprint decision needs training and serving over the same declared observation period. Different workload scope prevents reading these bars as a model-efficiency leaderboard.","focus":["recommend","public"]}],"artwork_reviewed":true,"art_sha1":"66ec0a0cc0fed2f833f790068e35f1bca812b3b9","art_kind":"png","art_width":3654,"art_height":3300},"vol2:fig-mfu-progression":{"key":"vol2:fig-mfu-progression","figure_id":"fig-mfu-progression","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"The MFU progression","status":"ready","treatment":"annotated","question":"What does a reported MFU percentage actually let us compare?","scope":"Published systems differ in hardware, workload, batch, precision convention, and measurement window. Chronological ordering does not isolate a causal improvement.","regions":{"early":{"x":0.01,"y":0.07,"w":0.68,"h":0.4,"label":"Earlier reported systems"},"palm":{"x":0.01,"y":0.45,"w":0.73,"h":0.17,"label":"PaLM 46.2 percent"},"llama":{"x":0.01,"y":0.62,"w":0.8,"h":0.29,"label":"Two Llama 3 scales"},"reference":{"x":0.65,"y":0.01,"w":0.08,"h":0.91,"label":"Illustrative 50 percent reference"}},"steps":[{"title":"Read each configuration’s result","description":"The first three bars show reported MFU for GPT-3, Megatron-Turing NLG, and Gopher. Their different system labels prevent treating them as one controlled experiment.","focus":["early"]},{"title":"Compare without claiming attribution","description":"PaLM’s 46.2 percent is higher than the earlier plotted values. The chart alone cannot assign that difference to parallelism or overlap.","focus":["palm"]},{"title":"Inspect scale within the reported family","description":"The Llama 3 rows fall from 43 to 41 percent when the listed GPU count doubles. Configuration and batch details are needed to interpret the decrease.","focus":["llama"]},{"title":"Keep the reference descriptive","description":"The dashed 50 percent line is an illustrative reference. It is not a feasibility boundary or a universal target imposed by the workload.","focus":["reference"]}],"artwork_reviewed":true,"art_sha1":"0527a7d895986c3d5bf80766c24dad113b8e63e8","art_kind":"png","art_width":3596,"art_height":2399},"vol2:fig-ml-cicd":{"key":"vol2:fig-ml-cicd","figure_id":"fig-ml-cicd","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"ML CI/CD pipeline","status":"ready","treatment":"annotated","question":"Where can a release stop before it reaches all users?","scope":"The arrows show a gated workflow; detected drift prompts validation and investigation, not automatic unconditional retraining.","regions":{"ci":{"x":0.01,"y":0.04,"w":0.36,"h":0.29,"label":"Commit and unit tests"},"ct":{"x":0.38,"y":0.04,"w":0.61,"h":0.29,"label":"Data validation, training, evaluation"},"gate":{"x":0.6,"y":0.32,"w":0.38,"h":0.32,"label":"Metrics gate and block path"},"release":{"x":0.39,"y":0.59,"w":0.59,"h":0.29,"label":"Registry, staging, canary"},"prod":{"x":0.01,"y":0.69,"w":0.36,"h":0.24,"label":"Production and monitoring"}},"steps":[{"title":"Validate the change and data","description":"CI checks code while CT validates data, trains, and evaluates the candidate. Passing code tests alone does not establish model quality.","focus":["ci","ct"]},{"title":"Stop a failing candidate","description":"The metrics gate can block and alert before registration. A failed candidate does not proceed into deployment because training completed.","focus":["gate"]},{"title":"Expand exposure in stages","description":"A registered version passes through staging and canary before full production. These states separate candidate identity from the fraction of users exposed.","focus":["release"]},{"title":"Close the evidence loop","description":"Production monitoring returns drift evidence to data validation and investigation. That loop informs a retraining decision rather than bypassing the earlier gates.","focus":["prod","ct"]}],"artwork_reviewed":true,"art_sha1":"d6dd86948b181623041e2aa3afebaae868a03797","art_kind":"svg","art_width":1200,"art_height":576,"art_structural_sha1":"e8238538e911255059994e12be3734537362c525"},"vol2:fig-ml-lifecycle-threats":{"key":"vol2:fig-ml-lifecycle-threats","figure_id":"fig-ml-lifecycle-threats","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"ML lifecycle threats","status":"ready","treatment":"annotated","question":"Why do security controls belong at several lifecycle boundaries?","scope":"Controls are candidate barriers, not guarantees; dashed missed-defense paths show residual propagation.","regions":{"data":{"x":0.01,"y":0.03,"w":0.24,"h":0.74,"label":"Data collection and validation"},"train":{"x":0.26,"y":0.03,"w":0.24,"h":0.74,"label":"Training environment"},"deploy":{"x":0.51,"y":0.03,"w":0.24,"h":0.74,"label":"Deployment and access"},"infer":{"x":0.76,"y":0.03,"w":0.23,"h":0.74,"label":"Inference input validation"},"miss":{"x":0.08,"y":0.75,"w":0.9,"h":0.23,"label":"Missed attacks reaching compromise"}},"steps":[{"title":"Validate before learning","description":"Poisoned samples and flipped labels target collection. Validation and provenance checks aim to prevent corrupted inputs entering training.","focus":["data"]},{"title":"Protect execution and distribution","description":"The training environment faces backdoor insertion; deployment faces artifact or API theft. Their controls protect different assets.","focus":["train","deploy"]},{"title":"Check live requests","description":"Adversarial inputs arrive during inference, after the model has been built. Input validation addresses a later boundary.","focus":["infer"]},{"title":"Follow missed barriers","description":"The dashed paths show attacks continuing toward a compromised model when earlier controls fail. Defense in depth requires checking downstream behavior too.","focus":["miss"]}],"artwork_reviewed":true,"art_sha1":"ac79370a910f626b7067d0fb39db3803a7f37f02","art_kind":"svg","art_width":1200,"art_height":452,"art_structural_sha1":"fe65e8e98cd12859e1208c4d5b5b2880d4cf04b0"},"vol2:fig-ml-org-models":{"key":"vol2:fig-ml-org-models","figure_id":"fig-ml-org-models","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Organizational patterns for ML","status":"ready","treatment":"annotated","question":"Where does each ML organization place shared infrastructure work?","scope":"These are organizational trade-offs, not a universal ranking; actual queue pressure and coordination depend on staffing and workload.","regions":{"central":{"x":0.02,"y":0.04,"w":0.31,"h":0.92,"label":"Central platform and shared queue"},"embedded":{"x":0.36,"y":0.04,"w":0.31,"h":0.92,"label":"Embedded tooling per team"},"hybrid":{"x":0.69,"y":0.04,"w":0.3,"h":0.92,"label":"Core platform with team MLEs"}},"steps":[{"title":"Centralize the infrastructure","description":"A single platform serves all teams, but every request passes through the shared queue. Standardization can therefore concentrate coordination delay.","focus":["central"]},{"title":"Give each team local control","description":"Embedded teams own their tooling and can move independently. Their differently shaped stacks show duplicated work and divergence.","focus":["embedded"]},{"title":"Connect a shared core to local teams","description":"The hybrid keeps common infrastructure and places MLEs within product teams. Liaisons must sustain both platform consistency and local responsiveness.","focus":["hybrid"]}],"artwork_reviewed":true,"art_sha1":"2e5cf3e89e369636639a5d0500d7705e3201ce73","art_kind":"svg","art_width":1200,"art_height":391,"art_structural_sha1":"b6c7e8d557e3ecf778a2d30374a3fb5cb1f4a2e3"},"vol2:fig-mlperf-software-gains":{"key":"vol2:fig-mlperf-software-gains","figure_id":"fig-mlperf-software-gains","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Software-Only Gains on Fixed Hardware","status":"ready","treatment":"annotated","question":"What do repeated submissions on unchanged hardware reveal about software performance?","scope":"These are offline benchmark results normalized separately to each workload’s first submission. They do not isolate a single compiler optimization or predict online SLO performance.","regions":{"gptj":{"x":0.14,"y":0.1,"w":0.63,"h":0.6,"label":"GPT-J throughput gains"},"llama":{"x":0.33,"y":0.48,"w":0.66,"h":0.24,"label":"Llama 2 70B gains"},"sdxl":{"x":0.33,"y":0.48,"w":0.35,"h":0.22,"label":"Stable Diffusion XL gains"},"mature":{"x":0.13,"y":0.69,"w":0.38,"h":0.14,"label":"Flat BERT and ResNet results"},"rounds":{"x":0.09,"y":0.86,"w":0.88,"h":0.13,"label":"Submission rounds on the same system"}},"steps":[{"title":"Hold the hardware fixed","description":"The horizontal labels identify four MLPerf rounds on the same eight-H100 system. Each curve is relative to that benchmark’s first result, not to another model’s throughput.","focus":["rounds"]},{"title":"Observe substantial software headroom","description":"GPT-J reaches 2.7 times its initial offline throughput. The fixed hardware makes software evolution a material part of delivered performance.","focus":["gptj"]},{"title":"Compare workload-specific gains","description":"Llama 2 70B reaches 1.4 times its own baseline, while Stable Diffusion XL reaches 1.2 times. Different workloads expose different remaining optimization opportunities.","focus":["llama","sdxl"]},{"title":"Recognize mature baselines","description":"BERT and ResNet stay at 1.0 across their two submitted rounds. A hardware comparison that changes software versions can measure software maturity as well as silicon.","focus":["mature"]}],"artwork_reviewed":true,"art_sha1":"df7e4f77f85b764a3a2fccc266e6982576e13077","art_kind":"png","art_width":3806,"art_height":2199},"vol2:fig-mlperf-storage-demand":{"key":"vol2:fig-mlperf-storage-demand","figure_id":"fig-mlperf-storage-demand","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"Measured Storage Demand per Accelerator","status":"ready","treatment":"annotated","question":"How does accelerator demand determine the storage bandwidth a fleet must deliver?","scope":"MLPerf Storage uses emulated accelerators and fixed sample-consumption times. These passing submissions measure storage systems, not actual GPU execution.","regions":{"scatter":{"x":0.08,"y":0.02,"w":0.91,"h":0.47,"label":"Throughput versus emulated accelerator count"},"unet":{"x":0.11,"y":0.6,"w":0.22,"h":0.36,"label":"3D U-Net per-accelerator demand"},"cosmo":{"x":0.41,"y":0.6,"w":0.23,"h":0.36,"label":"CosmoFlow per-accelerator demand"},"resnet":{"x":0.72,"y":0.6,"w":0.23,"h":0.36,"label":"ResNet-50 per-accelerator demand"}},"steps":[{"title":"Scale the consumers","description":"The upper log-log plot shows throughput rising with the number of emulated accelerators. Each workload forms a different demand band.","focus":["scatter"]},{"title":"Compare sample workloads","description":"The lower bars show much higher per-accelerator demand for 3D U-Net than ResNet-50, with CosmoFlow between them. Data shape and consumption rate matter, not only accelerator count.","focus":["unet","cosmo","resnet"]},{"title":"Change the emulated generation","description":"Within each workload, the solid H100 bar exceeds the lighter A100 bar. Faster consumption raises required input bandwidth even when bytes per sample are unchanged.","focus":["unet","cosmo"]},{"title":"Size for the fleet workload","description":"A fleet’s required input rate combines consumer count with its workload-specific per-consumer demand. Passing busy-time thresholds define these observations, not unlimited storage scalability.","focus":["scatter","resnet"]}],"artwork_reviewed":true,"art_sha1":"fa66d843227e474c8b5c04a8c3ebccf7655baa5b","art_kind":"png","art_width":3349,"art_height":3333},"vol2:fig-mlperf-training-scaling":{"key":"vol2:fig-mlperf-training-scaling","figure_id":"fig-mlperf-training-scaling","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Measured Scaling in MLPerf Training","status":"ready","treatment":"annotated","question":"What can measured time-to-quality scaling reveal—and leave unresolved?","scope":"Each series compares one benchmark round and configuration family. Larger global batches can alter convergence, so deviation from ideal is not entirely communication overhead.","regions":{"baseline":{"x":0.1,"y":0.05,"w":0.23,"h":0.47,"label":"Smallest configurations"},"large":{"x":0.65,"y":0.31,"w":0.32,"h":0.53,"label":"Largest runs and efficiency labels"},"ideal":{"x":0.42,"y":0.35,"w":0.5,"h":0.59,"label":"Dashed within-series ideal lines"},"legend":{"x":0.1,"y":0.63,"w":0.48,"h":0.29,"label":"Benchmark and hardware series"}},"steps":[{"title":"Compare within a series","description":"Color and legend identify five benchmark/configuration series. Their smallest runs establish separate baselines; this is not a controlled cross-hardware contest.","focus":["legend","baseline"]},{"title":"Read the ideal reference","description":"Dashed lines divide each baseline time by its scale increase. They define perfect relative scaling from that series’ smallest configuration.","focus":["ideal"]},{"title":"Inspect retained efficiency","description":"The largest configurations finish faster but lie above their ideal lines. The printed 71–84 percent labels quantify retained relative scaling for these runs.","focus":["large"]},{"title":"Separate time and convergence","description":"Time-to-quality includes both step execution and the number of steps or examples required. Batch-dependent convergence must be inspected before attributing the whole gap to the fabric.","focus":["large","ideal"]}],"artwork_reviewed":true,"art_sha1":"a7eba6b6e5d7d9c7d8ff85d6f657719d5e23d19e","art_kind":"png","art_width":3829,"art_height":2280},"vol2:fig-mobile-ai-spread":{"key":"vol2:fig-mobile-ai-spread","figure_id":"fig-mobile-ai-spread","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Measured AI Performance across Phone Processors","status":"ready","treatment":"annotated","question":"Why can one local-work quota fail across a heterogeneous phone fleet?","scope":"AI Benchmark scores measure inference through each processor’s software acceleration path. Release year and family do not isolate hardware causality or predict training speed.","regions":{"older":{"x":0.15,"y":0.45,"w":0.43,"h":0.47,"label":"Older phone-processor score distribution"},"fleetlow":{"x":0.57,"y":0.42,"w":0.24,"h":0.21,"label":"Lower-scoring processors within 2020-onward window"},"fleethigh":{"x":0.6,"y":0.03,"w":0.29,"h":0.28,"label":"Recent high-scoring processors"},"spread":{"x":0.89,"y":0.05,"w":0.08,"h":0.51,"label":"Roughly 400-fold fleet-window spread"},"legend":{"x":0.14,"y":0.04,"w":0.26,"h":0.32,"label":"Processor-family legend"}},"steps":[{"title":"Read a measured score","description":"The plot combines processor release years with logarithmic AI Benchmark inference scores. The colors identify processor families, not controlled experimental conditions.","focus":["legend","older"]},{"title":"Keep older devices in the fleet","description":"The shaded 2020-onward window still contains much lower-scoring processors than the leaders. A current fleet can contain widely different execution paths and capabilities.","focus":["fleetlow"]},{"title":"Inspect the full within-window range","description":"High-scoring recent processors extend the range upward. The right bracket shows roughly a four-hundredfold score spread within the shaded window.","focus":["fleethigh","spread"]},{"title":"Schedule with measured device budgets","description":"A single local-work quota may not fit this population. Training feasibility must still be measured because these inference scores do not establish backward speed or memory capacity.","focus":["fleetlow","fleethigh"]}],"artwork_reviewed":true,"art_sha1":"005476d79045591bc9217f455d4bf42064fadb62","art_kind":"png","art_width":3811,"art_height":2096},"vol2:fig-model-registry":{"key":"vol2:fig-model-registry","figure_id":"fig-model-registry","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Dependency-aware model registry","status":"ready","treatment":"annotated","question":"How far can a registry safely propagate a model change?","scope":"Only recorded dependency edges are traversed. The drawing omits direct embedding-to-ranker feature edges described in the caption.","regions":{"change":{"x":0.01,"y":0.35,"w":0.2,"h":0.27,"label":"Embedding version bump"},"retrieval":{"x":0.29,"y":0.37,"w":0.17,"h":0.23,"label":"Retrieval dependency"},"rankers":{"x":0.51,"y":0.22,"w":0.17,"h":0.58,"label":"Three rankers"},"ensemble":{"x":0.75,"y":0.37,"w":0.17,"h":0.23,"label":"Ensemble consumer"},"missing":{"x":0.05,"y":0.59,"w":0.19,"h":0.35,"label":"Unrecorded fraud dependency"}},"steps":[{"title":"Start at the changed artifact","description":"Embedding E moves from v3.1 to v3.2. The registry starts from this versioned artifact and follows its recorded downstream edges.","focus":["change"]},{"title":"Expand the impact set","description":"Retrieval R and rankers K₁ through K₃ are downstream of the change. Re-evaluation includes consumers beyond the directly connected retrieval node.","focus":["retrieval","rankers"]},{"title":"Reach the final consumer","description":"Ensemble M joins the impact set through the rankers. The dashed region marks the consumers that need re-evaluation before release.","focus":["ensemble"]},{"title":"Inspect the blind spot","description":"Fraud model F is not flagged because its edge is unrecorded. An empty registry edge is not proof of independence.","focus":["missing"]}],"artwork_reviewed":true,"art_sha1":"b339a4a42e6658bf34e073f66a1990c9a2903a08","art_kind":"svg","art_width":1200,"art_height":523,"art_structural_sha1":"0f550080316f153278bf208578a69972a8a63078"},"vol2:fig-model-scaling":{"key":"vol2:fig-model-scaling","figure_id":"fig-model-scaling","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Model Scaling Laws","status":"ready","treatment":"annotated","question":"Why do fixed fractional loss improvements require multiplicative resource growth?","scope":"These normalized power-law fits apply within the cited study’s regimes. Resource axes are multiples of separate minima, not equal physical quantities.","regions":{"dataset":{"x":0.09,"y":0.07,"w":0.24,"h":0.42,"label":"Dataset exponent −0.095"},"parameters":{"x":0.28,"y":0.26,"w":0.45,"h":0.57,"label":"Parameter exponent −0.076"},"compute":{"x":0.49,"y":0.61,"w":0.47,"h":0.31,"label":"Compute exponent −0.050"},"stair":{"x":0.49,"y":0.28,"w":0.32,"h":0.33,"label":"Successive compute multiples"}},"steps":[{"title":"Read normalized slopes","description":"Each law starts at its own smallest studied resource value. On log-log axes the straight-line slope is the printed power-law exponent.","focus":["dataset","parameters"]},{"title":"Inspect the shallow compute law","description":"Compute’s −0.050 exponent means increasing work buys relatively small fractional loss reductions in this fitted regime. The curve is not a joules measurement.","focus":["compute"]},{"title":"Repeat a proportional gain","description":"The dashed staircase marks successive 10 percent loss reductions, each costing about 8.2 times the compute under the shown fit. The next equal fractional gain repeats the multiplier.","focus":["stair"]},{"title":"Bring efficiency into the energy account","description":"A resource multiplier becomes an energy multiplier only at unchanged realized FLOPs per joule. Hardware and execution efficiency must be accounted for separately.","focus":["compute"]}],"artwork_reviewed":true,"art_sha1":"f6152f129cb6963a467b4f6a2099b17c74775662","art_kind":"png","art_width":3839,"art_height":2280},"vol2:fig-model-theft-types":{"key":"vol2:fig-model-theft-types","figure_id":"fig-model-theft-types","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Model theft strategies","status":"ready","treatment":"annotated","question":"How does copying a model artifact differ from learning its behavior?","scope":"Behavioral cloning is approximate and task-dependent; the diagram does not imply identical weights or universal extraction success.","regions":{"artifact":{"x":0.04,"y":0.08,"w":0.36,"h":0.38,"label":"Stored model access"},"copy":{"x":0.04,"y":0.58,"w":0.36,"h":0.35,"label":"Exact weight copy"},"queries":{"x":0.54,"y":0.08,"w":0.43,"h":0.39,"label":"API queries and recorded outputs"},"clone":{"x":0.57,"y":0.58,"w":0.36,"h":0.35,"label":"Trained behavioral clone"}},"steps":[{"title":"Access the artifact","description":"The left path begins with a registry, bucket, or device holding the model file. Direct access can expose the weights themselves.","focus":["artifact"]},{"title":"Copy without retraining","description":"The exact-copy endpoint contains the same weights. Its access path differs from inference-only API exposure.","focus":["copy"]},{"title":"Collect input-output evidence","description":"The right path records query inputs and returned labels, logits, or scores. These pairs provide training evidence without revealing the original weights directly.","focus":["queries"]},{"title":"Train a surrogate","description":"The behavioral clone has different weights but aims for similar outputs. Interface restrictions and artifact access controls therefore address different theft mechanisms.","focus":["clone"]}],"artwork_reviewed":true,"art_sha1":"9f7ec4b2b3fcc5260c2019b1f9f955d0d901bc92","art_kind":"svg","art_width":1200,"art_height":632,"art_structural_sha1":"ff7a3921dfeab0d51a6cd716605ebba7fcd41fbf"},"vol2:fig-moe-all-to-all-routing":{"key":"vol2:fig-moe-all-to-all-routing","figure_id":"fig-moe-all-to-all-routing","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Mixture-of-experts (MoE) AllToAll routing","status":"ready","treatment":"annotated","question":"Why does expert execution require two peer exchanges?","scope":"The artwork traces token a with top-1 routing across four ranks, one expert per rank. The general gate may choose more experts.","regions":{"gate":{"x":0.02,"y":0.03,"w":0.23,"h":0.92,"label":"Tokens on source ranks"},"dispatch":{"x":0.25,"y":0.03,"w":0.16,"h":0.92,"label":"Dispatch All-to-All"},"expert":{"x":0.4,"y":0.03,"w":0.23,"h":0.92,"label":"Expert FFNs"},"return":{"x":0.63,"y":0.03,"w":0.15,"h":0.92,"label":"Return All-to-All"},"combine":{"x":0.77,"y":0.03,"w":0.21,"h":0.92,"label":"Source-rank combination"}},"steps":[{"title":"Choose an expert","description":"Token a begins on rank 0 but its gate selects Expert 2. Input ownership and expert placement need not match.","focus":["gate","expert"]},{"title":"Dispatch to expert owners","description":"The first All-to-All sends token payloads to their selected experts. Highlighted token a crosses from rank 0 to Expert 2.","focus":["dispatch"]},{"title":"Execute the expert","description":"Each expert runs its FFN on the routed tokens it receives, which may originate from multiple ranks. Uneven routing can also produce unequal loads.","focus":["expert"]},{"title":"Return and combine","description":"The second exchange returns expert results to original token owners. Rank 0 combines the result for a with its gate weight, preserving the source token order.","focus":["return","combine"]}],"artwork_reviewed":true,"art_sha1":"141e45a9104bd7c1d76c242168d1aae446787a5c","art_kind":"svg","art_width":1200,"art_height":692,"art_structural_sha1":"141e45a9104bd7c1d76c242168d1aae446787a5c"},"vol2:fig-moe-routing":{"key":"vol2:fig-moe-routing","figure_id":"fig-moe-routing","source":"books/vol2/10_inference/10_inference.qmd","title":"Mixture-of-experts (MoE) routing","status":"ready","treatment":"annotated","question":"How does top-2 expert routing create communication around sparse computation?","scope":"The four tokens and three experts are a schematic assignment; routing does not guarantee balanced expert load.","regions":{"region-1":{"x":0.03,"y":0.25,"w":0.28,"h":0.55,"label":"Tokens and top-2 gate"},"region-2":{"x":0.31,"y":0.04,"w":0.35,"h":0.91,"label":"Expert dispatch paths"},"region-3":{"x":0.65,"y":0.05,"w":0.33,"h":0.69,"label":"Gather and weighted sum"}},"steps":[{"title":"Choose experts per token","description":"The gate selects two experts for each token. This selection changes which devices must receive that token’s activations.","focus":["region-1"]},{"title":"Dispatch to selected expert devices","description":"AllToAll dispatch sends token copies to the chosen experts. Token t1 appears at Expert A and Expert B; the other shown assignments need not be equally distributed.","focus":["region-2"]},{"title":"Combine selected expert outputs","description":"AllToAll gather returns the expert outputs. The weighted sum uses the gate weights to form one output for each token; selecting fewer experts does not remove communication.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"bb962329a0ce9674dcbf08c1d5021b39ccd93597","art_kind":"svg","art_width":1200,"art_height":490,"art_structural_sha1":"152ce5cf128ca14e1a023ec0df6c515d3df6b61f"},"vol2:fig-monitoring-pipeline":{"key":"vol2:fig-monitoring-pipeline","figure_id":"fig-monitoring-pipeline","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Fairness Monitoring Pipeline","status":"ready","treatment":"annotated","question":"What must happen between detecting a subgroup gap and deploying a correction?","scope":"The threshold is an approved tolerance; label-dependent metrics wait for matched outcomes. Alerts trigger investigation, not automatic deployment.","regions":{"region-1":{"x":0.02,"y":0.04,"w":0.5,"h":0.56,"label":"Predictions and subgroup gaps"},"region-2":{"x":0.58,"y":0.28,"w":0.4,"h":0.23,"label":"Alert and candidate update"},"region-3":{"x":0.5,"y":0.76,"w":0.48,"h":0.21,"label":"Validation and authorized release"}},"steps":[{"title":"Collect enough evidence to compare groups","description":"Predictions feed subgroup gaps, with delayed matched labels arriving from above. G3 exceeds the dashed fairness tolerance while the other drawn bars stay below it.","focus":["region-1"]},{"title":"Investigate before proposing a change","description":"An exceedance opens a fairness alert for investigation. Recalibration or retraining produces a candidate update; a threshold crossing alone does not establish a safe remedy.","focus":["region-2"]},{"title":"Close the loop through a gate","description":"Subgroup-labeled validation precedes the authorized owner’s release gate. Only the approved-update path returns to the serving model; the within-tolerance branch keeps serving.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"39c0a4abd6292761081784c5ccde9c27920945ea","art_kind":"svg","art_width":1200,"art_height":468,"art_structural_sha1":"026c865beb2c359fdfc173b3b42addc5dc05c792"},"vol2:fig-monitoring-pyramid":{"key":"vol2:fig-monitoring-pyramid","figure_id":"fig-monitoring-pyramid","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Hierarchical monitoring architecture","status":"ready","treatment":"annotated","question":"How does monitoring separate incident signals from diagnostic detail?","scope":"The figure is an ownership hierarchy, not a claim that low-level metrics are unimportant or should never alert.","regions":{"business":{"x":0.16,"y":0.02,"w":0.32,"h":0.19,"label":"Business metrics and incident lead"},"portfolio":{"x":0.12,"y":0.22,"w":0.4,"h":0.2,"label":"Portfolio metrics and domain teams"},"model":{"x":0.07,"y":0.44,"w":0.51,"h":0.23,"label":"Model metrics and owners"},"infra":{"x":0.02,"y":0.69,"w":0.61,"h":0.28,"label":"Infrastructure metrics and platform team"},"signals":{"x":0.66,"y":0.02,"w":0.33,"h":0.95,"label":"Signals and owners columns"}},"steps":[{"title":"Start with broad impairment","description":"Business metrics identify revenue, conversion, or engagement trouble and route incident ownership. Few signals should require paging at this level.","focus":["business","signals"]},{"title":"Locate the model family","description":"Portfolio metrics narrow the affected domain using aggregate model outcomes. Domain teams connect broad incidents to the relevant system family.","focus":["portfolio"]},{"title":"Diagnose the model","description":"Task quality, latency, drift, and saturation provide model-specific detail. Most records support diagnosis instead of becoming separate urgent pages.","focus":["model"]},{"title":"Inspect shared resources","description":"Accelerator, feature-store, network, storage, and pipeline metrics help the platform team explain resource causes. Ownership and diagnostic depth expand toward the base.","focus":["infra"]}],"artwork_reviewed":true,"art_sha1":"0f9ef34b00e53443b200a245459254f8ca2e0248","art_kind":"svg","art_width":1200,"art_height":594,"art_structural_sha1":"ae2207f932b7e5baca5a457bb49addb341ebc4fc"},"vol2:fig-n-models-complexity":{"key":"vol2:fig-n-models-complexity","figure_id":"fig-n-models-complexity","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"The N-models complexity explosion","status":"ready","treatment":"annotated","question":"Why can portfolio coordination outgrow per-model monitoring work?","scope":"All growth shapes and team capacity are illustrative. The near-50 crossing is not a measured staffing threshold or a scheduling complexity theorem.","regions":{"linear":{"x":0.57,"y":0.38,"w":0.42,"h":0.18,"label":"Linear alert load"},"coord":{"x":0.57,"y":0.55,"w":0.42,"h":0.21,"label":"N log N deployment coordination"},"quadratic":{"x":0.6,"y":0.08,"w":0.39,"h":0.26,"label":"Quadratic dependency conflicts"},"cross":{"x":0.45,"y":0.35,"w":0.14,"h":0.19,"label":"Total-load capacity crossing"}},"steps":[{"title":"Separate fixed work per model","description":"The dotted blue alert curve grows linearly with model count under the assumed fixed monitoring burden per model.","focus":["linear"]},{"title":"Include coordination work","description":"Deployment coordination grows as the assumed N log N sketch. Release dependencies can add work beyond simply operating each model independently.","focus":["coord"]},{"title":"Inspect dense dependency risk","description":"The purple curve reflects a dense-pair quadratic assumption. A real registry’s recorded edge density determines which model pairs can actually conflict.","focus":["quadratic"]},{"title":"Measure before choosing the threshold","description":"The total crosses the illustrative team-capacity line near 50 models. A platform decision needs measured repeated work and remediation costs, not this count alone.","focus":["cross"]}],"artwork_reviewed":true,"art_sha1":"6c7724669e95eab50ff433a708601db77c0caa43","art_kind":"png","art_width":3296,"art_height":2099},"vol2:fig-nccl-allreduce-measured":{"key":"vol2:fig-nccl-allreduce-measured","figure_id":"fig-nccl-allreduce-measured","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"Measured All-Reduce Time against the Two-Parameter Model","status":"ready","treatment":"annotated","question":"Where does a two-parameter AllReduce model explain the measurements, and where does it miss?","scope":"The red points are one eight-H100 NVLink NCCL run. NVLink SHARP status is unspecified; this inspection cannot attribute residual error to one unmeasured mechanism.","regions":{"small":{"x":0.12,"y":0.68,"w":0.39,"h":0.22,"label":"Small-message floor and early outlier"},"knee":{"x":0.57,"y":0.08,"w":0.19,"h":0.77,"label":"Model knee near 5 MB"},"middle":{"x":0.48,"y":0.3,"w":0.33,"h":0.57,"label":"Intermediate-size measured excess"},"large":{"x":0.78,"y":0.04,"w":0.18,"h":0.45,"label":"Large-message agreement"},"legend":{"x":0.11,"y":0.02,"w":0.37,"h":0.17,"label":"Model and measurement legend"}},"steps":[{"title":"Distinguish observations from model","description":"The red markers are measured times and the solid line is the two-parameter model. Both axes are logarithmic, so gaps are relative differences.","focus":["legend"]},{"title":"Fit the small-message floor","description":"Most small-message points lie near the latency floor, with one early timing outlier. The model uses that floor as one of its two anchors.","focus":["small"]},{"title":"Inspect the middle mismatch","description":"Around the knee and through intermediate message sizes, measured points sit above the model. Matching the endpoints does not guarantee an accurate transition region.","focus":["knee","middle"]},{"title":"Check the bandwidth end","description":"The largest-message delivered bandwidth anchors the other end, where line and measurements converge. This is a useful bound model rather than a complete explanation of all collective regimes.","focus":["large"]}],"artwork_reviewed":true,"art_sha1":"0c088d50034679b14d3905765630c5a335700fa1","art_kind":"png","art_width":3780,"art_height":2146},"vol2:fig-network-bandwidth-scaling":{"key":"vol2:fig-network-bandwidth-scaling","figure_id":"fig-network-bandwidth-scaling","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"Historical network bandwidth scaling","status":"ready","treatment":"annotated","question":"What does the historical link-rate gap tell us about crossing a node boundary?","scope":"The series compare per-direction link budgets, including summed NVLink links per GPU and individual external ports. They are product specifications, not collective timings.","regions":{"axes":{"x":0.0,"y":0.01,"w":0.17,"h":0.86,"label":"Logarithmic per-direction bandwidth axis"},"nvlink":{"x":0.42,"y":0.04,"w":0.48,"h":0.44,"label":"NVLink generations"},"external":{"x":0.11,"y":0.42,"w":0.79,"h":0.39,"label":"Ethernet, InfiniBand, and PCIe series"},"gap":{"x":0.49,"y":0.13,"w":0.36,"h":0.53,"label":"Intra-node versus external-port gap"},"legend":{"x":0.77,"y":0.73,"w":0.22,"h":0.16,"label":"Link-family legend"}},"steps":[{"title":"Use a common unit","description":"The vertical axis is per-direction bandwidth on a logarithmic scale. Equal vertical distances represent equal ratios rather than equal absolute rate increases.","focus":["axes","legend"]},{"title":"Locate the local budget","description":"NVLink appears in 2016 and rises above the external-port series. Its points represent the GPU’s aggregate intra-node budget in the charted configurations.","focus":["nvlink"]},{"title":"Compare the exit path","description":"Ethernet and InfiniBand external ports offer smaller budgets than NVLink in these configurations. Crossing nodes can therefore expose a narrower communication path.","focus":["external","gap"]},{"title":"Avoid a timing shortcut","description":"The shaded gap bounds a resource mismatch. Payload size, port provisioning, routing, contention, and overlap determine how much of it a training step actually experiences.","focus":["gap"]}],"artwork_reviewed":true,"art_sha1":"e0ad6f053e0183c19a8139b692c935689c6a059a","art_kind":"png","art_width":3659,"art_height":2460},"vol2:fig-network-five-level-model":{"key":"vol2:fig-network-five-level-model","figure_id":"fig-network-five-level-model","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"The five-level network model for ML training","status":"ready","treatment":"annotated","question":"How do physical links become a usable training fabric?","scope":"The five tiers organize dependent design concerns; the upward arrow denotes abstraction, not a measured performance gain.","regions":{"wire":{"x":0.02,"y":0.8,"w":0.9,"h":0.18,"label":"L1: wire and link"},"transport":{"x":0.02,"y":0.61,"w":0.9,"h":0.18,"label":"L2: transport"},"topology":{"x":0.02,"y":0.42,"w":0.9,"h":0.18,"label":"L3: switch and topology"},"behavior":{"x":0.02,"y":0.23,"w":0.9,"h":0.18,"label":"L4: fabric behavior"},"cluster":{"x":0.02,"y":0.04,"w":0.9,"h":0.18,"label":"L5: cluster design"}},"steps":[{"title":"Move bits","description":"L1 starts with SerDes signaling and the copper or optical path. Every higher-level transfer must first cross these physical links.","focus":["wire"]},{"title":"Transfer between accelerators","description":"L2 adds RDMA, RoCEv2, and GPUDirect to connect GPU memory through NICs. Its cost includes both startup latency and payload transfer.","focus":["transport"]},{"title":"Arrange available paths","description":"L3 connects switches into a topology. The arrangement determines which paths and shared cuts carry simultaneous collective traffic.","focus":["topology"]},{"title":"Handle competing traffic","description":"L4 governs queues, congestion feedback, and routing under load. A connected topology alone does not establish good collective completion time.","focus":["behavior"]},{"title":"Integrate the cluster","description":"L5 combines the lower tiers with placement and failure domains. A production training fabric must satisfy all five levels together.","focus":["cluster"]}],"artwork_reviewed":true,"art_sha1":"acfd348da26de60bc67fb1d8afa0fad00e58002b","art_kind":"svg","art_width":1200,"art_height":628,"art_structural_sha1":"ec18ef3be3d6fec0f8f509184f9fce65494bb3e2"},"vol2:fig-network-topologies":{"key":"vol2:fig-network-topologies","figure_id":"fig-network-topologies","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"An illustrative bandwidth-cost scenario for ML network topologies","status":"ready","treatment":"annotated","question":"Why is topology choice a comparison of a declared configuration rather than a family name?","scope":"Bandwidths follow the stated structures and link rate; costs are assumed scenario inputs. The dashed trend is a visual comparison, not a universal pricing law.","regions":{"torus":{"x":0.17,"y":0.63,"w":0.36,"h":0.2,"label":"3D torus scenario point"},"rail":{"x":0.15,"y":0.44,"w":0.37,"h":0.19,"label":"Rail-optimized scenario point"},"fat":{"x":0.7,"y":0.21,"w":0.29,"h":0.2,"label":"Fat-tree scenario point"},"dragon":{"x":0.36,"y":0.12,"w":0.4,"h":0.18,"label":"Dragonfly scenario point"},"riser":{"x":0.61,"y":0.15,"w":0.04,"h":0.43,"label":"Dragonfly above-trend riser"}},"steps":[{"title":"Read both axes","description":"Moving right buys more bisection bandwidth; moving up pays more assumed cost per Gb/s. The torus point has the smallest capacity and lowest assumed price in this scenario.","focus":["torus"]},{"title":"Compare the configured alternatives","description":"The rail-optimized and fat-tree points offer more cut capacity at higher assumed unit cost. Their coordinates belong to these particular structures and provisioning choices.","focus":["rail","fat"]},{"title":"Inspect the exception","description":"The tapered dragonfly sits above the drawn price-capacity trend. Its long-link savings at larger scale need not appear at the scenario’s cluster size.","focus":["dragon","riser"]},{"title":"Retain the scenario boundary","description":"Changing endpoint count, radix, routing, link speed, or equipment price can move these points. A topology family name alone does not establish the plotted ranking.","focus":["dragon","fat"]}],"artwork_reviewed":true,"art_sha1":"5b73892cc1cd79f6cee30d473c71095039988b4a","art_kind":"png","art_width":3541,"art_height":2219},"vol2:fig-node-topology-comparison":{"key":"vol2:fig-node-topology-comparison","figure_id":"fig-node-topology-comparison","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Intra-node GPU topology comparison","status":"ready","treatment":"annotated","question":"How do node topologies change a transfer path and wiring cost?","scope":"Hop counts describe the drawn G0-to-G4 paths; contention and achieved collective bandwidth require additional modeling.","regions":{"ring":{"x":0.01,"y":0.03,"w":0.32,"h":0.94,"label":"Ring path"},"mesh":{"x":0.35,"y":0.03,"w":0.31,"h":0.94,"label":"Full mesh links"},"switch":{"x":0.68,"y":0.03,"w":0.32,"h":0.94,"label":"NVSwitch fabric"}},"steps":[{"title":"Traverse the ring","description":"G0 reaches G4 along four highlighted hops. Each GPU has only two direct neighbor links.","focus":["ring"]},{"title":"Pay for direct connectivity","description":"The full mesh offers a direct G0-to-G4 link, but needs seven links per GPU and 28 links in total.","focus":["mesh"]},{"title":"Share a switch fabric","description":"NVSwitch gives the pair a path through one switch fabric. This changes the wiring organization; it does not remove fabric bandwidth and contention constraints.","focus":["switch"]}],"artwork_reviewed":true,"art_sha1":"1c580b98a9e802f35aee24cbc839f45702223892","art_kind":"svg","art_width":1200,"art_height":551,"art_structural_sha1":"1c580b98a9e802f35aee24cbc839f45702223892"},"vol2:fig-observability-three-pillars":{"key":"vol2:fig-observability-three-pillars","figure_id":"fig-observability-three-pillars","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"The three pillars of observability","status":"ready","treatment":"annotated","question":"How do metrics, logs, and traces support one recovery decision?","scope":"Correlated observations narrow causes; correlation by itself does not prove a physical or software root cause.","regions":{"metrics":{"x":0.01,"y":0.01,"w":0.3,"h":0.53,"label":"Metrics"},"logs":{"x":0.34,"y":0.01,"w":0.3,"h":0.53,"label":"Logs"},"traces":{"x":0.67,"y":0.01,"w":0.31,"h":0.53,"label":"Traces"},"join":{"x":0.01,"y":0.61,"w":0.98,"h":0.17,"label":"Shared identifiers"},"action":{"x":0.25,"y":0.82,"w":0.5,"h":0.16,"label":"Recovery action"}},"steps":[{"title":"Locate the symptom","description":"Metrics establish when and where the utilization pattern changed. They do not identify the exact operation that failed.","focus":["metrics"]},{"title":"Inspect the event and request path","description":"The log records an OOM exception while the trace locates a problematic service span. These streams answer different parts of the investigation.","focus":["logs","traces"]},{"title":"Join compatible evidence","description":"Request, trace, model, feature, and deployment identifiers connect events belonging to the same operating context. An unrelated log message is weaker evidence.","focus":["join"]},{"title":"Choose a bounded response","description":"The combined evidence can support shedding load, restarting, rolling back, or degrading service. Validate the result of the action rather than treating the correlation as proof.","focus":["action"]}],"artwork_reviewed":true,"art_sha1":"f90b0d55c5de0ff1a906e86d7829d1230414a1fb","art_kind":"svg","art_width":1200,"art_height":593,"art_structural_sha1":"f392c70cdb3e6539e8f114ac719da51aa62df25e"},"vol2:fig-ondevice-gboard":{"key":"vol2:fig-ondevice-gboard","figure_id":"fig-ondevice-gboard","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"On-device prediction strategies","status":"ready","treatment":"annotated","question":"How do next-word suggestions differ from inline Smart Compose?","scope":"The screenshots show request-time local inference. They do not depict a federated-training round or show how shared model parameters are updated.","regions":{"nwpcontext":{"x":0.02,"y":0.19,"w":0.46,"h":0.11,"label":"Next-word local input context"},"suggestions":{"x":0.08,"y":0.29,"w":0.36,"h":0.11,"label":"Ranked next-word candidates"},"smartcontext":{"x":0.54,"y":0.19,"w":0.44,"h":0.11,"label":"Smart Compose input buffer"},"inline":{"x":0.7,"y":0.2,"w":0.15,"h":0.09,"label":"Inline ghost completion"},"rescore":{"x":0.57,"y":0.29,"w":0.26,"h":0.11,"label":"Rescored local candidates"}},"steps":[{"title":"Condition on typed context","description":"The left input reads “What’s your”. Next-word prediction uses that local context to rank discrete candidate tokens.","focus":["nwpcontext"]},{"title":"Offer separate candidates","description":"“favorite,” “address,” and “schedule” appear in a suggestion bar. Selecting a candidate is a request-time interaction with the inference output.","focus":["suggestions"]},{"title":"Complete inside the buffer","description":"The right panel places the multi-word continuation “ail address” inline with the typed prefix. Smart Compose rescoring supports this different presentation.","focus":["smartcontext","inline","rescore"]},{"title":"Keep inference separate from training","description":"Both panels use local context to produce immediate suggestions. Asynchronous federated training is a separate process for improving eligible shared parameters.","focus":["suggestions","inline"]}],"artwork_reviewed":true,"art_sha1":"489e84f1c1338b083941774a1b9360fc441950f6","art_kind":"png","art_width":1034,"art_height":524},"vol2:fig-ondevice-pretraining":{"key":"vol2:fig-ondevice-pretraining","figure_id":"fig-ondevice-pretraining","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Selective on-device fine-tuning","status":"ready","treatment":"annotated","question":"How is a device budget turned into a selective fine-tuning plan?","scope":"Benefit scores and the cut are schematic. Independently ranked layer gains and costs need joint validation when selected units train together.","regions":{"meta":{"x":0.02,"y":0.03,"w":0.26,"h":0.87,"label":"Cloud meta-training"},"ranking":{"x":0.3,"y":0.18,"w":0.42,"h":0.65,"label":"Benefit per unit device cost ranking"},"cut":{"x":0.43,"y":0.18,"w":0.04,"h":0.65,"label":"Device budget cut"},"update":{"x":0.77,"y":0.03,"w":0.22,"h":0.87,"label":"Selected on-device updates"}},"steps":[{"title":"Prepare an adaptable base","description":"The cloud stage meta-trains the full network on generic data so that later local updates can adapt it. This is distinct from the subsequent device-specific selection.","focus":["meta"]},{"title":"Rank candidate units","description":"Layers or channel groups are ordered by expected adaptation benefit per unit of device cost. The horizontal axis accumulates device cost.","focus":["ranking"]},{"title":"Apply the measured budget","description":"The red cut limits what fits the device’s data, compute, and memory allowance. A high-ranked unit still needs a feasible combined execution schedule.","focus":["cut"]},{"title":"Train only the selected set","description":"The final panel updates Layer 3 and the head while freezing other units in this schematic case. Backward dependencies through frozen layers may still incur work and storage.","focus":["update"]}],"artwork_reviewed":true,"art_sha1":"bc819b83b85212c17dd4a325b36e3fd574fbc71f","art_kind":"svg","art_width":1200,"art_height":494,"art_structural_sha1":"6564f7ae09b02055909617a93260589202256857"},"vol2:fig-optimization-hierarchy":{"key":"vol2:fig-optimization-hierarchy","figure_id":"fig-optimization-hierarchy","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"The profiling hierarchy","status":"ready","treatment":"annotated","question":"How does profiling connect a fleet symptom to a hardware cause?","scope":"The windows illustrate narrowing diagnostic scope; their trace shapes are schematic rather than a measured common execution.","regions":{"application":{"x":0.02,"y":0.01,"w":0.96,"h":0.2,"label":"Application and fleet metrics"},"framework":{"x":0.02,"y":0.27,"w":0.96,"h":0.22,"label":"Framework and distributed traces"},"timeline":{"x":0.02,"y":0.56,"w":0.96,"h":0.2,"label":"Kernel timeline"},"hardware":{"x":0.02,"y":0.82,"w":0.96,"h":0.17,"label":"Hardware counters"}},"steps":[{"title":"Find the service symptom","description":"The application trace compares behavior against the SLO over fleet-hours. Its highlighted window selects the interval worth investigating.","focus":["application"]},{"title":"Locate the slow rank or operation","description":"Framework and distributed traces narrow the scope to ranks and steps. The marked straggler is evidence about where the symptom concentrates.","focus":["framework"]},{"title":"Inspect execution gaps","description":"The kernel timeline resolves stream activity in milliseconds. Launch gaps and communication overlap become visible at this scale.","focus":["timeline"]},{"title":"Test a hardware explanation","description":"SM-level counters expose bandwidth, occupancy, and stalls over microseconds. This detail can explain a kernel cause but must remain connected to the original application symptom.","focus":["hardware"]}],"artwork_reviewed":true,"art_sha1":"4a1d6f2e9bf600e7e336f3c184959831b61d36f9","art_kind":"svg","art_width":1200,"art_height":853,"art_structural_sha1":"4a1d6f2e9bf600e7e336f3c184959831b61d36f9"},"vol2:fig-overlap-budget":{"key":"vol2:fig-overlap-budget","figure_id":"fig-overlap-budget","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"The overlap budget","status":"ready","treatment":"annotated","question":"Why can a fixed compute budget hide a shrinking share of communication?","scope":"The normalized bar values are illustrative operating points. GPU count alone does not determine overhead, and overlapped time is not an extra serial cost.","regions":{"budget":{"x":0.16,"y":0.7,"w":0.8,"h":0.05,"label":"Fixed 100-unit compute budget"},"small":{"x":0.17,"y":0.7,"w":0.17,"h":0.13,"label":"Small-scale bars"},"overlap":{"x":0.37,"y":0.68,"w":0.24,"h":0.15,"label":"Hidden communication inside compute budget"},"exposed":{"x":0.68,"y":0.18,"w":0.2,"h":0.55,"label":"Large exposed communication tail"},"percent":{"x":0.18,"y":0.07,"w":0.7,"h":0.1,"label":"Share of communication hidden"}},"steps":[{"title":"Keep computation fixed","description":"The dashed line holds useful computation at 100 units. Violet overlap occupies time inside that budget rather than being added serially on top.","focus":["budget","overlap"]},{"title":"Inspect the small case","description":"At the smallest scale, little communication remains above the compute budget. Most of its assumed communication can fit behind independent computation.","focus":["small"]},{"title":"Exhaust the hiding window","description":"At larger scales, the red hatched portion extends far above the same compute budget. That exposed portion lengthens the modeled execution window.","focus":["exposed"]},{"title":"Read the denominator correctly","description":"The percentages report the fraction of communication hidden, falling from 92 to 18 percent. They are not compute utilization or the fraction of total step time hidden.","focus":["percent"]}],"artwork_reviewed":true,"art_sha1":"94aa6db6e03d1729bd13179d48a2eef21f0a97a0","art_kind":"png","art_width":3661,"art_height":2220},"vol2:fig-pam4-vs-nrz":{"key":"vol2:fig-pam4-vs-nrz","figure_id":"fig-pam4-vs-nrz","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"From NRZ to PAM4 signaling","status":"ready","treatment":"annotated","question":"Why can PAM4 carry more bits per symbol while reducing voltage margin?","scope":"Equal symbol periods and normalized voltage ranges are a schematic comparison, not a complete link throughput or error-rate model.","regions":{"nrz":{"x":0.03,"y":0.06,"w":0.46,"h":0.73,"label":"NRZ waveform and two levels"},"nrzbits":{"x":0.1,"y":0.74,"w":0.34,"h":0.2,"label":"Six NRZ bits"},"pam":{"x":0.52,"y":0.06,"w":0.47,"h":0.73,"label":"PAM4 waveform and four levels"},"pambits":{"x":0.58,"y":0.74,"w":0.34,"h":0.2,"label":"Twelve PAM4 bits"},"margin":{"x":0.91,"y":0.27,"w":0.07,"h":0.43,"label":"One-third swing spacing"}},"steps":[{"title":"Encode one bit","description":"The NRZ panel uses two signal levels. Its six symbol slots encode six bits.","focus":["nrz","nrzbits"]},{"title":"Encode a pair","description":"PAM4 selects among four levels for each symbol. The same six symbol slots encode twelve bits.","focus":["pam","pambits"]},{"title":"Pay for closer levels","description":"The PAM4 level spacing is one third of the full swing. Distinguishing nearby levels demands greater signal integrity and error-control care.","focus":["margin"]},{"title":"Separate encoding from delivered rate","description":"The panel compares bits per symbol; coding overhead and link implementation still determine usable bandwidth and latency.","focus":["nrzbits","pambits"]}],"artwork_reviewed":true,"art_sha1":"3e38460953fb82a7c8a4149c97ddeb6eb5e3ffc2","art_kind":"svg","art_width":1200,"art_height":481,"art_structural_sha1":"0481841de58d55d4bfb4d5ff12215ac878e6a1bc"},"vol2:fig-parallelism-flowchart":{"key":"vol2:fig-parallelism-flowchart","figure_id":"fig-parallelism-flowchart","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Parallelism strategy decision framework","status":"ready","treatment":"annotated","question":"Which constraint should determine the first parallelism candidate?","scope":"This is a selection guide, not an automatic optimizer. Peak memory, global batch, input delivery, bandwidth, and imbalance constrain every branch.","regions":{"fit":{"x":0.02,"y":0.05,"w":0.53,"h":0.27,"label":"Memory and throughput questions"},"depth":{"x":0.02,"y":0.35,"w":0.25,"h":0.2,"label":"Deep sequential stack decision"},"layer":{"x":0.02,"y":0.55,"w":0.25,"h":0.19,"label":"Single-layer fit decision"},"choices":{"x":0.62,"y":0.13,"w":0.35,"h":0.75,"label":"Candidate strategies"},"combine":{"x":0.62,"y":0.91,"w":0.35,"h":0.07,"label":"Combine axes"}},"steps":[{"title":"Start with memory fit","description":"A model that fits on one GPU can remain single-device if it meets the target. Otherwise data parallelism is a candidate, provided input delivery and global-batch constraints permit it.","focus":["fit"]},{"title":"Identify what breaks the budget","description":"A deep sequence of layers suggests pipeline stages. A single oversized layer suggests tensor partitioning rather than only moving whole layers.","focus":["depth","layer"]},{"title":"Consider state sharding","description":"The remaining memory case leads to sharded data parallelism such as FSDP or ZeRO. The candidate cards describe different state and communication arrangements.","focus":["choices"]},{"title":"Combine after checking constraints","description":"The bottom box combines TP, PP, and DP when necessary. The guide does not remove the need to validate memory peaks and the network hierarchy.","focus":["combine"]}],"artwork_reviewed":true,"art_sha1":"ae734af690ff7ff73bfcf585159aba3e0215915f","art_kind":"svg","art_width":1200,"art_height":870,"art_structural_sha1":"558b5856ce41246c1a34d3738b0941e54d644885"},"vol2:fig-performance-engineering-block-quantization":{"key":"vol2:fig-performance-engineering-block-quantization","figure_id":"fig-performance-engineering-block-quantization","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Block-wise versus per-tensor quantization","status":"ready","treatment":"annotated","question":"How does block scaling confine an outlier’s quantization damage?","scope":"This fixed eight-weight INT8 example demonstrates representation resolution; it is not a model-quality or kernel-speed benchmark.","regions":{"tensorweights":{"x":0.02,"y":0.14,"w":0.47,"h":0.25,"label":"Per-tensor FP16 weights and outlier"},"tensorscale":{"x":0.02,"y":0.4,"w":0.47,"h":0.16,"label":"One shared scale"},"tensorint":{"x":0.02,"y":0.65,"w":0.47,"h":0.32,"label":"Per-tensor INT8 results"},"blocks":{"x":0.52,"y":0.16,"w":0.47,"h":0.41,"label":"Two blocks with separate scales"},"blockint":{"x":0.52,"y":0.65,"w":0.47,"h":0.32,"label":"Block-wise INT8 results"}},"steps":[{"title":"Find the extreme value","description":"Both panels contain the same weight 58.7 beside much smaller values. One tensor-wide scale must accommodate that outlier.","focus":["tensorweights","tensorscale"]},{"title":"Lose small-value resolution","description":"With the shared coarse scale, six small weights round to zero and the remaining small weight rounds to one. INT8 range is spent representing the outlier.","focus":["tensorint"]},{"title":"Separate the blocks","description":"The right panel assigns one scale to each four-weight block. The block without the outlier can use a much finer scale.","focus":["blocks"]},{"title":"Confine rather than erase damage","description":"The first block retains distinct integer values; small weights sharing the outlier’s block still collapse. More blocks require more scale metadata.","focus":["blockint"]}],"artwork_reviewed":true,"art_sha1":"74cecb0aa5a7a5f45c8fb84fb688d5a575da7b89","art_kind":"svg","art_width":1200,"art_height":422,"art_structural_sha1":"b90f3ab093906c3d960b3fb7812533b052fe008c"},"vol2:fig-performance-engineering-compilation-pipeline":{"key":"vol2:fig-performance-engineering-compilation-pipeline","figure_id":"fig-performance-engineering-compilation-pipeline","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Deep learning compilation pipeline","status":"ready","treatment":"annotated","question":"How do four captured operations become three generated kernels?","scope":"This is one illustrative lowering of a feed-forward block; backend decisions and actual kernel counts depend on the model and target.","regions":{"capture":{"x":0.02,"y":0.02,"w":0.22,"h":0.94,"label":"Graph capture"},"optimize":{"x":0.27,"y":0.02,"w":0.23,"h":0.94,"label":"Graph optimization"},"fusion":{"x":0.52,"y":0.02,"w":0.23,"h":0.94,"label":"Operator fusion"},"codegen":{"x":0.77,"y":0.02,"w":0.22,"h":0.94,"label":"Code generation"}},"steps":[{"title":"Capture the operations","description":"TorchDynamo records Linear, GELU, Linear, and LayerNorm. The captured graph contains four operations.","focus":["capture"]},{"title":"Expose GEMM primitives","description":"Graph-level decomposition and optimization represent the linear stages as GEMM plus bias. Operation identity is retained while the compiler exposes lower-level structure.","focus":["optimize"]},{"title":"Form a fused group","description":"TorchInductor groups the first GEMM with its GELU epilogue. The remaining GEMM and LayerNorm stay separate, giving three groups.","focus":["fusion"]},{"title":"Select executable kernels","description":"Code generation maps the fused group and normalization to Triton and the separate GEMM to cuBLAS in this example. The result is three kernels, not a universal compiler promise.","focus":["codegen"]}],"artwork_reviewed":true,"art_sha1":"543c5c3b451852d9ea773f98435555435c035c14","art_kind":"svg","art_width":1200,"art_height":600,"art_structural_sha1":"db8db05671cdc9da639057a909e726183629e4ab"},"vol2:fig-performance-engineering-flashattention-tiling":{"key":"vol2:fig-performance-engineering-flashattention-tiling","figure_id":"fig-performance-engineering-flashattention-tiling","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"FlashAttention memory hierarchy tiling","status":"ready","treatment":"annotated","question":"How does FlashAttention avoid storing the full score matrix in HBM?","scope":"The drawn tile schedule explains storage placement. SRAM capacity, accumulators, buffering, and tile reloads still affect the complete working set and traffic.","regions":{"hbm":{"x":0.01,"y":0.01,"w":0.55,"h":0.98,"label":"HBM matrices Q, K, V, O"},"tiles":{"x":0.75,"y":0.16,"w":0.21,"h":0.18,"label":"Loaded Q, K, V tiles in SRAM"},"score":{"x":0.73,"y":0.36,"w":0.24,"h":0.12,"label":"On-chip score tile"},"softmax":{"x":0.73,"y":0.55,"w":0.24,"h":0.13,"label":"Online softmax state"},"accumulate":{"x":0.73,"y":0.75,"w":0.24,"h":0.13,"label":"Rescaled output accumulator"},"avoid":{"x":0.19,"y":0.56,"w":0.31,"h":0.15,"label":"Quadratic scores never written"}},"steps":[{"title":"Stage blocks","description":"The selected Qi, Kj, and Vj tiles are loaded from HBM to SRAM. The full input and output matrices remain in HBM.","focus":["hbm","tiles"]},{"title":"Consume a score tile","description":"The on-chip product Sij = Qi Kj transpose produces one score tile. It is consumed locally instead of becoming a full sequence-by-sequence HBM tensor.","focus":["score","avoid"]},{"title":"Update normalization online","description":"Running maxima and sums let softmax incorporate successive tiles. The output accumulator is rescaled as the normalization changes.","focus":["softmax","accumulate"]},{"title":"Write the accumulated output","description":"After the required tiles have been processed, Oi is written to HBM. Eliminating the quadratic intermediate does not eliminate input loads or tile reloads.","focus":["accumulate","hbm"]}],"artwork_reviewed":true,"art_sha1":"e448f044f6ef82037ee87faff92e6e3c5dc808db","art_kind":"svg","art_width":1200,"art_height":749,"art_structural_sha1":"b5bc7d5eee1db8a34d1ed93d0ca3252b282a654a"},"vol2:fig-personalization-arch":{"key":"vol2:fig-personalization-arch","figure_id":"fig-personalization-arch","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Federated personalization architectures","status":"ready","treatment":"annotated","question":"How does the adaptation choice change backward-state requirements?","scope":"The comparison fixes the shown backbone structure. Frozen parameters remove their own gradients and optimizer state, but not every backward dependency.","regions":{"full":{"x":0.02,"y":0.01,"w":0.29,"h":0.84,"label":"A: full fine-tuning"},"head":{"x":0.36,"y":0.01,"w":0.29,"h":0.84,"label":"B: head-only adaptation"},"adapters":{"x":0.68,"y":0.01,"w":0.31,"h":0.84,"label":"C: adapter-based adaptation"},"legend":{"x":0.13,"y":0.87,"w":0.78,"h":0.12,"label":"Frozen, trainable, and retained-state legend"}},"steps":[{"title":"Train the whole network","description":"Full fine-tuning updates each layer and the task head. The full-height backward arrow and hatched state column show its deep backward dependencies.","focus":["full"]},{"title":"Stop at the head","description":"Head-only adaptation freezes the feature extractor. In this comparison, backpropagation stops at the task head, so the backbone’s backward state is unnecessary.","focus":["head"]},{"title":"Train small modules at depth","description":"Adapters leave backbone weights frozen but introduce trainable modules beside its layers. Reaching those modules requires backward propagation through the intervening frozen backbone.","focus":["adapters"]},{"title":"Separate parameters from live state","description":"Small trainable parameter count alone does not establish a short backward path. The hatched marks identify state that must still be retained or recomputed.","focus":["adapters","legend"]}],"artwork_reviewed":true,"art_sha1":"59f1547f0bf6089be12f7d5f962e12b7ccc7d88f","art_kind":"svg","art_width":1200,"art_height":527,"art_structural_sha1":"c5c7c8128061b02239446a2b3abbca877720c242"},"vol2:fig-pfc-credit-deadlock":{"key":"vol2:fig-pfc-credit-deadlock","figure_id":"fig-pfc-credit-deadlock","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"A PFC deadlock from a cyclic buffer dependency","status":"ready","treatment":"annotated","question":"Why can four full queues remain blocked after traffic injection stops?","scope":"A directed cycle alone is insufficient: this example additionally assumes occupied buffers, blocked successors, and persistent PAUSE states.","regions":{"b1":{"x":0.38,"y":0.04,"w":0.24,"h":0.22,"label":"Switch 1 full queue"},"b2":{"x":0.69,"y":0.4,"w":0.24,"h":0.22,"label":"Switch 2 full queue"},"b3":{"x":0.38,"y":0.76,"w":0.24,"h":0.22,"label":"Switch 3 full queue"},"b4":{"x":0.07,"y":0.4,"w":0.24,"h":0.22,"label":"Switch 4 full queue"},"forward":{"x":0.6,"y":0.08,"w":0.31,"h":0.34,"label":"Clockwise forwarding dependency"},"pause":{"x":0.47,"y":0.24,"w":0.29,"h":0.24,"label":"Counterclockwise PAUSE feedback"}},"steps":[{"title":"Need downstream space","description":"Switch 1 holds packets whose next buffer is b2. The solid clockwise arrows continue this requirement through b3 and b4 back to b1.","focus":["b1","forward","b2"]},{"title":"Pause the predecessor","description":"Each full queue sends PAUSE upstream, against the forwarding direction. Switch 2 therefore prevents its predecessor from sending more traffic.","focus":["pause","b2"]},{"title":"Close the waiting cycle","description":"All four queues wait for successors that are themselves blocked. No queue can drain enough to clear its PAUSE state.","focus":["b1","b2","b3","b4"]},{"title":"Break a dependency","description":"In the depicted deadlock, stopping new injection is insufficient. Recovery must break the closed wait, for example through the stated watchdog dropping packets.","focus":["b3","b4"]}],"artwork_reviewed":true,"art_sha1":"21c7291d8485449f912d5f8ce38a412a30d63380","art_kind":"svg","art_width":1200,"art_height":742,"art_structural_sha1":"8d207d62d2695de55ed77750e02994910fb3623f"},"vol2:fig-pipeline-bubbles":{"key":"vol2:fig-pipeline-bubbles","figure_id":"fig-pipeline-bubbles","source":"books/vol2/10_inference/10_inference.qmd","title":"Pipeline parallelism bubbles","status":"ready","treatment":"annotated","question":"How can several independent requests fill a pipeline that one request cannot?","scope":"Time cells are illustrative stage slots; this diagram does not model unequal stage times or the pipeline drain.","regions":{"region-1":{"x":0.03,"y":0.04,"w":0.95,"h":0.25,"label":"Single-request stage chain"},"region-2":{"x":0.13,"y":0.58,"w":0.34,"h":0.28,"label":"Pipeline fill bubbles"},"region-3":{"x":0.48,"y":0.45,"w":0.49,"h":0.41,"label":"Full pipeline columns"}},"steps":[{"title":"Follow one request’s dependencies","description":"One request passes through Stage 0 to Stage 3 in order. Activations cross GPUs; the later stage cannot process that request before its predecessor finishes.","focus":["region-1"]},{"title":"Account for initial idle slots","description":"In the multi-request timeline, lower GPUs initially show hatched fill bubbles. They are idle because no earlier stage has supplied activations yet.","focus":["region-2"]},{"title":"Overlap different requests","description":"Once filled, each GPU works on a different request in the same time slot. This raises aggregate utilization while each individual request still traverses all stages.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"d8562fbd5634f88b41742e4e8f3011b5d8a79d73","art_kind":"svg","art_width":1200,"art_height":607,"art_structural_sha1":"5aa8bd7a3543cab9501c4c2ca4a43edfda329b2d"},"vol2:fig-pipeline-parallelism":{"key":"vol2:fig-pipeline-parallelism","figure_id":"fig-pipeline-parallelism","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Pipeline parallelism schedule","status":"ready","treatment":"annotated","question":"Where do fill and drain bubbles remain in a microbatched pipeline?","scope":"This is GPipe-style all-forward-then-all-backward scheduling with four stages, four microbatches, and equal illustrative slots.","regions":{"fill":{"x":0.1,"y":0.12,"w":0.17,"h":0.7,"label":"Pipeline fill"},"forward":{"x":0.26,"y":0.12,"w":0.22,"h":0.7,"label":"Forward microbatch wave"},"backward":{"x":0.47,"y":0.12,"w":0.37,"h":0.7,"label":"Backward dependency wave"},"summary":{"x":0.85,"y":0.1,"w":0.14,"h":0.73,"label":"Six idle slots per stage"}},"steps":[{"title":"Fill the pipeline","description":"Early stages start microbatches before later stages have inputs. The left hatched triangles are dependency-driven idle slots.","focus":["fill"]},{"title":"Keep multiple batches active","description":"Forward blocks m1 through m4 form a diagonal wave. Different stages can work concurrently because they hold different microbatches.","focus":["forward"]},{"title":"Respect backward dependencies","description":"Backward blocks return in reverse microbatch order. A stage waits for the next stage’s gradient for that same microbatch.","focus":["backward"]},{"title":"Retain the bubble cost","description":"The summary shows six of fourteen slots idle for every stage. Microbatching improves occupancy here but does not remove fill and drain.","focus":["summary"]}],"artwork_reviewed":true,"art_sha1":"012f31da286a3e247e018fe440361ad08936c02f","art_kind":"svg","art_width":1200,"art_height":532,"art_structural_sha1":"8ba84bd890896db3cfe54adfffd098e4f97a96d2"},"vol2:fig-platform-roi-threshold":{"key":"vol2:fig-platform-roi-threshold","figure_id":"fig-platform-roi-threshold","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"The platform benefit-cost threshold","status":"ready","treatment":"annotated","question":"How does a benefit–cost ratio differ from net ROI?","scope":"The model assumes $100K annual benefit per model and fixed $2M/year or $5M/year running cost. These are not the separate worked example’s one-time build costs.","regions":{"cheap":{"x":0.11,"y":0.08,"w":0.88,"h":0.56,"label":"Two-million annual platform curve"},"enterprise":{"x":0.29,"y":0.49,"w":0.7,"h":0.39,"label":"Five-million annual platform curve"},"break":{"x":0.09,"y":0.69,"w":0.89,"h":0.17,"label":"Benefit/cost = 1 break-even"},"five":{"x":0.52,"y":0.23,"w":0.21,"h":0.24,"label":"Ratio five and 400 percent ROI"}},"steps":[{"title":"Locate annual break-even","description":"The horizontal line at benefit/cost = 1 means annual benefit equals annual running cost. Net ROI is zero there, not 100 percent.","focus":["break"]},{"title":"Change the cost budget","description":"With the fixed per-model benefit, the $2M/year platform crosses at 20 models and the $5M/year platform at 50. Higher fixed annual cost requires more benefit to cover it.","focus":["cheap","enterprise"]},{"title":"Translate the ratio","description":"At 100 models the cheaper platform has benefit/cost = 5. Subtracting the original cost gives net ROI = 4, or 400 percent.","focus":["five"]},{"title":"Preserve the assumptions","description":"The straight lines assume constant marginal benefit and fixed platform cost. Dependency growth or diminishing savings would change the slopes and crossings.","focus":["cheap","enterprise"]}],"artwork_reviewed":true,"art_sha1":"0af28543d3972075275f348f815a11b23aa03475","art_kind":"png","art_width":3300,"art_height":2100},"vol2:fig-pod-network-topology":{"key":"vol2:fig-pod-network-topology","figure_id":"fig-pod-network-topology","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Pod-scale network topologies","status":"ready","treatment":"annotated","question":"How does pod topology change the resources crossing a network cut?","scope":"The diagrams compare topology and stated provisioning, not measured latency or a universal performance ranking.","regions":{"fat":{"x":0.01,"y":0.02,"w":0.49,"h":0.96,"label":"Switched fat-tree"},"torus":{"x":0.52,"y":0.02,"w":0.47,"h":0.96,"label":"Two-dimensional torus"},"cut":{"x":0.73,"y":0.11,"w":0.07,"h":0.7,"label":"Torus bisection cut"}},"steps":[{"title":"Provision the leaf boundary","description":"The highlighted fat-tree leaf has four uplinks matching four node ports. This illustrated provisioning supports full bisection bandwidth.","focus":["fat"]},{"title":"Connect local neighbors","description":"Each torus node connects to four neighbors, with wraparound links at the edges. Link count remains local as the array grows.","focus":["torus"]},{"title":"Count cut-crossing links","description":"The dashed bisection crosses a limited number of torus links. The figure’s square-root growth describes this two-dimensional construction.","focus":["cut"]}],"artwork_reviewed":true,"art_sha1":"49f3e19e3e519dbf47e7bc900f93686b064968b6","art_kind":"svg","art_width":1200,"art_height":551,"art_structural_sha1":"49f3e19e3e519dbf47e7bc900f93686b064968b6"},"vol2:fig-poisoning":{"key":"vol2:fig-poisoning","figure_id":"fig-poisoning","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Concept Poisoning Dose-Response","status":"ready","treatment":"annotated","question":"How does the reported poisoning dose change generated concepts?","scope":"These are observed Stable Diffusion XL outputs under the study’s tested pipeline; comparisons do not reveal the internal representation or predict other models.","regions":{"clean":{"x":0.14,"y":0.04,"w":0.86,"h":0.22,"label":"Clean outputs across prompts"},"dog":{"x":0.14,"y":0.04,"w":0.11,"h":0.92,"label":"Dog prompt toward cat destination"},"car":{"x":0.25,"y":0.04,"w":0.11,"h":0.92,"label":"Car prompt toward cow destination"},"dose":{"x":0.14,"y":0.76,"w":0.86,"h":0.22,"label":"300-sample outputs and destination concepts"}},"steps":[{"title":"Establish the clean baseline","description":"The top row shows outputs for the original source prompts before the added poison samples. Preserve each column’s prompt when comparing doses.","focus":["clean"]},{"title":"Follow one fixed prompt down the doses","description":"The dog column changes toward the cat destination as the displayed dose increases. This compares generated outputs rather than directly measuring a hidden representation.","focus":["dog"]},{"title":"Check a second concept","description":"The car column progresses toward the cow destination. Different source prompts share the experiment but need not respond identically.","focus":["car"]},{"title":"Read the highest displayed dose","description":"The bottom row compares 300-sample outputs with the printed destination concepts. It supports a dose-response observation within these conditions, not a universal threshold.","focus":["dose"]}],"artwork_reviewed":true,"art_sha1":"25125749b71572e829142ecfca6ee2c99c7adfa8","art_kind":"png","art_width":673,"art_height":346},"vol2:fig-poisoning-attack-example":{"key":"vol2:fig-poisoning-attack-example","figure_id":"fig-poisoning-attack-example","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Collaborative Poisoning via Aggregation","status":"ready","treatment":"annotated","question":"How can one malicious federated update influence the aggregated model?","scope":"The figure illustrates weighted aggregation and a malicious contribution; it does not quantify attack success or prescribe an attack.","regions":{"clients":{"x":0.01,"y":0.73,"w":0.98,"h":0.25,"label":"Client update sources"},"bad":{"x":0.25,"y":0.73,"w":0.23,"h":0.25,"label":"Malicious client 2"},"server":{"x":0.01,"y":0.02,"w":0.98,"h":0.43,"label":"Aggregation server"},"vectors":{"x":0.6,"y":0.04,"w":0.37,"h":0.36,"label":"Honest poisoned and aggregate directions"}},"steps":[{"title":"Collect distributed updates","description":"Each client sends a local model update to the server. The server combines contributions with the printed sample-count weighting.","focus":["clients","server"]},{"title":"Distinguish the malicious contribution","description":"Client 2 sends the red poisoned update among honest updates. Aggregation receives a mixture of trusted and adversarial behavior.","focus":["bad"]},{"title":"Inspect the aggregate direction","description":"The inset contrasts honest directions, the malicious direction, and their aggregate. A weighted mean does not automatically identify or neutralize a malicious contribution.","focus":["vectors"]}],"artwork_reviewed":true,"art_sha1":"4baca840590a0cff88acd63a96b466f9ec601bbe","art_kind":"svg","art_width":1200,"art_height":611,"art_structural_sha1":"fe9ed5429291d913881ad67d7780b1562c17b37d"},"vol2:fig-poisoning-impact":{"key":"vol2:fig-poisoning-impact","figure_id":"fig-poisoning-impact","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Data Poisoning Impact","status":"ready","treatment":"annotated","question":"How can poisoning preserve ordinary accuracy while changing targeted behavior?","scope":"The two rows are conceptual mechanisms, not quantitative experimental results or proof of a particular poisoning rate.","regions":{"clean":{"x":0.12,"y":0.06,"w":0.86,"h":0.4,"label":"Nominal training path"},"entry":{"x":0.12,"y":0.55,"w":0.4,"h":0.37,"label":"Poisoned ingestion and corpus"},"optim":{"x":0.56,"y":0.55,"w":0.19,"h":0.37,"label":"Shifted optimization path"},"boundary":{"x":0.8,"y":0.55,"w":0.19,"h":0.4,"label":"Backdoor pocket in trained model"}},"steps":[{"title":"Establish nominal learning","description":"The top row follows clean ingestion through a verified corpus and ordinary optimization to a nominal decision boundary.","focus":["clean"]},{"title":"Admit a poisoned record","description":"The lower row changes one incoming record and carries it into the corpus. The corruption need not dominate the dataset.","focus":["entry"]},{"title":"Alter the learned target","description":"The red optimization path is pulled toward a trigger-related behavior. This is distinct from simply increasing average training loss.","focus":["optim"]},{"title":"Inspect the localized failure","description":"The final model contains a backdoor pocket while clean accuracy remains intact in this illustration. Aggregate clean accuracy alone can miss a targeted failure.","focus":["boundary"]}],"artwork_reviewed":true,"art_sha1":"ec2550c4547dad63b5c50998a2dedde016583405","art_kind":"svg","art_width":1200,"art_height":614,"art_structural_sha1":"623dc20a2e88a0c531019090d7f009ab5513a5a8"},"vol2:fig-power-path":{"key":"vol2:fig-power-path","figure_id":"fig-power-path","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"The power delivery path","status":"ready","treatment":"annotated","question":"Why does a megawatt of GPU power require more power at the utility input?","scope":"Loss percentages and power levels are an illustrative power path, not a facility-wide efficiency measurement.","regions":{"upstream":{"x":0.01,"y":0.02,"w":0.44,"h":0.85,"label":"Utility transformer and UPS"},"cabinet":{"x":0.46,"y":0.02,"w":0.38,"h":0.85,"label":"Rack PDU and server PSU"},"gpu":{"x":0.84,"y":0.02,"w":0.16,"h":0.85,"label":"VRM and GPU dies"}},"steps":[{"title":"Enter through facility conversion","description":"The utility, transformer, and UPS supply the IT load. Each conversion loses some input energy as heat.","focus":["upstream"]},{"title":"Distribute inside cabinets","description":"Rack PDUs and server PSUs continue the conversion path. The dashed cabinet boundary identifies losses inside the rack envelope.","focus":["cabinet"]},{"title":"Reach the GPU voltage","description":"The final voltage regulator delivers the low voltage required at the dies. The drawn 1 MW endpoint therefore requires about 1.3 MW at the beginning of this example.","focus":["gpu"]}],"artwork_reviewed":true,"art_sha1":"65e14e7c866cb5cba50ddb5629f852002e198446","art_kind":"svg","art_width":1200,"art_height":590,"art_structural_sha1":"65e14e7c866cb5cba50ddb5629f852002e198446"},"vol2:fig-predictive-reactive-scaling":{"key":"vol2:fig-predictive-reactive-scaling","figure_id":"fig-predictive-reactive-scaling","source":"books/vol2/10_inference/10_inference.qmd","title":"Predictive vs. reactive scaling","status":"ready","treatment":"annotated","question":"Why can predictive scaling reduce a capacity shortfall that reactive scaling reaches too late?","scope":"Both panels are illustrative normalized schedules. Predictive scaling depends on forecast quality and does not eliminate every shortfall.","regions":{"region-1":{"x":0.12,"y":0.03,"w":0.86,"h":0.42,"label":"Reactive demand and deficit"},"region-2":{"x":0.12,"y":0.52,"w":0.86,"h":0.39,"label":"Predictive early scale-up"},"region-3":{"x":0.18,"y":0.69,"w":0.3,"h":0.22,"label":"Residual shortfall"}},"steps":[{"title":"Observe demand before capacity arrives","description":"In panel (a), the dashed demand curve rises while reactive capacity stays low. The shaded red capacity deficit accumulates before scale-up begins.","focus":["region-1"]},{"title":"Start capacity preparation earlier","description":"Panel (b) begins scale-up before the demand peak. Capacity ramps ahead of most of the surge rather than waiting for the late reactive trigger.","focus":["region-2"]},{"title":"Retain the remaining mismatch","description":"The lower panel still labels a brief, small shortfall. Forecasting and provisioning improve this constructed alignment without guaranteeing perfect anticipation.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"e7515235a202aa4403110cb7fe6d131eafb754c8","art_kind":"png","art_width":3028,"art_height":2700},"vol2:fig-prefill-decode-energy":{"key":"vol2:fig-prefill-decode-energy","figure_id":"fig-prefill-decode-energy","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Reuse in Prefill and Decode","status":"ready","treatment":"annotated","question":"How does the available weight reuse differ between prefill and decode?","scope":"These are mechanisms rather than measured utilization or a universal energy-per-token ratio. Decode batch size changes the reuse opportunity.","regions":{"prefillweights":{"x":0.02,"y":0.02,"w":0.46,"h":0.37,"label":"Prefill weights"},"prefillwork":{"x":0.05,"y":0.39,"w":0.42,"h":0.44,"label":"New prompt positions"},"decodeweights":{"x":0.54,"y":0.02,"w":0.44,"h":0.24,"label":"Decode weights"},"decodework":{"x":0.54,"y":0.27,"w":0.44,"h":0.28,"label":"Active decode compute and idle slots"},"cache":{"x":0.58,"y":0.54,"w":0.37,"h":0.4,"label":"KV cache read each step"}},"steps":[{"title":"Reuse across prompt positions","description":"Prefill uses the same weights across many new positions in the prompt. The fan-out leads to multiple active compute blocks.","focus":["prefillweights","prefillwork"]},{"title":"Reuse across active sequences","description":"A decode iteration generates new tokens for the active sequences. Increasing that active batch can create additional reuse of the same weights.","focus":["decodeweights","decodework"]},{"title":"Retain and read prior context","description":"Decode reads the KV cache at each step as well as producing the new token. Persistent context therefore adds memory traffic beyond reading weights.","focus":["cache"]},{"title":"Recognize the underfilled case","description":"The dashed idle blocks illustrate arithmetic capacity that a small decode batch cannot fill. This mechanism does not itself give an energy ratio.","focus":["decodework"]}],"artwork_reviewed":true,"art_sha1":"dd848f6e6cfad3f2893bd1c5ae8f54b1cc6df28c","art_kind":"svg","art_width":1200,"art_height":564,"art_structural_sha1":"dd848f6e6cfad3f2893bd1c5ae8f54b1cc6df28c"},"vol2:fig-prefix-caching":{"key":"vol2:fig-prefix-caching","figure_id":"fig-prefix-caching","source":"books/vol2/10_inference/10_inference.qmd","title":"Prefix caching via block sharing","status":"ready","treatment":"annotated","question":"Which KV blocks can two requests reuse without sharing their distinct suffixes?","scope":"Reuse requires identical token prefixes and compatible model computation, adapters, and other state-affecting inputs, with authorized tenant sharing. Matching visible text alone is insufficient.","regions":{"region-1":{"x":0.2,"y":0.04,"w":0.43,"h":0.23,"label":"Request A shared prefix"},"region-2":{"x":0.2,"y":0.36,"w":0.43,"h":0.2,"label":"Physical prefix blocks"},"region-3":{"x":0.7,"y":0.04,"w":0.26,"h":0.86,"label":"Private suffix blocks"}},"steps":[{"title":"Identify the reusable prefix","description":"Request A’s green logical pages P0 through P5 form the shared prefix. The ellipsis omits intermediate pages without changing the prefix boundary.","focus":["region-1"]},{"title":"Map both requests to one copy","description":"Both requests’ green prefix pages point to B0 through B5 in GPU HBM. Logical page identity is separate from physical block ownership and reuse.","focus":["region-2"]},{"title":"Keep suffix state distinct","description":"Suffix A maps to B10 and B11, while suffix B maps to B12 through B14. Newly diverging tokens require distinct state even when earlier prefix blocks are shared.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"19de7b0160ac3223b67cc764ba05c2cb8f5e64dc","art_kind":"svg","art_width":1200,"art_height":600,"art_structural_sha1":"90e329a8e1a4bbebaf3190fdcee740c56f639576"},"vol2:fig-privacy-risk-flow":{"key":"vol2:fig-privacy-risk-flow","figure_id":"fig-privacy-risk-flow","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Privacy Boundaries in Federated Training","status":"ready","treatment":"annotated","question":"Which privacy protection applies before aggregation and which applies to the public release?","scope":"This is central differential privacy with a trusted curator. Secure aggregation and DP have different assumptions and do not form a universal strength ranking.","regions":{"region-1":{"x":0.02,"y":0.06,"w":0.26,"h":0.81,"label":"Client records and clipped updates"},"region-2":{"x":0.32,"y":0.03,"w":0.22,"h":0.91,"label":"Secure aggregation boundary"},"region-3":{"x":0.58,"y":0.03,"w":0.4,"h":0.86,"label":"Trusted curator and public release"}},"steps":[{"title":"Keep raw records on clients","description":"Client cards retain raw-record tiles. Their outbound contributions are clipped updates; clipping bounds contribution magnitude but does not by itself make an update private.","focus":["region-1"]},{"title":"Protect individual contributions during combination","description":"Masked update bars combine at the sum node inside Secure aggregation. Protection depends on the protocol’s bounded-collusion and dropout assumptions.","focus":["region-2"]},{"title":"Account for released information","description":"The trusted curator adds calibrated noise to the aggregate and tracks budget spent per release. Only the released model crosses the public boundary; repeated releases must be accounted for.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"c123d19d21f93259ec69c03b32ec6e946b874612","art_kind":"svg","art_width":1200,"art_height":546,"art_structural_sha1":"bafe25165c97c8aed254e22b835541db07578e9a"},"vol2:fig-privacy-utility-frontier":{"key":"vol2:fig-privacy-utility-frontier","figure_id":"fig-privacy-utility-frontier","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Published privacy-utility results","status":"ready","treatment":"annotated","question":"Why must privacy budgets be compared with the full experimental setting?","scope":"The points are selected published results, not a universal accuracy frontier. Adjacency, accountant, slack, architecture, and training data matter.","regions":{"mnist":{"x":0.18,"y":0.09,"w":0.71,"h":0.2,"label":"Published MNIST results"},"cifar":{"x":0.39,"y":0.41,"w":0.33,"h":0.27,"label":"Published CIFAR-10 results at epsilon 8"},"baselines":{"x":0.12,"y":0.04,"w":0.86,"h":0.07,"label":"MNIST nonprivate reference"},"gap":{"x":0.66,"y":0.2,"w":0.06,"h":0.46,"label":"CIFAR-10 reference gap"},"cifar_baseline":{"x":0.12,"y":0.2,"w":0.86,"h":0.07,"label":"CIFAR-10 nonprivate reference"}},"steps":[{"title":"Read the MNIST evidence","description":"The blue markers and line identify published MNIST results at selected privacy budgets. Their dataset and training conditions remain part of each result.","focus":["mnist"]},{"title":"Compare within a stated setting","description":"The orange CIFAR-10 points share epsilon 8 but come from different studies. Their different accuracies cannot be explained by epsilon alone.","focus":["cifar"]},{"title":"Use the correct reference","description":"Dashed nonprivate references belong to different datasets. They are comparison points, not universal accuracy ceilings.","focus":["baselines","cifar_baseline"]},{"title":"Keep the utility cost conditional","description":"The marked CIFAR-10 gap is roughly 12 to 20 percentage points below its displayed reference. That observed gap does not imply the same cost for every DP mechanism or task.","focus":["gap"]}],"artwork_reviewed":true,"art_sha1":"26cd8f378fb08e23f1bb89135004bd08ef132ab6","art_kind":"png","art_width":3231,"art_height":1911},"vol2:fig-prompt-energy-boundary":{"key":"vol2:fig-prompt-energy-boundary","figure_id":"fig-prompt-energy-boundary","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Energy per Prompt Depends on the Measurement Boundary","status":"ready","treatment":"annotated","question":"Why can two energy-per-prompt figures differ for the same serving workload?","scope":"This is the median Gemini text prompt in May 2025 under the cited boundaries. Full-stack accelerator attribution also changes with which machines are included; totals are not universal per-query constants.","regions":{"narrow":{"x":0.24,"y":0.18,"w":0.2,"h":0.28,"label":"Narrow active-accelerator account"},"omitted":{"x":0.43,"y":0.18,"w":0.2,"h":0.28,"label":"Hatched excluded components"},"full":{"x":0.24,"y":0.62,"w":0.51,"h":0.27,"label":"Full-stack counted energy"},"total":{"x":0.69,"y":0.66,"w":0.28,"h":0.18,"label":"0.24 Wh full-stack total"}},"steps":[{"title":"State the narrow boundary","description":"The upper bar counts 0.10 Wh from active accelerators on the most efficiently used machines. It does not count the entire serving fleet.","focus":["narrow"]},{"title":"Find excluded support costs","description":"Hatched host, idle provisioned capacity, and facility-overhead segments mark energy that the accelerator-only boundary leaves out.","focus":["omitted"]},{"title":"Expand the measured scope","description":"The full-stack bar includes host CPU and DRAM, idle capacity held for latency and availability, and PUE overhead across the fleet. Its accelerator term also reflects that broader machine scope.","focus":["full"]},{"title":"Attach a boundary to the number","description":"The full account is 0.24 Wh, or 2.4 times the narrow result. Date, workload, utilization, and accounting boundary belong with any per-prompt number.","focus":["total"]}],"artwork_reviewed":true,"art_sha1":"57722f2be4e1c9a60c7e2de2019c9ae06d0dfed5","art_kind":"png","art_width":3982,"art_height":2179},"vol2:fig-published-failure-rates":{"key":"vol2:fig-published-failure-rates","figure_id":"fig-published-failure-rates","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Published failure rates from production clusters","status":"ready","treatment":"annotated","question":"How do production failure observations differ from a GPU-only planning line?","scope":"Filled measurements, hollow fitted projections, and the Llama 3 observation are distinct evidence. The theoretical line assumes one device rate; incidents need not arrive on a regular schedule.","regions":{"measured":{"x":0.15,"y":0.1,"w":0.4,"h":0.48,"label":"Measured RSC job sizes"},"theory":{"x":0.26,"y":0.17,"w":0.34,"h":0.34,"label":"Theoretical inverse-count relation"},"llama":{"x":0.66,"y":0.48,"w":0.32,"h":0.19,"label":"Llama 3 measured interruption interval"},"projected":{"x":0.45,"y":0.62,"w":0.41,"h":0.25,"label":"Projected larger-cluster intervals"}},"steps":[{"title":"Start from measured operating data","description":"The filled blue RSC points report observed mean time to failure at particular GPU counts. They include the behavior of jobs, not just individual GPU specifications.","focus":["measured"]},{"title":"Compare with the idealized device model","description":"The dashed line applies 50,000 device-hours divided by required GPU count. Its slope is a useful planning relationship, but a training job can fail through additional components.","focus":["theory"]},{"title":"Keep observations separate from projections","description":"The Llama 3 diamond is a measured interruption average; the nearby hollow RSC point is a fitted projection. Together they indicate roughly two-to-three-hour failure cadence at that scale under their respective evidence.","focus":["llama","projected"]}],"artwork_reviewed":true,"art_sha1":"e5b48af3ec1b03b117d1c7621c9f80f18cc22737","art_kind":"png","art_width":3632,"art_height":2999},"vol2:fig-puf":{"key":"vol2:fig-puf","figure_id":"fig-puf","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Physical unclonable functions","status":"ready","treatment":"annotated","question":"How do physical manufacturing variations become device responses?","scope":"PUF responses need enrollment and may require correction under changing conditions; the panels do not establish absolute unclonability or runtime integrity.","regions":{"fingerprint":{"x":0.01,"y":0.01,"w":0.48,"h":0.48,"label":"A device fingerprints"},"optical":{"x":0.51,"y":0.01,"w":0.48,"h":0.48,"label":"B optical scattering"},"arbiter":{"x":0.01,"y":0.51,"w":0.48,"h":0.48,"label":"C arbiter path race"},"sram":{"x":0.51,"y":0.51,"w":0.48,"h":0.48,"label":"D SRAM startup mismatch"}},"steps":[{"title":"Compare identical designs","description":"Panel A gives two chips the same challenge and obtains different responses because fabrication introduces device-specific variation.","focus":["fingerprint"]},{"title":"Read a scattering response","description":"Panel B uses a laser challenge and random token structure to produce a speckle pattern. The response depends on the physical token.","focus":["optical"]},{"title":"Race configured paths","description":"Panel C configures straight or crossed stages with challenge bits. The arbiter converts the relative arrival times into a response bit.","focus":["arbiter"]},{"title":"Observe a startup preference","description":"Panel D uses transistor mismatch to bias a cross-coupled SRAM cell toward one power-up state. Repeatability is an engineering requirement rather than an automatic guarantee.","focus":["sram"]}],"artwork_reviewed":true,"art_sha1":"82e77bf6b13790cc48e8f3dae9b8c807a235c2fb","art_kind":"svg","art_width":1200,"art_height":777,"art_structural_sha1":"682b0cb3c698373d1ee7f0fa925481b2468b0b37"},"vol2:fig-queuing-hockey-stick":{"key":"vol2:fig-queuing-hockey-stick","figure_id":"fig-queuing-hockey-stick","source":"books/vol2/backmatter/appendix_inference.qmd","title":"The queuing hockey stick","status":"ready","treatment":"annotated","question":"Why does retaining utilization headroom matter in an M/M/1 queue?","scope":"The curve is mean system occupancy L = rho/(1 − rho) for a stable M/M/1 queue, including the request in service. The shaded thresholds are illustrative, not universal safe limits.","regions":{"equation":{"x":0.16,"y":0.68,"w":0.33,"h":0.18,"label":"M/M/1 mean occupancy formula"},"low":{"x":0.14,"y":0.86,"w":0.5,"h":0.1,"label":"Lower-utilization curve"},"knee":{"x":0.5,"y":0.57,"w":0.29,"h":0.3,"label":"Illustrated knee near rho = 0.8"},"steep":{"x":0.76,"y":0.05,"w":0.16,"h":0.76,"label":"Near-saturation rise"},"bands":{"x":0.72,"y":0.05,"w":0.18,"h":0.15,"label":"Illustrative caution and danger bands"}},"steps":[{"title":"Identify what is counted","description":"L counts requests in the system, including any request currently being served. The equation describes occupancy rather than latency in milliseconds.","focus":["equation"]},{"title":"Leave room to drain bursts","description":"At lower utilization the expected occupancy grows gradually. Spare service capacity gives a stable system more opportunity to drain accumulated work.","focus":["low"]},{"title":"Observe nonlinear growth","description":"At rho = 0.8 the displayed equation gives L = 4. Increasing utilization further raises occupancy rapidly rather than adding a constant penalty.","focus":["knee"]},{"title":"Approach the stability boundary","description":"The curve diverges as rho approaches one from below. The colored operating bands illustrate headroom choices and must not be read as universal production thresholds.","focus":["steep","bands"]}],"artwork_reviewed":true,"art_sha1":"e40531d3cedf20030159e80b5fdb0f22253f56e5","art_kind":"png","art_width":3530,"art_height":2700},"vol2:fig-rail-optimized-cabling":{"key":"vol2:fig-rail-optimized-cabling","figure_id":"fig-rail-optimized-cabling","source":"books/vol2/03_network_fabrics/03_network_fabrics.qmd","title":"Rail-optimized physical wiring","status":"ready","treatment":"annotated","question":"Why connect the same GPU position to a dedicated network rail?","scope":"The drawing shows four rails and three nodes as a schematic subset; the spine is explicitly not drawn, and rail locality depends on the job partition.","regions":{"rails":{"x":0.12,"y":0.06,"w":0.71,"h":0.13,"label":"Rail 0 through Rail 3 switches"},"node0":{"x":0.0,"y":0.46,"w":0.32,"h":0.44,"label":"Node 0 GPU positions and NVSwitch"},"node1":{"x":0.34,"y":0.46,"w":0.32,"h":0.44,"label":"Node 1 GPU positions and NVSwitch"},"node2":{"x":0.68,"y":0.46,"w":0.31,"h":0.44,"label":"Node 2 GPU positions and NVSwitch"},"cables":{"x":0.03,"y":0.19,"w":0.91,"h":0.3,"label":"Same-position rail connections"}},"steps":[{"title":"Retain fast local exchange","description":"Each node has GPU 0 through GPU 3 joined by its own NVSwitch. Tensor-parallel work can remain within this local domain.","focus":["node0","node1"]},{"title":"Connect matching positions","description":"The cabling joins the same GPU position across nodes to the corresponding rail switch. These are same-position paths rather than one shared switch for every GPU.","focus":["rails","cables"]},{"title":"Match the parallel split","description":"A data-parallel group that holds the same shard at matching GPU positions can use its dedicated rail. Other traffic patterns may require the bridging fabric.","focus":["node0","node1","node2"]},{"title":"Do not hide upper tiers","description":"The upward note says the spine is not drawn. The lesson identifies locality, not a claim that every transfer avoids spine capacity or contention.","focus":["rails"]}],"artwork_reviewed":true,"art_sha1":"5fe01520e11ffd4c024db98a962d60645e4a5408","art_kind":"svg","art_width":1200,"art_height":487,"art_structural_sha1":"5fe01520e11ffd4c024db98a962d60645e4a5408"},"vol2:fig-ranking-cascade":{"key":"vol2:fig-ranking-cascade","figure_id":"fig-ranking-cascade","source":"books/vol2/10_inference/10_inference.qmd","title":"Ranking cascade architecture","status":"ready","treatment":"annotated","question":"Why spend more model work on fewer recommendation candidates?","scope":"Candidate counts and latency budgets are the printed schematic; band width follows log candidate count rather than a linear count.","regions":{"region-1":{"x":0.02,"y":0.12,"w":0.95,"h":0.15,"label":"Retrieval band"},"region-2":{"x":0.02,"y":0.28,"w":0.95,"h":0.34,"label":"Intermediate ranking bands"},"region-3":{"x":0.02,"y":0.64,"w":0.95,"h":0.19,"label":"Final reranking band"}},"steps":[{"title":"Filter a very large candidate pool","description":"Lexical and ANN retrieval reduces 1,000,000 candidates to 10,000 under the smallest shown latency budget. It preserves a tractable pool for later models.","focus":["region-1"]},{"title":"Reserve heavier scoring for survivors","description":"First-stage ranking reduces 10,000 to 1,000; second-stage scoring reduces 1,000 to 100. The latency budget increases as the candidate pool shrinks.","focus":["region-2"]},{"title":"Apply the most expensive comparison selectively","description":"The cross-attention transformer reranks 100 candidates down to 10 under the largest shown budget. Early filtering controls how many candidates incur this final cost. A relevant candidate discarded upstream cannot be recovered by the final ranker, so filtering also creates a recall constraint.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"4aab4786b87048f2bb861fa695fae6d4b24ee7c5","art_kind":"svg","art_width":1200,"art_height":511,"art_structural_sha1":"4aab4786b87048f2bb861fa695fae6d4b24ee7c5"},"vol2:fig-reliability-gap-collapse":{"key":"vol2:fig-reliability-gap-collapse","figure_id":"fig-reliability-gap-collapse","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The reliability collapse","status":"ready","treatment":"annotated","question":"Why can very reliable nodes still yield poor simultaneous availability for a large job?","scope":"The curves assume independent node availability and an unreplicated job requiring every node. They do not model recovery or actual useful training goodput.","regions":{"region-1":{"x":0.01,"y":0.03,"w":0.97,"h":0.96,"label":"All-node availability axes"},"region-2":{"x":0.56,"y":0.47,"w":0.41,"h":0.41,"label":"99.9-percent curve collapse"},"region-3":{"x":0.57,"y":0.19,"w":0.4,"h":0.47,"label":"99.99-percent curve and equal-value arrow"}},"steps":[{"title":"Read the job’s joint requirement","description":"The horizontal axis is required job size on a log scale; the vertical axis is simultaneous all-node availability. Requiring every node compounds individual unavailability.","focus":["region-1"]},{"title":"Follow the larger required set","description":"The blue 99.9%-per-node curve reaches 36.8% at 1,000 nodes and approaches the bottom by 10,000. Good individual availability does not transfer unchanged to the all-node event.","focus":["region-2"]},{"title":"Postpone rather than remove the problem","description":"The green curve reaches the same 36.8% at 10,000 required nodes. The extra nine shifts the collapse to a larger job under this model; resilience still needs system-level mechanisms.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"57154c57c22d15e70f196fa5e0119a8cc7ed078a","art_kind":"png","art_width":3648,"art_height":2460},"vol2:fig-responsible-ai-architecture":{"key":"vol2:fig-responsible-ai-architecture","figure_id":"fig-responsible-ai-architecture","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Production Responsible AI Architecture","status":"ready","treatment":"annotated","question":"Which governance checks can run without blocking every inference response?","scope":"The architecture separates synchronous service from asynchronous review; monitoring by itself does not authorize a model update.","regions":{"region-1":{"x":0.02,"y":0.03,"w":0.96,"h":0.3,"label":"Synchronous request lane"},"region-2":{"x":0.13,"y":0.37,"w":0.6,"h":0.22,"label":"Evidence and delayed outcomes"},"region-3":{"x":0.03,"y":0.7,"w":0.61,"h":0.17,"label":"Asynchronous metrics"},"region-4":{"x":0.78,"y":0.7,"w":0.18,"h":0.17,"label":"Release gate"}},"steps":[{"title":"Keep the serving path bounded","description":"Request, access control and minimization, inference, and response sit inside the serving SLO. They are the synchronous path for one decision.","focus":["region-1"]},{"title":"Separate immediate records from later labels","description":"Inference emits bounded evidence records. Older decisions have known outcomes; recent decisions remain pending, so label-dependent error metrics cannot yet include them.","focus":["region-2"]},{"title":"Compute only metrics the evidence supports","description":"Explanations and parity metrics consume decision evidence. Error-rate metrics additionally require matched outcomes; these governance computations occur asynchronously.","focus":["region-3"]},{"title":"Require an authorized update","description":"The named owner’s release gate mediates the dashed approved-update path back to inference. A detected issue supplies evidence for review, not automatic permission to deploy.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"72180d13d76dc585d9cdfc492032c8a8c5dcfac3","art_kind":"svg","art_width":1200,"art_height":698,"art_structural_sha1":"acce7d23a55e64998b2f625f7fade92c64bbcade"},"vol2:fig-reward-hacking-loop":{"key":"vol2:fig-reward-hacking-loop","figure_id":"fig-reward-hacking-loop","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Reward Hacking Loop","status":"ready","treatment":"annotated","question":"How can optimizing clicks reinforce a mismatch with long-term user value?","scope":"This is a possible feedback mechanism, not proof that click optimization inevitably harms users or that the proxy becomes useless.","regions":{"region-1":{"x":0.23,"y":0.04,"w":0.7,"h":0.14,"label":"Proxy and true goal"},"region-2":{"x":0.25,"y":0.24,"w":0.42,"h":0.42,"label":"Recommender and served content"},"region-3":{"x":0.05,"y":0.54,"w":0.43,"h":0.42,"label":"Clicks and retraining feedback"}},"steps":[{"title":"Separate the target from its measure","description":"Long-term user value is the true goal; maximize clicks is the measurable proxy. The measured-by link does not establish that every increase in clicks improves the goal.","focus":["region-1"]},{"title":"Trace how the policy changes experience","description":"The recommender optimizes the proxy and serves content. The red content example illustrates a possible way the policy could increase clicks while undermining user value.","focus":["region-2"]},{"title":"Follow the data back to the policy","description":"Clicks are logged as training data for the next model. This closes a possible reinforcing loop; establishing harm requires evidence about the deployed policy and the user-value criterion.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"d3bbd32adbe21158b87b4dbd01b230729c6f4cee","art_kind":"svg","art_width":1200,"art_height":800,"art_structural_sha1":"6eea3d0cab015349545df897bde01eaf827e9273"},"vol2:fig-ring-allreduce":{"key":"vol2:fig-ring-allreduce","figure_id":"fig-ring-allreduce","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Ring AllReduce data flow","status":"ready","treatment":"annotated","question":"Why does Ring AllReduce need two phases?","scope":"The artwork shows four ranks and phase endpoints, with per-link step tiles; annotations do not interpolate unshown packet timings.","regions":{"scatter":{"x":0.01,"y":0.02,"w":0.98,"h":0.4,"label":"ReduceScatter endpoint and step tiles"},"gpu0":{"x":0.01,"y":0.1,"w":0.18,"h":0.25,"label":"GPU 0 reduced shard"},"wrap":{"x":0.06,"y":0.35,"w":0.87,"h":0.1,"label":"Wrap-around link"},"gather":{"x":0.01,"y":0.48,"w":0.98,"h":0.4,"label":"AllGather endpoint"},"sums":{"x":0.01,"y":0.62,"w":0.98,"h":0.18,"label":"All ranks hold all sums"}},"steps":[{"title":"Reduce separate chunks","description":"After three ReduceScatter steps, GPU 0 holds the complete sum of B while the other GPUs hold different complete sums. Gray partial tiles are not finished replicas.","focus":["scatter","gpu0"]},{"title":"Close the logical ring","description":"The return link from GPU 3 to GPU 0 is part of every circulation round. The numbered tiles on links identify successive chunks, not simultaneous duplicate payloads.","focus":["wrap"]},{"title":"Distribute the finished sums","description":"Three further AllGather steps forward the completed shards without reducing them again. Every rank then holds the full sum.","focus":["gather","sums"]}],"artwork_reviewed":true,"art_sha1":"5622e86f50f8076592b8c5e5adc762fe7e32aad7","art_kind":"svg","art_width":1200,"art_height":520,"art_structural_sha1":"048187d35bddc41d8fdde50c3a550adf0f89930b"},"vol2:fig-rlhf-pipeline":{"key":"vol2:fig-rlhf-pipeline","figure_id":"fig-rlhf-pipeline","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Reinforcement Learning from Human Feedback (RLHF) Alignment Pipeline","status":"ready","treatment":"annotated","question":"How do human preferences reach policy weights in the pictured RLHF pipeline?","scope":"The diagram describes SFT plus PPO with a learned reward model and KL reference; it is not every possible alignment method.","regions":{"region-1":{"x":0.25,"y":0.05,"w":0.24,"h":0.58,"label":"SFT policy and sampled outputs"},"region-2":{"x":0.03,"y":0.55,"w":0.69,"h":0.38,"label":"Human preferences and reward model"},"region-3":{"x":0.5,"y":0.04,"w":0.23,"h":0.72,"label":"PPO reward and KL reference"}},"steps":[{"title":"Start from a supervised policy","description":"The pretrained model undergoes supervised fine-tuning. Sampled SFT outputs enter preference pairs for human comparison, rather than sending judgments directly into PPO weights.","focus":["region-1"]},{"title":"Learn a proxy for preferences","description":"Human raters rank paired outputs. Those comparisons train the reward model r(x,y), which converts candidate outputs into scores.","focus":["region-2"]},{"title":"Constrain the policy update","description":"The reward signal drives PPO, while the frozen SFT model supplies a KL-divergence penalty discouraging departure from the reference. This is not a hard bound on every response or proof of compliance; preferences reach the weights through the learned reward model here.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"4f2b50548d5163d67bf227657b35f806e6636ab6","art_kind":"svg","art_width":1200,"art_height":508,"art_structural_sha1":"d51ab99b2fd8d63a216f93e114da45d1d2f9dbcc"},"vol2:fig-rlhf-ppo-step":{"key":"vol2:fig-rlhf-ppo-step","figure_id":"fig-rlhf-ppo-step","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"One PPO-style RLHF step","status":"ready","treatment":"annotated","question":"Which models in a PPO-style RLHF step need optimizer state?","scope":"The diagram is one PPO-style arrangement. State strip widths follow 2/2/12 bytes per parameter and are not the equal-width ZeRO columns.","regions":{"policy":{"x":0.15,"y":0.33,"w":0.25,"h":0.23,"label":"Trained policy"},"frozen":{"x":0.52,"y":0.07,"w":0.25,"h":0.53,"label":"Frozen reference and reward models"},"value":{"x":0.52,"y":0.63,"w":0.25,"h":0.24,"label":"Trained value model"},"advantage":{"x":0.81,"y":0.35,"w":0.18,"h":0.3,"label":"Advantages and update path"}},"steps":[{"title":"Generate responses","description":"The policy produces responses from prompts and retains weights, gradients, and optimizer state. Its blue strip marks a trainable model.","focus":["policy"]},{"title":"Run frozen evaluators","description":"The reference provides log-probabilities for the KL term and the reward model provides a scalar score. Their state strips hold weights only because these models run forward passes without updates.","focus":["frozen"]},{"title":"Estimate values","description":"The value model supplies estimates and is itself trained. Its optimizer state therefore shares the large persistent-state burden of the policy.","focus":["value"]},{"title":"Update the trained pair","description":"Reward, KL, and value estimates form advantages. The returning PPO update reaches policy and value, so placement must account for both trainable state and evaluator capacity.","focus":["advantage","policy","value"]}],"artwork_reviewed":true,"art_sha1":"dfaef0d0577dfcd11aabd50d0dda99442f9ea653","art_kind":"svg","art_width":1200,"art_height":666,"art_structural_sha1":"a605d4c17d57fbe90011a82fad71716c979e039f"},"vol2:fig-robustbench-progress":{"key":"vol2:fig-robustbench-progress","figure_id":"fig-robustbench-progress","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Standardized Robustness Evaluation of Published Defenses","status":"ready","treatment":"annotated","question":"Why must robustness be evaluated under a shared threat model?","scope":"These are published CIFAR-10 defenses under AutoAttack at the fixed 8/255 l-infinity budget. Yearly best is an observed envelope, not a forecast or guaranteed robustness outside that set.","regions":{"legend":{"x":0.17,"y":0.01,"w":0.79,"h":0.11,"label":"Clean, robust, and additional-data legend"},"clean":{"x":0.14,"y":0.16,"w":0.83,"h":0.17,"label":"Clean-accuracy observations"},"robust":{"x":0.2,"y":0.31,"w":0.77,"h":0.3,"label":"Under-attack observations and envelope"},"broken":{"x":0.28,"y":0.84,"w":0.21,"h":0.05,"label":"Near-zero robust-accuracy defenses"}},"steps":[{"title":"Fix the evaluation and data conventions","description":"Gray denotes clean accuracy; red denotes accuracy under the common attack. Hollow red points used additional training data, so comparisons must retain that distinction.","focus":["legend"]},{"title":"Contrast clean and attacked performance","description":"Clean scores cluster high while attacked scores spread much lower. Clean accuracy alone does not establish resilience within the tested perturbation set.","focus":["clean","robust"]},{"title":"Inspect failures standardized evaluation reveals","description":"The near-zero red observations are published defenses that do not withstand this standardized attack. A defense-specific weakness can be missed by an unsuitable evaluation.","focus":["broken"]},{"title":"Read progress within the declared evidence","description":"The red step line tracks the best robust accuracy published by each year. Improvement leaves a residual failure fraction and applies only to this benchmark and threat model.","focus":["robust"]}],"artwork_reviewed":true,"art_sha1":"7543e205e04c3eba4a3ca0f260f1cf2db300e7b2","art_kind":"png","art_width":3696,"art_height":2398},"vol2:fig-robustness-taxonomy":{"key":"vol2:fig-robustness-taxonomy","figure_id":"fig-robustness-taxonomy","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"The Robustness Taxonomy","status":"ready","treatment":"annotated","question":"Why must the defense match the source of the failure?","scope":"The taxonomy names candidate defenses, not universal guarantees; software and pipeline defects cross all three pillars.","regions":{"environment":{"x":0.01,"y":0.01,"w":0.31,"h":0.64,"label":"Environmental shifts"},"input":{"x":0.34,"y":0.01,"w":0.31,"h":0.64,"label":"Input-level attacks"},"system":{"x":0.67,"y":0.01,"w":0.31,"h":0.64,"label":"System-level faults"},"pipeline":{"x":0.01,"y":0.7,"w":0.98,"h":0.27,"label":"Cross-cutting software and pipeline defects"}},"steps":[{"title":"Identify changed operating data","description":"Environmental shifts alter inputs, labels, or their relation. Reweighting, recalibration, and adaptation address different changes and require outcome evidence.","focus":["environment"]},{"title":"Specify the adversary’s access","description":"Input-level attacks include evasion, poisoning, and physical perturbations. Their defenses act at different boundaries of data acquisition, training, and serving.","focus":["input"]},{"title":"Verify the computing substrate","description":"System-level faults include silent corruption, bit flips, numerical exceptions, and desynchronization. Input filtering alone does not verify these execution paths.","focus":["system"]},{"title":"Check the whole pipeline","description":"The dashed software boundary spans all pillars. A data or orchestration defect can undermine a defense even when its local method is appropriate.","focus":["pipeline"]}],"artwork_reviewed":true,"art_sha1":"7ce3415a8c277fb2ea4bf500cbfd4226af7a7951","art_kind":"svg","art_width":1200,"art_height":604,"art_structural_sha1":"7b71ea96a714f838c0e468826944a77a33899929"},"vol2:fig-roofline-landscape":{"key":"vol2:fig-roofline-landscape","figure_id":"fig-roofline-landscape","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"The H100 roofline landscape","status":"ready","treatment":"annotated","question":"Which ceiling limits each workload on the H100 roofline?","scope":"The curve is a peak-bound model and the dots are representative workload intensities, not measured achieved throughputs.","regions":{"decode":{"x":0.11,"y":0.67,"w":0.25,"h":0.18,"label":"LLM Decode Batch 1"},"slope":{"x":0.26,"y":0.16,"w":0.39,"h":0.47,"label":"Memory bandwidth slope"},"ridge":{"x":0.6,"y":0.08,"w":0.08,"h":0.78,"label":"Ridge point"},"roof":{"x":0.66,"y":0.06,"w":0.32,"h":0.4,"label":"Compute roof and high-intensity examples"},"decode32":{"x":0.26,"y":0.26,"w":0.21,"h":0.15,"label":"LLM Decode Batch 32"}},"steps":[{"title":"Read low-reuse decode","description":"The decode examples lie left of the ridge. Their modeled limit follows memory bandwidth because they perform relatively few operations per byte.","focus":["decode","decode32"]},{"title":"Increase arithmetic per byte","description":"Along the rising segment, higher arithmetic intensity raises the bandwidth-derived ceiling. That is an upper bound rather than a promised achieved rate.","focus":["slope"]},{"title":"Reach the crossover","description":"The dashed ridge marks where bandwidth times intensity equals the compute roof, about 295 FLOP per byte in this figure.","focus":["ridge"]},{"title":"Respect the compute ceiling","description":"The higher-intensity examples meet the horizontal roof. Additional reuse alone cannot raise the ceiling beyond the declared peak arithmetic rate.","focus":["roof"]}],"artwork_reviewed":true,"art_sha1":"56785ea25f6a747c9d4cc05556faf6f504935293","art_kind":"png","art_width":3658,"art_height":2340},"vol2:fig-roofline-model":{"key":"vol2:fig-roofline-model","figure_id":"fig-roofline-model","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"The roofline model","status":"ready","treatment":"annotated","question":"Which ideal resource bound limits each operation at its stated intensity?","scope":"Markers lie on ideal FP16 bounds for the declared H100 configuration; they are not measured kernel throughput. Arithmetic intensity uses bytes crossing the stated memory boundary.","regions":{"decode":{"x":0.23,"y":0.59,"w":0.33,"h":0.22,"label":"Batch-one decode on bandwidth slope"},"unfused":{"x":0.19,"y":0.21,"w":0.4,"h":0.23,"label":"Unfused attention prefill"},"ridge":{"x":0.51,"y":0.18,"w":0.16,"h":0.72,"label":"Ridge at about 295 FLOP per byte"},"ceiling":{"x":0.6,"y":0.06,"w":0.38,"h":0.35,"label":"FP16 compute ceiling and high-intensity markers"},"bandwidth":{"x":0.24,"y":0.39,"w":0.25,"h":0.25,"label":"HBM bandwidth slope"}},"steps":[{"title":"Bound traffic-limited work","description":"The blue slope multiplies arithmetic intensity by HBM bandwidth. Batch-one decode lies far left because little arithmetic is performed per byte of weights moved.","focus":["decode","bandwidth"]},{"title":"Increase data reuse","description":"Unfused attention prefill also lies on the slope in the stated workload. Reducing HBM traffic can raise its intensity without requiring the same proportional increase in arithmetic.","focus":["unfused"]},{"title":"Find the binding-resource switch","description":"At the ridge, the HBM bound meets the FP16 compute ceiling. The tighter ideal bound changes from memory bandwidth to compute capacity.","focus":["ridge"]},{"title":"Interpret the upper markers","description":"Tiled attention prefill and the large GEMM reach the ideal ceiling at their plotted intensities. Actual implementations can remain below it because scheduling, locality, or other overheads intervene.","focus":["ceiling"]}],"artwork_reviewed":true,"art_sha1":"584229f7c1b9a1877f300503a119f8f1431a6583","art_kind":"png","art_width":3544,"art_height":2160},"vol2:fig-scale-moment-discontinuity":{"key":"vol2:fig-scale-moment-discontinuity","figure_id":"fig-scale-moment-discontinuity","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The scale discontinuity","status":"ready","treatment":"annotated","question":"What changes when one machine becomes a synchronized fleet?","scope":"The fleet panel depicts tightly coupled work; independent serving requests need not wait at the same barrier.","regions":{"region-1":{"x":0.035,"y":0.14,"w":0.27,"h":0.7,"label":"Local accelerators and HBM"},"region-2":{"x":0.385,"y":0.49,"w":0.5,"h":0.14,"label":"Shared network fabric"},"region-3":{"x":0.515,"y":0.13,"w":0.23,"h":0.09,"label":"Scheduler and recovery"},"region-4":{"x":0.515,"y":0.28,"w":0.37,"h":0.52,"label":"Failed and slow nodes"}},"steps":[{"title":"Start at the local memory wall","description":"The single-machine panel places HBM below its accelerators. Every accelerator-memory link crosses the red memory wall; there are no peer nodes to wait for.","focus":["region-1"]},{"title":"Cross the fleet network","description":"The fleet connects multiple nodes through the amber network fabric. This shared communication path introduces a network wall beyond each node’s local memory wall.","focus":["region-2"]},{"title":"Place and recover the job","description":"Scheduler and recovery sit above the node group. Coordination must manage placement and failures as well as the compute and communication substrates.","focus":["region-3"]},{"title":"Identify fleet-wide waiting","description":"One node is failed and another slow while healthy nodes are labeled waiting. A required participant can hold up synchronized progress; more accelerators alone do not remove that dependency.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"0ccbae2ab34a131d935f4871e30ed6ef253cbf5c","art_kind":"svg","art_width":1200,"art_height":538,"art_structural_sha1":"0ccbae2ab34a131d935f4871e30ed6ef253cbf5c"},"vol2:fig-scaling-regimes":{"key":"vol2:fig-scaling-regimes","figure_id":"fig-scaling-regimes","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The three scaling phases","status":"ready","treatment":"annotated","question":"Which compute budget grows in pretraining, posttraining, and test-time scaling?","scope":"This is a schematic capability curve, not a measured common intelligence scale or proof of additive gains across all techniques.","regions":{"region-1":{"x":0.05,"y":0.53,"w":0.32,"h":0.38,"label":"Pretraining segment"},"region-2":{"x":0.34,"y":0.34,"w":0.27,"h":0.57,"label":"Posttraining segment"},"region-3":{"x":0.59,"y":0.09,"w":0.31,"h":0.82,"label":"Test-time segment"}},"steps":[{"title":"Build a foundation in one long run","description":"The orange pretraining segment is paired with the bracket one long foundation run. It spends training compute and data to establish the base model.","focus":["region-1"]},{"title":"Spend compute refining behavior","description":"The blue posttraining segment is paired with many smaller runs. It represents methods such as instruction tuning and RLHF rather than repeating the original foundation run.","focus":["region-2"]},{"title":"Spend additional work per request","description":"The green long-thinking segment is paired with compute per request. Its cost recurs at inference; dashed continuations are schematic comparisons, not observed future outcomes.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"07b7fbb73f95d5ae3535c9e98806256489851252","art_kind":"png","art_width":3659,"art_height":2460},"vol2:fig-scaling-tax":{"key":"vol2:fig-scaling-tax","figure_id":"fig-scaling-tax","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"The scaling tax","status":"ready","treatment":"annotated","question":"Why can a small residual baseline fraction cap a large fleet’s speedup?","scope":"These curves use fixed illustrative residual fractions in N/(1+(N−1)r). Actual communication and coordination can change with device count; r is not the profiler’s distributed-step synchronization share.","regions":{"near":{"x":0.08,"y":0.58,"w":0.29,"h":0.36,"label":"Small-fleet near-linear region"},"smallr":{"x":0.48,"y":0.07,"w":0.49,"h":0.38,"label":"Residual 0.1 percent curve"},"oner":{"x":0.48,"y":0.27,"w":0.49,"h":0.34,"label":"Residual 1 percent curve"},"tenr":{"x":0.3,"y":0.55,"w":0.67,"h":0.22,"label":"Residual 10 percent curve"}},"steps":[{"title":"Begin near the linear regime","description":"At small N, the curves lie close together because the unscaled residual has not yet overtaken the divided compute term.","focus":["near"]},{"title":"Keep a tiny residual visible","description":"Even the 0.1 percent curve falls below the ideal diagonal at large N. A small baseline fraction can matter once compute is divided over many devices.","focus":["smallr"]},{"title":"Inspect the asymptote","description":"The 1 percent curve bends toward 1/r = 100. Adding GPUs cannot remove a residual that this model leaves fixed.","focus":["oner"]},{"title":"Recognize an early ceiling","description":"At 10 percent the total speedup approaches ten despite hundreds of GPUs. This is a model sensitivity result, not a measured limit for a particular collective.","focus":["tenr"]}],"artwork_reviewed":true,"art_sha1":"11b3bac6a0f3c9b0622f809289f59227859c4406","art_kind":"png","art_width":3621,"art_height":2400},"vol2:fig-sdc-controller":{"key":"vol2:fig-sdc-controller","figure_id":"fig-sdc-controller","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Hot-spare failover","status":"ready","treatment":"annotated","question":"How does a hot-spare protocol preserve capacity while isolating a suspect GPU?","scope":"The checker and replay identify a suspect, not a proof from one anomalous gradient; the sequence is a fleet protocol rather than full-step replication.","regions":{"flag":{"x":0.01,"y":0.15,"w":0.31,"h":0.73,"label":"Checker flags G2"},"promote":{"x":0.34,"y":0.15,"w":0.31,"h":0.73,"label":"Drain G2 and promote S"},"repair":{"x":0.67,"y":0.15,"w":0.31,"h":0.73,"label":"Repair and replenish spare"}},"steps":[{"title":"Separate suspect from healthy participants","description":"The checker flags G2 while S is still an idle spare. Runtime evidence and replay guide which device should be isolated.","focus":["flag"]},{"title":"Promote the standby into active work","description":"G2 leaves the active set and S takes its role. Spare capacity is consumed to keep productive execution going.","focus":["promote"]},{"title":"Restore the reserve capacity","description":"A replacement S′ refills the spare position while G2 undergoes repair. The protocol must replenish the pool to handle another failure.","focus":["repair"]}],"artwork_reviewed":true,"art_sha1":"c73da375471ba63bef6439829bb57aa72e316976","art_kind":"svg","art_width":1200,"art_height":297,"art_structural_sha1":"cc5eadde9ff48084ba582f794278ee7b5feb1385"},"vol2:fig-sdc-example":{"key":"vol2:fig-sdc-example","figure_id":"fig-sdc-example","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Silent data corruption propagation","status":"ready","treatment":"annotated","question":"Why can silent corruption make recent checkpoints unsafe?","scope":"Time is explicitly not to scale; the causal chain illustrates possible propagation rather than the outcome of every bit flip.","regions":{"origin":{"x":0.01,"y":0.01,"w":0.3,"h":0.35,"label":"Bit flip and wrong tensor entry"},"propagate":{"x":0.37,"y":0.01,"w":0.36,"h":0.35,"label":"Backward pass and weight update"},"detected":{"x":0.01,"y":0.42,"w":0.98,"h":0.17,"label":"Detected-error recovery"},"silent":{"x":0.01,"y":0.64,"w":0.98,"h":0.24,"label":"Corrupt checkpoints and delayed alert"}},"steps":[{"title":"A valid-looking value changes","description":"A bit flip in memory or the ALU changes one tensor entry without necessarily stopping execution. A live process can therefore hold invalid numerical state.","focus":["origin"]},{"title":"Training commits the error","description":"The backward pass can propagate corrupted values into gradients and weights. Future work then depends on state already affected by the fault.","focus":["propagate"]},{"title":"Contrast immediate detection","description":"A detected error traps and restarts from a checkpoint. Its recovery begins close to the fault rather than after extended training.","focus":["detected"]},{"title":"Find the last trustworthy state","description":"The silent path saves corrupted state into later checkpoints before evaluation alerts. Rolling back requires a trustworthy earlier checkpoint, not simply the newest file.","focus":["silent"]}],"artwork_reviewed":true,"art_sha1":"7b3f4919bf59edefa60bde3179f8342e2666be1c","art_kind":"svg","art_width":1200,"art_height":615,"art_structural_sha1":"5ab99b0b67c76819f88721dcf79ba52a1b8edb48"},"vol2:fig-secure-agg":{"key":"vol2:fig-secure-agg","figure_id":"fig-secure-agg","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Secure aggregation protocol","status":"ready","treatment":"annotated","question":"How can the server recover a sum without seeing each raw update?","scope":"This two-client illustration assumes both complete and do not disclose their masks. It demonstrates cancellation, not dropout recovery, collusion resistance, or differential privacy.","regions":{"a":{"x":0.02,"y":0.05,"w":0.54,"h":0.33,"label":"Client A adds the shared mask"},"mask":{"x":0.18,"y":0.4,"w":0.36,"h":0.18,"label":"Shared pairwise mask s"},"b":{"x":0.02,"y":0.6,"w":0.52,"h":0.29,"label":"Client B subtracts the shared mask"},"uploads":{"x":0.53,"y":0.19,"w":0.11,"h":0.54,"label":"Masked uploads crossing boundary"},"server":{"x":0.65,"y":0.26,"w":0.33,"h":0.58,"label":"Server sums and masks cancel"}},"steps":[{"title":"Agree on one shared mask","description":"Clients A and B share the random mask s. The server does not receive s as an ordinary upload in this illustration.","focus":["mask"]},{"title":"Mask opposite contributions","description":"Client A forms yA = delta theta A + s, while Client B forms yB = delta theta B − s. Each transmitted vector hides its individual raw update under the stated assumptions.","focus":["a","b"]},{"title":"Upload masked values","description":"Only the orange masked vectors cross into the aggregation-server domain. Conventional per-client inspection of the raw contributions is therefore unavailable.","focus":["uploads"]},{"title":"Cancel in the sum","description":"Adding yA and yB cancels +s and −s, leaving the exact aggregate of both updates. The aggregate can still reveal information and may need differential privacy.","focus":["server"]}],"artwork_reviewed":true,"art_sha1":"edb9619ae75de48552e1e24b56a910e19954a215","art_kind":"svg","art_width":1200,"art_height":654,"art_structural_sha1":"2fbf2d1dba59455f5f49a2efc0679577d549becf"},"vol2:fig-secure-boot":{"key":"vol2:fig-secure-boot","figure_id":"fig-secure-boot","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Secure boot sequence","status":"ready","treatment":"annotated","question":"How does authenticated loading differ from recording boot measurements?","scope":"Model-artifact authentication requires the explicit model-loader extension; boot verification alone does not establish runtime safety.","regions":{"early":{"x":0.01,"y":0.27,"w":0.39,"h":0.36,"label":"Root and verified bootloader"},"model":{"x":0.4,"y":0.27,"w":0.45,"h":0.36,"label":"OS and model authentication gates"},"reject":{"x":0.14,"y":0.01,"w":0.55,"h":0.2,"label":"Reject failed verification"},"log":{"x":0.01,"y":0.68,"w":0.83,"h":0.29,"label":"Measurement log"},"runtime":{"x":0.86,"y":0.27,"w":0.14,"h":0.36,"label":"After-boot runtime controls"}},"steps":[{"title":"Authenticate before loading","description":"The immutable root authenticates the next boot component. Each accepted stage establishes the next loading decision.","focus":["early"]},{"title":"Extend the chain explicitly","description":"The last gate authenticates the manifest and artifact digest before the authorized ML workload. This model extension is additional to generic verified boot.","focus":["model"]},{"title":"Reject rather than merely record","description":"A failed green gate follows a red arrow to halt and rejection. Enforcing that decision differs from recording evidence.","focus":["reject"]},{"title":"Keep evidence and runtime separate","description":"The measurement log stores hashes and digests, while the after-boot box still requires runtime controls. A recorded digest does not itself block a component or prevent later compromise.","focus":["log","runtime"]}],"artwork_reviewed":true,"art_sha1":"63d7b94ad98c94d907deced93ab313da4b7e38ee","art_kind":"svg","art_width":1200,"art_height":463,"art_structural_sha1":"60880d0145849a686a5e38960baeb6c28af84877"},"vol2:fig-serving-cost-crossover":{"key":"vol2:fig-serving-cost-crossover","figure_id":"fig-serving-cost-crossover","source":"books/vol2/10_inference/10_inference.qmd","title":"The serving cost crossover","status":"ready","treatment":"annotated","question":"When does recurring serving cost equal the initial training expense?","scope":"The curves are specified deployment-cost scenarios; crossings depend on training expense, traffic, and unit serving cost.","regions":{"region-1":{"x":0.11,"y":0.1,"w":0.86,"h":0.87,"label":"Initial training baselines"},"region-2":{"x":0.145,"y":0.325,"w":0.065,"h":0.12,"label":"LLM crossover"},"region-3":{"x":0.28,"y":0.6,"w":0.69,"h":0.24,"label":"Low-traffic scenario A"},"recsys":{"x":0.12,"y":0.705,"w":0.065,"h":0.12,"label":"RecSys crossover"}},"steps":[{"title":"Separate initial from recurring cost","description":"Dotted horizontal lines mark one-time training cost. Each cumulative-total curve starts at its training baseline and then accumulates serving expense.","focus":["region-1"]},{"title":"Locate early serving dominance","description":"The high-traffic LLM and recommender scenarios reach twice their training cost early. At that point, the serving portion equals the one-time training expense.","focus":["region-2","recsys"]},{"title":"Compare the slower crossover","description":"Scenario A’s open-circle crossover occurs at month 10 in the plotted construction. Lower traffic changes the balance; serving does not dominate on the same schedule for every deployment.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"9f170ce638d978651d19314488e0cf2c4b7c835b","art_kind":"png","art_width":3298,"art_height":2400},"vol2:fig-serving-cost-curve":{"key":"vol2:fig-serving-cost-curve","figure_id":"fig-serving-cost-curve","source":"books/vol2/10_inference/10_inference.qmd","title":"The serving cost curve","status":"ready","treatment":"annotated","question":"What makes the modeled serving cost cross the assumed price line?","scope":"These are constructed curves and an assumed price, not measured profitability or guaranteed optimization savings.","regions":{"region-1":{"x":0.12,"y":0.03,"w":0.7,"h":0.51,"label":"Price line and cost-above region"},"region-2":{"x":0.37,"y":0.42,"w":0.41,"h":0.08,"label":"Three break-even crossings"},"region-3":{"x":0.51,"y":0.55,"w":0.48,"h":0.37,"label":"Labeled strategies below price"}},"steps":[{"title":"Fix the economic comparison","description":"The dashed horizontal line represents a typical assumed price. The pink region above it means modeled unit serving cost exceeds that price.","focus":["region-1"]},{"title":"Compare the required request volume","description":"Open circles mark the cost/price crossing for each curve. The optimized curve crosses at lower daily request volume in this constructed scenario.","focus":["region-2"]},{"title":"Keep the assumptions attached to the result","description":"Single-GPU, multi-GPU batching, and fully optimized costs are separate assumptions. The green region means modeled cost below price, not a complete business profit calculation.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"d0b707e7d2812255d559ea3667158aa227386a19","art_kind":"png","art_width":3254,"art_height":2280},"vol2:fig-serving-deployment-stack":{"key":"vol2:fig-serving-deployment-stack","figure_id":"fig-serving-deployment-stack","source":"books/vol2/10_inference/10_inference.qmd","title":"Serving deployment stack","status":"ready","treatment":"annotated","question":"How does the serving stack spend latency before and during GPU generation?","scope":"These are stated tier budgets, not measurements; bar length is proportional to the logarithm of budget.","regions":{"region-1":{"x":0.02,"y":0.12,"w":0.95,"h":0.22,"label":"Edge-cache tier"},"region-2":{"x":0.02,"y":0.39,"w":0.95,"h":0.23,"label":"Gateway and router tier"},"region-3":{"x":0.02,"y":0.65,"w":0.95,"h":0.26,"label":"Model-serving tier"}},"steps":[{"title":"Authorize before edge reuse","description":"The client request passes authorization before the Edge PoP cache. An eligible hit can avoid the lower tiers; a miss continues downward.","focus":["region-1"]},{"title":"Enforce and route the request","description":"Rate limiting, authentication, and routing occur before GPU dispatch. Telemetry observes the path; these tasks still consume part of the end-to-end latency budget.","focus":["region-2"]},{"title":"Run prefill and decode","description":"The GPU worker runs prefill then decode and streams tokens back. The autoscaler uses queue depth and KV usage to manage workers, while readiness limits how quickly extra capacity can help.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"abd6573cd6bd0b618aa320d730c15e3da7b3c291","art_kind":"svg","art_width":1200,"art_height":633,"art_structural_sha1":"6646e75d5510cac42b79a540e52d0b3fc4f51b0f"},"vol2:fig-serving-redundancy":{"key":"vol2:fig-serving-redundancy","figure_id":"fig-serving-redundancy","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Serving redundancy strategies","status":"ready","treatment":"annotated","question":"What resource is paid for before a replica fails?","scope":"Weights remain resident in both schemes; the diagram compares allocation and traffic placement rather than a measured failover delay.","regions":{"active":{"x":0.01,"y":0.02,"w":0.47,"h":0.85,"label":"Active-active replicas"},"headroom":{"x":0.02,"y":0.65,"w":0.45,"h":0.28,"label":"Per-replica traffic headroom"},"primary":{"x":0.52,"y":0.4,"w":0.23,"h":0.45,"label":"Active primary"},"standby":{"x":0.76,"y":0.4,"w":0.23,"h":0.45,"label":"Loaded warm standby"}},"steps":[{"title":"Share requests among active replicas","description":"Active-active sends one-third of ingress traffic to each replica. All three hold weights and serve requests.","focus":["active"]},{"title":"Reserve room for redistribution","description":"Unused serving headroom allows survivors to absorb a failed replica’s share. Full normal utilization would remove this reserve.","focus":["headroom"]},{"title":"Pay for an idle but loaded standby","description":"Active-passive routes healthy traffic to the primary while the standby keeps weights loaded. The dashed path activates on failure, trading idle capacity for readiness.","focus":["primary","standby"]}],"artwork_reviewed":true,"art_sha1":"9163f286f7d1f8df932199ab173157b1759f67e3","art_kind":"svg","art_width":1200,"art_height":507,"art_structural_sha1":"75fe0d1c5c11fc1a978e1193eae5dbf6e7e0752a"},"vol2:fig-shadow-deployment":{"key":"vol2:fig-shadow-deployment","figure_id":"fig-shadow-deployment","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Shadow and canary deployment","status":"ready","treatment":"annotated","question":"What does a shadow test expose that a canary test does not?","scope":"The printed traffic fractions are one illustrative canary stage, not universal rollout policy; rollback uses the stated SLO and error evidence.","regions":{"shadow":{"x":0.01,"y":0.02,"w":0.96,"h":0.43,"label":"Mirrored requests and production-only response"},"diff":{"x":0.69,"y":0.13,"w":0.29,"h":0.27,"label":"Offline comparison and logged candidate output"},"canary":{"x":0.01,"y":0.54,"w":0.65,"h":0.36,"label":"Weighted live split"},"stages":{"x":0.67,"y":0.55,"w":0.31,"h":0.42,"label":"Canary widening and rollback"}},"steps":[{"title":"Duplicate requests without serving the candidate","description":"In the shadow panel, every production request is copied to the candidate. Users receive only production v1 responses.","focus":["shadow"]},{"title":"Budget the extra inference","description":"Candidate outputs are logged and compared offline. Mirroring every request doubles inference load in this example, so isolation and capacity are necessary even without user exposure.","focus":["diff"]},{"title":"Expose a measured live slice","description":"The canary panel routes 5 percent of live traffic to candidate v2 and 95 percent to production v1. Candidate responses now reach real users.","focus":["canary"]},{"title":"Widen only with evidence","description":"The stage scale increases exposure through the listed fractions. SLO or error drift triggers rollback rather than automatic progression.","focus":["stages"]}],"artwork_reviewed":true,"art_sha1":"43045e0d7c75f75050d671d460bb8c1bc204daa2","art_kind":"svg","art_width":1200,"art_height":611,"art_structural_sha1":"5b7d4f2aac6dd39de4d341705545863abcaf2ab8"},"vol2:fig-shadow-validation":{"key":"vol2:fig-shadow-validation","figure_id":"fig-shadow-validation","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"On-device shadow validation","status":"ready","treatment":"annotated","question":"Why is prediction disagreement a gate rather than a verdict?","scope":"The comparator is label-free. A threshold crossing signals change but does not identify which model is correct or prove a quality regression.","regions":{"models":{"x":0.01,"y":0.02,"w":0.66,"h":0.44,"label":"Shared inputs and two prediction rows"},"comparison":{"x":0.01,"y":0.49,"w":0.66,"h":0.12,"label":"Label-free equality comparison"},"rate":{"x":0.68,"y":0.47,"w":0.3,"h":0.19,"label":"Disagreement rate and threshold"},"evidence":{"x":0.01,"y":0.71,"w":0.3,"h":0.15,"label":"Validated outcome or safety invariant"},"gate":{"x":0.58,"y":0.7,"w":0.34,"h":0.14,"label":"Hold candidate out of service"},"outcomes":{"x":0.54,"y":0.87,"w":0.4,"h":0.11,"label":"Clear or roll back"}},"steps":[{"title":"Compare on the same inputs","description":"The frozen baseline and serving candidate receive x1 through x8. Their class predictions differ at x4 and x7 in this example.","focus":["models"]},{"title":"Measure a label-free change","description":"The comparator marks equality or disagreement without ground-truth labels. It cannot tell which disagreeing prediction is correct.","focus":["comparison"]},{"title":"Hold on a threshold crossing","description":"The disagreement-rate bar exceeds tau and feeds the gate. The gate suspends the candidate rather than declaring a regression.","focus":["rate","gate"]},{"title":"Decide using validated evidence","description":"A validated outcome signal or safety invariant supports the final decision. Clear returns the candidate to service; confirmed regression justifies rollback.","focus":["evidence","outcomes"]}],"artwork_reviewed":true,"art_sha1":"98375e1bdd40d5494b004c5207cf8550d40fc5cf","art_kind":"svg","art_width":1200,"art_height":675,"art_structural_sha1":"63251e19c2a3eeaaa6d047d2c69f704d683656e9"},"vol2:fig-shard-group-scaling":{"key":"vol2:fig-shard-group-scaling","figure_id":"fig-shard-group-scaling","source":"books/vol2/10_inference/10_inference.qmd","title":"Horizontal scaling with shard groups","status":"ready","treatment":"annotated","question":"Why do more shard groups increase aggregate serving capacity without replacing tensor-parallel communication?","scope":"One group is one model replica with TP=8 in this schematic. More groups do not inherently reduce one request’s latency.","regions":{"region-1":{"x":0.18,"y":0.03,"w":0.74,"h":0.26,"label":"Load balancer"},"region-2":{"x":0.02,"y":0.35,"w":0.47,"h":0.51,"label":"Eight-device shard group"},"region-3":{"x":0.52,"y":0.45,"w":0.44,"h":0.49,"label":"Additional shard groups"}},"steps":[{"title":"Choose a replica group","description":"The load balancer sends each request to a shard group using a policy such as round-robin, two-choice, or session affinity.","focus":["region-1"]},{"title":"Communicate within the selected replica","description":"Shard group 0 is one tensor-parallel replica across eight devices. NVLink AllReduce occurs every layer inside the group, setting part of its request latency.","focus":["region-2"]},{"title":"Scale independent request capacity","description":"Groups 1 through N provide additional replicas. Their purpose is more aggregate throughput; they do not split the selected group’s collective across all requests.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"7e7b3855035859ee45237835b83f437b6731e57f","art_kind":"svg","art_width":1200,"art_height":731,"art_structural_sha1":"196ff55983a3e75deef878cec5c656cefe5efec5"},"vol2:fig-sharp-innetwork":{"key":"vol2:fig-sharp-innetwork","figure_id":"fig-sharp-innetwork","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Endpoint and in-network reduction","status":"ready","treatment":"annotated","question":"Where does the reduction arithmetic execute?","scope":"The two panels contrast logical placement of addition, not measured SHARP speedup or universal switch support.","regions":{"endpoint":{"x":0.01,"y":0.01,"w":0.47,"h":0.92,"label":"Endpoint reduction"},"leaves":{"x":0.01,"y":0.73,"w":0.98,"h":0.22,"label":"GPU contributions"},"switches":{"x":0.52,"y":0.46,"w":0.46,"h":0.26,"label":"Switch partial sums"},"root":{"x":0.52,"y":0.12,"w":0.46,"h":0.29,"label":"Root switch sum"}},"steps":[{"title":"Start from device contributions","description":"Each GPU supplies a different g contribution. Both designs seek the same total sum.","focus":["leaves"]},{"title":"Forward raw values to an endpoint","description":"In endpoint reduction, switches only forward; the reducer GPU performs all additions. The raw contributions must reach that endpoint.","focus":["endpoint"]},{"title":"Aggregate inside the network","description":"The lower switches add pairs before forwarding partial sums. The root switch combines those partial sums, moving reduction work into supported fabric components.","focus":["switches","root"]}],"artwork_reviewed":true,"art_sha1":"6e3ce93bb1ab511468e7ded9a32ddb2bc5fc039e","art_kind":"svg","art_width":1200,"art_height":649,"art_structural_sha1":"e8b382499e1e3eb1db67595934a20ff834864278"},"vol2:fig-shift-types":{"key":"vol2:fig-shift-types","figure_id":"fig-shift-types","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Types of Distribution Shift","status":"ready","treatment":"annotated","question":"Which probability changes in each kind of distribution shift?","scope":"Panels are schematic regimes; input-only monitoring cannot generally identify label or conditional changes without additional evidence.","regions":{"covariate":{"x":0.01,"y":0.01,"w":0.31,"h":0.86,"label":"Covariate shift"},"label":{"x":0.34,"y":0.01,"w":0.31,"h":0.86,"label":"Label shift"},"concept":{"x":0.67,"y":0.01,"w":0.31,"h":0.86,"label":"Concept drift"}},"steps":[{"title":"Move the input population","description":"In covariate shift, p(x) changes while p(y|x) is fixed. Training and deployment points occupy different parts of the same decision relationship.","focus":["covariate"]},{"title":"Change the class proportions","description":"In label shift, p(y) changes while p(x|y) is fixed. The bars compare class priors rather than a new decision boundary.","focus":["label"]},{"title":"Change the label relationship","description":"In concept drift, the old and new boundaries differ: p(y|x) changes, and p(x) may remain fixed. Detecting the changed mapping generally needs outcome evidence.","focus":["concept"]}],"artwork_reviewed":true,"art_sha1":"f469323cda6a87eee0fdbdfe9240c107b740630b","art_kind":"svg","art_width":1200,"art_height":582,"art_structural_sha1":"899f81163fa8f02b64a3bb56d10652f5b43bdfd6"},"vol2:fig-side-channel-curves":{"key":"vol2:fig-side-channel-curves","figure_id":"fig-side-channel-curves","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Power traces","status":"ready","treatment":"annotated","question":"Why can a cryptographic operation reveal information through power use?","scope":"These are schematic Hamming-weight-ordered traces, not captured device measurements or calibrated leakage amplitudes.","regions":{"full":{"x":0.06,"y":0.08,"w":0.43,"h":0.8,"label":"Full schematic power trace"},"window":{"x":0.2,"y":0.14,"w":0.06,"h":0.6,"label":"Selected S-box window"},"zoom":{"x":0.6,"y":0.08,"w":0.39,"h":0.8,"label":"Zoomed data-dependent traces"},"legend":{"x":0.84,"y":0.17,"w":0.15,"h":0.24,"label":"Bit patterns and Hamming weights"}},"steps":[{"title":"Find the operation window","description":"The full trace contains an emphasized S-box interval within a longer sequence of clock cycles. Leakage analysis needs to align observations to relevant operations.","focus":["full","window"]},{"title":"Compare internal-data cases","description":"The zoomed panel separates traces for bit patterns with different Hamming weights. Its amplitudes illustrate ordering rather than measured device behavior.","focus":["zoom","legend"]},{"title":"Interpret the signal as a side channel","description":"The vertical difference represents data-dependent physical behavior. Protection must address implementation leakage as well as the mathematical security of the cryptographic algorithm.","focus":["zoom"]}],"artwork_reviewed":true,"art_sha1":"757a8c359d4cf0a1f040a8969a43049cfb16113e","art_kind":"png","art_width":3840,"art_height":1800},"vol2:fig-silent-error-probability":{"key":"vol2:fig-silent-error-probability","figure_id":"fig-silent-error-probability","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Silent Error Probability at Scale","status":"ready","treatment":"annotated","question":"How does a small per-device silent-error probability compound across a fleet?","scope":"Each p is an illustrative independent residual-error probability over the same hour, not a measured hardware rate; corrected errors are excluded.","regions":{"high":{"x":0.17,"y":0.18,"w":0.44,"h":0.69,"label":"Higher per-device probability curve"},"middle":{"x":0.49,"y":0.23,"w":0.36,"h":0.64,"label":"Intermediate probability and 10K marker"},"low":{"x":0.73,"y":0.43,"w":0.25,"h":0.45,"label":"Lower per-device probability curve"},"certain":{"x":0.11,"y":0.01,"w":0.87,"h":0.09,"label":"Near-certain event band"}},"steps":[{"title":"Accumulate independent exposure","description":"The solid p=10^-3 curve rises with device count because the probability that every device avoids an event shrinks. The model computes one minus that no-event probability.","focus":["high"]},{"title":"Read the fixed one-hour example","description":"The dashed p=10^-4 curve reaches about 0.63 at 10,000 GPUs. This is the chance of at least one event somewhere, not a fraction of failed devices.","focus":["middle"]},{"title":"Separate better devices from guaranteed correctness","description":"The p=10^-5 dotted curve grows more slowly, but increasing fleet size still increases exposure. None of the curves certifies which result is trustworthy after an event.","focus":["low","certain"]}],"artwork_reviewed":true,"art_sha1":"76ee2b89cd707fd1b7438a343fe0dc3ce89e5126","art_kind":"png","art_width":3087,"art_height":1924},"vol2:fig-speculative-decoding":{"key":"vol2:fig-speculative-decoding","figure_id":"fig-speculative-decoding","source":"books/vol2/09_performance_engineering/09_performance_engineering.qmd","title":"Speculative decoding process","status":"ready","treatment":"annotated","question":"How can one target pass emit several verified tokens?","scope":"The shorter schematic timeline assumes drafting, verification, and correction cost less than the sequential target passes they replace; acceptance is not guaranteed.","regions":{"standard":{"x":0.02,"y":0.03,"w":0.96,"h":0.31,"label":"Four sequential target passes"},"draft":{"x":0.16,"y":0.42,"w":0.16,"h":0.23,"label":"Draft token proposals"},"verify":{"x":0.33,"y":0.42,"w":0.23,"h":0.23,"label":"One parallel target verification"},"accept":{"x":0.33,"y":0.58,"w":0.24,"h":0.14,"label":"Accepted prefix and first rejection"},"correct":{"x":0.45,"y":0.71,"w":0.17,"h":0.13,"label":"Corrected sample"},"saved":{"x":0.57,"y":0.43,"w":0.41,"h":0.16,"label":"Illustrative time comparison"}},"steps":[{"title":"Establish sequential work","description":"Standard decoding uses a separate target-model pass for each next token. The upper row shows four such passes.","focus":["standard"]},{"title":"Propose a short future","description":"The small draft model sequentially proposes T1 through T4. These are candidates, not yet emitted target-model outputs.","focus":["draft"]},{"title":"Verify the prefix together","description":"One target pass checks the proposed positions. The illustrated acceptance test accepts T1 through T3 and rejects T4.","focus":["verify","accept"]},{"title":"Correct the first rejection","description":"Residual sampling supplies the corrected T4 prime. Any draft after a first rejection would be discarded; net benefit depends on draft cost and acceptance.","focus":["correct","saved"]}],"artwork_reviewed":true,"art_sha1":"7ceb5cfb6d127171cf1ad7e9919609b2500053d4","art_kind":"svg","art_width":1200,"art_height":490,"art_structural_sha1":"005a3ba5f061df7d4a306b762b08bb16e3fe96e2"},"vol2:fig-spot-aware-routing":{"key":"vol2:fig-spot-aware-routing","figure_id":"fig-spot-aware-routing","source":"books/vol2/10_inference/10_inference.qmd","title":"Spot-aware traffic distribution","status":"ready","treatment":"annotated","question":"How does SLO-aware routing use spot capacity without treating it as always available?","scope":"The 70/30 split is the printed scenario, not a recommended universal allocation. Spot capacity can be reclaimed.","regions":{"region-1":{"x":0.24,"y":0.03,"w":0.51,"h":0.31,"label":"Spot-aware gateway"},"region-2":{"x":0.03,"y":0.48,"w":0.46,"h":0.48,"label":"On-demand pool"},"region-3":{"x":0.54,"y":0.2,"w":0.44,"h":0.76,"label":"Spot pool and notice"}},"steps":[{"title":"Classify each request’s contract","description":"Requests carry an SLO class. The gateway classifies the contract, watches preemption notices, and coordinates draining.","focus":["region-1"]},{"title":"Reserve stable capacity for critical work","description":"The SLO-critical path reaches Workers 0–2 in the on-demand pool. This scenario avoids spot reclamation on that pool.","focus":["region-2"]},{"title":"Drain reclaimable capacity","description":"Best-effort work reaches the spot pool. Worker 5 is draining after an eviction notice, so new work must respect its changing readiness instead of treating all workers as interchangeable.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"a10f93e200b2c61a8ddba5841a95d424740086b3","art_kind":"svg","art_width":1200,"art_height":634,"art_structural_sha1":"443634250b93515596cc66e7ce85cb759cceb3ae"},"vol2:fig-stm32f-board":{"key":"vol2:fig-stm32f-board","figure_id":"fig-stm32f-board","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"STM32F target board","status":"ready","treatment":"annotated","question":"Which parts of the photographed setup support physical leakage measurement?","scope":"The photograph documents a target setup; visible hardware alone does not establish an attack outcome or protection level.","regions":{"target":{"x":0.21,"y":0.01,"w":0.56,"h":0.85,"label":"STM32F target board"},"chip":{"x":0.35,"y":0.2,"w":0.24,"h":0.27,"label":"Target microcontroller"},"carrier":{"x":0.01,"y":0.01,"w":0.2,"h":0.98,"label":"Carrier-board connections"}},"steps":[{"title":"Identify the target board","description":"The central blue board is labeled as an STM32F target for ChipWhisperer. It is the device under observation in the illustrated setup.","focus":["target"]},{"title":"Locate the executing device","description":"The black microcontroller on the target board runs the workload whose physical behavior is measured.","focus":["chip"]},{"title":"Separate target and measurement support","description":"The surrounding carrier and labeled connections support power, clock, and signal access. Security evaluation must consider these physical interfaces as well as software behavior.","focus":["carrier"]}],"artwork_reviewed":true,"art_sha1":"55dc4aa6b427786da5cda9628bbbc81f15710d84","art_kind":"png","art_width":402,"art_height":324},"vol2:fig-storage-complete-data-path":{"key":"vol2:fig-storage-complete-data-path","figure_id":"fig-storage-complete-data-path","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"The complete data path","status":"ready","treatment":"annotated","question":"Which data copies must the training loop wait for?","scope":"This running example bypasses the parallel file system for training input; other deployments can stage differently.","regions":{"stage":{"x":0.01,"y":0.34,"w":0.43,"h":0.23,"label":"Dataset staging to local NVMe"},"input":{"x":0.34,"y":0.33,"w":0.65,"h":0.24,"label":"Prefetch, batch, and optional GDS path"},"checkpoint":{"x":0.34,"y":0.68,"w":0.65,"h":0.2,"label":"Model state to local shard"},"durable":{"x":0.01,"y":0.68,"w":0.45,"h":0.22,"label":"Background durable checkpoint copies"},"node":{"x":0.31,"y":0.04,"w":0.68,"h":0.87,"label":"One GPU node boundary"}},"steps":[{"title":"Stage the input once","description":"The dashed arrow copies the dataset from object storage into local NVMe. This once-per-job work differs from a transfer required for every training batch.","focus":["stage"]},{"title":"Supply each batch","description":"Solid arrows move staged input through host prefetch to GPU HBM. The optional GDS route bypasses host DRAM for payload movement.","focus":["input"]},{"title":"Pause for a local save","description":"Checkpoint traffic starts at model state in HBM and writes a local shard. That solid path is inside the GPU node and is part of the training pause.","focus":["checkpoint","node"]},{"title":"Make the save durable","description":"Dashed copies carry shards to the parallel file system and selected checkpoints to object storage. Background copying needs a completed durable generation before it becomes a restore point.","focus":["durable"]}],"artwork_reviewed":true,"art_sha1":"8833a4faf663129f2da88662d7bf12c78c787ae3","art_kind":"svg","art_width":1200,"art_height":622,"art_structural_sha1":"e6f1ee22303bda88088cd299979abc2483c70f26"},"vol2:fig-storage-pfs-architecture":{"key":"vol2:fig-storage-pfs-architecture","figure_id":"fig-storage-pfs-architecture","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"Parallel file system architecture","status":"ready","treatment":"annotated","question":"How can a parallel file system separate lookup from bulk reads?","scope":"The drawing is a Lustre-style logical architecture; aggregate OSS bandwidth is not a guarantee at any one client.","regions":{"lookup":{"x":0.08,"y":0.07,"w":0.88,"h":0.19,"label":"Metadata lookup and stripe map"},"clients":{"x":0.02,"y":0.27,"w":0.18,"h":0.65,"label":"Compute clients"},"servers":{"x":0.35,"y":0.27,"w":0.21,"h":0.65,"label":"Object storage servers"},"stripes":{"x":0.61,"y":0.27,"w":0.37,"h":0.65,"label":"Round-robin file stripes"}},"steps":[{"title":"Obtain the map","description":"Client 1 asks the metadata server for the stripe map stored on the metadata target. This lookup identifies the objects without sending the file payload through the MDS.","focus":["lookup"]},{"title":"Locate consecutive stripes","description":"Dark tiles 0, 1, 2, and N−1 occupy different OSTs. Each target also holds later stripes separated by N.","focus":["stripes"]},{"title":"Read in parallel","description":"The client uses the green data path to contact the OSS nodes directly. Multiple servers can supply different parts of the same file concurrently.","focus":["clients","servers"]},{"title":"Separate bottlenecks","description":"Every client shares the OSS service, while metadata stays on its own path. Adding data servers does not by itself increase metadata-operation capacity.","focus":["lookup","servers"]}],"artwork_reviewed":true,"art_sha1":"ffdd15538586ecec84ffb35e0e4ebf25fdaf0a92","art_kind":"svg","art_width":1200,"art_height":816,"art_structural_sha1":"450c692e68c611f7529a9cebf3e0569cce931c8a"},"vol2:fig-storage-pyramid":{"key":"vol2:fig-storage-pyramid","figure_id":"fig-storage-pyramid","source":"books/vol2/04_data_storage/04_data_storage.qmd","title":"ML storage hierarchy","status":"ready","treatment":"annotated","question":"Whose bandwidth is each storage tier sharing?","scope":"Band widths show schematic capacity, not measured throughput; use the chapter table for quantities.","regions":{"hbm":{"x":0.28,"y":0.09,"w":0.43,"h":0.14,"label":"HBM: per accelerator"},"node":{"x":0.08,"y":0.23,"w":0.56,"h":0.31,"label":"DRAM and NVMe: per node"},"shared":{"x":0.05,"y":0.54,"w":0.75,"h":0.41,"label":"Shared service tiers"},"paths":{"x":0.72,"y":0.1,"w":0.26,"h":0.83,"label":"Physical paths"}},"steps":[{"title":"Begin at HBM","description":"The top tier supplies one accelerator. Its bandwidth is not an aggregate shared-storage rating.","focus":["hbm"]},{"title":"Account for the node","description":"Host DRAM and local NVMe serve the accelerators inside one node. The bracket and eight-chip glyph identify the scope that must be divided among consumers.","focus":["node"]},{"title":"Divide shared supply","description":"Parallel file systems and object storage serve many nodes; archive is offline media. Growing the client fleet does not automatically increase this shared supply.","focus":["shared"]},{"title":"Follow the physical route","description":"The right column progresses from an interposer to buses, networks, and offline media. A bandwidth comparison must retain both this route and its sharing scope.","focus":["paths"]}],"artwork_reviewed":true,"art_sha1":"29aa9a6ae1778338b20acb7b2013b6e13541f0a7","art_kind":"svg","art_width":1200,"art_height":592,"art_structural_sha1":"29aa9a6ae1778338b20acb7b2013b6e13541f0a7"},"vol2:fig-stuxnet":{"key":"vol2:fig-stuxnet","figure_id":"fig-stuxnet","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Stuxnet and the ML supply chain","status":"ready","treatment":"annotated","question":"How can a trusted processing chain carry a hidden payload?","scope":"The Stuxnet row is historical; the ML row is a structural analogy, not evidence of an identical attack.","regions":{"entry":{"x":0.01,"y":0.1,"w":0.35,"h":0.69,"label":"Entry and trust boundary"},"historic":{"x":0.38,"y":0.1,"w":0.62,"h":0.28,"label":"Stuxnet downstream control"},"ml":{"x":0.38,"y":0.52,"w":0.62,"h":0.28,"label":"ML artifact downstream behavior"}},"steps":[{"title":"Cross a trust boundary","description":"USB media and a public ML artifact enter different systems through an accepted input. The dashed line marks the point where an input becomes trusted downstream.","focus":["entry"]},{"title":"Separate displayed and actual state","description":"The Stuxnet chain reaches altered PLC logic while operators see normal behavior. Passing observations do not necessarily establish control integrity.","focus":["historic"]},{"title":"Trace the ML analogy","description":"A build host can pass a poisoned dependency into training and the model artifact. Health checks can pass while model behavior is compromised; the analogy motivates provenance checks across stages.","focus":["ml"]}],"artwork_reviewed":true,"art_sha1":"0350fea14da0435d9fabf622a4015441e4c886af","art_kind":"svg","art_width":1200,"art_height":537,"art_structural_sha1":"76b05d7647f2c5de4da5eb30a8ccbef49a40c305"},"vol2:fig-sync-model-timeline":{"key":"vol2:fig-sync-model-timeline","figure_id":"fig-sync-model-timeline","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Distributed synchronization models","status":"ready","treatment":"annotated","question":"What does relaxing a global barrier permit workers to do?","scope":"The timelines are schematic; removing a global barrier does not eliminate resource contention or guarantee better convergence.","regions":{"bsp":{"x":0.01,"y":0.01,"w":0.97,"h":0.28,"label":"BSP: barrier each step"},"ssp":{"x":0.01,"y":0.31,"w":0.97,"h":0.27,"label":"SSP: bounded lead"},"asp":{"x":0.01,"y":0.61,"w":0.97,"h":0.29,"label":"ASP: independent progress"}},"steps":[{"title":"Wait at every barrier","description":"BSP holds workers at each step boundary until the slow worker arrives. Hatched waits accumulate even on workers that finished their compute.","focus":["bsp"]},{"title":"Permit a bounded lead","description":"SSP allows workers to move ahead only within its staleness bound. Faster workers eventually wait when that allowance is exhausted.","focus":["ssp"]},{"title":"Remove the global barrier","description":"ASP lets workers advance without a global update barrier. Their progress diverges, so updates may use stale state; communication and contention still impose delays.","focus":["asp"]}],"artwork_reviewed":true,"art_sha1":"52c7aec5e99dff5e9ed21947d2e9e51e5633483f","art_kind":"svg","art_width":1200,"art_height":894,"art_structural_sha1":"bb2b49652c88e29dc345eb8edb3b7ac6064524a7"},"vol2:fig-tco-build-vs-buy":{"key":"vol2:fig-tco-build-vs-buy","figure_id":"fig-tco-build-vs-buy","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Build vs. buy TCO","status":"ready","treatment":"annotated","question":"When does owning overcome its upfront cluster cost?","scope":"The chart is the high-utilization H100 reference scenario over the shown 30-month horizon, not a forecast for arbitrary cloud prices or utilization.","regions":{"capex":{"x":0.1,"y":0.2,"w":0.39,"h":0.2,"label":"Upfront ownership cost"},"rental":{"x":0.26,"y":0.48,"w":0.45,"h":0.23,"label":"Cloud utilization-dependent running cost"},"cross":{"x":0.56,"y":0.07,"w":0.17,"h":0.22,"label":"Crossover near month 26"},"end":{"x":0.73,"y":0.02,"w":0.26,"h":0.3,"label":"Horizon-end cost comparison"}},"steps":[{"title":"Pay before operating","description":"The blue on-premises curve starts with the printed CapEx step for 1,024 H100s, fabric, and facility. Owning therefore begins above the rental bill.","focus":["capex"]},{"title":"Accumulate the rental bill","description":"The dashed cloud curve rises at the assumed 80 percent utilization and $4/GPU-hour. Less sustained use would change this slope.","focus":["rental"]},{"title":"Find scenario break-even","description":"The curves cross around month 26 at roughly $63.1M in the shown scenario. Before the crossing, renting is cheaper on this cumulative account.","focus":["cross"]},{"title":"Keep the horizon explicit","description":"At month 30 the labels show $63.5M on premises and $71.8M cloud. Service life, utilization, and cost boundary decide whether that comparison applies.","focus":["end"]}],"artwork_reviewed":true,"art_sha1":"6e6e7143202aca35bd91afac4d95f633ae3a3850","art_kind":"png","art_width":3292,"art_height":2099},"vol2:fig-tco-iceberg":{"key":"vol2:fig-tco-iceberg","figure_id":"fig-tco-iceberg","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"The TCO iceberg","status":"ready","treatment":"annotated","question":"Which operational obligations vanish from a compute-only budget?","scope":"One cell is one percent of this illustrative TCO budget. The 50/50 split is not a universal cost distribution; all categories need one accounting horizon without double-counting.","regions":{"compute":{"x":0.05,"y":0.01,"w":0.7,"h":0.32,"label":"GPU cloud compute 40 percent"},"storage":{"x":0.05,"y":0.35,"w":0.7,"h":0.1,"label":"Object storage 10 percent"},"labor":{"x":0.05,"y":0.46,"w":0.7,"h":0.18,"label":"Engineering labor 20 percent"},"maintenance":{"x":0.05,"y":0.65,"w":0.7,"h":0.31,"label":"Pipeline and ongoing operations"},"waterline":{"x":0.01,"y":0.43,"w":0.88,"h":0.04,"label":"Visibility boundary"}},"steps":[{"title":"Count the visible infrastructure","description":"GPU compute and object storage occupy the top half of the budget. Stopping here counts only half of the illustrated total.","focus":["compute","storage"]},{"title":"Include engineering ownership","description":"Engineering labor alone occupies 20 cells. Integrating, operating, and maintaining models is a resource obligation in the same budget.","focus":["labor"]},{"title":"Include recurring system care","description":"Pipeline maintenance, retraining, monitoring, incidents, and compliance fill the rest of the operational half. These costs continue after a successful first deployment.","focus":["maintenance"]},{"title":"Use visibility as an audit prompt","description":"The waterline distinguishes costs that are easier to notice from those easier to omit. It does not separate real costs from optional ones.","focus":["waterline"]}],"artwork_reviewed":true,"art_sha1":"38fb9dc95e5a54d28f6be996fedf51f0f6f9fbff","art_kind":"png","art_width":3375,"art_height":3060},"vol2:fig-tensor-core-tiling":{"key":"vol2:fig-tensor-core-tiling","figure_id":"fig-tensor-core-tiling","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Tensor Core tiling strategy","status":"ready","treatment":"annotated","question":"How does a matrix tile reuse operands without repeatedly writing partial sums?","scope":"This is the figure’s declared tile organization; the guide does not predict kernel timing.","regions":{"hbm":{"x":0.01,"y":0.14,"w":0.41,"h":0.69,"label":"Matrices in HBM"},"shared":{"x":0.47,"y":0.14,"w":0.24,"h":0.69,"label":"A and B tiles in shared memory"},"accum":{"x":0.76,"y":0.14,"w":0.24,"h":0.69,"label":"Tensor Cores and C accumulator"},"write":{"x":0.24,"y":0.84,"w":0.65,"h":0.15,"label":"Final C writeback"}},"steps":[{"title":"Choose a reduction slice","description":"The highlighted slices of A and B supply a portion of the reduction for the output C tile. Full matrices remain in HBM.","focus":["hbm"]},{"title":"Stage operands for reuse","description":"Shared memory holds the A and B tiles close to the compute units. Their dimensions are the source figure’s worked configuration.","focus":["shared"]},{"title":"Retain partial sums","description":"MMA instructions update the C tile held with the compute units. Loading another K slice does not require writing this partial C back to HBM.","focus":["accum"]},{"title":"Write after the reduction","description":"The bottom return path writes the completed C tile once, after the last K slice. Operand reuse and retained accumulators reduce different kinds of traffic.","focus":["write"]}],"artwork_reviewed":true,"art_sha1":"a2e910569295ab5cab39e2067b64a85f184aed66","art_kind":"svg","art_width":1200,"art_height":600,"art_structural_sha1":"7f1389b2931030b83ceba6d4316ece348cfd434b"},"vol2:fig-tensor-parallel-flow":{"key":"vol2:fig-tensor-parallel-flow","figure_id":"fig-tensor-parallel-flow","source":"books/vol2/10_inference/10_inference.qmd","title":"Tensor parallelism for inference","status":"ready","treatment":"annotated","question":"Where do two tensor-parallel GPUs need to exchange partial results?","scope":"This is the printed two-GPU decomposition; it is not a claim that every tensor-parallel implementation uses identical collective placement.","regions":{"region-1":{"x":0.19,"y":0.04,"w":0.75,"h":0.22,"label":"Split attention heads"},"region-2":{"x":0.16,"y":0.27,"w":0.79,"h":0.09,"label":"Attention AllReduce"},"region-3":{"x":0.18,"y":0.38,"w":0.76,"h":0.41,"label":"Feed-forward slices"},"region-4":{"x":0.16,"y":0.81,"w":0.79,"h":0.07,"label":"Feed-forward AllReduce"}},"steps":[{"title":"Compute different attention heads","description":"GPU 0 holds the first half of the attention heads and GPU 1 the second half. Each produces a partial output from its local share.","focus":["region-1"]},{"title":"Combine attention contributions","description":"The first amber AllReduce combines the attention partial outputs across the NVLink path before the feed-forward block.","focus":["region-2"]},{"title":"Keep the intermediate local","description":"Column slices of W1 produce activations locally. The diagram marks no communication between W1 and row slices of W2; each GPU then produces a partial sum.","focus":["region-3"]},{"title":"Finish the shared layer output","description":"The second AllReduce combines W2 partial sums. Only after this exchange does the next layer receive the completed output.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"a56eee7919c5c619886ebc8872b7b933de3eb729","art_kind":"svg","art_width":1200,"art_height":975,"art_structural_sha1":"a450d96f0d4b6718ae4d54e2a9d996d23e2eb6b8"},"vol2:fig-tensor-parallel-split":{"key":"vol2:fig-tensor-parallel-split","figure_id":"fig-tensor-parallel-split","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"Matrix partitioning under tensor parallelism","status":"ready","treatment":"annotated","question":"Why can one tensor-parallel layer pair communicate only after partial sums?","scope":"The figure illustrates the displayed Megatron-style layer pair on two GPUs; it is not a communication bound for every model layer.","regions":{"column":{"x":0.08,"y":0.04,"w":0.31,"h":0.9,"label":"Replicated X and column shards A₁/A₂"},"local":{"x":0.38,"y":0.08,"w":0.27,"h":0.85,"label":"Local Y slices and row shards B₁/B₂"},"reduce":{"x":0.74,"y":0.19,"w":0.15,"h":0.68,"label":"AllReduce of partial outputs"},"result":{"x":0.9,"y":0.23,"w":0.09,"h":0.66,"label":"Full Z on both GPUs"}},"steps":[{"title":"Split output columns","description":"Both GPUs read replicated X but use different column shards of A. Each produces its own Y slice.","focus":["column"]},{"title":"Consume matching slices locally","description":"The following row-parallel B shard consumes its matching Y slice on the same GPU. The marked no-communication boundary preserves this pairing.","focus":["local"]},{"title":"Sum partial results","description":"Z₁ and Z₂ are partial contributions to the same output, not independent complete outputs. AllReduce sums them.","focus":["reduce"]},{"title":"Recover a replicated output","description":"Both GPUs receive full Z after the collective. This is where the displayed pair restores the result needed by the next operation.","focus":["result"]}],"artwork_reviewed":true,"art_sha1":"b5a07b9b9b711b5f4c31535cdbd34a903ce3d97d","art_kind":"svg","art_width":1200,"art_height":591,"art_structural_sha1":"7aea3e7fbfaf3b3a8e44427420d097f60add736a"},"vol2:fig-threat-matrix":{"key":"vol2:fig-threat-matrix","figure_id":"fig-threat-matrix","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Threat prioritization matrix","status":"ready","treatment":"annotated","question":"How should likelihood and impact influence defense priorities?","scope":"Point locations are qualitative judgments; changed context can move a threat without changing its name.","regions":{"high":{"x":0.51,"y":0.02,"w":0.48,"h":0.44,"label":"High-likelihood high-impact quadrant"},"hardware":{"x":0.02,"y":0.02,"w":0.48,"h":0.44,"label":"Hardware side-channel context"},"member":{"x":0.02,"y":0.47,"w":0.48,"h":0.45,"label":"Membership-inference context"},"api":{"x":0.51,"y":0.47,"w":0.48,"h":0.45,"label":"API model-extraction context"}},"steps":[{"title":"Prioritize recurring severe exposure","description":"Data poisoning in federated training appears in the upper-right quadrant, motivating automated defenses for the illustrated threat model.","focus":["high"]},{"title":"Condition hardware risk on access","description":"Hardware side channels start at lower likelihood, but the dashed arrow shows how exposed hardware or sensitive co-tenants can change that judgment.","focus":["hardware"]},{"title":"Condition privacy impact on data","description":"Membership inference moves upward when the training data becomes sensitive. The same access pattern can have different consequences.","focus":["member"]},{"title":"Shape the interface","description":"Public-API extraction lies in the lower-right quadrant of this example. Access and output policies should reflect the actual value and exposure of the model.","focus":["api"]}],"artwork_reviewed":true,"art_sha1":"a7fce8ff6b944749d66ead7ad49daac4f7263fe5","art_kind":"svg","art_width":1200,"art_height":639,"art_structural_sha1":"9abe69682da120d1f6f64e16cbb911e72395b44b"},"vol2:fig-threat-mitigation-flow":{"key":"vol2:fig-threat-mitigation-flow","figure_id":"fig-threat-mitigation-flow","source":"books/vol2/13_security_privacy/13_security_privacy.qmd","title":"Threat mitigation flow","status":"ready","treatment":"annotated","question":"How does threat evidence guide the choice of a security control?","scope":"Candidate controls require validation against the actual threat model; connectors are not guarantees of mitigation.","regions":{"extract":{"x":0.01,"y":0.1,"w":0.98,"h":0.22,"label":"Extraction evidence and controls"},"poison":{"x":0.01,"y":0.34,"w":0.98,"h":0.2,"label":"Poisoning evidence and controls"},"adv":{"x":0.01,"y":0.56,"w":0.98,"h":0.2,"label":"Adversarial-input evidence and controls"},"privacy":{"x":0.01,"y":0.78,"w":0.98,"h":0.2,"label":"Membership-inference evidence and DP"}},"steps":[{"title":"Measure exposed behavior","description":"Model extraction leads to query telemetry and interface controls. Access limits and output restrictions address what the API exposes.","focus":["extract"]},{"title":"Trace data integrity","description":"Data poisoning calls for provenance audits and targeted evaluation before deciding on intake controls, quarantine, or retraining.","focus":["poison"]},{"title":"Evaluate adaptively","description":"Adversarial-input defenses need attack tests adapted to the deployed model and controls. Training and validation policies must be evaluated together.","focus":["adv"]},{"title":"Account for privacy protection","description":"Membership-inference assessment combines attack auditing with privacy accounting. A DP claim comes from an accounted mechanism, not from attack failure alone.","focus":["privacy"]}],"artwork_reviewed":true,"art_sha1":"d2470e45dceb739d1a62be21759d25133ceba16b","art_kind":"svg","art_width":1200,"art_height":611,"art_structural_sha1":"d2470e45dceb739d1a62be21759d25133ceba16b"},"vol2:fig-three-walls-grid":{"key":"vol2:fig-three-walls-grid","figure_id":"fig-three-walls-grid","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"The four infrastructure walls","status":"ready","treatment":"annotated","question":"Why does adding accelerators expose different infrastructure limits?","scope":"The four configuration-specific examples illustrate distinct limits; they do not predict a universal bottleneck.","regions":{"memory":{"x":0.02,"y":0.43,"w":0.23,"h":0.55,"label":"Node memory wall"},"power":{"x":0.28,"y":0.43,"w":0.22,"h":0.55,"label":"Rack power wall"},"comm":{"x":0.53,"y":0.43,"w":0.22,"h":0.55,"label":"Pod communication wall"},"failure":{"x":0.78,"y":0.43,"w":0.22,"h":0.55,"label":"Fleet reliability wall"}},"steps":[{"title":"Feed arithmetic","description":"The narrow HBM connection feeds the FP8 arithmetic block. Peak arithmetic is useful only when the workload supplies enough reuse per byte.","focus":["memory"]},{"title":"Power the rack","description":"The DGX H100 bar exceeds the traditional rack reference. More compute density requires a compatible electrical and cooling envelope.","focus":["power"]},{"title":"Cross the node boundary","description":"The NVLink and InfiniBand bars expose different per-direction bandwidth budgets. A collective crossing nodes cannot assume local-link bandwidth.","focus":["comm"]},{"title":"Accumulate failure exposure","description":"The fleet bar uses independent failures: more GPUs shorten the interval between fleet interruptions even when each GPU is individually reliable.","focus":["failure"]}],"artwork_reviewed":true,"art_sha1":"9aedcacbe9c3e1d7d5eba42d18ea30cb875e8067","art_kind":"svg","art_width":1200,"art_height":667,"art_structural_sha1":"85c8a55e111c14ec4fd3acbc3a5e98d127729426"},"vol2:fig-throughput-interactivity":{"key":"vol2:fig-throughput-interactivity","figure_id":"fig-throughput-interactivity","source":"books/vol2/10_inference/10_inference.qmd","title":"Throughput versus Interactivity in Measured LLM Serving","status":"ready","treatment":"annotated","question":"How does the measured throughput frontier change when each user needs faster token delivery?","scope":"Points are benchmark observations for the source workload and system configurations. Frontiers do not establish isolated hardware causality or predict arbitrary deployments.","regions":{"region-1":{"x":0.01,"y":0.02,"w":0.55,"h":0.97,"label":"Axes and interactivity reference"},"region-2":{"x":0.12,"y":0.04,"w":0.26,"h":0.44,"label":"High-throughput low-interactivity region"},"region-3":{"x":0.64,"y":0.02,"w":0.35,"h":0.77,"label":"High-interactivity frontier and legend"}},"steps":[{"title":"Keep aggregate rate separate from user rate","description":"The x-axis is output tokens per second per user, or inverse TPOT; the log y-axis is output tokens per second per GPU. The dashed line marks the 50-token/s/user reference.","focus":["region-1"]},{"title":"Observe batching’s throughput side","description":"The upper-left frontier points combine high aggregate output with lower user interactivity. These are observed operating points rather than an assertion that maximizing batch size always wins.","focus":["region-2"]},{"title":"Compare valid operating points","description":"The curves generally fall as per-user token rate rises. The legend distinguishes system configurations; a serving choice must satisfy user pacing as well as aggregate throughput.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"94922ac38bbe52cca809e358146f7e5d526f7342","art_kind":"png","art_width":3780,"art_height":2234},"vol2:fig-tiered-adaptation":{"key":"vol2:fig-tiered-adaptation","figure_id":"fig-tiered-adaptation","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Tiered adaptation strategy","status":"ready","treatment":"annotated","question":"How should adaptation demand and device limits guide deployment?","scope":"The cards describe candidate adaptation methods, not rigid device tiers. Every branch still requires measured quality, memory, runtime, and energy feasibility.","regions":{"need":{"x":0.26,"y":0.01,"w":0.48,"h":0.17,"label":"Heavy adaptation decision"},"budget":{"x":0.59,"y":0.19,"w":0.28,"h":0.12,"label":"Compute and energy decision"},"light":{"x":0.03,"y":0.34,"w":0.29,"h":0.31,"label":"Bias-only candidate"},"moderate":{"x":0.35,"y":0.34,"w":0.29,"h":0.31,"label":"Adapters or LoRA candidate"},"full":{"x":0.67,"y":0.34,"w":0.3,"h":0.31,"label":"Partial or full fine-tuning candidate"},"sharing":{"x":0.3,"y":0.68,"w":0.4,"h":0.12,"label":"Cross-device update value"},"outcomes":{"x":0.04,"y":0.82,"w":0.93,"h":0.16,"label":"Local-only or federated deployment"}},"steps":[{"title":"Ask what change is needed","description":"A light adaptation need routes toward bias-only updates. A powerful device does not make a larger update necessary if the smaller method meets the quality target.","focus":["need","light"]},{"title":"Admit a larger candidate","description":"A heavier change requires checking whether the larger update fits compute and energy limits. The moderate adapter branch remains a candidate when full fine-tuning is unnecessary or infeasible.","focus":["budget","moderate","full"]},{"title":"Check whether sharing helps","description":"Only after selecting an adaptation candidate does the flow ask whether updates are valuable across devices. This determines whether federation is useful.","focus":["sharing"]},{"title":"Choose an operational policy","description":"Local-only deployment uses local validation and monitoring; federation adds coordination and appropriate privacy controls. The named differential-privacy configuration is not mandatory for every threat model.","focus":["outcomes"]}],"artwork_reviewed":true,"art_sha1":"ee50e576548aebce136cbcd20aa5be5419492c81","art_kind":"svg","art_width":1200,"art_height":953,"art_structural_sha1":"fdc6d45d4cf5e653f933f2dc775cf6bfe7f8c30a"},"vol2:fig-time-travel":{"key":"vol2:fig-time-travel","figure_id":"fig-time-travel","source":"books/vol2/12_ops_scale/12_ops_scale.qmd","title":"Point-in-time correctness","status":"ready","treatment":"annotated","question":"Which click count was available to a noon prediction?","scope":"The worked example concerns event-time availability, not a recommendation to expose later batch aggregates during training.","regions":{"known":{"x":0.06,"y":0.09,"w":0.42,"h":0.26,"label":"Four events known by noon"},"future":{"x":0.53,"y":0.09,"w":0.42,"h":0.26,"label":"Six later events"},"correct":{"x":0.04,"y":0.72,"w":0.45,"h":0.24,"label":"Point-in-time count: 4"},"leak":{"x":0.54,"y":0.72,"w":0.43,"h":0.24,"label":"Naive midnight count: 10"}},"steps":[{"title":"Freeze the information boundary","description":"The dashed noon line separates four logged clicks from events that have not yet happened. A noon example can use only the earlier information.","focus":["known"]},{"title":"Identify future leakage","description":"Six later click markers contribute to the midnight total but were unavailable at noon. Joining that total would expose the future to the training example.","focus":["future"]},{"title":"Join at event time","description":"The green result total_clicks_today = 4 preserves the inference-time information boundary.","focus":["correct"]},{"title":"Reject the convenient batch value","description":"The red result uses the midnight total of 10. A feature can have the correct entity key and still be temporally invalid.","focus":["leak"]}],"artwork_reviewed":true,"art_sha1":"a513797b0cfa5a3895ef4a543b351fc49f2d1cf9","art_kind":"svg","art_width":1200,"art_height":548,"art_structural_sha1":"4910f0997ce9b535fa8425fea870e477231f09d2"},"vol2:fig-tinytl-architecture":{"key":"vol2:fig-tinytl-architecture","figure_id":"fig-tinytl-architecture","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"TinyTL adaptation paths","status":"ready","treatment":"annotated","question":"Why can TinyTL reduce memory without shortening the backward path?","scope":"The diagram compares update structure and retained state; actual savings depend on activation, normalization, and residual-module choices.","regions":{"fullblocks":{"x":0.19,"y":0.06,"w":0.28,"h":0.76,"label":"Full fine-tuning backbone"},"fullstate":{"x":0.01,"y":0.17,"w":0.17,"h":0.64,"label":"Full-path retained state and backward pass"},"tinyblocks":{"x":0.66,"y":0.06,"w":0.21,"h":0.76,"label":"Frozen TinyTL blocks and trainable biases"},"residual":{"x":0.86,"y":0.22,"w":0.13,"h":0.43,"label":"Lite residual modules"},"tinystate":{"x":0.51,"y":0.17,"w":0.16,"h":0.64,"label":"TinyTL backward state and full-depth arrow"}},"steps":[{"title":"Update every weight","description":"Full fine-tuning trains the backbone and classifier. The left state columns represent dependencies retained or recomputed for those gradients.","focus":["fullblocks","fullstate"]},{"title":"Restrict trainable parameters","description":"TinyTL freezes the main block weights while training biases, lite residual modules, and the classifier. Gray backbone weights remain present in the model.","focus":["tinyblocks","residual"]},{"title":"Keep backward reach","description":"The dashed backward arrow still spans the TinyTL network. Gradients must traverse frozen blocks to reach trainable biases at earlier depths.","focus":["tinystate"]},{"title":"Explain the memory lever","description":"TinyTL changes which backward values must remain live rather than simply stopping backpropagation early. Activation and normalization choices determine the remaining state.","focus":["fullstate","tinystate"]}],"artwork_reviewed":true,"art_sha1":"fe5e20351135886f67c8e7e0531f2bbd45d49289","art_kind":"svg","art_width":1200,"art_height":560,"art_structural_sha1":"9c6a9fbf2c2dac179623cc572219d1df1f4c1eb6"},"vol2:fig-tinytl-memory":{"key":"vol2:fig-tinytl-memory","figure_id":"fig-tinytl-memory","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"Adaptation memory budget","status":"ready","treatment":"annotated","question":"What must fit in working memory before local adaptation can run?","scope":"Segment heights are schematic. The peak is taken over the actual live activation-plus-workspace sum, not a sum of independently occurring peaks.","regions":{"flash":{"x":0.04,"y":0.68,"w":0.25,"h":0.23,"label":"Nonvolatile flash weights"},"resident":{"x":0.35,"y":0.61,"w":0.28,"h":0.17,"label":"Resident working-memory weights"},"train":{"x":0.35,"y":0.51,"w":0.28,"h":0.11,"label":"Trainable state"},"live":{"x":0.35,"y":0.25,"w":0.28,"h":0.26,"label":"Peak live activations and workspace"},"reserve":{"x":0.35,"y":0.1,"w":0.28,"h":0.15,"label":"Reserved runtime and application memory"},"time":{"x":0.68,"y":0.18,"w":0.31,"h":0.39,"label":"Execution-dependent peak"}},"steps":[{"title":"Distinguish storage from residency","description":"Frozen weights in flash occupy deployment storage. Once staged into SRAM or RAM, resident weights and staging workspace count against working memory.","focus":["flash","resident"]},{"title":"Add trainable state","description":"Gradients and optimizer state for the selected trainable parameters occupy a separate region. Freezing weights can reduce this region without removing the resident base.","focus":["train","resident"]},{"title":"Follow the live peak","description":"Activations and operator workspace change during execution. The drawn peak must reflect their simultaneous live sum under the actual schedule.","focus":["live","time"]},{"title":"Reserve room for the device","description":"Admission requires the adaptation peak plus the runtime and foreground-app reserve to fit under the device limit. The dashed red ceiling represents that complete constraint.","focus":["reserve","live"]}],"artwork_reviewed":true,"art_sha1":"6b326b3672a6dcf6711a07e7da74af0ee15f6247","art_kind":"svg","art_width":1200,"art_height":545,"art_structural_sha1":"ab94a84462d7c369b43a5d5f19538b51f72f6a1b"},"vol2:fig-topology-placement":{"key":"vol2:fig-topology-placement","figure_id":"fig-topology-placement","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Topology placement impact","status":"ready","treatment":"annotated","question":"Which communication delays does progressively more local placement avoid?","scope":"Latencies are assumed for a 0.5 GB synchronization on 64 GPUs. Payload divided by completion time is algorithm throughput, not physical link bandwidth.","regions":{"random":{"x":0.14,"y":0.06,"w":0.15,"h":0.83,"label":"Random placement"},"rack":{"x":0.35,"y":0.06,"w":0.15,"h":0.83,"label":"Rack-aware placement and removed spine hops"},"rail":{"x":0.56,"y":0.31,"w":0.15,"h":0.58,"label":"Rail-optimized placement"},"optimal":{"x":0.77,"y":0.66,"w":0.16,"h":0.23,"label":"Topology-optimal placement"}},"steps":[{"title":"Start from the assumed baseline","description":"Random placement takes 120 ms in this scenario. The first bar establishes a comparison, not a measured universal penalty.","focus":["random"]},{"title":"Remove wider network crossings","description":"Rack-aware placement removes the delay attributed to spine hops in the ghosted segment, reaching the assumed 85 ms endpoint.","focus":["rack"]},{"title":"Improve the remaining paths","description":"Rail optimization removes another illustrated crossing cost. The final placement also avoids the contended leaf-port component.","focus":["rail","optimal"]},{"title":"Interpret the ratio narrowly","description":"The 25 ms endpoint is 4.8 times lower than the assumed baseline. The printed GB/s values divide payload by completion time and must not be read as link specifications.","focus":["optimal"]}],"artwork_reviewed":true,"art_sha1":"0d1d019d4e89c3907fea6cd7f4fddc9feaae1e3e","art_kind":"png","art_width":3660,"art_height":2517},"vol2:fig-topology-placement-paths":{"key":"vol2:fig-topology-placement-paths","figure_id":"fig-topology-placement-paths","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"Topology-unaware vs. topology-aware placement","status":"ready","treatment":"annotated","question":"How can the same four-GPU job traverse different communication paths?","scope":"The path budgets are illustrative and configuration-specific; locality does not by itself guarantee a measured speedup.","regions":{"unaware":{"x":0.01,"y":0.01,"w":0.47,"h":0.97,"label":"Cross-rack placement"},"spine":{"x":0.08,"y":0.11,"w":0.29,"h":0.21,"label":"Shared spine uplinks"},"aware":{"x":0.53,"y":0.01,"w":0.46,"h":0.97,"label":"Single-rack placement"}},"steps":[{"title":"Split a gang across racks","description":"The topology-unaware placement assigns two GPUs in each rack. Their traffic must leave a leaf switch and traverse the spine.","focus":["unaware"]},{"title":"Identify the shared resource","description":"The highlighted spine uplinks add a boundary and share capacity. Counting GPUs alone misses this communication constraint.","focus":["spine"]},{"title":"Keep the gang local","description":"The topology-aware placement fits all four GPUs under one leaf switch. The drawn path uses one hop and the corresponding local network budget.","focus":["aware"]}],"artwork_reviewed":true,"art_sha1":"efab9487deb581fedf0bf2ee4bfc80bdc8ccf16a","art_kind":"svg","art_width":1200,"art_height":477,"art_structural_sha1":"efab9487deb581fedf0bf2ee4bfc80bdc8ccf16a"},"vol2:fig-torus-reduction":{"key":"vol2:fig-torus-reduction","figure_id":"fig-torus-reduction","source":"books/vol2/05_collective_communication/05_collective_communication.qmd","title":"Dimension-ordered reduction on a torus topology","status":"ready","treatment":"annotated","question":"How does a two-dimensional torus reduce startup rounds?","scope":"The illustration is a 4×4 logical topology; startup-round counts do not predict end-to-end time without the byte terms and fabric behavior.","regions":{"x":{"x":0.01,"y":0.01,"w":0.48,"h":0.7,"label":"X-ring reduction"},"y":{"x":0.51,"y":0.01,"w":0.48,"h":0.7,"label":"Y-ring reduction"},"rounds":{"x":0.01,"y":0.73,"w":0.98,"h":0.18,"label":"Startup-round comparison"}},"steps":[{"title":"Reduce along each row","description":"The X rings combine four ranks per row in six steps. Pale partial-sum tiles contain row contributions, not the full sixteen-rank result.","focus":["x"]},{"title":"Reduce the row results down columns","description":"The Y rings combine those row partial sums in six more steps. Green tiles now represent the full sum. Dashed edge arrows indicate wrap-around links.","focus":["y"]},{"title":"Separate startup count from runtime","description":"The bars compare twelve startup rounds for the two-dimensional torus with thirty for a one-dimensional sixteen-rank ring. In this simple schedule each axis processes the full message, so fewer startup rounds come with extra byte traffic; contention and bandwidth still affect elapsed time.","focus":["rounds"]}],"artwork_reviewed":true,"art_sha1":"912c148dca5f88e4cf0ef21f81ba376e6021e2db","art_kind":"svg","art_width":1200,"art_height":798,"art_structural_sha1":"206b32cd8aef815c67ae0dbb343e02669a64d931"},"vol2:fig-traditional-vs-ml-fleet":{"key":"vol2:fig-traditional-vs-ml-fleet","figure_id":"fig-traditional-vs-ml-fleet","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Retryable tasks vs. shared training steps","status":"ready","treatment":"annotated","question":"Why does a slow worker affect synchronous training differently from a retryable map task?","scope":"These are illustrative critical paths. MapReduce still has downstream dependencies; synchronous-training penalties depend on overlap.","regions":{"region-1":{"x":0.05,"y":0.23,"w":0.43,"h":0.29,"label":"Independent map outputs"},"region-2":{"x":0.05,"y":0.52,"w":0.44,"h":0.3,"label":"Retry and dependent reduce"},"region-3":{"x":0.55,"y":0.23,"w":0.35,"h":0.46,"label":"Worker waiting and collective"},"region-4":{"x":0.8,"y":0.74,"w":0.11,"h":0.11,"label":"Shared update"}},"steps":[{"title":"Finish independent map work","description":"Map 1 and Map 2 emit their own outputs and finish. They do not wait for Map 3 to retry.","focus":["region-1"]},{"title":"Retry the missing contribution","description":"Only Map 3 is re-run after its failure. Its missing output delays the reduce work that depends on it.","focus":["region-2"]},{"title":"Wait for every required gradient","description":"Workers 0 and 1 finish compute before slow Worker 2. Their gray waiting segments end only when the AllReduce can collect all required contributions.","focus":["region-3"]},{"title":"Advance one shared step","description":"The update follows the collective. Consistent shared progress is why local retry techniques need additional coordination in synchronous training.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"24203695ea210c67a71d7775f0b0610be75aa3cc","art_kind":"svg","art_width":1200,"art_height":414,"art_structural_sha1":"09980a4e4706f617bda49d7a0761458f8bb384b5"},"vol2:fig-training-compute-trend":{"key":"vol2:fig-training-compute-trend","figure_id":"fig-training-compute-trend","source":"books/vol2/01_introduction/01_introduction.qmd","title":"Where Training-Compute Growth Comes From","status":"ready","treatment":"annotated","question":"How much training-compute growth came from faster accelerators versus a larger, longer-running fleet?","scope":"These are fitted historical trends with estimated run data. A trend fit is not a forecast or a causal attribution to hardware alone.","regions":{"region-1":{"x":0.2,"y":0.04,"w":0.78,"h":0.52,"label":"Training-compute scatter"},"region-2":{"x":0.02,"y":0.65,"w":0.82,"h":0.15,"label":"Compute and accelerator-count bars"},"region-3":{"x":0.02,"y":0.8,"w":0.82,"h":0.14,"label":"Duration and delivered-rate bars"}},"steps":[{"title":"Read the historical trend","description":"Panel (a) places notable runs by publication date and training FLOPs on a logarithmic axis. The domain colors and dashed least-squares fit summarize substantial variation between individual runs.","focus":["region-1"]},{"title":"Separate fleet size from total compute","description":"Panel (b) gives annual growth factors for the reporting subset. Accelerator count is one multiplicative contributor to compute growth; its bar is not the entire compute increase.","focus":["region-2"]},{"title":"Account for runtime and delivered rate","description":"Training duration and delivered rate per accelerator supply the remaining factors. Delivered rate includes both hardware speed and utilization; logarithmic bar lengths make multiplicative growth contributions comparable.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"96f0c68d0cc2feff94080d44125afdd7b8ff14b8","art_kind":"png","art_width":3810,"art_height":3551},"vol2:fig-training-failure-signatures":{"key":"vol2:fig-training-failure-signatures","figure_id":"fig-training-failure-signatures","source":"books/vol2/07_fault_tolerance/07_fault_tolerance.qmd","title":"Training failure signatures","status":"ready","treatment":"annotated","question":"What can a loss signature tell an operator before a diagnosis is confirmed?","scope":"All four curves are synthetic examples. A transient rise or plateau is a symptom, not a unique diagnosis, and real healthy training need not decrease monotonically.","regions":{"healthy":{"x":0.07,"y":0.01,"w":0.45,"h":0.42,"label":"Normal training"},"explosion":{"x":0.53,"y":0.01,"w":0.46,"h":0.42,"label":"Gradient explosion"},"plateau":{"x":0.07,"y":0.49,"w":0.45,"h":0.48,"label":"Loss plateau"},"nan":{"x":0.53,"y":0.49,"w":0.46,"h":0.48,"label":"NaN divergence and halt"}},"steps":[{"title":"Establish the expected trend","description":"The healthy panel supplies a declining but noisy reference. Monitoring should compare departures with the variation expected for the workload.","focus":["healthy"]},{"title":"Investigate a sharp spike","description":"The explosion panel highlights a short large increase before recovery. The signature narrows hypotheses but needs gradient and execution evidence before a cause is assigned.","focus":["explosion"]},{"title":"Detect lack of useful progress","description":"The plateau remains above the healthy reference. The shaded gap represents impaired optimization rather than a process that necessarily stopped running.","focus":["plateau"]},{"title":"Verify nonfinite-value handling","description":"The divergence trace ends where the NaN check halts execution. Without that check the process can continue computing nonfinite values rather than crash.","focus":["nan"]}],"artwork_reviewed":true,"art_sha1":"40444f7c077f6341ed66e74c5aef6d95513a77fe","art_kind":"png","art_width":3657,"art_height":2640},"vol2:fig-training-memory-amplifier":{"key":"vol2:fig-training-memory-amplifier","figure_id":"fig-training-memory-amplifier","source":"books/vol2/11_edge_intelligence/11_edge_intelligence.qmd","title":"The training memory amplifier","status":"ready","treatment":"annotated","question":"Which additional objects amplify the memory cost of training?","scope":"The example assumes FP32 weights, Adam state, and activations fixed at five times weight memory. Its ninefold ratio is representative for this configuration, not a universal training multiplier.","regions":{"inference":{"x":0.12,"y":0.74,"w":0.11,"h":0.18,"label":"40 MB inference weights"},"weightsgrad":{"x":0.24,"y":0.66,"w":0.27,"h":0.26,"label":"Training weights and gradients"},"adam":{"x":0.24,"y":0.48,"w":0.27,"h":0.22,"label":"80 MB Adam state"},"activations":{"x":0.24,"y":0.16,"w":0.29,"h":0.34,"label":"200 MB activations"},"scaling":{"x":0.57,"y":0.04,"w":0.39,"h":0.91,"label":"Log-scale totals across model sizes"}},"steps":[{"title":"Begin with resident weights","description":"The inference bar contains 40 MB of weights for the 10M-parameter FP32 example. Training retains those weights as well.","focus":["inference","weightsgrad"]},{"title":"Add parameter-dependent state","description":"Gradients add another 40 MB and Adam state adds 80 MB. These objects must be distinguished from the original weights when budgeting memory.","focus":["weightsgrad","adam"]},{"title":"Include saved activations","description":"The assumed 200 MB activation region is the largest part of the training bar. The complete example reaches 360 MB rather than the 40 MB inference footprint.","focus":["activations"]},{"title":"Retain the stated assumption","description":"The right panel keeps the same ninefold total ratio across model sizes because the accounting assumptions scale together. Real activation lifetimes and optimizer choices can change that ratio.","focus":["scaling"]}],"artwork_reviewed":true,"art_sha1":"dea3be8dce43200cc7d95db2ed9e1d8f5c5791ba","art_kind":"png","art_width":3773,"art_height":2040},"vol2:fig-utilization-paradox":{"key":"vol2:fig-utilization-paradox","figure_id":"fig-utilization-paradox","source":"books/vol2/08_fleet_orchestration/08_fleet_orchestration.qmd","title":"The utilization paradox","status":"ready","treatment":"annotated","question":"Why does pushing offered load toward capacity increase waiting so sharply?","scope":"This is a toy queue model using offered service load, not measured GPU utilization or a universal 75-percent operating target.","regions":{"low":{"x":0.1,"y":0.45,"w":0.44,"h":0.49,"label":"Lower-load queueing region"},"target":{"x":0.73,"y":0.1,"w":0.04,"h":0.81,"label":"Illustrative headroom target"},"saturation":{"x":0.78,"y":0.01,"w":0.2,"h":0.91,"label":"High-load region"},"jobs":{"x":0.44,"y":0.36,"w":0.35,"h":0.45,"label":"Different mean job durations"}},"steps":[{"title":"Distinguish offered load from busy time","description":"The horizontal axis is offered service load divided by capacity. It is not simply the fraction of GPUs reported busy.","focus":["low"]},{"title":"Compare job duration scales","description":"Large, mixed, and small job classes have different waiting-time curves. Even this simplified model depends on service-duration assumptions.","focus":["jobs"]},{"title":"Leave headroom deliberately","description":"The dashed 75-percent line is an illustrative policy choice. It is not an empirically validated threshold for all fleets.","focus":["target"]},{"title":"Inspect the saturation limit","description":"The curves rise steeply near full offered load. Real gang constraints, size distributions, and arrival variability can change the actual delays beyond this toy model.","focus":["saturation"]}],"artwork_reviewed":true,"art_sha1":"9be4cd6dfad8bdda0cd089e65caf2dabfc86d2d2","art_kind":"png","art_width":3743,"art_height":2734},"vol2:fig-vol2-chapter-dependencies":{"key":"vol2:fig-vol2-chapter-dependencies","figure_id":"fig-vol2-chapter-dependencies","source":"books/vol2/frontmatter/about.qmd","title":"Chapter Dependency Map","status":"ready","treatment":"annotated","question":"How do prerequisites cross the book’s part boundaries?","scope":"Arrows encode direct cross-reference dependencies, with transitive links omitted; they do not mark optional chapters.","regions":{"fleet":{"x":0.2,"y":0.16,"w":0.59,"h":0.14,"label":"Fleet foundations"},"distributed":{"x":0.2,"y":0.32,"w":0.78,"h":0.14,"label":"Distributed ML"},"production":{"x":0.2,"y":0.49,"w":0.78,"h":0.13,"label":"Deployment at scale"},"responsible":{"x":0.2,"y":0.64,"w":0.78,"h":0.14,"label":"Responsible fleet"},"conclusion":{"x":0.76,"y":0.82,"w":0.22,"h":0.11,"label":"Conclusion"}},"steps":[{"title":"Establish fleet constraints","description":"Compute infrastructure feeds network fabrics and data storage. These earlier results constrain the distributed mechanisms in Part II.","focus":["fleet","distributed"]},{"title":"Follow a cross-part dependency","description":"Fleet orchestration consumes communication and fault-tolerance results, then feeds inference at scale. Reading order alone does not express these dependencies.","focus":["distributed","production"]},{"title":"Reach the shared conclusion","description":"Responsible AI receives both Robust AI and Sustainable AI results before the conclusion. Every chapter lies on a path to the conclusion.","focus":["responsible","conclusion"]}],"artwork_reviewed":true,"art_sha1":"1868023f0b99a7ed1c719af44516ea3a95e2c71c","art_kind":"svg","art_width":1200,"art_height":1236,"art_structural_sha1":"a7222d63c422b142ded1b418c1a2c850a94492f6"},"vol2:fig-vol2-interpretability-spectrum":{"key":"vol2:fig-vol2-interpretability-spectrum","figure_id":"fig-vol2-interpretability-spectrum","source":"books/vol2/16_responsible_ai/16_responsible_ai.qmd","title":"Model Interpretability Spectrum","status":"ready","treatment":"annotated","question":"What kind of explanation handle does each model family provide?","scope":"This is a heuristic ordering; model size, feature meaning, and audience can change practical interpretability.","regions":{"region-1":{"x":0.02,"y":0.04,"w":0.31,"h":0.75,"label":"Interpretable-by-design models"},"region-2":{"x":0.34,"y":0.04,"w":0.15,"h":0.75,"label":"Prototype and concept models"},"region-3":{"x":0.5,"y":0.04,"w":0.48,"h":0.75,"label":"Post-hoc explanation families"}},"steps":[{"title":"Read coefficients and split paths","description":"Sparse linear models expose nonzero coefficients; small decision trees expose split paths. These are useful handles only when the model and inputs remain understandable to the intended reader.","focus":["region-1"]},{"title":"Use exemplars as a hybrid handle","description":"The prototype/concept sketch connects an input to an exemplar. Its hybrid bracket indicates a different explanation route from coefficients or tree paths.","focus":["region-2"]},{"title":"Distinguish explanation from model transparency","description":"Tree ensembles name TreeSHAP, deep networks name gradients and SHAP, and foundation models name probing. These methods investigate model behavior without making the underlying model transparent by design.","focus":["region-3"]}],"artwork_reviewed":true,"art_sha1":"441b53440b675aa3a21d8e0e5dff332503695c92","art_kind":"svg","art_width":1200,"art_height":447,"art_structural_sha1":"1e97ee5a090aa0f56070920628de1ad7efa37e04"},"vol2:fig-vol2-roadmap":{"key":"vol2:fig-vol2-roadmap","figure_id":"fig-vol2-roadmap","source":"books/vol2/01_introduction/01_introduction.qmd","title":"The chapter roadmap","status":"ready","treatment":"annotated","question":"Where should a reader find each fleet engineering responsibility?","scope":"Reading order is shown top to bottom; the roadmap does not require a deployment to execute chapters in sequence.","regions":{"region-1":{"x":0.02,"y":0.16,"w":0.95,"h":0.17,"label":"Part I infrastructure"},"region-2":{"x":0.02,"y":0.34,"w":0.95,"h":0.17,"label":"Part II distribution"},"region-3":{"x":0.02,"y":0.52,"w":0.95,"h":0.17,"label":"Part III deployment"},"region-4":{"x":0.02,"y":0.7,"w":0.95,"h":0.17,"label":"Part IV responsible fleet"}},"steps":[{"title":"Build the fleet substrate","description":"Compute Infrastructure, Network Fabrics, and Data Storage establish the machines, links, and data paths on which later decisions depend.","focus":["region-1"]},{"title":"Coordinate many machines","description":"Collective Communication and Distributed Training introduce shared execution. Fault Tolerance and Fleet Orchestration address failures and placement.","focus":["region-2"]},{"title":"Deliver the service","description":"Performance Engineering, Inference at Scale, Edge Intelligence, and ML Operations turn fleet resources into a maintained service.","focus":["region-3"]},{"title":"Evaluate the operating contract","description":"Security and Privacy, Robust AI, Sustainable AI, and Responsible AI constrain how the fleet may operate. Their stack icons mark the upper governance band.","focus":["region-4"]}],"artwork_reviewed":true,"art_sha1":"43d770f0fe1214fced7fc9e9022c0df72b88439d","art_kind":"svg","art_width":1200,"art_height":724,"art_structural_sha1":"43d770f0fe1214fced7fc9e9022c0df72b88439d"},"vol2:fig-wafer-scale-engine":{"key":"vol2:fig-wafer-scale-engine","figure_id":"fig-wafer-scale-engine","source":"books/vol2/02_compute_infrastructure/02_compute_infrastructure.qmd","title":"Wafer-scale engine (WSE) architecture","status":"ready","treatment":"annotated","question":"Which physical communication boundaries does wafer-scale integration remove?","scope":"The WSE totals are vendor-reported and cannot be directly compared with GPU HBM bandwidth.","regions":{"node":{"x":0.01,"y":0.06,"w":0.43,"h":0.63,"label":"DGX node and NVSwitch"},"network":{"x":0.13,"y":0.67,"w":0.3,"h":0.26,"label":"External InfiniBand boundary"},"wafer":{"x":0.45,"y":0.04,"w":0.36,"h":0.81,"label":"On-wafer core mesh"},"defect":{"x":0.5,"y":0.33,"w":0.25,"h":0.16,"label":"Route around defective core"}},"steps":[{"title":"Exchange inside a chassis","description":"The eight GPUs communicate through NVSwitch, but remain separate packages joined by a board-level fabric.","focus":["node"]},{"title":"Leave the node","description":"The arrow to other nodes crosses the external InfiniBand boundary. Local and external transfers have different budgets.","focus":["network"]},{"title":"Move on the wafer","description":"The WSE maps cores and local SRAM onto one mesh, replacing some off-package transfers with on-wafer communication.","focus":["wafer"]},{"title":"Route around defects","description":"The highlighted path bends around the crossed-out core. Defect-aware routing preserves usable mesh connectivity rather than requiring every core to work.","focus":["defect"]}],"artwork_reviewed":true,"art_sha1":"f3c964db276506494e9e823074c666bd162b9f60","art_kind":"svg","art_width":1200,"art_height":586,"art_structural_sha1":"b72d72de95ffd34f5ba4a2d3461288dd15fd46af"},"vol2:fig-water-cycle":{"key":"vol2:fig-water-cycle","figure_id":"fig-water-cycle","source":"books/vol2/15_sustainable_ai/15_sustainable_ai.qmd","title":"Semiconductor Water Cycle","status":"ready","treatment":"annotated","question":"Why is recycled water different from water consumed?","scope":"The figure is a qualitative balance; any numerical reuse fraction must state its denominator.","regions":{"withdraw":{"x":0.01,"y":0.06,"w":0.24,"h":0.88,"label":"Watershed and freshwater withdrawal"},"process":{"x":0.24,"y":0.06,"w":0.54,"h":0.27,"label":"Intake, treatment, and fab"},"reuse":{"x":0.26,"y":0.49,"w":0.51,"h":0.21,"label":"Wastewater treatment and reuse"},"consume":{"x":0.78,"y":0.06,"w":0.21,"h":0.69,"label":"Evaporation and unreturned water"},"return":{"x":0.1,"y":0.72,"w":0.63,"h":0.18,"label":"Discharge returned to watershed"}},"steps":[{"title":"Withdraw and prepare water","description":"Freshwater leaves the watershed through intake, becomes ultrapure process water, and enters the fab. Withdrawal records this source demand.","focus":["withdraw","process"]},{"title":"Recover part of the process flow","description":"Wastewater treatment returns reused water to intake. Internal reuse can reduce new freshwater demand without being a return to the watershed.","focus":["reuse"]},{"title":"Identify consumption","description":"Evaporation and unreturned treated flows end in the Consumed box. Those flows determine consumption, rather than the total volume that circulated through the fab.","focus":["consume"]},{"title":"Track water that returns","description":"The discharge arrow returns water to the watershed. Keep this external return distinct from the internal reuse loop when defining fractions.","focus":["return","reuse"]}],"artwork_reviewed":true,"art_sha1":"6f85c3f53498f43bcc0f24e3e012827d5df74d7e","art_kind":"svg","art_width":1200,"art_height":415,"art_structural_sha1":"8f69c01e62d8e7155d730c869e21c4fc5182396d"},"vol2:fig-weight-corruption":{"key":"vol2:fig-weight-corruption","figure_id":"fig-weight-corruption","source":"books/vol2/14_robust_ai/14_robust_ai.qmd","title":"Weight Corruption via Bit Flip","status":"ready","treatment":"annotated","question":"How can one finite weight corruption affect multiple outputs?","scope":"The shown bit flip is a specific FP32 example, not the expected effect of every random upset; output dominance depends on inputs and downstream computation.","regions":{"path":{"x":0.01,"y":0.01,"w":0.48,"h":0.96,"label":"Forward path through h2"},"before":{"x":0.52,"y":0.1,"w":0.47,"h":0.29,"label":"Original FP32 exponent"},"flip":{"x":0.52,"y":0.43,"w":0.47,"h":0.39,"label":"Bit 30 flip and extreme finite weight"}},"steps":[{"title":"Locate the corrupted connection","description":"The red weight feeds hidden unit h2, whose outgoing edges reach both output logits. A single stored parameter can therefore influence more than one result.","focus":["path"]},{"title":"Read the original representation","description":"The upper bit field separates sign, eight exponent bits, and the mantissa. The stored weight is approximately 0.042 before corruption.","focus":["before"]},{"title":"Distinguish a large finite value from NaN","description":"Flipping the highlighted exponent bit scales the magnitude by 2^128 in this example. The resulting extreme value remains finite, so NaN and infinity checks alone need not catch it.","focus":["flip"]}],"artwork_reviewed":true,"art_sha1":"fc8301583460b43dd73e462817cfe17dc919ea66","art_kind":"svg","art_width":1200,"art_height":563,"art_structural_sha1":"da757d8e07f9e739ebc321d7f277d3d00ebde42f"},"vol2:fig-zero-memory":{"key":"vol2:fig-zero-memory","figure_id":"fig-zero-memory","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"ZeRO memory reduction","status":"ready","treatment":"annotated","question":"Which persistent state term makes early ZeRO stages effective?","scope":"The example is a 7B-parameter model on 64 ranks at 16 bytes per parameter. Bars exclude activations, temporary gathered parameters, communication buffers, and runtime allocations.","regions":{"ddp":{"x":0.12,"y":0.13,"w":0.2,"h":0.84,"label":"DDP 112 GB state"},"zero1":{"x":0.36,"y":0.55,"w":0.18,"h":0.42,"label":"ZeRO-1 29.3 GB"},"zero2":{"x":0.59,"y":0.66,"w":0.19,"h":0.31,"label":"ZeRO-2 15.5 GB"},"zero3":{"x":0.82,"y":0.69,"w":0.17,"h":0.28,"label":"ZeRO-3 1.75 GB"},"ceiling":{"x":0.09,"y":0.36,"w":0.89,"h":0.07,"label":"80 GB accelerator ceiling"}},"steps":[{"title":"Find the largest replicated term","description":"DDP stores 14 GB weights, 14 GB gradients, and 84 GB optimizer state per rank. The 112 GB stack exceeds the displayed 80 GB ceiling.","focus":["ddp","ceiling"]},{"title":"Shard optimizer state first","description":"ZeRO-1 retains replicated weights and gradients while partitioning the largest term. The remaining 29.3 GB persistent stack already fits below that ceiling.","focus":["zero1"]},{"title":"Continue partitioning","description":"ZeRO-2 also shards gradients; ZeRO-3 also shards parameters. The bars shrink to 15.5 GB and 1.75 GB under this fixed example.","focus":["zero2","zero3"]},{"title":"Check the actual peak separately","description":"Dashed outlines mark removed replicated state, not extra free capacity guaranteed to a batch. Activations and transient gathered state must still fit simultaneously.","focus":["ceiling","zero3"]}],"artwork_reviewed":true,"art_sha1":"1e26df398691f2cff9096c84d0436e2ee019a7c1","art_kind":"png","art_width":4217,"art_height":2578},"vol2:fig-zero-partitioning":{"key":"vol2:fig-zero-partitioning","figure_id":"fig-zero-partitioning","source":"books/vol2/06_distributed_training/06_distributed_training.qmd","title":"ZeRO state partitioning across GPU ranks","status":"ready","treatment":"annotated","question":"Which training-state copies disappear at each ZeRO stage?","scope":"Four ranks and 2/2/12 bytes per parameter are the diagram’s mixed-precision Adam example; tile width is a shard fraction, not actual relative byte size.","regions":{"ddp":{"x":0.1,"y":0.13,"w":0.21,"h":0.83,"label":"DDP replicated state"},"one":{"x":0.32,"y":0.13,"w":0.21,"h":0.83,"label":"ZeRO-1 optimizer shards"},"two":{"x":0.54,"y":0.13,"w":0.21,"h":0.83,"label":"ZeRO-2 gradient shards"},"three":{"x":0.76,"y":0.13,"w":0.22,"h":0.83,"label":"ZeRO-3 parameter shards"}},"steps":[{"title":"Identify replicated ownership","description":"In DDP every rank holds complete W, G, and O tiles. Rank count therefore does not reduce each rank’s persistent model-state footprint.","focus":["ddp"]},{"title":"Shard optimizer state","description":"ZeRO-1 distributes O across ranks. Quarter-width filled segments show different owners while W and G remain replicated.","focus":["one"]},{"title":"Also shard gradients","description":"ZeRO-2 distributes both G and O. Dashed outlines mark the full stacks each rank no longer stores persistently.","focus":["two"]},{"title":"Shard weights and communicate","description":"ZeRO-3 also distributes W. Its footer records higher per-worker communication because parameters must be gathered when needed.","focus":["three"]}],"artwork_reviewed":true,"art_sha1":"fa3556a105001fec4cb93ec1c563e5f5b731cfff","art_kind":"svg","art_width":1200,"art_height":520,"art_structural_sha1":"fa3556a105001fec4cb93ec1c563e5f5b731cfff"}});
